  ('25000886-5d4b-7b48-9fd5-4fdbbd0f5e56', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Source ("},{"type":"text","text":"list.stream()","marks":[{"type":"code"}]},{"type":"text","text":") → Intermediate ops ("},{"type":"text","text":"filter","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":"…) — lazy → Terminal op ("},{"type":"text","text":"collect","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"sum","marks":[{"type":"code"}]},{"type":"text","text":"…) — triggers work → Result"}]}]}}'),
