  ('8dbd1e78-5983-7d88-94ec-6cdb317c53f5', 'a9', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"What it does"}],[{"type":"text","text":"Stateful?"}]],[[{"type":"text","text":"filter(pred)","marks":[{"type":"code"}]}],[{"type":"text","text":"keep elements matching"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"map(fn)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"mapToInt(fn)","marks":[{"type":"code"}]}],[{"type":"text","text":"transform each element (1 → 1)"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"flatMap(fn)","marks":[{"type":"code"}]}],[{"type":"text","text":"each element → a stream, flattened (1 → many)"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"peek(action)","marks":[{"type":"code"}]}],[{"type":"text","text":"look at elements as they pass (debugging)"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"distinct()","marks":[{"type":"code"}]}],[{"type":"text","text":"drop duplicates (uses "},{"type":"text","text":"equals","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"hashCode","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Yes","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"sorted()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"sorted(cmp)","marks":[{"type":"code"}]}],[{"type":"text","text":"sort — must see "},{"type":"text","text":"all","marks":[{"type":"italic"}]},{"type":"text","text":" elements first"}],[{"type":"text","text":"Yes","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"limit(n)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"skip(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"first n / drop first n (short-circuit "},{"type":"text","text":"limit","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Yes (count)"}]],[[{"type":"text","text":"takeWhile","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"dropWhile","marks":[{"type":"code"}]},{"type":"text","text":" (9+)"}],[{"type":"text","text":"prefix while predicate holds"}],[{"type":"text","text":"No"}]]]}'),
  ('faaaceb3-60ae-7e42-96dd-39d8bd2656a1', 'aA', 'code', '{"language":"java","code":"import java.util.*;\nimport java.util.stream.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<List<Integer>> nested = List.of(List.of(1, 2), List.of(3, 4), List.of(4, 5));\n        System.out.println(nested.stream().flatMap(List::stream).toList());\n        System.out.println(nested.stream().flatMap(List::stream).distinct().skip(1).limit(3).toList());\n\n        System.out.println(Stream.of(\"b\", \"a\", \"c\").sorted(Comparator.reverseOrder()).toList());\n        System.out.println(Stream.iterate(1, x -> x * 2).limit(6).toList());\n        System.out.println(IntStream.rangeClosed(1, 10).takeWhile(i -> i < 5).boxed().toList());\n        System.out.println(\"hello\".chars().filter(c -> c == ''l'').count());\n    }\n}","filename":"Java"}'),
  ('823b600b-3f74-796f-b584-8d59ad3f7522', 'aB', 'code', '{"language":"text","code":"[1, 2, 3, 4, 4, 5]\n[2, 3, 4]\n[c, b, a]\n[1, 2, 4, 8, 16, 32]\n[1, 2, 3, 4]\n2","filename":"Output"}'),
  ('5de68fb4-cd73-75cf-90c2-00b57322e16b', 'aC', 'heading', '{"level":1,"content":[{"type":"text","text":"Laziness: nothing runs until the terminal op"}]}'),
  ('cdee941f-6e66-7788-9d1e-cb04a098a779', 'aD', 'code', '{"language":"java","code":"import java.util.stream.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Stream<Integer> pipeline = Stream.of(1, 2, 3, 4, 5, 6)\n                .peek(x -> System.out.println(\"saw \" + x))\n                .filter(x -> x % 2 == 0)\n                .map(x -> x * 10);\n        System.out.println(\"pipeline built, nothing printed yet\");\n\n        Integer first = pipeline.findFirst().orElseThrow();   // terminal op\n        System.out.println(\"first = \" + first);\n    }\n}","filename":"Java"}'),
  ('baaf4129-bea9-7c57-a29d-cbb4595735ef', 'aE', 'code', '{"language":"text","code":"pipeline built, nothing printed yet\nsaw 1\nsaw 2\nfirst = 20","filename":"Output"}'),
  ('906329c2-a877-7d18-b49f-5746765ecb5d', 'aF', 'callout', '{"variant":"note","title":"Vertical, short-circuiting","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Elements flow through the pipeline "},{"type":"text","text":"one at a time","marks":[{"type":"bold"}]},{"type":"text","text":" (vertical processing), not stage by stage. With a short-circuiting terminal op like "},{"type":"text","text":"findFirst","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"anyMatch","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"limit","marks":[{"type":"code"}]},{"type":"text","text":", the stream stops as soon as it has its answer — here it never looked at 3–6."}]}]}}'),
  ('a7943023-798e-7224-b1cf-f52a53fc1522', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Terminal operations"}]}'),
  ('79a5cc5f-7d4e-7515-b507-d464681a0f8c', 'aH', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Operation"}],[{"type":"text","text":"Returns"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"forEach(action)","marks":[{"type":"code"}]}],[{"type":"text","text":"void"}],[{"type":"text","text":"order not guaranteed on parallel streams ("},{"type":"text","text":"forEachOrdered","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"collect(collector)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"toList()","marks":[{"type":"code"}]}],[{"type":"text","text":"a collection / value"}],[{"type":"text","text":"see Collectors topic"}]],[[{"type":"text","text":"reduce(identity, op)","marks":[{"type":"code"}]}],[{"type":"text","text":"T","marks":[{"type":"code"}]}],[{"type":"text","text":"fold into one value"}]],[[{"type":"text","text":"count()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"min(cmp)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"max(cmp)","marks":[{"type":"code"}]}],[{"type":"text","text":"long","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Optional<T>","marks":[{"type":"code"}]}],[{"type":"text","text":"min/max are Optional — stream may be empty"}]],[[{"type":"text","text":"sum()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"average()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"summaryStatistics()","marks":[{"type":"code"}]}],[{"type":"text","text":"number / "},{"type":"text","text":"OptionalDouble","marks":[{"type":"code"}]}],[{"type":"text","text":"only on "},{"type":"text","text":"IntStream","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"LongStream","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"DoubleStream","marks":[{"type":"code"}]}]],[[{"type":"text","text":"anyMatch","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"allMatch","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"noneMatch","marks":[{"type":"code"}]}],[{"type":"text","text":"boolean","marks":[{"type":"code"}]}],[{"type":"text","text":"short-circuit; "},{"type":"text","text":"allMatch","marks":[{"type":"code"}]},{"type":"text","text":" on empty = "},{"type":"text","text":"true","marks":[{"type":"code"}]}]],[[{"type":"text","text":"findFirst()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"findAny()","marks":[{"type":"code"}]}],[{"type":"text","text":"Optional<T>","marks":[{"type":"code"}]}],[{"type":"text","text":"findAny","marks":[{"type":"code"}]},{"type":"text","text":" is faster on parallel streams"}]],[[{"type":"text","text":"toArray()","marks":[{"type":"code"}]}],[{"type":"text","text":"array"}],[{"type":"text","text":"toArray(String[]::new)","marks":[{"type":"code"}]},{"type":"text","text":" for a typed array"}]]]}'),
  ('f6773e2c-207d-7154-ada6-67485ac437b0', 'aI', 'code', '{"language":"java","code":"import java.util.*;\nimport java.util.stream.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> nums = List.of(4, 8, 15, 16, 23, 42);\n\n        System.out.println(nums.stream().reduce(0, Integer::sum));\n        System.out.println(nums.stream().reduce(Integer::max).get());\n        System.out.println(nums.stream().mapToInt(Integer::intValue).sum());\n        System.out.println(nums.stream().mapToInt(i -> i).average().getAsDouble());\n        System.out.println(nums.stream().max(Comparator.naturalOrder()).get());\n        System.out.println(nums.stream().filter(n -> n > 100).count());\n        System.out.println(nums.stream().anyMatch(n -> n % 2 == 1) + \" \" + nums.stream().allMatch(n -> n > 0));\n        IntSummaryStatistics st = nums.stream().mapToInt(i -> i).summaryStatistics();\n        System.out.println(st.getMin() + \"..\" + st.getMax() + \" avg \" + st.getAverage());\n        String[] arr = Stream.of(\"x\", \"y\").toArray(String[]::new);\n        System.out.println(Arrays.toString(arr));\n    }\n}","filename":"Java"}'),
