import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        List<List<Integer>> nested = List.of(List.of(1, 2), List.of(3, 4), List.of(4, 5));
        System.out.println(nested.stream().flatMap(List::stream).toList());
