SELECT '67960bff-77bc-71ff-ad3f-4905b37360eb', 'b65bf087-1d8d-7b90-9f53-c8c03d56073e', 1, 'PUBLISHED', 'String & Memory Interview Traps', '[{"id":"a6dd6462-f51e-72b4-8778-1af241bf6ed6","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A collection of classic “what does this print?” questions about strings, the pool, boxing and constant folding — each verified."}]}]}},"revision":1},{"id":"3b28e221-5962-7346-9822-925e25d29092","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"== on strings"}]},"revision":1},{"id":"edc39598-557b-7785-8832-b6e810605236","type":"code","position":"a2","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        String a = \"java\";\n        String b = \"java\";                 // same pooled literal\n        String c = new String(\"java\");     // a new heap object\n        String d = \"ja\" + \"va\";            // compile-time constant → folded to \"java\"\n        String part = \"ja\";\n        String e = part + \"va\";            // runtime concatenation → new object\n        final String fpart = \"ja\";\n        String f = fpart + \"va\";           // final + literal is a constant → folded\n\n        System.out.println(a == b);\n        System.out.println(a == c);\n        System.out.println(a == d);\n        System.out.println(a == e);\n        System.out.println(a == f);\n        System.out.println(a == e.intern());\n        System.out.println(a.equals(c));\n    }\n}","filename":"Java"},"revision":1},{"id":"8f414c27-b49d-7b5f-9b0b-d16dda97bbe4","type":"code","position":"a3","content":{"language":"text","code":"true\nfalse\ntrue\nfalse\ntrue\ntrue\ntrue","filename":"Output"},"revision":1},{"id":"e2d761c1-86d9-7da7-a6af-aca78b03976b","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Expression"}],[{"type":"text","text":"Pooled?"}],[{"type":"text","text":"Why"}]],[[{"type":"text","text":"\"java\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Every string literal is interned in the pool"}]],[[{"type":"text","text":"new String(\"java\")","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":" always creates a fresh heap object"}]],[[{"type":"text","text":"\"ja\" + \"va\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Constant expression, folded by "},{"type":"text","text":"javac","marks":[{"type":"code"}]}]],[[{"type":"text","text":"part + \"va\"","marks":[{"type":"code"}]},{"type":"text","text":" (non-final "},{"type":"text","text":"part","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Computed at run time ("},{"type":"text","text":"StringConcatFactory","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"StringBuilder","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"fpart + \"va\"","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":" with constant initialiser)"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"fpart","marks":[{"type":"code"}]},{"type":"text","text":" is a "},{"type":"text","text":"constant variable","marks":[{"type":"italic"}]},{"type":"text","text":", so the whole expression is constant"}]],[[{"type":"text","text":"s.intern()","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Returns the pooled instance, adding it if absent"}]]]},"revision":1},{"id":"791e9b98-bd3a-7ec9-843c-94cbeb80838f","type":"callout","position":"a5","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rule: compare strings with "},{"type":"text","text":"equals","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"Objects.equals","marks":[{"type":"code"}]},{"type":"text","text":" for null-safety). "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" only tells you whether two references point at the same object."}]}]}},"revision":1},{"id":"90262a84-4253-7c89-9cbd-86bdcc14a742","type":"question","position":"a6","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How many objects does new String(\"hello\") create?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Up to two: the literal "},{"type":"text","text":"\"hello\"","marks":[{"type":"code"}]},{"type":"text","text":" is placed in the string pool when the class is loaded (if it isn''t already there), and "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":" creates one more "},{"type":"text","text":"String","marks":[{"type":"code"}]},{"type":"text","text":" object on the heap. If the literal was already pooled, only one new object is created at run time."}]}]}},"revision":1},{"id":"07c49bfd-8c1e-7b05-ab1f-dd503331ad45","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Integer cache and boxing"}]},"revision":1},{"id":"19b6d43c-138c-738e-b928-50dc0affb220","type":"code","position":"a8","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        Integer a = 127, b = 127;\n        Integer c = 128, d = 128;\n        System.out.println(a == b);          // cached: -128..127\n        System.out.println(c == d);          // two different objects\n        System.out.println(c.equals(d));\n\n        Long big = 127L;\n        System.out.println(big.equals(127));  // Integer vs Long → false\n        System.out.println(big == 127);       // unboxed numeric comparison → true\n\n        Integer missing = null;\n        try {\n            int n = missing;                  // auto-unboxing null\n            System.out.println(n);\n        } catch (NullPointerException ex) {\n            System.out.println(\"NPE on unboxing\");\n        }\n\n        boolean flag = true;\n        try {\n            int r = flag ? missing : 0;       // ternary unboxes `missing`\n            System.out.println(r);\n        } catch (NullPointerException ex) {\n            System.out.println(\"NPE in ternary\");\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"0f079ea1-aff4-7216-b88c-ac89a5421384","type":"code","position":"a9","content":{"language":"text","code":"true\nfalse\ntrue\nfalse\ntrue\nNPE on unboxing\nNPE in ternary","filename":"Output"},"revision":1},{"id":"bc2beb31-e6e8-73d2-b8ca-028fb3ac0b3a","type":"callout","position":"aA","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The cache covers "},{"type":"text","text":"Integer","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Short","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Long","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Byte","marks":[{"type":"code"}]},{"type":"text","text":" in −128…127, "},{"type":"text","text":"Character","marks":[{"type":"code"}]},{"type":"text","text":" up to 127 and both "},{"type":"text","text":"Boolean","marks":[{"type":"code"}]},{"type":"text","text":" values. The upper bound for "},{"type":"text","text":"Integer","marks":[{"type":"code"}]},{"type":"text","text":" can be raised with "},{"type":"text","text":"-XX:AutoBoxCacheMax","marks":[{"type":"code"}]},{"type":"text","text":", so "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" on boxed numbers is never reliable."}]}]}},"revision":1},{"id":"b9254105-1b58-7db3-922e-29b19baa5306","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Concatenation and char arithmetic"}]},"revision":1},{"id":"27759580-2adc-7358-97f1-14a8ca2c450f","type":"code","position":"aC","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        System.out.println(\"a\" + 1 + 2);      // left to right: (\"a\" + 1) + 2\n        System.out.println(1 + 2 + \"a\");      // (1 + 2) + \"a\"\n        System.out.println(''a'' + ''b'');        // char + char → int\n        System.out.println(\"\" + ''a'' + ''b'');\n        System.out.println((char) (''a'' + 1));\n        System.out.println(Math.abs(Integer.MIN_VALUE));   // overflow: no positive counterpart\n        System.out.println(0.1 + 0.2);\n    }\n}","filename":"Java"},"revision":1},{"id":"de8420a1-e1c5-7d3c-b6ff-04e5edd3b4ca","type":"code","position":"aD","content":{"language":"text","code":"a12\n3a\n195\nab\nb\n-2147483648\n0.30000000000000004","filename":"Output"},"revision":1},{"id":"1e45db72-d73f-7e90-b4a2-c29c5b301681","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"String + in a loop"}]},"revision":1},{"id":"9b2887a0-3fd1-746d-8928-c99d98f4fada","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each "},{"type":"text","text":"s += x","marks":[{"type":"code"}]},{"type":"text","text":" creates a brand-new string and copies everything so far — O(n²) for n appends. Inside loops use a "},{"type":"text","text":"StringBuilder","marks":[{"type":"code"}]},{"type":"text","text":" (single-expression concatenations are fine: the compiler optimises them)."}]}]}},"revision":1},{"id":"92370fa6-cadf-72d6-aef6-f81e138540ce","type":"code","position":"aG","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < 5; i++) {\n            sb.append(i).append('','');\n        }\n        sb.setLength(sb.length() - 1);            // drop the trailing comma\n        System.out.println(sb);\n\n        System.out.println(String.join(\",\", \"a\", \"b\", \"c\"));   // often simplest\n    }\n}","filename":"Java"},"revision":1},{"id":"bcc13f97-bc63-7155-917a-8bff3db1a44e","type":"code","position":"aH","content":{"language":"text","code":"0,1,2,3,4\na,b,c","filename":"Output"},"revision":1},{"id":"482c79c0-3eb3-7b3b-8a44-cccd1c8139fd","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Other traps"}]},"revision":1},{"id":"eea0c321-51d1-7f9c-a47b-393f6363daf8","type":"callout","position":"aJ","content":{"variant":"note","title":"substring copies","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Before Java 7u6, "},{"type":"text","text":"substring","marks":[{"type":"code"}]},{"type":"text","text":" shared the parent''s "},{"type":"text","text":"char[]","marks":[{"type":"code"}]},{"type":"text","text":" — a tiny substring could pin a huge string in memory. Now it copies, so no leak (but O(k) cost)."}]}]}},"revision":1},{"id":"4897c450-6c93-73cf-919a-3fce95a96534","type":"callout","position":"aK","content":{"variant":"note","title":"Passwords in char[]","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"String","marks":[{"type":"code"}]},{"type":"text","text":" is immutable and may be pooled; it lingers in memory until GC and can show up in heap dumps. A "},{"type":"text","text":"char[]","marks":[{"type":"code"}]},{"type":"text","text":" can be wiped with "},{"type":"text","text":"Arrays.fill(pw, ''\\0'')","marks":[{"type":"code"}]},{"type":"text","text":" right after use — that''s why "},{"type":"text","text":"Console.readPassword()","marks":[{"type":"code"}]},{"type":"text","text":" returns "},{"type":"text","text":"char[]","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"8a6bdaa0-af90-7ab7-99d5-23295cdf6938","type":"callout","position":"aL","content":{"variant":"note","title":"Compact strings (9+)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Strings that contain only Latin-1 characters store one byte per char instead of two ("},{"type":"text","text":"byte[]","marks":[{"type":"code"}]},{"type":"text","text":" + a coder flag)."}]}]}},"revision":1},{"id":"82271913-7de4-790f-ad9c-fd17c426c3c1","type":"callout","position":"aM","content":{"variant":"note","title":"Strings are immutable","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"s.toUpperCase()","marks":[{"type":"code"}]},{"type":"text","text":" returns a new string; calling it without assigning the result does nothing."}]}]}},"revision":1},{"id":"431242df-b49c-74aa-83bd-deeea3d318e8","type":"code","position":"aN","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        String s = \"hello\";\n        s.toUpperCase();                   // result discarded\n        System.out.println(s);\n        s = s.toUpperCase();\n        System.out.println(s);\n    }\n}","filename":"Java"},"revision":1},{"id":"111ef177-8b0a-7224-b806-3839036404be","type":"code","position":"aO","content":{"language":"text","code":"hello\nHELLO","filename":"Output"},"revision":1},{"id":"28206151-3a3b-776f-a89b-53e187064aa6","type":"heading","position":"aP","content":{"level":1,"content":[{"type":"text","text":"switch on strings and null"}]},"revision":1},{"id":"38f9607e-bc52-7b6d-bf64-9115fed08edf","type":"text","position":"aQ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"switch","marks":[{"type":"code"}]},{"type":"text","text":" on a "},{"type":"text","text":"String","marks":[{"type":"code"}]},{"type":"text","text":" compiles to a switch on "},{"type":"text","text":"hashCode()","marks":[{"type":"code"}]},{"type":"text","text":" followed by "},{"type":"text","text":"equals()","marks":[{"type":"code"}]},{"type":"text","text":". A "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" selector throws "},{"type":"text","text":"NullPointerException","marks":[{"type":"code"}]},{"type":"text","text":" — unless (Java 21) you add "},{"type":"text","text":"case null","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"8ddbd8d5-bdba-7c64-86cb-8b5db292ac27","type":"code","position":"aR","content":{"language":"java","code":"public class Main {\n    static String classic(String cmd) {\n        switch (cmd) {\n            case \"start\": return \"starting\";\n            case \"stop\":  return \"stopping\";\n            default:      return \"unknown\";\n        }\n    }\n\n    static String modern(String cmd) {\n        return switch (cmd) {\n            case null -> \"no command\";            // Java 21\n            case \"start\" -> \"starting\";\n            default -> \"unknown\";\n        };\n    }\n\n    public static void main(String[] args) {\n        System.out.println(classic(\"stop\"));\n        try {\n            classic(null);\n        } catch (NullPointerException e) {\n            System.out.println(\"NPE from classic switch\");\n        }\n        System.out.println(modern(null));\n    }\n}","filename":"Java"},"revision":1},{"id":"855f4cd7-272a-7a10-a6cd-4d7ffa9ceee0","type":"code","position":"aS","content":{"language":"text","code":"stopping\nNPE from classic switch\nno command","filename":"Output"},"revision":1},{"id":"a73f75a8-0f0c-74de-baeb-86a46b1a897c","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is String immutable in Java?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"(1) The string pool is only safe if pooled strings can''t change. (2) Security: class names, file paths and URLs passed to APIs can''t be altered after a check. (3) Thread safety for free. (4) The hash code can be cached, which makes strings fast "},{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":" keys."}]}]}},"revision":1},{"id":"2d6441f5-5a68-7f6a-8d04-5e3068caf9aa","type":"question","position":"aU","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does intern() do, and should you use it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It returns the canonical pooled copy of the string, adding it to the pool if needed, so equal interned strings are "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":". It can save memory for many duplicate strings, but the pool lookup has a cost — modern G1 also offers "},{"type":"text","text":"-XX:+UseStringDeduplication","marks":[{"type":"code"}]},{"type":"text","text":", which deduplicates backing arrays automatically."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
