SELECT '09a3255d-459f-7ccb-84e2-ce292a5f3726', '68f86f6e-bc39-769f-8b98-a5dc399538af', 1, 'PUBLISHED', 'Strings, Immutability & the String Pool', '[{"id":"7b2ea2f4-7a45-7350-9cca-8ad2f2d5de51","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"String","marks":[{"type":"code"}]},{"type":"text","text":" is an immutable object, not a primitive. Literals are interned in the "},{"type":"text","text":"string pool","marks":[{"type":"italic"}]},{"type":"text","text":", so "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" sometimes “works” — and that is exactly the trap."}]}]}},"revision":1},{"id":"3aaccf32-f7ad-7dcb-b208-a718f32cf3d3","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"String","marks":[{"type":"bold"}]},{"type":"text","text":" — a final class holding an immutable sequence of UTF-16 characters (since Java 9 stored compactly as "},{"type":"text","text":"byte[]","marks":[{"type":"code"}]},{"type":"text","text":" + a coder flag: Latin-1 or UTF-16). Every “modifying” method returns a "},{"type":"text","text":"new","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"String","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"faffa338-3274-7ab0-b97c-5dfca5252194","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Creating strings"}]},"revision":1},{"id":"c61a3a70-6a5c-757f-8ada-188e362228d0","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Form"}],[{"type":"text","text":"Where it lives"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"String a = \"hi\";","marks":[{"type":"code"}]}],[{"type":"text","text":"String pool (interned)"}],[{"type":"text","text":"Identical literals in the whole JVM share one object"}]],[[{"type":"text","text":"String b = new String(\"hi\");","marks":[{"type":"code"}]}],[{"type":"text","text":"A new heap object"}],[{"type":"text","text":"Always a distinct object — almost never what you want"}]],[[{"type":"text","text":"\"h\" + \"i\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Pool"}],[{"type":"text","text":"Constant expression — folded to "},{"type":"text","text":"\"hi\"","marks":[{"type":"code"}]},{"type":"text","text":" by the compiler"}]],[[{"type":"text","text":"s1 + s2","marks":[{"type":"code"}]},{"type":"text","text":" (non-final variables)"}],[{"type":"text","text":"New heap object"}],[{"type":"text","text":"Built at runtime (via "},{"type":"text","text":"StringConcatFactory","marks":[{"type":"code"}]},{"type":"text","text":" since Java 9)"}]],[[{"type":"text","text":"b.intern()","marks":[{"type":"code"}]}],[{"type":"text","text":"Pool"}],[{"type":"text","text":"Returns the pooled copy (adds it if missing)"}]]]},"revision":1},{"id":"20705c59-8a62-7797-a57a-bca460d486cb","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" vs "},{"type":"text","text":"equals()","marks":[{"type":"code"}]}]},"revision":1},{"id":"726e4ee6-a2c2-7e8b-952a-74406529baef","type":"code","position":"a5","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        String a = \"java\";\n        String b = \"java\";\n        String c = new String(\"java\");\n        String d = \"ja\" + \"va\";          // compile-time constant → pooled\n        String part = \"ja\";\n        String e = part + \"va\";          // runtime concatenation → new object\n\n        System.out.println(a == b);          // same pooled object\n        System.out.println(a == c);          // different objects\n        System.out.println(a.equals(c));     // same characters\n        System.out.println(a == d);\n        System.out.println(a == e);\n        System.out.println(a == e.intern());\n    }\n}","filename":"Java"},"revision":1},{"id":"8caaf42b-0e73-7cf9-bed6-8212c5174757","type":"code","position":"a6","content":{"language":"text","code":"true\nfalse\ntrue\ntrue\nfalse\ntrue","filename":"Output"},"revision":1},{"id":"2b141872-c75d-7845-9564-d668130eaf04","type":"callout","position":"a7","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Always compare string "},{"type":"text","text":"contents","marks":[{"type":"italic"}]},{"type":"text","text":" with "},{"type":"text","text":"equals()","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"equalsIgnoreCase()","marks":[{"type":"code"}]},{"type":"text","text":"). "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" compares references and only looks right when both sides happen to be pooled."}]}]}},"revision":1},{"id":"c471977a-db64-7a92-8f04-01ec911cb4ee","type":"callout","position":"a8","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Write "},{"type":"text","text":"\"yes\".equals(input)","marks":[{"type":"code"}]},{"type":"text","text":" — the literal on the left can never throw "},{"type":"text","text":"NullPointerException","marks":[{"type":"code"}]},{"type":"text","text":" when "},{"type":"text","text":"input","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":". Or use "},{"type":"text","text":"Objects.equals(a, b)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"dc269c33-7df8-72b8-8a95-08dcad193721","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Immutability in action"}]},"revision":1},{"id":"16a6516f-4a14-7c1d-b786-2f64e0139bb4","type":"code","position":"aA","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        String s = \"hello\";\n        s.toUpperCase();                 // result discarded — s is unchanged\n        System.out.println(s);\n        s = s.toUpperCase();             // rebind the variable to the new object\n        System.out.println(s);\n\n        String t = s;\n        s = s + \"!\";                     // creates a new String; t still points at the old one\n        System.out.println(t + \" \" + s);\n    }\n}","filename":"Java"},"revision":1},{"id":"5fccf28f-07d8-70a2-80a9-ac5f436ecf03","type":"code","position":"aB","content":{"language":"text","code":"hello\nHELLO\nHELLO HELLO!","filename":"Output"},"revision":1},{"id":"f548a541-c284-7a34-a2e8-86fbb24d6bed","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Why is String immutable?"}]},"revision":1},{"id":"be4133a3-506b-771c-ab12-e577708512bc","type":"callout","position":"aD","content":{"variant":"note","title":"String pool","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sharing one object between many references is only safe if nobody can change it."}]}]}},"revision":1},{"id":"77600a9a-4e1f-7825-9e27-d736d68533a4","type":"callout","position":"aE","content":{"variant":"note","title":"Security","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Class names, file paths, URLs and DB credentials passed as strings can''t be altered after validation."}]}]}},"revision":1},{"id":"f284e55a-8af7-72a6-a628-a34764c93c3f","type":"callout","position":"aF","content":{"variant":"note","title":"Hash caching","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"hashCode()","marks":[{"type":"code"}]},{"type":"text","text":" is computed once and cached — perfect for "},{"type":"text","text":"HashMap","marks":[{"type":"code"}]},{"type":"text","text":" keys."}]}]}},"revision":1},{"id":"2d759fc2-7856-733c-b5ca-5103576a7983","type":"callout","position":"aG","content":{"variant":"note","title":"Thread safety","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Immutable objects can be shared across threads with no synchronization."}]}]}},"revision":1},{"id":"d98b8b21-a72e-73fc-acb6-e8a7ae280158","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Concatenation in loops"}]},"revision":1},{"id":"d9f342d1-a67a-7775-905c-e270870868f7","type":"text","position":"aI","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each "},{"type":"text","text":"+=","marks":[{"type":"code"}]},{"type":"text","text":" on a "},{"type":"text","text":"String","marks":[{"type":"code"}]},{"type":"text","text":" allocates a new object and copies all characters so far — O(n²) for a loop of n appends. Use "},{"type":"text","text":"StringBuilder","marks":[{"type":"code"}]},{"type":"text","text":" (next topics) or "},{"type":"text","text":"String.join","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"Collectors.joining","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"b71d7eea-ec7f-7f74-9d81-5b36a3a6aa67","type":"code","position":"aJ","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        String slow = \"\";\n        for (int i = 0; i < 5; i++) slow += i;      // 5 new String objects\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 0; i < 5; i++) sb.append(i);   // one growing buffer\n        System.out.println(slow + \" \" + sb);\n        System.out.println(String.join(\"-\", \"a\", \"b\", \"c\"));\n    }\n}","filename":"Java"},"revision":1},{"id":"15064e08-eaa1-79bd-a74e-5872bf02459d","type":"code","position":"aK","content":{"language":"text","code":"01234 01234\na-b-c","filename":"Output"},"revision":1},{"id":"11b63802-be46-7e1c-a8e8-e0203da24f56","type":"q