SELECT '9e3b41c5-88b3-7b4f-8e95-154a6ce498da', '547d1c0d-6b9a-7bb0-aca6-45069933a48a', 1, 'PUBLISHED', 'Switch Expressions & Pattern Matching', '[{"id":"0fe2083c-60d6-7981-bee3-24a0d580bfeb","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Modern "},{"type":"text","text":"switch","marks":[{"type":"code"}]},{"type":"text","text":" (Java 14) is an expression with arrow labels and no fall-through; Java 16–21 add pattern matching for "},{"type":"text","text":"instanceof","marks":[{"type":"code"}]},{"type":"text","text":", type patterns in "},{"type":"text","text":"switch","marks":[{"type":"code"}]},{"type":"text","text":", guards and record patterns."}]}]}},"revision":1},{"id":"98ae84c5-72b5-7aba-99b0-b7cc6e7812db","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Classic switch statement (fall-through)"}]},"revision":1},{"id":"302c37d5-cdb8-78a6-bd63-503c5b0917c2","type":"code","position":"a2","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        int day = 2;\n        switch (day) {\n            case 1:\n                System.out.println(\"Mon\");\n            case 2:\n                System.out.println(\"Tue\");      // matches here...\n            case 3:\n                System.out.println(\"Wed\");      // ...and falls through (no break!)\n                break;\n            default:\n                System.out.println(\"Other\");\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"2e44e0e6-956b-71da-877c-b2e62bf1f7a2","type":"code","position":"a3","content":{"language":"text","code":"Tue\nWed","filename":"Output"},"revision":1},{"id":"31a603a3-21c5-779d-8992-df4cd95053a8","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Old-style "},{"type":"text","text":"switch","marks":[{"type":"code"}]},{"type":"text","text":" works on "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":"-like types ("},{"type":"text","text":"byte","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"short","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" and their wrappers), "},{"type":"text","text":"String","marks":[{"type":"code"}]},{"type":"text","text":" (Java 7) and "},{"type":"text","text":"enum","marks":[{"type":"code"}]},{"type":"text","text":" — never on "},{"type":"text","text":"long","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"boolean","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"0012008c-e96b-7d83-a10b-5cfd3c6d76d6","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Switch expressions (Java 14)"}]},"revision":1},{"id":"1b8b519b-fb21-7e52-9e72-17f5bb5da2b7","type":"code","position":"a6","content":{"language":"java","code":"public class Main {\n    enum Day { MON, TUE, WED, THU, FRI, SAT, SUN }\n\n    static int letters(Day d) {\n        return switch (d) {                     // an expression — yields a value\n            case MON, FRI, SUN -> 6;            // several labels, no fall-through\n            case TUE -> 7;\n            case THU, SAT -> 8;\n            case WED -> {\n                int n = \"Wednesday\".length();\n                yield n;                        // yield returns from a block\n            }\n        };                                      // exhaustive over the enum: no default needed\n    }\n\n    public static void main(String[] args) {\n        System.out.println(letters(Day.MON) + \" \" + letters(Day.WED));\n        String cmd = \"stop\";\n        String msg = switch (cmd) {\n            case \"go\" -> \"moving\";\n            case \"stop\" -> \"halted\";\n            default -> \"unknown\";\n        };\n        System.out.println(msg);\n    }\n}","filename":"Java"},"revision":1},{"id":"278b73b1-5763-7161-917f-63ae17efbce9","type":"code","position":"a7","content":{"language":"text","code":"6 9\nhalted","filename":"Output"},"revision":1},{"id":"5bc19d79-f5c4-79b9-8469-0e5602d00f8d","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"case X:","marks":[{"type":"code"}]},{"type":"text","text":" (colon)"}],[{"type":"text","text":"case X ->","marks":[{"type":"code"}]},{"type":"text","text":" (arrow)"}]],[[{"type":"text","text":"Fall-through"}],[{"type":"text","text":"Yes, until "},{"type":"text","text":"break","marks":[{"type":"code"}]}],[{"type":"text","text":"Never"}]],[[{"type":"text","text":"As an expression"}],[{"type":"text","text":"Yes, with "},{"type":"text","text":"yield","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Multiple labels"}],[{"type":"text","text":"case 1: case 2:","marks":[{"type":"code"}]}],[{"type":"text","text":"case 1, 2 ->","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Exhaustiveness"}],[{"type":"text","text":"Only required for switch "},{"type":"text","text":"expressions","marks":[{"type":"italic"}]}],[{"type":"text","text":"Same"}]]]},"revision":1},{"id":"31cdbab2-9f83-7349-986b-23b88c9d50c4","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Pattern matching for "},{"type":"text","text":"instanceof","marks":[{"type":"code"}]},{"type":"text","text":" (Java 16)"}]},"revision":1},{"id":"c7a10763-20de-73c2-b4c0-7430ede812da","type":"code","position":"aA","content":{"language":"java","code":"public class Main {\n    static String describe(Object o) {\n        if (o instanceof String s && !s.isEmpty())   // test + cast + bind in one step\n            return \"String of length \" + s.length();\n        if (o instanceof Integer i)\n            return \"Integer doubled \" + (i * 2);\n        return \"something else\";\n    }\n\n    public static void main(String[] args) {\n        System.out.println(describe(\"hello\"));\n        System.out.println(describe(21));\n        System.out.println(describe(3.5));\n    }\n}","filename":"Java"},"revision":1},{"id":"36197a22-b08c-75b1-99ea-ea5906e66122","type":"code","position":"aB","content":{"language":"text","code":"String of length 5\nInteger doubled 42\nsomething else","filename":"Output"},"revision":1},{"id":"fa2eccbc-ea19-7af2-bdde-06e16387343b","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Type patterns, guards & null in switch (Java 21)"}]},"revision":1},{"id":"a1fc292a-987d-708f-bbee-263dd870ffcf","type":"code","position":"aD","content":{"language":"java","code":"public class Main {\n    static String classify(Object o) {\n        return switch (o) {\n            case null -> \"null!\";                          // otherwise NPE\n            case Integer i when i < 0 -> \"negative int\";   // guard with `when`\n            case Integer i -> \"int \" + i;\n            case String s when s.isBlank() -> \"blank string\";\n            case String s -> \"string ''\" + s + \"''\";\n            case int[] arr -> \"int array of \" + arr.length;\n            default -> \"other: \" + o.getClass().getSimpleName();\n        };\n    }\n\n    public static void main(String[] args) {\n        Object[] inputs = {-5, 7, \" \", \"hi\", new int[3], 2.5, null};\n        for (Object o : inputs) System.out.println(classify(o));\n    }\n}","filename":"Java"},"revision":1},{"id":"c7d7a7da-6428-764b-94c2-c1042fd0a594","type":"code","position":"aE","content":{"language":"text","code":"negative int\nint 7\nblank string\nstring ''hi''\nint array of 3\nother: Double\nnull!","filename":"Output"},"revision":1},{"id":"0ef154e0-84e6-74e0-96e7-ac31106e512f","type":"callout","position":"aF","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Order matters: a more general pattern before a specific one ("},{"type":"text","text":"case Integer i","marks":[{"type":"code"}]},{"type":"text","text":" before "},{"type":"text","text":"case Integer i when i < 0","marks":[{"type":"code"}]},{"type":"text","text":") is a "},{"type":"text","text":"dominance","marks":[{"type":"italic"}]},{"type":"text","text":" compile error. Without "},{"type":"text","text":"case null","marks":[{"type":"code"}]},{"type":"text","text":", a "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" selector throws "},{"type":"text","text":"NullPointerException","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"5b609b11-83ff-7b52-ad47-335d206f7922","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Record patterns & sealed hierarchies (Java 21)"}]},"revision":1},{"id":"89321833-1ed2-772a-bc24-216677670ed4","type":"code","position":"aH","content":{"language":"java","code":"public class Main {\n    sealed interface Shape permits Circle, Rect, Square {}\n    record Circle(double r) implements Shape {}\n    record Rect(double w, double h) implements Shape {}\n    record Square(double side) implements Shape {}\n\n    static double area(Shape s) {\n        return switch (s) {                        // exhaustive: compiler knows all subtypes\n            case Circle(double r) -> Math.PI * r * r;\n            case Rect(double w, double h) -> w * h;     // deconstruct the record\n            case Square(var side) -> side * side;\n        };\n    }\n\n    record Point(int x, int y) {}\n    record Line(Point from, Point to) {}\n\n    public static void main(String[] args) {\n        System.out.printf(\"%.2f %.1f %.1f%n\", area(new Circle(1)), area(new Rect(2, 3)), area(new Square(4)));\n        Object o = new Line(new Point(0, 0), new Point(3, 4));\n        if (o instanceof Line(Point(var x1, var y1), Point(var x2, var y2)))   // nested patterns\n            System.out.println(\"dx=\" + (x2 - x1) + \" dy=\" + (y2 - y1));\n    }\n}","filename":"Java"},"revision":1},{"id":"e9d9ef25-0baf-731c-a048-bfc99fadb8ff","type":"code","position":"aI","content":{"language":"text","code":"3.14 6.0 16.0\ndx=3 dy=4","filename":"Output"},"revision":1},{"id":"d61c27ab-97b4-7ccb-9cd1-3baa8fae802e","type":"callout","position":"aJ","content":{"variant":"note","title":"Why it matters","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sealed interface + records + pattern "},{"type":"text","text":"switch","marks":[{"type":"code"}]},{"type":"text","text":" = algebraic data types in Java. Add a new subtype and every non-exhaustive "},{"type":"text","text":"switch","marks":[{"type":"code"}]},{"type":"text","text":" fails to compile — the compiler finds the code you forgot."}]}]}},"revision":1},{"id":"5706265d-06b8-7252-990c-fd7ab48b0708","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does yield do in a switch expression?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It returns a value from a block-bodied "},{"type":"text","text":"case","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"case X -> { …; yield v; }","marks":[{"type":"code"}]},{"type":"text","text":") or from a colon-style case in a switch "},{"type":"text","text":"expression","marks":[{"type":"italic"}]},{"type":"text","text":". "},{"type":"text","text":"return","marks":[{"type":"code"}]},{"type":"text","text":" would try to leave the enclosing method instead."}]}]}},"revision":1},{"id":"7530c0c4-6e18-78aa-8034-87fdffcc6ea2","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is a default needed in a switch expression?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The switch expression must be "},{"type":"text","text":"exhaustive","marks":[{"type":"bold"}]},{"type":"text","text":". For an "},{"type":"text","text":"enum","marks":[{"type":"code"}]},{"type":"text","text":" or a "},{"type":"text","text":"sealed","marks":[{"type":"code"}]},{"type":"text","text":" type covering every constant/subtype, no "},{"type":"text","text":"default","marks":[{"type":"code"}]},{"type":"text","text":" is needed; for "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"String","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Object","marks":[{"type":"code"}]},{"type":"text","text":" you need "},{"type":"text","text":"default","marks":[{"type":"code"}]},{"type":"text","text":" (or an unconditional pattern)."}]}]}},"revision":1},{"id":"45cedfab-89ad-78d5-8980-0084f90df444","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What happens if the selector of a switch is null?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Traditionally a "},{"type":"text","text":"NullPointerException","marks":[{"type":"code"}]},{"type":"text","text":". From Java 21 you can add "},{"type":"text","text":"case null","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"case null, default ->","marks":[{"type":"code"}]},{"type":"text","text":") to handle it explicitly."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
