SELECT '4b82b1c3-df97-75d2-845a-e0d7a5c60bf5', '0a0a0eb5-faf0-7a52-b6d7-4a597eb69c96', 1, 'PUBLISHED', 'synchronized, volatile & the Java Memory Model', '[{"id":"b42959f3-2f1b-7bff-ad43-a99bfcb8a68b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Shared mutable state + more than one thread = a race. "},{"type":"text","text":"synchronized","marks":[{"type":"code"}]},{"type":"text","text":" gives "},{"type":"text","text":"mutual exclusion and visibility","marks":[{"type":"italic"}]},{"type":"text","text":"; "},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":" gives "},{"type":"text","text":"visibility and ordering only","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"e80df8c2-f273-713f-a790-e43fd850d52b","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Race condition","marks":[{"type":"bold"}]},{"type":"text","text":" — the result depends on the timing of threads. The classic case is "},{"type":"text","text":"count++","marks":[{"type":"code"}]},{"type":"text","text":", which is really three steps — "},{"type":"text","text":"read","marks":[{"type":"italic"}]},{"type":"text","text":", "},{"type":"text","text":"add 1","marks":[{"type":"italic"}]},{"type":"text","text":", "},{"type":"text","text":"write","marks":[{"type":"italic"}]},{"type":"text","text":" — so two threads can read the same old value and one increment is lost."}]}]}},"revision":1},{"id":"e0ab4a96-e512-72c3-b28c-1cf9ad97f875","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"The lost-update problem"}]},"revision":1},{"id":"efa7a7a9-9345-79fd-bffd-a869215c5984","type":"code","position":"a3","content":{"language":"java","code":"public class Main {\n    static int count = 0;\n\n    public static void main(String[] args) throws InterruptedException {\n        Runnable inc = () -> { for (int i = 0; i < 100_000; i++) count++; };\n        Thread a = new Thread(inc), b = new Thread(inc);\n        a.start(); b.start();\n        a.join();  b.join();\n        System.out.println(\"unsafe count = \" + count + \" (expected 200000)\");\n    }\n}","filename":"Java"},"revision":1},{"id":"05f88bce-a7bf-7d62-9ba0-34cf6b5e8f95","type":"code","position":"a4","content":{"language":"text","code":"unsafe count = 104072 (expected 200000)","filename":"Output (a typical run — different every time)"},"revision":1},{"id":"a27a5206-768a-7fe7-ab97-7aa0da1b2676","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"The fix: "},{"type":"text","text":"synchronized","marks":[{"type":"code"}]}]},"revision":1},{"id":"35c6b4d1-ab33-7a8b-812f-744bb99210ff","type":"code","position":"a6","content":{"language":"java","code":"public class Main {\n    private int count = 0;\n\n    synchronized void increment() { count++; }     // lock = this\n    synchronized int get() { return count; }\n\n    public static void main(String[] args) throws InterruptedException {\n        Main counter = new Main();\n        Runnable inc = () -> { for (int i = 0; i < 100_000; i++) counter.increment(); };\n        Thread a = new Thread(inc), b = new Thread(inc);\n        a.start(); b.start();\n        a.join();  b.join();\n        System.out.println(\"safe count = \" + counter.get());\n        System.out.println(\"correct? \" + (counter.get() == 200_000));\n    }\n}","filename":"Java"},"revision":1},{"id":"e5a02e69-a937-7198-8cf1-5fa06167beea","type":"code","position":"a7","content":{"language":"text","code":"safe count = 200000\ncorrect? true","filename":"Output"},"revision":1},{"id":"c2e1aa98-dd4f-7381-bffb-6bcd2ec3b3dc","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every object has an "},{"type":"text","text":"intrinsic lock","marks":[{"type":"bold"}]},{"type":"text","text":" (monitor). Only one thread at a time can hold it; others trying to enter a "},{"type":"text","text":"synchronized","marks":[{"type":"code"}]},{"type":"text","text":" region on the same object go "},{"type":"text","text":"BLOCKED","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"0751c5bc-e618-7d2c-a9ed-74949c281784","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Form"}],[{"type":"text","text":"Lock used"}],[{"type":"text","text":"Use when"}]],[[{"type":"text","text":"synchronized void m()","marks":[{"type":"code"}]}],[{"type":"text","text":"this","marks":[{"type":"code"}]}],[{"type":"text","text":"The whole method touches shared state"}]],[[{"type":"text","text":"static synchronized void m()","marks":[{"type":"code"}]}],[{"type":"text","text":"the "},{"type":"text","text":"Class","marks":[{"type":"code"}]},{"type":"text","text":" object ("},{"type":"text","text":"Main.class","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Guarding static fields"}]],[[{"type":"text","text":"synchronized (lock) { ... }","marks":[{"type":"code"}]}],[{"type":"text","text":"any object you choose"}],[{"type":"text","text":"Only a few lines need the lock — keep critical sections short"}]]]},"revision":1},{"id":"cf06c0f6-7840-7709-93d9-9a390e93d97a","type":"code","position":"aA","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\n\nclass Inventory {\n    private final Object lock = new Object();      // private lock: outsiders can''t grab it\n    private final List<String> items = new ArrayList<>();\n\n    void add(String item) {\n        String cleaned = item.trim().toLowerCase(); // no lock needed for local work\n        synchronized (lock) {                       // lock only the shared mutation\n            items.add(cleaned);\n        }\n    }\n\n    int size() {\n        synchronized (lock) { return items.size(); }\n    }\n}","filename":"Java"},"revision":1},{"id":"38a93cf3-ef02-7077-b584-2414e2d6dc24","type":"callout","position":"aB","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An instance lock and a static lock are "},{"type":"text","text":"different","marks":[{"type":"italic"}]},{"type":"text","text":" locks: a "},{"type":"text","text":"synchronized","marks":[{"type":"code"}]},{"type":"text","text":" instance method and a "},{"type":"text","text":"static synchronized","marks":[{"type":"code"}]},{"type":"text","text":" method can run at the same time. Also, locking on different objects protects nothing — every access to the shared field must use the "},{"type":"text","text":"same","marks":[{"type":"italic"}]},{"type":"text","text":" lock."}]}]}},"revision":1},{"id":"438676f4-5270-76f3-9690-8705a2baca66","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Reentrancy"}]},"revision":1},{"id":"891e019c-6776-7967-9e51-012054af9899","type":"code","position":"aD","content":{"language":"java","code":"public class Main {\n    synchronized void outer() {\n        System.out.println(\"outer holds lock: \" + Thread.holdsLock(this));\n        inner();              // same thread, same lock — no self-deadlock\n    }\n\n    synchronized void inner() {\n        System.out.println(\"inner re-entered the same lock\");\n    }\n\n    public static void main(String[] args) {\n        new Main().outer();\n    }\n}","filename":"Java"},"revision":1},{"id":"46ab9fcd-d913-7fe2-ad37-f4c2489eb5d3","type":"code","position":"aE","content":{"language":"text","code":"outer holds lock: true\ninner re-entered the same lock","filename":"Output"},"revision":1},{"id":"28411682-5c2c-7648-b209-b7e1c51a7c6e","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Intrinsic locks are "},{"type":"text","text":"reentrant","marks":[{"type":"bold"}]},{"type":"text","text":": the JVM keeps a hold count per owning thread, so a synchronized method can call another synchronized method on the same object."}]}]}},"revision":1},{"id":"3dae237d-a9e0-7c84-b924-845ead56d607","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Visibility and the Java Memory Model"}]},"revision":1},{"id":"7fa7596d-f630-7cbd-b162-e95b2504170d","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Without synchronisation, a thread may "},{"type":"text","text":"never see","marks":[{"type":"italic"}]},{"type":"text","text":" another thread''s write: values can sit in CPU caches or registers, and the compiler/CPU may reorder instructions. The "},{"type":"text","text":"Java Memory Model (JMM)","marks":[{"type":"bold"}]},{"type":"text","text":" defines when a write is guaranteed visible through "},{"type":"text","text":"happens-before","marks":[{"type":"italic"}]},{"type":"text","text":" rules."}]}]}},"revision":1},{"id":"8e6f19db-0d37-79de-a6f9-da67cf9f2b0f","type":"table","position":"aI","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Happens-before rule"}],[{"type":"text","text":"Guarantee"}]],[[{"type":"text","text":"Program order"}],[{"type":"text","text":"Each action in a thread happens-before later actions in the same thread"}]],[[{"type":"text","text":"Monitor lock"}],[{"type":"text","text":"Unlocking a monitor happens-before every later lock of the "},{"type":"text","text":"same","marks":[{"type":"italic"}]},{"type":"text","text":" monitor"}]],[[{"type":"text","text":"volatile","marks":[{"type":"code"}]}],[{"type":"text","text":"A write to a volatile field happens-before every later read of it"}]],[[{"type":"text","text":"Thread start"}],[{"type":"text","text":"t.start()","marks":[{"type":"code"}]},{"type":"text","text":" happens-before anything "},{"type":"text","text":"t","marks":[{"type":"code"}]},{"type":"text","text":" does"}]],[[{"type":"text","text":"Thread join"}],[{"type":"text","text":"Everything "},{"type":"text","text":"t","marks":[{"type":"code"}]},{"type":"text","text":" does happens-before "},{"type":"text","text":"t.join()","marks":[{"type":"code"}]},{"type":"text","text":" returns"}]],[[{"type":"text","text":"Transitivity"}],[{"type":"text","text":"A hb B and B hb C ⇒ A hb C"}]]]},"revision":1},{"id":"03dc1b24-a7e0-727a-9e20-e8b4cff90a46","type":"heading","position":"aJ","content":{"level":1,"content":[{"type":"text","text":"volatile","marks":[{"type":"code"}]}]},"revision":1},{"id":"6dc43188-0e3d-7584-9177-88c72b035023","type":"code","position":"aK","content":{"language":"java","code":"public class Main {\n    static volatile boolean running = true;     // try removing volatile: the loop may never end\n\n    public static void main(String[] args) throws InterruptedException {\n        Thread worker = new Thread(() -> {\n            long spins = 0;\n            while (running) spins++;\n            System.out.println(\"worker saw running=false and exited\");\n        });\n        worker.start();\n        Thread.sleep(50);\n        running = false;                        // visible to the worker immediately\n        worker.join();\n        System.out.println(\"done\");\n    }\n}","filename":"Java"},"revision":1},{"id":"06a0ba42-eda6-7b38-9e56-49f666124525","type":"code","position":"aL","content":{"language":"text","code":"worker saw running=false and exited\ndone","filename":"Output"},"revision":1},{"id":"e0f8ad69-84ee-725f-a441-2b42e2a42adb","type":"table","position":"aM","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"volatile","marks":[{"type":"code"}]}],[{"type":"text","text":"synchronized","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Visibility"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Prevents reordering around it"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Atomic compound actions ("},{"type":"text","text":"x++","marks":[{"type":"code"}]},{"type":"text","text":", check-then-act)"}],[{"type":"text","text":"No","marks":[{"type":"bold"}]}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Blocks other threads"}],[{"type":"text","text":"Never"}],[{"type":"text","text":"Yes (mutual exclusion)"}]],[[{"type":"text","text":"Typical use"}],[{"type":"text","text":"Status flags, safe publication, DCL"}],[{"type":"text","text":"Invariants spanning several fields/steps"}]]]},"revision":1},{"id":"b6b0e4f8-1042-7688-b486-7a6921e84f2a","type":"callout","position":"aN","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"volatile int count; count++","marks":[{"type":"code"}]},{"type":"text","text":" is still a race — "},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":" makes each read and write visible but does not make read-modify-write atomic. Use "},{"type":"text","text":"synchronized","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"AtomicInteger","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"LongAdder","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"49227869-9dc7-7280-9380-8a878c771c67","type":"heading","position":"aO","content":{"level":1,"content":[{"type":"text","text":"Double-checked locking (lazy singleton)"}]},"revision":1},{"id":"e65fde09-ce15-7106-95e4-fe05238005bf","type":"code","position":"aP","content":{"language":"java","code":"final class Config {\n    private static volatile Config instance;    // volatile is essential here\n\n    private Config() { }\n\n    static Config getInstance() {\n        Config local = instance;                // 1st check without locking (fast path)\n        if (local == null) {\n            synchronized (Config.class) {\n                local = instance;               // 2nd check under the lock\n                if (local == null) {\n                    instance = local = new Config();\n                }\n            }\n        }\n        return local;\n    }\n}","filename":"Java"},"revision":1},{"id":"bf8037aa-a303-7dda-bd17-5c37c60009b3","type":"text","position":"aQ","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Without "},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":", the write of the reference could be reordered before the constructor finishes, so another thread might see a "},{"type":"text","text":"partially constructed","marks":[{"type":"italic"}]},{"type":"text","text":" object. Simpler alternatives: an "},{"type":"text","text":"enum","marks":[{"type":"code"}]},{"type":"text","text":" singleton or the holder idiom ("},{"type":"text","text":"private static class Holder { static final Config I = new Config(); }","marks":[{"type":"code"}]},{"type":"text","text":") — class initialisation is already thread-safe and lazy."}]}]}},"revision":1},{"id":"f0c3125e-3960-7255-b8fa-c71e4609183e","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is count++ atomic in Java?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No — it compiles to read, add, write ("},{"type":"text","text":"getfield","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"iadd","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"putfield","marks":[{"type":"code"}]},{"type":"text","text":"). Two threads can interleave and lose updates, even if "},{"type":"text","text":"count","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":". Use "},{"type":"text","text":"synchronized","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"AtomicInteger.incrementAndGet()","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"LongAdder","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"6ff2ca0f-3417-723c-8110-6ce01ef28731","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does volatile guarantee?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Visibility (a read sees the latest write by any thread) and ordering (no reordering across the volatile access; it creates a happens-before edge). It does "},{"type":"text","text":"not","marks":[{"type":"italic"}]},{"type":"text","text":" give atomicity or mutual exclusion."}]}]}},"revision":1},{"id":"f938a90c-5f68-7814-a6f9-e05c0494799e","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Synchronized method vs synchronized block?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A synchronized method locks "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" (or the "},{"type":"text","text":"Class","marks":[{"type":"code"}]},{"type":"text","text":" for static methods) for the whole method. A block lets you choose the lock object — often a private final field — and keep the critical section as small as possible, which improves throughput and prevents outside code from locking on your object."}]}]}},"revision":1},{"id":"3cd58880-d70a-77b0-9920-ee827ea61909","type":"question","position":"aU","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why must the double-checked-locking field be volatile?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"instance = new Config()","marks":[{"type":"code"}]},{"type":"text","text":" is allocate → construct → assign, and the JIT/CPU may publish the reference before construction completes. "},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":" forbids that reordering, so a thread that sees a non-null reference also sees a fully initialised object."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
