SELECT 'eb8d9d7f-af92-7536-aa13-52c7c9ef7b1a', '78b91f30-237f-79b8-93de-15a3b1f96082', 1, 'PUBLISHED', 'Threads & Runnable', '[{"id":"c1ffef87-ac3a-77ad-af25-9cf8cdb1322c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A thread is an independent path of execution inside one JVM process — create it with a "},{"type":"text","text":"Runnable","marks":[{"type":"code"}]},{"type":"text","text":", start it with "},{"type":"text","text":"start()","marks":[{"type":"code"}]},{"type":"text","text":", wait for it with "},{"type":"text","text":"join()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"fe4095e7-921f-7bc3-bb71-fa03ade89568","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Thread","marks":[{"type":"bold"}]},{"type":"text","text":" — the smallest unit the OS schedules. All threads of a process share its heap (objects, static fields) but each has its "},{"type":"text","text":"own stack","marks":[{"type":"italic"}]},{"type":"text","text":" (local variables, call frames) and program counter."}]}]}},"revision":1},{"id":"a0872d7f-4af8-79eb-a8a2-3caf26f82b25","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Process vs thread"}]},"revision":1},{"id":"e054a675-ad51-7345-bc1f-5e2aabecfa56","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Process"}],[{"type":"text","text":"Thread"}]],[[{"type":"text","text":"Memory"}],[{"type":"text","text":"Own address space"}],[{"type":"text","text":"Shares the process heap; own stack"}]],[[{"type":"text","text":"Creation cost"}],[{"type":"text","text":"Heavy (fork, new address space)"}],[{"type":"text","text":"Lighter (~1 MB stack reserved for a platform thread)"}]],[[{"type":"text","text":"Communication"}],[{"type":"text","text":"IPC: pipes, sockets, files"}],[{"type":"text","text":"Shared objects — fast, but needs synchronisation"}]],[[{"type":"text","text":"Crash impact"}],[{"type":"text","text":"Isolated"}],[{"type":"text","text":"An uncaught error kills only that thread, but corrupted shared state affects all"}]],[[{"type":"text","text":"In Java"}],[{"type":"text","text":"ProcessBuilder","marks":[{"type":"code"}]},{"type":"text","text":", one JVM = one process"}],[{"type":"text","text":"Thread","marks":[{"type":"code"}]},{"type":"text","text":", executors, virtual threads"}]]]},"revision":1},{"id":"3d93646d-84db-7277-a517-9c71ad5b255f","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Creating and joining threads"}]},"revision":1},{"id":"aa836e57-0a0d-7829-8f08-2f1f1e7fac54","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Give each thread its own slice of the work, "},{"type":"text","text":"start()","marks":[{"type":"code"}]},{"type":"text","text":" them, then "},{"type":"text","text":"join()","marks":[{"type":"code"}]},{"type":"text","text":" before reading the results — "},{"type":"text","text":"join()","marks":[{"type":"code"}]},{"type":"text","text":" both waits "},{"type":"text","text":"and","marks":[{"type":"italic"}]},{"type":"text","text":" guarantees you see everything the thread wrote."}]}]}},"revision":1},{"id":"118ce9f7-dae8-7331-8d61-d6ff7a18eb4f","type":"code","position":"a6","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) throws InterruptedException {\n        long[] sums = new long[2];\n        Thread t1 = new Thread(() -> sums[0] = sum(1, 50), \"worker-1\");\n        Thread t2 = new Thread(() -> sums[1] = sum(51, 100), \"worker-2\");\n        t1.start();                 // both now run concurrently with main\n        t2.start();\n        t1.join();                  // wait for each to finish\n        t2.join();\n        System.out.println(t1.getName() + \" -> \" + sums[0]);\n        System.out.println(t2.getName() + \" -> \" + sums[1]);\n        System.out.println(\"total = \" + (sums[0] + sums[1]));\n    }\n\n    static long sum(int from, int to) {\n        long s = 0;\n        for (int i = from; i <= to; i++) s += i;\n        return s;\n    }\n}","filename":"Java"},"revision":1},{"id":"611f7807-557c-78df-846b-52e8913c2e0c","type":"code","position":"a7","content":{"language":"text","code":"worker-1 -> 1275\nworker-2 -> 3775\ntotal = 5050","filename":"Output"},"revision":1},{"id":"353590b5-6619-7a47-a4f7-5bd77eb0c8a7","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Three ways to define the task"}]},"revision":1},{"id":"c242c5da-b789-7947-b807-916e1382a237","type":"code","position":"a9","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) throws InterruptedException {\n        Thread a = new Greeter();                       // 1. subclass Thread\n        a.setName(\"greeter\");\n        a.start();\n        a.join();\n\n        Runnable task = new Runnable() {                // 2. implement Runnable\n            @Override public void run() {\n                System.out.println(\"2. Runnable on \" + Thread.currentThread().getName());\n            }\n        };\n        Thread b = new Thread(task, \"runner\");\n        b.start();\n        b.join();\n\n        Thread c = new Thread(                          // 3. lambda (Runnable is functional)\n            () -> System.out.println(\"3. lambda on \" + Thread.currentThread().getName()), \"lambda\");\n        c.start();\n        c.join();\n    }\n}\n\nclass Greeter extends Thread {\n    @Override public void run() {\n        System.out.println(\"1. Thread subclass on \" + getName());\n    }\n}","filename":"Java"},"revision":1},{"id":"507f2b72-d849-7150-9046-79316074d10e","type":"code","position":"aA","content":{"language":"text","code":"1. Thread subclass on greeter\n2. Runnable on runner\n3. lambda on lambda","filename":"Output"},"revision":1},{"id":"a1699a1e-03cc-7d33-8d7c-4ac016f468ed","type":"callout","position":"aB","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Implement "},{"type":"text","text":"Runnable","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"Callable","marks":[{"type":"code"}]},{"type":"text","text":") and hand it to a thread or executor — the task stays independent of "},{"type":"text","text":"how","marks":[{"type":"italic"}]},{"type":"text","text":" it is run, and your class can still extend something else."}]}]}},"revision":1},{"id":"f928ac18-e227-7722-badc-2662a3e0318c","type":"callout","position":"aC","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Extending "},{"type":"text","text":"Thread","marks":[{"type":"code"}]},{"type":"text","text":" just to override "},{"type":"text","text":"run()","marks":[{"type":"code"}]},{"type":"text","text":" — it burns your single superclass slot and couples the work to one thread."}]}]}},"revision":1},{"id":"2c53007f-5346-72cf-9f54-e414c6672c5f","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"start()","marks":[{"type":"code"}]},{"type":"text","text":" vs "},{"type":"text","text":"run()","marks":[{"type":"code"}]}]},"revision":1},{"id":"c375aba5-8ce3-778e-8c66-1a7c9181fa51","type":"code","position":"aE","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) throws InterruptedException {\n        Runnable r = () -> System.out.println(\"running in \" + Thread.currentThread().getName());\n        Thread t = new Thread(r, \"worker\");\n        t.run();     // an ordinary method call — runs on main, no new thread\n        t.start();   // creates the new call stack and calls run() there\n        t.join();\n        try {\n            t.start();   // a Thread object can be started only once\n        } catch (IllegalThreadStateException e) {\n            System.out.println(\"second start(): \" + e.getClass().getSimpleName());\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"8cba0ec9-9b9a-753e-b66f-d6b5ed694a1c","type":"code","position":"aF","content":{"language":"text","code":"running in main\nrunning in worker\nsecond start(): IllegalThreadStateException","filename":"Output"},"revision":1},{"id":"3916f3e6-e8d0-7918-8a9c-8cd0a94c3f04","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Thread lifecycle"}]},"revision":1},{"id":"9f4b02af-bc39-7cf7-8033-30fca2abbcc5","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"NEW","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"RUNNABLE","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"BLOCKED","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"WAITING","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"TIMED_WAITING","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"RUNNABLE","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"TERMINATED","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"134400a5-0157-723d-8a8a-4ea09a2912ae","type":"table","position":"aI","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Thread.State","marks":[{"type":"code"}]}],[{"type":"text","text":"Meaning"}],[{"type":"text","text":"Entered by"}]],[[{"type":"text","text":"NEW","marks":[{"type":"code"}]}],[{"type":"text","text":"Created, not yet started"}],[{"type":"text","text":"new Thread(...)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"RUNNABLE","marks":[{"type":"code"}]}],[{"type":"text","text":"Running "},{"type":"text","text":"or","marks":[{"type":"italic"}]},{"type":"text","text":" ready to run (the JVM doesn''t distinguish)"}],[{"type":"text","text":"start()","marks":[{"type":"code"}]},{"type":"text","text":"; also while doing blocking I/O"}]],[[{"type":"text","text":"BLOCKED","marks":[{"type":"code"}]}],[{"type":"text","text":"Waiting to acquire a monitor lock"}],[{"type":"text","text":"entering a "},{"type":"text","text":"synchronized","marks":[{"type":"code"}]},{"type":"text","text":" block held by another thread"}]],[[{"type":"text","text":"WAITING","marks":[{"type":"code"}]}],[{"type":"text","text":"Waiting indefinitely for another thread"}],[{"type":"text","text":"wait()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"join()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"LockSupport.park()","marks":[{"type":"code"}]}]],[[{"type":"text","text":"TIMED_WAITING","marks":[{"type":"code"}]}],[{"type":"text","text":"Waiting with a timeout"}],[{"type":"text","text":"sleep(ms)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"wait(ms)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"join(ms)","marks":[{"type":"code"}]}]],[[{"type":"text","text":"TERMINATED","marks":[{"type":"code"}]}],[{"type":"text","text":"run()","marks":[{"type":"code"}]},{"type":"text","text":" returned or threw"}],[{"type":"text","text":"end of "},{"type":"text","text":"run()","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"1ba77b64-f3cd-7bc0-a7d3-aaddbd2c33c5","type":"code","position":"aJ","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) throws InterruptedException {\n        Object lock = new Object();\n        Thread t = new Thread(() -> {\n            synchronized (lock) { System.out.println(\"worker got the lock\"); }\n        });\n        System.out.println(\"before start: \" + t.getState());\n        synchronized (lock) {                      // main holds the lock...\n            t.start();\n            while (t.getState() != Thread.State.BLOCKED) Thread.onSpinWait();\n            System.out.println(\"waiting for lock: \" + t.getState());\n        }                                          // ...and releases it here\n        t.join();\n        System.out.println(\"after join: \" + t.getState());\n    }\n}","filename":"Java"},"revision":1},{"id":"069ea07e-a8f6-78e0-aa9d-00b2a32d9863","type":"code","position":"aK","content":{"language":"text","code":"before start: NEW\nwaiting for lock: BLOCKED\nworker got the lock\nafter join: TERMINATED","filename":"Output"},"revision":1},{"id":"6afd68d1-6052-7987-84b2-258db194101a","type":"heading","position":"aL","content":{"level":1,"content":[{"type":"text","text":"sleep","marks":[{"type":"code"}]},{"type":"text","text":", interrupt and daemon threads"}]},"revision":1},{"id":"ef11ceff-ef7e-7582-92ac-798afcd880ba","type":"text","position":"aM","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Java has no safe way to "},{"type":"text","text":"kill","marks":[{"type":"italic"}]},{"type":"text","text":" a thread ("},{"type":"text","text":"stop()","marks":[{"type":"code"}]},{"type":"text","text":" is deprecated and removed in practice). Instead you "},{"type":"text","text":"interrupt","marks":[{"type":"bold"}]},{"type":"text","text":" it — a polite request the thread must check for. Blocking calls ("},{"type":"text","text":"sleep","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"wait","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"join","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"BlockingQueue.take","marks":[{"type":"code"}]},{"type":"text","text":") respond by throwing "},{"type":"text","text":"InterruptedException","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"clearing","marks":[{"type":"italic"}]},{"type":"text","text":" the flag."}]}]}},"revision":1},{"id":"adbc4565-dce9-7792-b578-d366c157b896","type":"code","position":"aN","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) throws InterruptedException {\n        Thread sleeper = new Thread(() -> {\n            try {\n                Thread.sleep(10_000);\n                System.out.println(\"woke normally\");\n            } catch (InterruptedException e) {\n                System.out.println(\"sleep interrupted, flag now \" + Thread.currentThread().isInterrupted());\n            }\n        });\n        sleeper.start();\n        sleeper.interrupt();\n        sleeper.join();\n\n        Thread spinner = new Thread(() -> {\n            long n = 0;\n            while (!Thread.currentThread().isInterrupted()) n++;   // cooperative check\n            System.out.println(\"spinner saw the interrupt and stopped\");\n        });\n        spinner.start();\n        spinner.interrupt();\n        spinner.join();\n\n        Thread daemon = new Thread(() -> {\n            while (true) {\n                try { Thread.sleep(1000); } catch (InterruptedException e) { return; }\n            }\n        });\n        daemon.setDaemon(true);          // must be set before start()\n        daemon.start();\n        System.out.println(\"daemon? \" + daemon.isDaemon() + \" - JVM exits without waiting for it\");\n    }\n}","filename":"Java"},"revision":1},{"id":"1648aff1-07c7-71e4-bf93-729a81d07263","type":"code","position":"aO","content":{"language":"text","code":"sleep interrupted, flag now false\nspinner saw the interrupt and stopped\ndaemon? true - JVM exits without waiting for it","filename":"Output"},"revision":1},{"id":"082c2735-ee5f-732f-b9eb-7938c85af68e","type":"table","position":"aP","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method"}],[{"type":"text","text":"What it does"}]],[[{"type":"text","text":"Thread.sleep(ms)","marks":[{"type":"code"}]}],[{"type":"text","text":"Pause the "},{"type":"text","text":"current","marks":[{"type":"italic"}]},{"type":"text","text":" thread; keeps any locks it holds"}]],[[{"type":"text","text":"t.join()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"t.join(ms)","marks":[{"type":"code"}]}],[{"type":"text","text":"Wait until "},{"type":"text","text":"t","marks":[{"type":"code"}]},{"type":"text","text":" terminates (happens-before: you see all its writes)"}]],[[{"type":"text","text":"t.interrupt()","marks":[{"type":"code"}]}],[{"type":"text","text":"Set "},{"type":"text","text":"t","marks":[{"type":"code"}]},{"type":"text","text":"''s interrupt flag; wakes it from "},{"type":"text","text":"sleep","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"wait","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"join","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Thread.interrupted()","marks":[{"type":"code"}]}],[{"type":"text","text":"Static","marks":[{"type":"italic"}]},{"type":"text","text":": test "},{"type":"text","text":"and clear","marks":[{"type":"bold"}]},{"type":"text","text":" the current thread''s flag"}]],[[{"type":"text","text":"t.isInterrupted()","marks":[{"type":"code"}]}],[{"type":"text","text":"Test the flag without clearing it"}]],[[{"type":"text","text":"t.setDaemon(true)","marks":[{"type":"code"}]}],[{"type":"text","text":"Background thread — the JVM exits when only daemons remain"}]],[[{"type":"text","text":"Thread.yield()","marks":[{"type":"code"}]}],[{"type":"text","text":"Hint to the scheduler; practically never needed"}]]]},"revision":1},{"id":"7193b2d2-70f4-71f8-8356-acb91e03e486","type":"callout","position":"aQ","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never swallow "},{"type":"text","text":"InterruptedException","marks":[{"type":"code"}]},{"type":"text","text":" with an empty "},{"type":"text","text":"catch","marks":[{"type":"code"}]},{"type":"text","text":". Either propagate it, or restore the flag with "},{"type":"text","text":"Thread.currentThread().interrupt()","marks":[{"type":"code"}]},{"type":"text","text":" so code higher up can see the request to stop."}]}]}},"revision":1},{"id":"dfb8c667-3eaa-7d99-9129-e722d89a1fc7","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between start() and run()?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"start()","marks":[{"type":"code"}]},{"type":"text","text":" asks the JVM to create a new thread, which then calls "},{"type":"text","text":"run()","marks":[{"type":"code"}]},{"type":"text","text":" on its own stack. Calling "},{"type":"text","text":"run()","marks":[{"type":"code"}]},{"type":"text","text":" directly is just a normal method call on the "},{"type":"text","text":"current","marks":[{"type":"italic"}]},{"type":"text","text":" thread — no concurrency. "},{"type":"text","text":"start()","marks":[{"type":"code"}]},{"type":"text","text":" may be called only once per "},{"type":"text","text":"Thread","marks":[{"type":"code"}]},{"type":"text","text":" object ("},{"type":"text","text":"IllegalThreadStateException","marks":[{"type":"code"}]},{"type":"text","text":" otherwise)."}]}]}},"revision":1},{"id":"e155ccb3-01ae-7258-ad5a-d23f394d77d3","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Runnable vs Callable?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Runnable.run()","marks":[{"type":"code"}]},{"type":"text","text":" returns "},{"type":"text","text":"void","marks":[{"type":"code"}]},{"type":"text","text":" and cannot throw checked exceptions. "},{"type":"text","text":"Callable<V>.call()","marks":[{"type":"code"}]},{"type":"text","text":" returns a value and may throw "},{"type":"text","text":"Exception","marks":[{"type":"code"}]},{"type":"text","text":". Threads accept only "},{"type":"text","text":"Runnable","marks":[{"type":"code"}]},{"type":"text","text":"; executors accept both and return a "},{"type":"text","text":"Future","marks":[{"type":"code"}]},{"type":"text","text":" for either."}]}]}},"revision":1},{"id":"1e79c452-532a-7aa5-bd51-a8120e3508ef","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you stop a thread?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cooperatively: call "},{"type":"text","text":"interrupt()","marks":[{"type":"code"}]},{"type":"text","text":" (or set a "},{"type":"text","text":"volatile","marks":[{"type":"code"}]},{"type":"text","text":" flag) and have the thread check "},{"type":"text","text":"isInterrupted()","marks":[{"type":"code"}]},{"type":"text","text":" / catch "},{"type":"text","text":"InterruptedException","marks":[{"type":"code"}]},{"type":"text","text":" and return. "},{"type":"text","text":"Thread.stop()","marks":[{"type":"code"}]},{"type":"text","text":" is deprecated because it releases locks mid-update and leaves objects corrupted."}]}]}},"revision":1},{"id":"38403c53-56c3-7e25-afcd-fa60e3263617","type":"question","position":"aU","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does sleep() release the lock?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. "},{"type":"text","text":"sleep()","marks":[{"type":"code"}]},{"type":"text","text":" keeps every monitor the thread holds. "},{"type":"text","text":"wait()","marks":[{"type":"code"}]},{"type":"text","text":" is the one that releases the monitor of the object it is called on while waiting."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
