SELECT '421e09f2-3996-7c7d-aee6-d290f6018f08', '913e24f6-0470-7a6a-85a9-d21ab5f739bc', 1, 'PUBLISHED', 'try/catch/finally & try-with-resources', '[{"id":"11cff9bd-bf5b-7eb5-ba6e-2a6a58a3b8ac","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"try","marks":[{"type":"code"}]},{"type":"text","text":" marks code that may fail, "},{"type":"text","text":"catch","marks":[{"type":"code"}]},{"type":"text","text":" handles specific exceptions, "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" always runs — and try-with-resources closes resources automatically, in reverse order, without losing exceptions."}]}]}},"revision":1},{"id":"4ee58b0d-4388-7908-9ab5-e95073394195","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Anatomy"}]},"revision":1},{"id":"55b91ddf-59aa-79de-a79f-2b75faffa3a3","type":"code","position":"a2","content":{"language":"java","code":"public class Main {\n    static void run(String input) {\n        try {\n            System.out.println(\"parsing \" + input);\n            int n = Integer.parseInt(input);\n            System.out.println(\"100 / n = \" + 100 / n);\n        } catch (NumberFormatException | ArithmeticException e) {   // multi-catch\n            System.out.println(\"bad input: \" + e.getClass().getSimpleName());\n        } finally {\n            System.out.println(\"finally\");                          // always\n        }\n    }\n\n    public static void main(String[] args) {\n        run(\"4\");\n        run(\"0\");\n        run(\"x\");\n    }\n}","filename":"Java"},"revision":1},{"id":"1da17177-166f-7f7d-a950-4fef0b25bca9","type":"code","position":"a3","content":{"language":"text","code":"parsing 4\n100 / n = 25\nfinally\nparsing 0\nbad input: ArithmeticException\nfinally\nparsing x\nbad input: NumberFormatException\nfinally","filename":"Output"},"revision":1},{"id":"f1c049cc-ca77-744b-9d0b-60dda16085c3","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Catch blocks are tried "},{"type":"text","text":"top to bottom","marks":[{"type":"bold"}]},{"type":"text","text":"; the first matching type wins."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A subclass catch must come "},{"type":"text","text":"before","marks":[{"type":"bold"}]},{"type":"text","text":" its superclass — "},{"type":"text","text":"catch (Exception e)","marks":[{"type":"code"}]},{"type":"text","text":" then "},{"type":"text","text":"catch (IOException e)","marks":[{"type":"code"}]},{"type":"text","text":" doesn''t compile (unreachable)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In a multi-catch "},{"type":"text","text":"A | B","marks":[{"type":"code"}]},{"type":"text","text":", the types can''t be related by inheritance and "},{"type":"text","text":"e","marks":[{"type":"code"}]},{"type":"text","text":" is implicitly "},{"type":"text","text":"final","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"try","marks":[{"type":"code"}]},{"type":"text","text":" needs at least one "},{"type":"text","text":"catch","marks":[{"type":"code"}]},{"type":"text","text":" or a "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" (or resources)."}]}]}]}]}},"revision":1},{"id":"74255b07-6796-786c-b8e4-0fc099fe8131","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"finally always runs — even after return"}]},"revision":1},{"id":"047f7d88-a21a-7aa3-a4a3-adc56a35d3af","type":"code","position":"a6","content":{"language":"java","code":"public class Main {\n    static int value() {\n        try {\n            return 1;\n        } finally {\n            System.out.println(\"finally runs before the method returns\");\n        }\n    }\n\n    @SuppressWarnings(\"finally\")\n    static int overridden() {\n        try {\n            throw new RuntimeException(\"lost!\");\n        } finally {\n            return 2;              // discards the exception AND any earlier return\n        }\n    }\n\n    static int snapshot() {\n        int x = 10;\n        try {\n            return x;              // return value (10) is saved here\n        } finally {\n            x = 99;                // changing x doesn''t affect it\n        }\n    }\n\n    public static void main(String[] args) {\n        System.out.println(value());\n        System.out.println(overridden());\n        System.out.println(snapshot());\n    }\n}","filename":"Java"},"revision":1},{"id":"8a1bfdff-b5ed-7726-a5c2-af9f6dff542f","type":"code","position":"a7","content":{"language":"text","code":"finally runs before the method returns\n1\n2\n10","filename":"Output"},"revision":1},{"id":"ef7aac90-ecc6-7bc5-9500-257f252fcd8a","type":"callout","position":"a8","content":{"variant":"warning","title":"Trap","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Never "},{"type":"text","text":"return","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"throw","marks":[{"type":"code"}]},{"type":"text","text":") from a "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" block: it silently replaces the method''s result and "},{"type":"text","text":"swallows","marks":[{"type":"bold"}]},{"type":"text","text":" any exception in flight. The only ways "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" doesn''t run are "},{"type":"text","text":"System.exit()","marks":[{"type":"code"}]},{"type":"text","text":", the JVM crashing, or the thread being killed."}]}]}},"revision":1},{"id":"59c105c1-9799-74d6-896f-f6281d7a28f6","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"try-with-resources"}]},"revision":1},{"id":"0dc5f976-ca2d-7f87-98ff-b1254043685d","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Any object implementing "},{"type":"text","text":"AutoCloseable","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"Closeable","marks":[{"type":"code"}]},{"type":"text","text":") declared in the "},{"type":"text","text":"try (…)","marks":[{"type":"code"}]},{"type":"text","text":" header is closed automatically when the block ends — normally or by exception. Resources close in "},{"type":"text","text":"reverse","marks":[{"type":"bold"}]},{"type":"text","text":" order of declaration."}]}]}},"revision":1},{"id":"2e6480be-e3d4-74c2-a23d-7d42ad95147d","type":"code","position":"aB","content":{"language":"java","code":"public class Main {\n    record Res(String name) implements AutoCloseable {\n        Res { System.out.println(\"open \" + name); }\n        @Override public void close() { System.out.println(\"close \" + name); }\n    }\n\n    public static void main(String[] args) {\n        try (Res db = new Res(\"db\"); Res file = new Res(\"file\")) {\n            System.out.println(\"working with \" + db.name() + \" and \" + file.name());\n            throw new IllegalStateException(\"failure\");\n        } catch (IllegalStateException e) {\n            System.out.println(\"caught \" + e.getMessage() + \" (resources already closed)\");\n        } finally {\n            System.out.println(\"finally\");\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"9c8f2d0b-ef75-7bd1-a7bc-fbfd5f162160","type":"code","position":"aC","content":{"language":"text","code":"open db\nopen file\nworking with db and file\nclose file\nclose db\ncaught failure (resources already closed)\nfinally","filename":"Output"},"revision":1},{"id":"94e0a6a3-5a75-709b-a08b-48f5333bedda","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Suppressed exceptions"}]},"revision":1},{"id":"8ae70bfe-c102-742d-b318-3337c6c86578","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If the body throws "},{"type":"text","text":"and","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"close()","marks":[{"type":"code"}]},{"type":"text","text":" throws, the body''s exception is the one propagated; the close exception is attached to it as "},{"type":"text","text":"suppressed","marks":[{"type":"bold"}]},{"type":"text","text":" instead of replacing it (which is what a hand-written "},{"type":"text","text":"finally { close(); }","marks":[{"type":"code"}]},{"type":"text","text":" would do)."}]}]}},"revision":1},{"id":"04a83918-5a4e-7e99-b8d8-da743dc9b1ba","type":"code","position":"aF","content":{"language":"java","code":"public class Main {\n    static class Conn implements AutoCloseable {\n        @Override public void close() { throw new IllegalStateException(\"close failed\"); }\n    }\n\n    public static void main(String[] args) {\n        try (Conn c = new Conn()) {\n            throw new RuntimeException(\"query failed\");\n        } catch (RuntimeException e) {\n            System.out.println(\"primary: \" + e.getMessage());\n            for (Throwable s : e.getSuppressed())\n                System.out.println(\"suppressed: \" + s.getMessage());\n        }\n    }\n}","filename":"Java"},"revision":1},{"id":"d2854039-7fc6-73bf-b40e-af66ea562ccf","type":"code","position":"aG","content":{"language":"text","code":"primary: query failed\nsuppressed: close failed","filename":"Output"},"revision":1},{"id":"bad2cf85-c2e7-70d1-9a18-aec398222c3a","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Before and after"}]},"revision":1},{"id":"63b51592-9f94-74de-bcf5-b2c8d93e0bc4","type":"callout","position":"aI","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"try (var in = Files.newBufferedReader(path)) { … }","marks":[{"type":"code"}]},{"type":"text","text":" — closed on every path, exceptions preserved. Java 9+ also accepts an existing effectively-final variable: "},{"type":"text","text":"try (in) { … }","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"44358aca-757a-72ae-bce7-9bb9dd55aa5b","type":"callout","position":"aJ","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Manual "},{"type":"text","text":"finally { if (in != null) in.close(); }","marks":[{"type":"code"}]},{"type":"text","text":" — verbose, "},{"type":"text","text":"close()","marks":[{"type":"code"}]},{"type":"text","text":" needs its own try/catch, and an exception from "},{"type":"text","text":"close()","marks":[{"type":"code"}]},{"type":"text","text":" hides the real one."}]}]}},"revision":1},{"id":"5b01a087-c05e-7bea-b03f-3b5706703cdc","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does finally run if there''s a return in try?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes. The return value is computed and saved, "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" runs, then the method returns. If "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" itself returns, that value wins and any pending exception is discarded — so never return from "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ab3a780c-a32f-7823-b938-c6114a637949","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When does finally NOT execute?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When the JVM stops: "},{"type":"text","text":"System.exit()","marks":[{"type":"code"}]},{"type":"text","text":", a crash / "},{"type":"text","text":"kill -9","marks":[{"type":"code"}]},{"type":"text","text":", or power loss. (Also if the "},{"type":"text","text":"try","marks":[{"type":"code"}]},{"type":"text","text":" never completes, e.g. an infinite loop, or a daemon thread killed at JVM exit.)"}]}]}},"revision":1},{"id":"96bc018b-7e63-7d47-9b04-b3251d98a10d","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are suppressed exceptions?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In try-with-resources, if the body throws and then "},{"type":"text","text":"close()","marks":[{"type":"code"}]},{"type":"text","text":" also throws, the close exception is added to the primary one via "},{"type":"text","text":"addSuppressed","marks":[{"type":"code"}]},{"type":"text","text":" and can be read with "},{"type":"text","text":"getSuppressed()","marks":[{"type":"code"}]},{"type":"text","text":", so no failure is lost."}]}]}},"revision":1},{"id":"893d42a2-8318-7421-8213-e5ff8db8074d","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In what order are resources closed?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reverse order of declaration — the last opened is closed first, like a stack — and before any "},{"type":"text","text":"catch","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":" block of that statement runs."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ 