SELECT '56a39fa7-8e7e-7cc4-9b2d-de56c36a9d98', '284441f0-677b-7704-93da-2f0953cd9b98', 1, 'PUBLISHED', 'Type Conversion & Casting', '[{"id":"81c6422c-13d1-749b-bcac-c842a0bbee7d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Widening conversions happen automatically; narrowing ones need an explicit cast and may silently lose information."}]}]}},"revision":1},{"id":"70302df8-53ca-7266-94e0-415f5711ae9f","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Widening (implicit) vs narrowing (explicit)"}]},"revision":1},{"id":"9317176a-871d-7ac6-b805-69ef610e253c","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"byte → short → int → long → float → double (char → int)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"628816e7-b773-77ce-995e-7f78bf7c3ea2","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Widening"}],[{"type":"text","text":"Narrowing"}]],[[{"type":"text","text":"Direction"}],[{"type":"text","text":"Smaller → larger type"}],[{"type":"text","text":"Larger → smaller type"}]],[[{"type":"text","text":"Syntax"}],[{"type":"text","text":"Automatic: "},{"type":"text","text":"long l = i;","marks":[{"type":"code"}]}],[{"type":"text","text":"Cast required: "},{"type":"text","text":"int i = (int) l;","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Data loss?"}],[{"type":"text","text":"No (except precision: "},{"type":"text","text":"long","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Possibly: high bits dropped, fraction truncated"}]]]},"revision":1},{"id":"b039bd35-40bb-782f-881a-04cfb9471b48","type":"code","position":"a4","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        int i = 100;\n        long l = i;              // widening\n        double d = l;            // widening\n        System.out.println(l + \" \" + d);\n\n        double price = 9.99;\n        int whole = (int) price;         // truncates toward zero, not rounds\n        System.out.println(whole + \" \" + (int) -9.99 + \" \" + Math.round(9.5));\n\n        int big = 300;\n        byte b = (byte) big;             // keeps only the low 8 bits: 300 - 256\n        System.out.println(b);\n        System.out.println((int) 3_000_000_000L);   // high 32 bits dropped\n        System.out.println((int) 1e20);             // double → int saturates\n        System.out.println((char) 97 + \" \" + (int) ''a'');\n\n        long precise = 123_456_789_123L;\n        float f = precise;                          // widening but loses precision\n        System.out.println((long) f);\n    }\n}","filename":"Java"},"revision":1},{"id":"e670ddf0-2d5f-7fc9-96a2-0701ad78af26","type":"code","position":"a5","content":{"language":"text","code":"100 100.0\n9 -9 10\n44\n-1294967296\n2147483647\na 97\n123456790528","filename":"Output"},"revision":1},{"id":"f4d7d1bc-b617-73f8-a8c6-fc8c51a41054","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Numeric promotion in expressions"}]},"revision":1},{"id":"938ffff7-caca-79b6-acf4-71314459deda","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In arithmetic, "},{"type":"text","text":"byte","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"short","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"char","marks":[{"type":"code"}]},{"type":"text","text":" are first promoted to "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If either operand is "},{"type":"text","text":"long","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"long","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":"; "},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"So "},{"type":"text","text":"byte + byte","marks":[{"type":"code"}]},{"type":"text","text":" is an "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" and must be cast back — but compound assignments ("},{"type":"text","text":"+=","marks":[{"type":"code"}]},{"type":"text","text":") cast implicitly."}]}]}]}]}},"revision":1},{"id":"d5a9e884-2756-70fc-81e3-4bd5e3576a02","type":"code","position":"a8","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        byte a = 10, b = 20;\n        // byte c = a + b;          // compile error: int cannot be converted to byte\n        byte c = (byte) (a + b);\n        a += 5;                     // OK: means a = (byte) (a + 5)\n        byte x = 120;\n        x += 10;                    // silently overflows!\n        System.out.println(c + \" \" + a + \" \" + x);\n        System.out.println(5 / 2 + \" \" + 5 / 2.0 + \" \" + (double) 5 / 2 + \" \" + (double) (5 / 2));\n        System.out.println(''a'' + ''b'' + \" vs \" + \"\" + ''a'' + ''b'');\n    }\n}","filename":"Java"},"revision":1},{"id":"a3daed8d-04c9-76e9-9d9e-f3790316850b","type"