SELECT 'e7b46095-28f8-7536-91d6-4676b4cb377f', '6bce66e1-99f5-7213-842f-dd68adea0ae1', 1, 'PUBLISHED', 'Varargs & Method Overloading', '[{"id":"54934edc-ab77-73c5-82c2-d8cdb2ce54ed","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Overloading = same name, different parameter lists, chosen at "},{"type":"text","text":"compile time","marks":[{"type":"italic"}]},{"type":"text","text":". Varargs ("},{"type":"text","text":"T...","marks":[{"type":"code"}]},{"type":"text","text":") lets a method accept zero or more arguments as an array."}]}]}},"revision":1},{"id":"f5c78132-2344-7b59-bca8-6d890c12199e","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Overloading"}]},"revision":1},{"id":"54c5d979-3785-7b36-b859-e4eaf2550129","type":"code","position":"a2","content":{"language":"java","code":"public class Main {\n    static int area(int side) { return side * side; }\n    static int area(int w, int h) { return w * h; }\n    static double area(double r) { return Math.PI * r * r; }\n\n    public static void main(String[] args) {\n        System.out.println(area(3));\n        System.out.println(area(2, 5));\n        System.out.printf(\"%.2f%n\", area(1.0));\n    }\n}","filename":"Java"},"revision":1},{"id":"6645a016-60f4-73a0-8eb2-a22bbb3a8ea8","type":"code","position":"a3","content":{"language":"text","code":"9\n10\n3.14","filename":"Output"},"revision":1},{"id":"e8f7e5b6-100e-7b27-9b02-a99bb0fae25e","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Overloads must differ in the "},{"type":"text","text":"number, types or order","marks":[{"type":"bold"}]},{"type":"text","text":" of parameters. Different return types, parameter names, or exceptions alone are not enough."}]}]}},"revision":1},{"id":"2dab88e4-c2f3-7c27-9023-971b6fab04b2","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Varargs"}]},"revision":1},{"id":"2b959fc1-b78f-7c9f-9685-dc6d306b50eb","type":"code","position":"a6","content":{"language":"java","code":"import java.util.Arrays;\n\npublic class Main {\n    static int sum(int... nums) {                   // nums is an int[]\n        int total = 0;\n        for (int n : nums) total += n;\n        return total;\n    }\n\n    static String tag(String name, Object... attrs) {   // varargs must be LAST\n        return name + Arrays.toString(attrs);\n    }\n\n    public static void main(String[] args) {\n        System.out.println(sum() + \" \" + sum(1) + \" \" + sum(1, 2, 3));\n        System.out.println(sum(new int[]{4, 5}));       // can pass an array directly\n        System.out.println(tag(\"div\", \"id\", 7, true));\n        System.out.println(String.format(\"%s-%s\", \"a\", \"b\"));   // printf/format use varargs\n    }\n}","filename":"Java"},"revision":1},{"id":"548c8390-a187-7729-ae13-5dca21d68aa3","type":"code","position":"a7","content":{"language":"text","code":"0 1 6\n9\ndiv[id, 7, true]\na-b","filename":"Output"},"revision":1},{"id":"5a0a9b18-2279-7cd3-8f5e-f0afcbe822c7","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Only "},{"type":"text","text":"one","marks":[{"type":"bold"}]},{"type":"text","text":" varargs parameter per method, and it must be the "},{"type":"text","text":"last","marks":[{"type":"bold"}]},{"type":"text","text":" one."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Inside the method it is an ordinary array (possibly empty, never "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" unless the caller passes "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each call allocates a new array — hot paths often add fixed-arity overloads (like "},{"type":"text","text":"List.of(e1, e2, …)","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}]}]}},"revision":1},{"id":"741a068c-5604-716d-9533-3e065caefc2c","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Overload resolution: which method wins?"}]},"revision":1},{"id":"aea43973-4299-7902-8560-b40a4709d665","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Phase 1 — exact / widening","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Match without boxing or varargs; primitive widening allowed ("},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"long","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"float","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"double","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Phase 2 — boxing / unboxing","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Allow "},{"type":"text","text":"int","marks":[{"type":"code"}]},{"type":"text","text":" ↔ "},{"type":"text","text":"Integer","marks":[{"type":"code"}]},{"type":"text","text":", then widening of references ("},{"type":"text","text":"Integer","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"Number","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"Object","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Phase 3 — varargs","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Only if nothing matched in phases 1–2."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Most specific","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If several match in the same phase, the most specific wins; if none is more specific → "},{"type":"text","text":"ambiguous","marks":[{"type":"italic"}]},{"type":"text","text":" compile error."}]}]}]}]}},"revision":1},{"id":"7580b93d-f2da-7602-82ce-bc1a2450405e","type":"code","position":"aB","content":{"language":"java","code":"public class Main {\n    static void f(long x)    { System.out.println(\"long (widening)\"); }\n    static void f(Integer x) { System.out.println(\"Integer (boxing)\"); }\n    static void f(int... x)  { System.out.println(\"int... (varargs)\"); }\n\n    static void g(Object o)  { System.out.println(\"g(Object)\"); }\n    static void g(String s)  { System.out.println(\"g(String)\"); }\n\n    static void h(double d)  { System.out.println(\"h(double)\"); }\n    static void h(Object o)  { System.out.println(\"h(Object)\"); }\n\n    public static void main(String[] args) {\n        f(5);              // widening beats boxing beats varargs\n        f(Integer.valueOf(5));\n        f();\n        g(null);           // String is more specific than Object\n        g((Object) \"hi\");  // static (compile-time) type decides\n        h(''A'');            // char → double widening wins over boxing to Character\n    }\n}","filename":"Java"},"revision":1},{"id":"ea2d1e10-27d4-7f43-9ea3-72d681e7ae51","type":"code","position":"aC","content":{"language":"text","code":"long (widening)\nInteger (boxing)\nint... (varargs)\ng(String)\ng(Object)\nh(double)","filename":"Output"},"revision":1},{"id":"7e450b34-5c9f-7b7b-a778-bd8850b4881d","type":"callout","position":"aD","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Overloads are chosen from the "},{"type":"text","text":"compile-time (static) types","marks":[{"type":"bold"}]},{"type":"text","text":" of the arguments, not the runtime objects. "},{"type":"text","text":"Object o = \"hi\"; g(o);","marks":[{"type":"code"}]},{"type":"text","text":" calls "},{"type":"text","text":"g(Object)","marks":[{"type":"code"}]},{"type":"text","text":". Contrast with overriding, which is chosen at runtime."}]}]}},"revision":1},{"id":"24dc1b48-2047-7ef1-8929-e7461518743c","type":"code","position":"aE","content":{"language":"java","code":"public class Main {\n    static void k(Integer a, long b) {}\n    static void k(long a, Integer b) {}\n\n    public static void main(String[] args) {\n        k(1, 2);          // error: reference to k is ambiguous\n    }\n}","filename":"Java"},"revision":1},{"id":"f4eefce8-5a13-7dce-8874-ea2abef13eac","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"A classic trap: "},{"type":"text","text":"List.remove","marks":[{"type":"code"}]}]},"revision":1},{"id":"62e9dbed-48d8-7bb6-aa51-f22e8ee5e15f","type":"code","position":"aG","content":{"language":"java","code":"import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        List<Integer> list = new ArrayList<>(List.of(10, 20, 30, 1));\n        list.remove(1);                       // remove(int index) → removes 20\n        System.out.println(list);\n        list.remove(Integer.valueOf(1));      // remove(Object) → removes the value 1\n        System.out.println(list);\n    }\n}","filename":"Java"},"revision":1},{"id":"bfafd91e-b2e3-703f-a0b7-e7dfe275f7cf","type":"code","position":"aH","content":{"language":"text","code":"[10, 30, 1]\n[10, 30]","filename":"Output"},"revision":1},{"id":"9b4304fe-a16b-7093-93f5-5317dd6e345e","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can we overload main?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes — you can declare other "},{"type":"text","text":"main","marks":[{"type":"code"}]},{"type":"text","text":" methods with different parameters, but the JVM only starts the program with "},{"type":"text","text":"public static void main(String[] args)","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"String...","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"a8bb9967-66ca-76fd-abc8-2e2c8d3e0962","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the priority order in overload resolution?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Exact match / primitive widening first, then boxing/unboxing, then varargs. Within a phase the most specific method is chosen; if none is most specific the call is ambiguous and won''t compile."}]}]}},"revision":1},{"id":"9b6de45d-0622-7981-b306-0a0d7bc65239","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is void f(int[] a) vs void f(int... a) a valid overload?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No — varargs compiles to an array parameter, so both have the same signature "},{"type":"text","text":"f(int[])","marks":[{"type":"code"}]},{"type":"text","text":": a "},{"type":"text","text":"duplicate method","marks":[{"type":"italic"}]},{"type":"text","text":" compile error."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
