SELECT '4d677915-32f1-7d06-b5be-74d3d5d448d9', '03b95950-0b98-79af-ace9-83abfc7522c7', 1, 'PUBLISHED', 'Virtual Threads (Java 21)', '[{"id":"72c222d5-a58d-7ec3-b157-ebddfb9a6da8","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Virtual threads (JEP 444, final in Java 21) are lightweight threads managed by the JVM — you can have "},{"type":"text","text":"millions","marks":[{"type":"italic"}]},{"type":"text","text":", so plain blocking code scales like async code."}]}]}},"revision":1},{"id":"5918b761-0a4b-75e7-941f-8876b8dbe984","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Virtual thread","marks":[{"type":"bold"}]},{"type":"text","text":" — a "},{"type":"text","text":"java.lang.Thread","marks":[{"type":"code"}]},{"type":"text","text":" not tied to an OS thread. The JVM "},{"type":"text","text":"mounts","marks":[{"type":"italic"}]},{"type":"text","text":" it on a small pool of "},{"type":"text","text":"carrier","marks":[{"type":"bold"}]},{"type":"text","text":" (platform) threads; when it blocks on I/O, "},{"type":"text","text":"sleep","marks":[{"type":"code"}]},{"type":"text","text":" or a lock, it "},{"type":"text","text":"unmounts","marks":[{"type":"italic"}]},{"type":"text","text":" and the carrier runs another virtual thread."}]}]}},"revision":1},{"id":"f480c5cb-55eb-7155-ac28-2aad6ac5a672","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Platform vs virtual threads"}]},"revision":1},{"id":"7feda041-b6e4-7720-af69-2d987ec81d1c","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Platform thread"}],[{"type":"text","text":"Virtual thread"}]],[[{"type":"text","text":"Backed by"}],[{"type":"text","text":"One OS thread for its whole life"}],[{"type":"text","text":"Any carrier thread, only while running"}]],[[{"type":"text","text":"Stack"}],[{"type":"text","text":"Fixed, ~1 MB reserved"}],[{"type":"text","text":"Heap-allocated, grows as needed (KBs)"}]],[[{"type":"text","text":"How many"}],[{"type":"text","text":"Thousands"}],[{"type":"text","text":"Millions"}]],[[{"type":"text","text":"Creation"}],[{"type":"text","text":"Expensive — pool them"}],[{"type":"text","text":"Cheap — create one per task, "},{"type":"text","text":"never pool","marks":[{"type":"bold"}]}]],[[{"type":"text","text":"Scheduler"}],[{"type":"text","text":"OS"}],[{"type":"text","text":"JVM ("},{"type":"text","text":"ForkJoinPool","marks":[{"type":"code"}]},{"type":"text","text":" of carriers, ~one per core)"}]],[[{"type":"text","text":"Always daemon?"}],[{"type":"text","text":"Configurable"}],[{"type":"text","text":"Yes; priority fixed"}]],[[{"type":"text","text":"Best for"}],[{"type":"text","text":"CPU-bound work, long-lived threads"}],[{"type":"text","text":"High-concurrency blocking I/O (servers, clients)"}]]]},"revision":1},{"id":"42602f59-0e4e-72f0-bc03-b06ff6a51b7b","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Creating virtual threads"}]},"revision":1},{"id":"e1144edc-8736-7913-b417-4e89fe2d46db","type":"code","position":"a5","content":{"language":"java","code":"public class Main {\n    public static void main(String[] args) throws InterruptedException {\n        Thread v = Thread.ofVirtual().name(\"v-worker\").start(() ->\n            System.out.println(Thread.currentThread().getName()\n                + \" virtual=\" + Thread.currentThread().isVirtual()\n                + \" daemon=\" + Thread.currentThread().isDaemon()));\n        v.join();\n\n        Thread quick = Thread.startVirtualThread(() -> System.out.println(\"started with startVirtualThread\"));\n        quick.join();\n\n        Thread unstarted = Thread.ofVirtual().unstarted(() -> { });\n        System.out.println(\"state = \" + unstarted.getState());\n\n        Thread p = Thread.ofPlatform().name(\"p-worker\").start(() ->\n            System.out.println(Thread.currentThread().getName() + \" virtual=\" + Thread.currentThread().isVirtual()));\n        p.join();\n    }\n}","filename":"Java"},"revision":1},{"id":"4a722b40-6151-7fb4-ba08-507180eaf6a3","type":"code","position":"a6","content":{"language":"text","code":"v-worker virtual=true daemon=true\nstarted with startVirtualThread\nstate = NEW\np-worker virtual=false","filename":"Output"},"revision":1},{"id":"0fccaf8f-6ef7-7dc1-b4be-1afa9703b451","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"One virtual thread per task"}]},"revision":1},{"id":"2dd253cc-612f-7984-b70f-cd8cfa1c7204","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"10 000 tasks that each block for 10 ms. A pool of 100 platform threads would need ~1 s; with a thread per task the sleeps all overlap and the whole batch finishes in roughly the time of one."}]}]}},"revision":1},{"id":"232acbac-03b2-772b-823f-3963534f55d2","type":"code","position":"a9","content":{"language":"java","code":"import java.util.ArrayList;\nimport java.util.List;\nimport java.util.concurrent.ExecutorService;\nimport java.util.concurrent.Executors;\nimport java.util.concurrent.Future;\n\npublic class Main {\n    public static void main(String[] args) throws Exception {\n        List<Future<Integer>> results = new ArrayList<>();\n        try (ExecutorService exec = Executors.newVirtualThreadPerTaskExecutor()) {\n            for (int i = 0; i < 10_000; i++) {\n                int n = i;\n                results.add(exec.submit(() -> {\n                    Thread.sleep(10);          // blocking call: the virtual thread unmounts\n                    return n;\n                }));\n            }\n        }                                      // close() waits for all 10 000\n        long sum = 0;\n        for (Future<Integer> f : results) sum += f.resultNow();\n        System.out.println(results.size() + \" tasks, sum = \" + sum);\n    }\n}","filename":"Java"},"revision":1},{"id":"3c06439b-c4b9-7e21-b23d-bd9bba6e4b63","type":"code","position":"aA","content":{"language":"text","code":"10000 tasks, sum = 49995000","filename":"Output"},"revision":1},{"id":"dab635cd-866e-7cbe-9465-b356ed55cf78","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"When they help — and when they don''t"}]},"revision":1},{"id":"2b784c9b-ba45-7328-8838-3fc033eb91ca","type":"callout","position":"aC","content":{"variant":"note","title":"Great for","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Thread-per-request servers, calling many HTTP/DB services, anything that spends most of its time "},{"type":"text","text":"waiting","marks":[{"type":"bold"}]},{"type":"text","text":". Write simple blocking code; get async-level throughput."}]}]}},"revision":1},{"id":"331a1166-ac1f-7ff8-b54b-f05b80ad68df","type":"callout","position":"aD","content":{"variant":"note","title":"No gain for","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CPU-bound","marks":[{"type":"bold"}]},{"type":"text","text":" work — there are still only as many carriers as cores. Virtual threads increase "},{"type":"text","text":"throughput","marks":[{"type":"italic"}]},{"type":"text","text":" for waiting tasks, not the "},{"type":"text","text":"speed","marks":[{"type":"italic"}]},{"type":"text","text":" of a single task."}]}]}},"revision":1},{"id":"e80c27fd-7b30-7472-ad8b-c94a3f748243","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Pitfalls"}]},"revision":1},{"id":"f2fe963d-3636-706a-8089-7c2d6f71d1b4","type":"table","position":"aF","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Pitfall"}],[{"type":"text","text":"Why"}],[{"type":"text","text":"Instead"}]],[[{"type":"text","text":"Pooling virtual threads"}],[{"type":"text","text":"They are cheap; pooling just limits concurrency"}],[{"type":"text","text":"One per task; limit access to a scarce resource with a "},{"type":"text","text":"Semaphore","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Pinning","marks":[{"type":"bold"}]},{"type":"text","text":" (Java 21)"}],[{"type":"text","text":"Blocking inside "},{"type":"text","text":"synchronized","marks":[{"type":"code"}]},{"type":"text","text":" (or a native call) keeps the carrier occupied"}],[{"type":"text","text":"Use "},{"type":"text","text":"ReentrantLock","marks":[{"type":"code"}]},{"type":"text","text":" around blocking I/O; diagnose with "},{"type":"text","text":"-Djdk.tracePinnedThreads=full","marks":[{"type":"code"}]},{"type":"text","text":" (fixed for "},{"type":"text","text":"synchronized","marks":[{"type":"code"}]},{"type":"text","text":" in JDK 24, JEP 491)"}]],[[{"type":"text","text":"Heavy "},{"type":"text","text":"ThreadLocal","marks":[{"type":"code"}]},{"type":"text","text":" caches"}],[{"type":"text","text":"A million threads × a cached object each = memory blow-up"}],[{"type":"text","text":"Pass context explicitly; scoped values (preview)"}]],[[{"type":"text","text":"Long CPU loops"}],[{"type":"text","text":"No time-slicing preemption between virtual threads"}],[{"type":"text","text":"Keep CPU-heavy work on a platform pool"}]]]},"revision":1},{"id":"6435c33e-4517-7dc3-b7fd-cf8ffa6d1112","type":"callout","position":"aG","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Virtual threads are always daemon threads: if "},{"type":"text","text":"main","marks":[{"type":"code"}]},{"type":"text","text":" returns without joining them (or closing their executor), the JVM exits and their work is lost."}]}]}},"revision":1},{"id":"ab20b530-c995-7106-bde4-8719a92df04e","type":"callout","position":"aH","content":{"variant":"note","title":"Related previews","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Structured concurrency","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"StructuredTaskScope","marks":[{"type":"code"}]},{"type":"text","text":", preview in Java 21, needs "},{"type":"text","text":"--enable-preview","marks":[{"type":"code"}]},{"type":"text","text":") treats a group of subtasks as one unit: fork them, "},{"type":"text","text":"join()","marks":[{"type":"code"}]},{"type":"text","text":" the scope, and if one fails the others are cancelled — no leaked threads. "},{"type":"text","text":"Scoped values","marks":[{"type":"bold"}]},{"type":"text","text":" (also preview) are the virtual-thread-friendly replacement for "},{"type":"text","text":"ThreadLocal","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"9fbfa311-19f4-7e05-9b51-b2993c841613","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Do virtual threads make code faster?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Not individual tasks — a CPU-bound computation runs at the same speed. They raise "},{"type":"text","text":"throughput","marks":[{"type":"italic"}]},{"type":"text","text":" for I/O-bound workloads by letting you have one cheap thread per concurrent task, so waiting no longer ties up an expensive OS thread."}]}]}},"revision":1},{"id":"b79e2295-ac02-7468-ab20-0d20ed82218d","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a carrier thread? What is pinning?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A carrier is the platform thread (from a "},{"type":"text","text":"ForkJoinPool","marks":[{"type":"code"}]},{"type":"text","text":") a virtual thread is mounted on while it runs. Pinning happens when a virtual thread blocks but can''t unmount — in Java 21, while inside a "},{"type":"text","text":"synchronized","marks":[{"type":"code"}]},{"type":"text","text":" block or a native method — so the carrier is blocked too, reducing scalability."}]}]}},"revision":1},{"id":"19c1ba30-14d3-7c5a-b10f-b1465a7f5fa4","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Should you use a thread pool of virtual threads?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. Pools exist to amortise expensive thread creation and cap resource use; virtual threads are cheap, so create one per task ("},{"type":"text","text":"newVirtualThreadPerTaskExecutor","marks":[{"type":"code"}]},{"type":"text","text":"). To cap access to a limited resource, use a "},{"type":"text","text":"Semaphore","marks":[{"type":"code"}]},{"type":"text","text":" instead."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '03b95950-0b98-79af-ace9-83abfc7522c7' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
