FROM (VALUES
  ('496398a0-d344-7e2e-a1ce-a4ce4a2d464d', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"wait()","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"notify()","marks":[{"type":"code"}]},{"type":"text","text":" let threads "},{"type":"text","text":"coordinate","marks":[{"type":"italic"}]},{"type":"text","text":" — sleep until a condition becomes true — instead of busy-spinning. In modern code a "},{"type":"text","text":"BlockingQueue","marks":[{"type":"code"}]},{"type":"text","text":" usually does this for you."}]}]}}'),
  ('b14444bf-709f-782a-a91f-ded53c2ab8eb', 'a1', 'callout', '{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Guarded wait","marks":[{"type":"bold"}]},{"type":"text","text":" — a thread holding an object''s monitor calls "},{"type":"text","text":"wait()","marks":[{"type":"code"}]},{"type":"text","text":" in a "},{"type":"text","text":"while (!condition)","marks":[{"type":"code"}]},{"type":"text","text":" loop: it releases the monitor and sleeps until another thread calls "},{"type":"text","text":"notify()","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"notifyAll()","marks":[{"type":"code"}]},{"type":"text","text":" on the same object, then re-acquires the monitor and re-checks the condition."}]}]}}'),
  ('298344ec-3f8c-7b37-a697-77c80b43cb13', 'a2', 'heading', '{"level":1,"content":[{"type":"text","text":"The rules"}]}'),
  ('2c1c4673-806e-7439-88c0-963a6276e388', 'a3', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method (on "},{"type":"text","text":"Object","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Effect"}]],[[{"type":"text","text":"wait()","marks":[{"type":"code"}]}],[{"type":"text","text":"Release this object''s monitor and wait (state "},{"type":"text","text":"WAITING","marks":[{"type":"code"}]},{"type":"text","text":") until notified or interrupted"}]],[[{"type":"text","text":"wait(ms)","marks":[{"type":"code"}]}],[{"type":"text","text":"Same, with a timeout ("},{"type":"text","text":"TIMED_WAITING","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"notify()","marks":[{"type":"code"}]}],[{"type":"text","text":"Wake "},{"type":"text","text":"one","marks":[{"type":"italic"}]},{"type":"text","text":" arbitrary waiting thread"}]],[[{"type":"text","text":"notifyAll()","marks":[{"type":"code"}]}],[{"type":"text","text":"Wake "},{"type":"text","text":"all","marks":[{"type":"italic"}]},{"type":"text","text":" waiting threads — they compete for the monitor and re-check their conditions"}]]]}'),
  ('825c92bc-9eaa-7c48-86b3-37ed5a262f35', 'a4', 'text', '{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"All three must be called while holding the object''s monitor (inside "},{"type":"text","text":"synchronized (obj)","marks":[{"type":"code"}]},{"type":"text","text":"), otherwise "},{"type":"text","text":"IllegalMonitorStateException","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Always wait in a "},{"type":"text","text":"while","marks":[{"type":"bold"},{"type":"code"}]},{"type":"text","text":" loop, never "},{"type":"text","text":"if","marks":[{"type":"code"}]},{"type":"text","text":": threads can wake "},{"type":"text","text":"spuriously","marks":[{"type":"italic"}]},{"type":"text","text":", and another thread may have consumed the condition first."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prefer "},{"type":"text","text":"notifyAll()","marks":[{"type":"code"}]},{"type":"text","text":" unless all waiters are interchangeable and only one can proceed."}]}]}]}]}}'),
  ('f886fc06-1afd-7581-a17e-9e18f05bf99e', 'a5', 'code', '{"language":"java","code":"public class Main {\n    public static void main(String[] args) {\n        Object o = new Object();\n        try {\n            o.wait();                           // not holding o''s monitor!\n        } catch (IllegalMonitorStateException | InterruptedException e) {\n            System.out.println(e.getClass().getSimpleName());\n        }\n    }\n}","filename":"Java"}'),
  ('3e3c586f-71e5-7e52-bb0c-a10f20e754d7', 'a6', 'code', '{"language":"text","code":"IllegalMonitorStateException","filename":"Output"}'),
  ('f6958a06-f72e-7913-9b1b-084eda55ee17', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"A bounded buffer with wait/notifyAll"}]}'),
  ('70feb112-997e-7f34-9485-e7b3dba6cd43', 'a8', 'code', '{"language":"java","code":"import java.util.ArrayDeque;\nimport java.util.Queue;\n\npublic class Main {\n    public static void main(String[] args) throws InterruptedException {\n        BoundedBuffer buf = new BoundedBuffer(2);\n        Thread producer = new Thread(() -> {\n            try {\n                for (int i = 1; i <= 5; i++) buf.put(i);\n                buf.put(-1);                              // poison pill: \"no more items\"\n            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        });\n        Thread consumer = new Thread(() -> {\n            try {\n                int sum = 0;\n                for (int x; (x = buf.take()) != -1; ) {\n                    System.out.println(\"consumed \" + x);\n                    sum += x;\n                }\n                System.out.println(\"sum = \" + sum);\n            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        });\n        producer.start(); consumer.start();\n        producer.join();  consumer.join();\n    }\n}\n\nclass BoundedBuffer {\n    private final Queue<Integer> items = new ArrayDeque<>();\n    private final int capacity;\n\n    BoundedBuffer(int capacity) { this.capacity = capacity; }\n\n    synchronized void put(int x) throws InterruptedException {\n        while (items.size() == capacity) wait();   // full: wait for space\n        items.add(x);\n        notifyAll();                               // wake consumers\n    }\n\n    synchronized int take() throws InterruptedException {\n        while (items.isEmpty()) wait();            // empty: wait for data\n        int x = items.remove();\n        notifyAll();                               // wake producers\n        return x;\n    }\n}","filename":"Java"}'),
  ('1bfc3728-4006-7962-aaad-1a6433b50e55', 'a9', 'code', '{"language":"text","code":"consumed 1\nconsumed 2\nconsumed 3\nconsumed 4\nconsumed 5\nsum = 15","filename":"Output"}'),
  ('dd5fbeec-f067-7cf9-aefe-d7ad6de3231b', 'aA', 'heading', '{"level":1,"content":[{"type":"text","text":"The modern way: "},{"type":"text","text":"BlockingQueue","marks":[{"type":"code"}]}]}'),
  ('039c74fc-fb61-783b-9968-d0a53f13bcbe', 'aB', 'code', '{"language":"java","code":"import java.util.concurrent.ArrayBlockingQueue;\nimport java.util.concurrent.BlockingQueue;\n\npublic class Main {\n    public static void main(String[] args) throws InterruptedException {\n        BlockingQueue<String> queue = new ArrayBlockingQueue<>(2);\n        Thread producer = new Thread(() -> {\n            try {\n                for (String job : new String[]{\"resize\", \"upload\", \"notify\"}) queue.put(job);\n                queue.put(\"DONE\");\n            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }\n        });\n        producer.start();\n        for (String job; !(job = queue.take()).equals(\"DONE\"); ) {\n            System.out.println(\"processing \" + job);\n        }\n        producer.join();\n        System.out.println(\"queue empty: \" + queue.isEmpty());\n    }\n}","filename":"Java"}'),
  ('bcead609-58fe-71c4-aa37-4027154d3f31', 'aC', 'code', '{"language":"text","code":"processing resize\nprocessing upload\nprocessing notify\nqueue empty: true","filename":"Output"}'),
  ('d0c8f0bb-ad51-72d1-898a-739a346de5e3', 'aD', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"BlockingQueue","marks":[{"type":"code"}]},{"type":"text","text":" op"}],[{"type":"text","text":"Full / empty behaviour"}]],[[{"type":"text","text":"put(e)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"take()","marks":[{"type":"code"}]}],[{"type":"text","text":"Block until space / an element is available"}]],[[{"type":"text","text":"offer(e)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"poll()","marks":[{"type":"code"}]}],[{"type":"text","text":"Return "},{"type":"text","text":"false","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" immediately"}]],[[{"type":"text","text":"offer(e, t, unit)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"poll(t, unit)","marks":[{"type":"code"}]}],[{"type":"text","text":"Block up to a timeout"}]],[[{"type":"text","text":"add(e)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"remove()","marks":[{"type":"code"}]}],[{"type":"text","text":"Throw an exception"}]]]}'),
