SELECT '4ba1cfe9-cb90-7af8-9530-07817a701685', 'fd07fa76-b693-7365-a1fd-54d6e6c70eb7', 1, 'PUBLISHED', 'map, filter & reduce', '[{"id":"d755746f-dad1-7583-831b-7f51e7dbd3fc","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The three workhorses of functional JavaScript: transform every item, keep some items, fold everything into one value — without mutating the original."}]}]}},"revision":1},{"id":"5f81fd48-8b1a-7f95-a930-c2dfbb7a0e27","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"map — transform each element"}]},"revision":1},{"id":"22dbd9c8-df30-7020-8da4-6dc7b7cc82d9","type":"code","position":"a2","content":{"language":"javascript","code":"const prices = [10, 20, 30];\nconst withTax = prices.map((p) => p * 1.1);\nconsole.log(withTax.map((p) => p.toFixed(2)));\nconst users = [{ name: \"Asha\", age: 28 }, { name: \"Ravi\", age: 17 }];\nconsole.log(users.map(({ name }) => name));\nconsole.log(users.map((u, i) => `${i + 1}. ${u.name}`));","filename":"JavaScript"},"revision":1},{"id":"a8c13422-e3ce-7d49-b71b-a27272d7b602","type":"code","position":"a3","content":{"language":"text","code":"[ ''11.00'', ''22.00'', ''33.00'' ]\n[ ''Asha'', ''Ravi'' ]\n[ ''1. Asha'', ''2. Ravi'' ]","filename":"Output"},"revision":1},{"id":"8aa942b0-9ba6-7814-a6f2-3928b0d0d239","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"filter — keep what passes the test"}]},"revision":1},{"id":"71dede77-fd79-7031-bdf3-c10b0ce89eef","type":"code","position":"a5","content":{"language":"javascript","code":"const nums = [5, 12, 8, 130, 44];\nconsole.log(nums.filter((n) => n > 10));\nconst mixed = [0, \"a\", null, \"\", 7, undefined, false];\nconsole.log(mixed.filter(Boolean));          // remove falsy values\nconst unique = [1, 2, 2, 3, 1].filter((x, i, arr) => arr.indexOf(x) === i);\nconsole.log(unique);","filename":"JavaScript"},"revision":1},{"id":"6d44a394-744c-7fe6-bca2-ed3815e3f9cd","type":"code","position":"a6","content":{"language":"text","code":"[ 12, 130, 44 ]\n[ ''a'', 7 ]\n[ 1, 2, 3 ]","filename":"Output"},"revision":1},{"id":"6ff7d0df-3ae2-716b-b5f1-0be23d1ed1bd","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"reduce — fold into a single value"}]},"revision":1},{"id":"deebb6e1-25c6-7105-9207-a50c615d3669","type":"text","position":"a8","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"array.reduce((accumulator, current, index, array) => newAccumulator, initialValue)","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"bf473582-f555-7fc7-8246-536f3ea603a7","type":"code","position":"a9","content":{"language":"javascript","code":"const nums = [1, 2, 3, 4];\nconsole.log(nums.reduce((sum, n) => sum + n, 0));\nconsole.log(nums.reduce((max, n) => (n > max ? n : max), -Infinity));\n\nconst words = [\"apple\", \"avocado\", \"banana\", \"cherry\", \"blueberry\"];\nconst byLetter = words.reduce((groups, w) => {\n  (groups[w[0]] ??= []).push(w);\n  return groups;\n}, {});\nconsole.log(byLetter);\n\nconst pairs = [[\"a\", 1], [\"b\", 2]];\nconsole.log(pairs.reduce((obj, [k, v]) => ({ ...obj, [k]: v }), {}));","filename":"JavaScript"},"revision":1},{"id":"b0851d8b-1af2-78d8-9898-6578617fe64a","type":"code","position":"aA","content":{"language":"text","code":"10\n4\n{\n  a: [ ''apple'', ''avocado'' ],\n  b: [ ''banana'', ''blueberry'' ],\n  c: [ ''cherry'' ]\n}\n{ a: 1, b: 2 }","filename":"Output"},"revision":1},{"id":"e34be5fd-8660-7a35-8b43-6494c0b7f984","type":"callout","position":"aB","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Always pass the initial value. Without it, "},{"type":"text","text":"reduce","marks":[{"type":"code"}]},{"type":"text","text":" uses the first element as the accumulator — and throws "},{"type":"text","text":"T