Async generators
const fakeApi = (page) =>
  new Promise((r) => setTimeout(() => r({ items: [`p${page}-a`, `p${page}-b`], next: page < 3 ? page + 1 : null }), 5));

async function* paginate() {
  let page = 1;
  while (page) {
    const { items, next } = await fakeApi(page);
    yield* items;
    page = next;
  }
}
for await (const item of paginate()) {
  console.log(item);
  if (item === "p3-a") break;
}
