nst res = await fetch(url, options);\n  if (!res.ok) throw new Error(`HTTP ${res.status}`);   // fetch doesn''t throw on 404!\n  return res.json();\n}\nconsole.log(await getJSON(`${base}/api/user`));\ntry {\n  await getJSON(`${base}/missing`);\n} catch (e) {\n  console.log(\"failed:\", e.message);\n}\nconst res = await fetch(`${base}/api/user`, { signal: AbortSignal.timeout(2000) });\nconsole.log(res.status, res.headers.get(\"content-type\"));\nserver.close();","filename":"JavaScript"},"revision":1},{"id":"45a1f6a2-8db2-7b93-953f-c2a2cda1f0bf","type":"code","position":"a4","content":{"language":"text","code":"{ id: 1, name: ''Asha'' }\nfailed: HTTP 404\n200 application/json","filename":"Output"},"revision":1},{"id":"787eab04-8c64-7964-9f3e-2dadba102fcb","type":"code","position":"a5","content":{"language":"javascript","code":"await fetch(\"/api/todos\", {\n  method: \"POST\",\n  headers: { \"Content-Type\": \"application/json\", Authorization: `Bearer ${token}` },\n  body: JSON.stringify({ title: \"Learn fetch\" }),\n  credentials: \"include\",            // send cookies cross-origin\n});","filename":"JavaScript"},"revision":1},{"id":"3d9e5988-4080-7520-abfe-1c527f76de91","type":"code","position":"a6","content":{"language":"text","code":"JavaScript (POST request, not run)","filename":"Output"},"revision":1},{"id":"95e8419d-3b9a-75ce-9a52-1473d93b3e20","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Web storage"}]},"revision":1},{"id":"86101d22-2f3f-74b5-b781-8d2533681f42","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"localStorage","marks":[{"type":"code"}]}],[{"type":"text","text":"sessionStorage","marks":[{"type":"code"}]}],[{"type":"text","text":"Cookies"}],[{"type":"text","text":"IndexedDB"}]],[[{"type":"text","text":"Lifetime"}],[{"type":"text","text":"Until cleared"}],[{"type":"text","text":"Until the tab closes"}],[{"type":"text","text":"Set by expiry"}],[{"type":"text",