async function getJSON(url, options = {}) {
  const res = await fetch(url, options);
  if (!res.ok) throw new Error(`HTTP ${res.status}`);   // fetch doesn''t throw on 404!
  return res.json();
}
console.log(await getJSON(`${base}/api/user`));
try {
