SELECT '44a40afb-5743-70dd-b5dd-b287a87cda56', '691df788-53e9-742b-bb22-6e8eace4e246', 1, 'PUBLISHED', 'Callbacks & Callback Hell', '[{"id":"8ce1b954-87d5-74ef-bfdc-0a2277e21639","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The original async pattern: pass a function to be called when the work is done. Simple — until you nest five of them."}]}]}},"revision":1},{"id":"ed48caa8-dddc-786a-a477-8a926586c81e","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Error-first callbacks (Node convention)"}]},"revision":1},{"id":"081e118f-f01c-7a8c-a82e-26e96d8d2336","type":"code","position":"a2","content":{"language":"javascript","code":"function readUser(id, callback) {\n  setTimeout(() => {\n    if (id <= 0) callback(new Error(\"invalid id\"));\n    else callback(null, { id, name: \"User\" + id });\n  }, 10);\n}\nreadUser(7, (err, user) => {\n  if (err) return console.log(\"failed:\", err.message);\n  console.log(\"got\", user);\n});\nreadUser(-1, (err, user) => {\n  if (err) return console.log(\"failed:\", err.message);\n  console.log(\"got\", user);\n});","filename":"JavaScript"},"revision":1},{"id":"88a6d4e8-8992-7765-9765-dac056d7212a","type":"code","position":"a3","content":{"language":"text","code":"got { id: 7, name: ''User7'' }\nfailed: invalid id","filename":"Output"},"revision":1},{"id":"ec7daecb-0418-7ee6-aa10-54b1583898fa","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Callback hell (the pyramid of doom)"}]},"revision":1},{"id":"5f62dcd1-4276-7a49-9357-3ae7e1b5e5d1","type":"code","position":"a5","content":{"language":"javascript","code":"const step = (name, cb) => setTimeout(() => cb(null, name), 5);\nstep(\"login\", (err, a) => {\n  step(\"load profile\", (err, b) => {\n    step(\"load orders\", (err, c) => {\n      step(\"render\", (err, d) => {\n        console.log([a, b, c, d].join(\" → \"));\n      });\n    });\n  });\n});","filename":"JavaScript"},"revision":1},{"id":"92814a2a-c518-7507-8dd3-08cbd371b524","type":"code","position":"a6","content":{"language":"text","code":"login → load profile → load orders → render","filename":"Output"},"revision":1},{"id":"e9b00ff1-2f13-7d77-b29e-be6dbbeecdaa","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Problem"}],[{"type":"text","text":"Why it hurts"}]],[[{"type":"text","text":"Nesting"}],[{"type":"text","text":"Code drifts right; hard to read and refactor"}]],[[{"type":"text","text":"Error handling"}],[{"type":"text","text":"Must check "},{"type":"text","text":"err","marks":[{"type":"code"}]},{"type":"text","text":" at every level; "},{"type":"text","text":"try/catch","marks":[{"type":"code"}]},{"type":"text","text":" cannot catch errors thrown in later callbacks"}]],[[{"type":"text","text":"Inversion of control"}],[{"type":"text","text":"You trust the callee to call you exactly once, not zero or twice, not sync "},{"type":"text","text":"and","marks":[{"type":"italic"}]},{"type":"text","text":" async"}]],[[{"type":"text","text":"Composition"}],[{"type":"text","text":"Parallel work, timeouts and \"first one wins\" need hand-written bookkeeping"}]]]},"revision":1},{"id":"88bd15e9-0e2f-77a1-9312-7101bb953ccd","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Promisify"}]},"revision":1},{"id":"3364ebc9-aa10-71f5-85a0-851b49dc3fdc","type":"code","position":"a9","content":{"language":"javascript","code":"import { promisify } from \"node:util\";\nfunction legacyAdd(a, b, cb) { setTimeout(() => cb(null, a + b), 5); }\n\nconst addAsync = promisify(legacyAdd);\nconsole.log(await addAsync(2, 3));\n\nconst manual = (a, b) =>\n  new Promise((resolve, reject) => legacyAdd(a, b, (err, v) => (err ? reject(err) : resolve(v))));\nconsole.log(await manual(10, 20));","filename":"JavaScript"},"revision":1},{"id":"ecc5ec3e-24bd-75fb-b9c6-bf10b58916aa","type":"c