SELECT 'd143d0f0-2359-7ff3-a3d8-eca588fe51fa', '770be6f5-af2d-7efe-a3c2-165f55bc2222', 1, 'PUBLISHED', 'Classes', '[{"id":"0b1fb33c-cd2a-7e57-bf9d-48b8250b9e0c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"class","marks":[{"type":"code"}]},{"type":"text","text":" is clean syntax over prototypes — with real extras: public and "},{"type":"text","text":"#private","marks":[{"type":"code"}]},{"type":"text","text":" fields, static members, static blocks, accessors, and strict mode by default."}]}]}},"revision":1},{"id":"693ffe34-8737-7dec-98cf-32cec7069ee9","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Anatomy of a class"}]},"revision":1},{"id":"22a64e21-f253-750f-b6c3-e1b11c247eeb","type":"code","position":"a2","content":{"language":"javascript","code":"class BankAccount {\n  static bankName = \"JS Bank\";        // static field (on the class)\n  static #count = 0;                  // private static field\n  owner;                              // public instance field\n  #balance = 0;                       // private instance field\n\n  constructor(owner, deposit = 0) {\n    this.owner = owner;\n    this.#balance = deposit;\n    BankAccount.#count++;\n  }\n  deposit(amount) {                   // method on BankAccount.prototype\n    if (amount <= 0) throw new RangeError(\"amount must be positive\");\n    this.#balance += amount;\n    return this;                      // enables chaining\n  }\n  get balance() { return this.#balance; }      // accessor\n  #audit() { return `audited ${this.owner}`; } // private method\n  report() { return this.#audit(); }\n  static count() { return BankAccount.#count; }\n}\n\nconst acc = new BankAccount(\"Asha\", 100);\nacc.deposit(50).deposit(25);\nconsole.log(acc.balance, acc.report(), acc);\nconsole.log(BankAccount.bankName, BankAccount.count(), typeof BankAccount);","filename":"JavaScript"},"revision":1},{"id":"87cd467a-5d2d-75a9-9222-447b866a543f","type":"code","position":"a3","content":{"language":"text","code":"175 audited Asha BankAccount { owner: ''Asha'' }\nJS Bank 1 function","filename":"Output"},"revision":1},{"id":"98e8f748-7713-7d7f-a8af-7e34671ffff0","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Private really means private"}]},"revision":1},{"id":"198ea10e-441f-789f-aed6-cffcad931d04","type":"code","position":"a5","content":{"language":"javascript","code":"class Secret {\n  #code = 1234;\n  static isSecret(obj) { return #code in obj; }   // brand check (ES2022)\n}\nconst s = new Secret();\nconsole.log(s.code, Object.keys(s), JSON.stringify(s));\nconsole.log(Secret.isSecret(s), Secret.isSecret({ code: 1 }));","filename":"JavaScript"},"revision":1},{"id":"68a13db4-7520-7572-9450-4f64c4ad3ae5","type":"code","position":"a6","content":{"language":"text","code":"undefined [] {}\ntrue false","filename":"Output"},"revision":1},{"id":"8eff5a37-83e1-7b7a-958e-516d0cf6e8e1","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Accessing "},{"type":"text","text":"s.#code","marks":[{"type":"code"}]},{"type":"text","text":" outside the class body is a "},{"type":"text","text":"SyntaxError","marks":[{"type":"bold"}]},{"type":"text","text":" — the program does not even parse. Before "},{"type":"text","text":"#","marks":[{"type":"code"}]},{"type":"text","text":", the convention was a leading underscore ("},{"type":"text","text":"this._code","marks":[{"type":"code"}]},{"type":"text","text":"), which is only a hint."}]}]}},"revision":1},{"id":"ad2a8daa-2a8b-7c24-a5c9-6b0bd68699ce","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Class fields with arrow functions"}]},"revision":1},{"id":"4b62a9bf-1666-7438-80f0-ad3e3eb8a83f","type":"code","position":"a9","content":{"language":"javascript","code":"class Button {\n  label = \"Save\";\n 