INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'b8928303-c73b-7a24-99fb-12f941517b75', 'ca57c787-98dc-7dc3-bae2-aa5a8a240f08', 1, 'PUBLISHED', 'Coding Challenges', '[{"id":"11945d3e-b927-71da-bd0b-5c38acd80f1a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Short problems that show up again and again in JavaScript interviews — each with a clean, idiomatic solution and its complexity."}]}]}},"revision":1},{"id":"e16f1506-e4c1-7e7c-bbbc-743434579e92","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Strings"}]},"revision":1},{"id":"e730cd94-730a-7a5c-bf71-257d3ecc94e7","type":"code","position":"a2","content":{"language":"javascript","code":"const isAnagram = (a, b) => {\n  if (a.length !== b.length) return false;\n  const counts = new Map();\n  for (const ch of a) counts.set(ch, (counts.get(ch) ?? 0) + 1);\n  for (const ch of b) {\n    if (!counts.get(ch)) return false;\n    counts.set(ch, counts.get(ch) - 1);\n  }\n  return true;\n};\nconst firstUnique = (s) => {\n  const freq = {};\n  for (const ch of s) freq[ch] = (freq[ch] ?? 0) + 1;\n  return [...s].find((ch) => freq[ch] === 1) ?? null;\n};\nconst longestUniqueSubstring = (s) => {        // sliding window, O(n)\n  let best = 0, start = 0;\n  const lastSeen = new Map();\n  [...s].forEach((ch, i) => {\n    if (lastSeen.get(ch) >= start) start = lastSeen.get(ch) + 1;\n    lastSeen.set(ch, i);\n    best = Math.max(best, i - start + 1);\n  });\n  return best;\n};\nconst compress = (s) => s.replace(/(.)\\1*/g, (run, ch) => ch + run.length);\n\nconsole.log(isAnagram(\"listen\", \"silent\"), isAnagram(\"rat\", \"car\"));\nconsole.log(firstUnique(\"swiss\"), longestUniqueSubstring(\"abcabcbb\"), compress(\"aaabccdddd\"));","filename":"JavaScript"},"revision":1},{"id":"ced9787d-80e0-77ab-bf68-d5e452c8a9c1","type":"code","position":"a3","content":{"language":"text","code":"true false\nw 3 a3b1c2d4","filename":"Output"},"revision":1},{"id":"0278fbb4-c8ae-7c0c-8f6e-fbe639130ab9","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Arrays"}]},"revision":1},{"id":"8a81f406-6281-7b15-95db-12111491603b","type":"code","position":"a5","content":{"language":"javascript","code":"const twoSum = (nums, target) => {             // O(n) with a hash map\n  const seen = new Map();\n  for (const [i, n] of nums.entries()) {\n    if (seen.has(target - n)) return [seen.get(target - n), i];\n    seen.set(n, i);\n  }\n  return null;\n};\nconst maxSubarray = (nums) => {                // Kadane, O(n)\n  let best = -Infinity, current = 0;\n  for (const n of nums) {\n    current = Math.max(n, current + n);\n    best = Math.max(best, current);\n  }\n  return best;\n};\nconst rotate = (arr, k) => {\n  k %= arr.length;\n  return [...arr.slice(-k), ...arr.slice(0, -k)];\n};\nconst missingNumber = (nums) => (nums.length * (nums.length + 1)) / 2 - nums.reduce((a, b) => a + b, 0);\nconst moveZeros = (arr) => [...arr.filter((x) => x !== 0), ...arr.filter((x) => x === 0)];\n\nconsole.log(twoSum([2, 7, 11, 15], 9), maxSubarray([-2, 1, -3, 4, -1, 2, 1, -5, 4]));\nconsole.log(rotate([1, 2, 3, 4, 5], 2), missingNumber([3, 0, 1]), moveZeros([0, 1, 0, 3, 12]));","filename":"JavaScript"},"revision":1},{"id":"b438fe7b-0513-7ee0-bf7f-1e1361687203","type":"code","position":"a6","content":{"language":"text","code":"[ 0, 1 ] 6\n[ 4, 5, 1, 2, 3 ] 2 [ 1, 3, 12, 0, 0 ]","filename":"Output"},"revision":1},{"id":"d86b9527-c76d-7967-9252-672f388038a1","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Objects and data shaping"}]},"revision":1},{"id":"eb836020-e6f7-71da-826d-f176c1ad756b","type":"code","position":"a8","content":{"language":"javascript","code":"const flattenObject = (obj, prefix = \"\") =>\n  Object.entries(obj).reduce((acc, [k, v]) => {\n    const key = prefix ? `${prefix}.${k}` : k;\n    return v && typeof v === \"object\" && !Array.isArray(v)\n      ? { ...acc, ...flattenObject(v, key) }\n      : { ...acc, [key]: v };\n  }, {});\nconst get = (obj, path, fallback) =>\n  path.split(\".\").reduce((cur, key) => cur?.[key], obj) ?? fallback;\nconst invert = (obj) => Object.fromEntries(Object.entries(obj).map(([k, v]) => [v, k]));\n\nconst config = { db: { host: \"localhost\", port: 5432 }, debug: true };\nconsole.log(flattenObject(config));\nconsole.log(get(config, \"db.port\"), get(config, \"db.user.name\", \"n/a\"));\nconsole.log(invert({ a: \"x\", b: \"y\" }));","filename":"JavaScript"},"revision":1},{"id":"24c773ea-d3be-7c50-9bd2-78afcea70659","type":"code","position":"a9","content":{"language":"text","code":"{ ''db.host'': ''localhost'', ''db.port'': 5432, debug: true }\n5432 n/a\n{ x: ''a'', y: ''b'' }","filename":"Output"},"revision":1},{"id":"2bea7a1a-3eae-7f18-a68b-fb1c20e36342","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Async utilities"}]},"revision":1},{"id":"f9527b0a-99b9-7115-a62c-d6f888ca4bf6","type":"code","position":"aB","content":{"language":"javascript","code":"const sleep = (ms) => new Promise((r) => setTimeout(r, ms));\n\nasync function retry(fn, { retries = 3, delay = 5 } = {}) {\n  for (let attempt = 1; ; attempt++) {\n    try {\n      return await fn(attempt);\n    } catch (err) {\n      if (attempt > retries) throw err;\n      await sleep(delay * 2 ** (attempt - 1));     // exponential back-off\n    }\n  }\n}\n\nasync function mapWithConcurrency(items, limit, fn) {\n  const results = new Array(items.length);\n  let next = 0, active = 0, peak = 0;\n  async function worker() {\n    while (next < items.length) {\n      const i = next++;\n      peak = Math.max(peak, ++active);\n      results[i] = await fn(items[i]);\n      active--;\n    }\n  }\n  await Promise.all(Array.from({ length: limit }, worker));\n  return { results, peak };\n}\n\nconst flaky = async (attempt) => {\n  if (attempt < 3) throw new Error(`attempt ${attempt} failed`);\n  return `succeeded on attempt ${attempt}`;\n};\nconsole.log(await retry(flaky));\nconst { results, peak } = await mapWithConcurrency([1, 2, 3, 4, 5], 2, async (n) => {\n  await sleep(5);\n  return n * n;\n});\nconsole.log(results, \"max concurrent:\", peak);","filename":"JavaScript"},"revision":1},{"id":"c17ab4bc-d990-76c0-a62d-6a4236c651d9","type":"code","position":"aC","content":{"language":"text","code":"succeeded on attempt 3\n[ 1, 4, 9, 16, 25 ] max concurrent: 2","filename":"Output"},"revision":1},{"id":"1ed01e6a-7acb-70b6-a953-09266015baac","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"A tiny LRU cache"}]},"revision":1},{"id":"1dbf7f97-9a28-7a71-9af5-eff331f47f61","type":"code","position":"aE","content":{"language":"javascript","code":"class LRUCache {\n  #map = new Map();                       // Map remembers insertion order\n  constructor(capacity) { this.capacity = capacity; }\n  get(key) {\n    if (!this.#map.has(key)) return -1;\n    const value = this.#map.get(key);\n    this.#map.delete(key);                // move to most-recent position\n    this.#map.set(key, value);\n    return value;\n  }\n  put(key, value) {\n    this.#map.delete(key);\n    this.#map.set(key, value);\n    if (this.#map.size > this.capacity) {\n      this.#map.delete(this.#map.keys().next().value);   // evict least recent\n    }\n  }\n  keys() { return [...this.#map.keys()]; }\n}\nconst lru = new LRUCache(2);\nlru.put(\"a\", 1);\nlru.put(\"b\", 2);\nlru.get(\"a\");\nlru.put(\"c\", 3);                          // evicts \"b\"\nconsole.log(lru.keys(), lru.get(\"b\"), lru.get(\"c\"));","filename":"JavaScript"},"revision":1},{"id":"6a63f5e0-b323-7a52-a5b2-11e90c7288ad","type":"code","position":"aF","content":{"language":"text","code":"[ ''a'', ''c'' ] -1 3","filename":"Output"},"revision":1},{"id":"710dc0c8-c3b4-7f6d-8654-3c505cdf9aac","type":"callout","position":"aG","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Talk through complexity as you go: the anagram and two-sum solutions are O(n) time / O(n) space; the LRU operations are O(1) because "},{"type":"text","text":"Map","marks":[{"type":"code"}]},{"type":"text","text":" keeps insertion order."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
