INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '4a31babe-4afd-733e-9aa8-b78499985485', 'd93d2b92-4bc0-71f1-a6f8-7b15d06f1084', 1, 'PUBLISHED', 'Dates & Intl', '[{"id":"c29fdaa3-2833-72ff-9948-93277cfcb8c2","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Date","marks":[{"type":"code"}]},{"type":"text","text":" stores a single number — milliseconds since 1 Jan 1970 UTC — and has an awkward API. "},{"type":"text","text":"Intl","marks":[{"type":"code"}]},{"type":"text","text":" formats dates, numbers and lists for any locale; "},{"type":"text","text":"Temporal","marks":[{"type":"code"}]},{"type":"text","text":" is the modern replacement arriving now."}]}]}},"revision":1},{"id":"c421b994-70c4-7111-914a-98ec0b704dae","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Creating dates"}]},"revision":1},{"id":"527f07a1-21c3-76dd-9776-3c4aa485505b","type":"code","position":"a2","content":{"language":"javascript","code":"const epoch = new Date(0);\nconsole.log(epoch.toISOString());\nconst utc = new Date(Date.UTC(2024, 0, 31, 12, 30));   // months are 0-based!\nconsole.log(utc.toISOString(), utc.getTime());\nconsole.log(new Date(\"2024-02-29T10:00:00Z\").toISOString());\nconsole.log(new Date(\"not a date\").getTime(), String(new Date(\"nope\")));","filename":"JavaScript"},"revision":1},{"id":"7bdb4370-d65a-78c1-acec-f27160f1aa54","type":"code","position":"a3","content":{"language":"text","code":"1970-01-01T00:00:00.000Z\n2024-01-31T12:30:00.000Z 1706704200000\n2024-02-29T10:00:00.000Z\nNaN Invalid Date","filename":"Output"},"revision":1},{"id":"412e9096-a641-781f-9988-15a97b237029","type":"callout","position":"a4","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Months are "},{"type":"text","text":"0-based","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" = January) but days are 1-based. Date-only strings like "},{"type":"text","text":"\"2024-01-15\"","marks":[{"type":"code"}]},{"type":"text","text":" are parsed as "},{"type":"text","text":"UTC","marks":[{"type":"bold"}]},{"type":"text","text":", while "},{"type":"text","text":"\"2024-01-15T10:00\"","marks":[{"type":"code"}]},{"type":"text","text":" (no zone) is "},{"type":"text","text":"local","marks":[{"type":"bold"}]},{"type":"text","text":" time. Always store and send ISO strings with "},{"type":"text","text":"Z","marks":[{"type":"code"}]},{"type":"text","text":" or an offset."}]}]}},"revision":1},{"id":"aac7d442-8943-7164-b8c2-1b2ee85b9598","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Reading and doing arithmetic"}]},"revision":1},{"id":"1a202c0a-797b-777a-8f55-632dbb5fb272","type":"code","position":"a6","content":{"language":"javascript","code":"const d = new Date(Date.UTC(2024, 0, 31));\nconsole.log(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate(), d.getUTCDay());\nd.setUTCMonth(d.getUTCMonth() + 1);        // Jan 31 + 1 month → overflows!\nconsole.log(d.toISOString().slice(0, 10));\n\nconst a = new Date(\"2024-03-01T00:00:00Z\"), b = new Date(\"2024-03-15T00:00:00Z\");\nconst days = (b - a) / (1000 * 60 * 60 * 24);   // subtraction → milliseconds\nconsole.log(days, a < b);\nconst addDays = (date, n) => new Date(date.getTime() + n * 86_400_000);\nconsole.log(addDays(a, 10).toISOString());","filename":"JavaScript"},"revision":1},{"id":"70ca6b62-eb80-7711-8331-aaff36d44338","type":"code","position":"a7","content":{"language":"text","code":"2024 0 31 3\n2024-03-02\n14 true\n2024-03-11T00:00:00.000Z","filename":"Output"},"revision":1},{"id":"2b5499a3-3e5e-7725-881d-20d0f16da650","type":"callout","position":"a8","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Date","marks":[{"type":"code"}]},{"type":"text","text":" objects are "},{"type":"text","text":"mutable","marks":[{"type":"bold"}]},{"type":"text","text":" — "},{"type":"text","text":"setX","marks":[{"type":"code"}]},{"type":"text","text":" methods change them in place. Copy first: "},{"type":"text","text":"new Date(d)","marks":[{"type":"code"}]},{"type":"text","text":". Adding fixed milliseconds ignores daylight-saving shifts; for calendar maths use "},{"type":"text","text":"Temporal","marks":[{"type":"code"}]},{"type":"text","text":" or a library (date-fns, Luxon, Day.js)."}]}]}},"revision":1},{"id":"32113f3d-da36-780d-aa79-fd165afdc55e","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Formatting with Intl"}]},"revision":1},{"id":"726e7c90-da88-7ac5-9922-c544e7e36536","type":"code","position":"aA","content":{"language":"javascript","code":"const when = new Date(Date.UTC(2024, 6, 4, 15, 5));\nconst opts = { dateStyle: \"long\", timeStyle: \"short\", timeZone: \"UTC\" };\nconsole.log(new Intl.DateTimeFormat(\"en-US\", opts).format(when));\nconsole.log(new Intl.DateTimeFormat(\"en-GB\", opts).format(when));\nconsole.log(when.toLocaleDateString(\"en-IN\", { timeZone: \"Asia/Kolkata\", weekday: \"short\", day: \"numeric\", month: \"short\" }));\n\nconsole.log(new Intl.NumberFormat(\"en-IN\", { style: \"currency\", currency: \"INR\" }).format(1234567.5));\nconsole.log(new Intl.NumberFormat(\"en-US\", { notation: \"compact\" }).format(2_500_000));\nconsole.log(new Intl.NumberFormat(\"en-US\", { style: \"percent\" }).format(0.256));\nconst rtf = new Intl.RelativeTimeFormat(\"en\", { numeric: \"auto\" });\nconsole.log(rtf.format(-1, \"day\"), \"|\", rtf.format(3, \"week\"));\nconsole.log(new Intl.ListFormat(\"en\", { type: \"conjunction\" }).format([\"JS\", \"CSS\", \"HTML\"]));\nconsole.log(new Intl.PluralRules(\"en\", { type: \"ordinal\" }).select(22));","filename":"JavaScript"},"revision":1},{"id":"62870328-6c9d-7e44-97e2-02dbfa96d7a0","type":"code","position":"aB","content":{"language":"tex