r":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare their timestamps: "},{"type":"text","text":"a.getTime() === b.getTime()","marks":[{"type":"code"}]},{"type":"text","text":" for equality ("},{"type":"text","text":"===","marks":[{"type":"code"}]},{"type":"text","text":" on Date objects compares references), and "},{"type":"text","text":"<","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":">","marks":[{"type":"code"}]},{"type":"text","text":" or subtraction for ordering, since Dates coerce to their millisecond value."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
