SELECT 'ce607a7e-b501-7311-9980-7d01ef912d81', '9759f467-b531-7df3-bffb-4e9c94d3970b', 1, 'PUBLISHED', 'Events: Bubbling, Capturing & Delegation', '[{"id":"4160de51-3420-7983-ad32-8b2d6787f4e1","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A DOM event travels "},{"type":"text","text":"down","marks":[{"type":"bold"}]},{"type":"text","text":" the tree (capture), hits the target, then travels back "},{"type":"text","text":"up","marks":[{"type":"bold"}]},{"type":"text","text":" (bubble). Delegation uses the bubbling phase to handle many elements with one listener."}]}]}},"revision":1},{"id":"62da2f7a-95f3-7a2f-bbfb-abad8dde331a","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The three phases"}]},"revision":1},{"id":"36acfbe8-7871-7835-8d54-51aec336bea2","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Capture","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"From "},{"type":"text","text":"window","marks":[{"type":"code"}]},{"type":"text","text":" down through each ancestor to the target''s parent. Listeners registered with "},{"type":"text","text":"{ capture: true }","marks":[{"type":"code"}]},{"type":"text","text":" run here."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Target","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Listeners on the element itself."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Bubble","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Back up from the parent to "},{"type":"text","text":"window","marks":[{"type":"code"}]},{"type":"text","text":". Default listeners run here. ("},{"type":"text","text":"focus","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"blur","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"mouseenter","marks":[{"type":"code"}]},{"type":"text","text":" don''t bubble.)"}]}]}]}]}},"revision":1},{"id":"8b0dd300-ae8a-7bed-9522-c114bfcaaa16","type":"code","position":"a3","content":{"language":"javascript","code":"// <div id=\"outer\"><button id=\"inner\">Click</button></div>\nouter.addEventListener(\"click\", () => console.log(\"outer capture\"), { capture: true });\nouter.addEventListener(\"click\", () => console.log(\"outer bubble\"));\ninner.addEventListener(\"click\", () => console.log(\"button\"));\n// clicking the button logs: outer capture → button → outer bubble","filename":"JavaScript"},"revision":1},{"id":"9585e6a4-c00f-7a08-adee-2a2a2c69585f","type":"code","position":"a4","content":{"language":"text","code":"JavaScript (browser, not run)","filename":"Output"},"revision":1},{"id":"8876901b-a5a8-79f6-b541-2bf6b29fbe40","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Event object essentials"}]},"revision":1},{"id":"e420b591-0d9a-72dc-940d-89dd89f8a453","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Member"}],[{"type":"text","text":"Purpose"}]],[[{"type":"text","text":"event.target","marks":[{"type":"code"}]}],[{"type":"text","text":"The element that was actually clicked (deepest)"}]],[[{"type":"text","text":"event.currentTarget","marks":[{"type":"code"}]}],[{"type":"text","text":"The element whose listener is running now"}]],[[{"type":"text","text":"event.preventDefault()","marks":[{"type":"code"}]}],[{"type":"text","text":"Cancel the default action (follow link, submit form)"}]],[[{"type":"text","text":"event.stopPropagation()","marks":[{"type":"code"}]}],[{"type":"text","text":"Stop travelling to further ancestors"}]],[[{"type":"text","text":"event.stopImmediatePropagation()","marks":[{"type":"code"}]}],[{"type":"text","text":"Also skip remaining listeners on the same element"}]],[[{"type":"text","text":"{ once: true }","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"{ passive: true }","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"{ signal }","marks":[{"type":"code"}]}],[{"type":"text","text":"Auto-remove; promise not to "},{"type":"text","text":"preventDefault","marks":[{"type":"code"}]},{"type":"text","text":" (smooth scrolling); remove via "},{"type":"text","text":"AbortController","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"0ed7a3bc-0ad0-764f-bbb1-8be2f995d387","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Event delegation"}]},"revision":1},{"id":"4ed749a9-5006-78e5-9518-01b717902538","type":"code","position":"a8","content":{"language":"javascript","code":"// One listener for any number of (even future) <li> items:\ndocument.querySelector(\"#todo\").addEventListener(\"click\", (event) => {\n  const item = event.target.closest(\"li[data-id]\");\n  if (!item || !event.currentTarget.contains(item)) return;\n  if (event.target.matches(\".delete\")) item.remove();\n  else item.classList.toggle(\"done\");\n});","filename":"JavaScript"},"revision":1},{"id":"3b7ccdda-59b9-7375-9f4d-ec97546fba8e","type":"code","position":"a9","content":{"language":"text","code":"JavaScript (browser, not run)","filename":"Output"},"revision":1},{"id":"ab0767d4-14f1-76ae-9e0b-a90ae61fb314","type":"callout","position":"aA","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Delegation means fewer listeners (less memory), automatic handling of elements added later, and one place for the logic."}]}]}},"revision":1},{"id":"332fe46b-9bdd-7fbd-9c6a-0995a4621254","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Runnable: EventTarget and CustomEvent"}]},"revision":1},{"id":"6d1dd3f1-e92b-7ecd-b97a-6d132a950d0e","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"EventTarget","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Event","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"CustomEvent","marks":[{"type":"code"}]},{"type":"text","text":" also exist in Node, so the listener API itself can be demonstrated (there is no tree, so no bubbling):"}]}]}},"revision":1},{"id":"d0908402-4b7e-7986-8d39-6dcf71b3b0c1","type":"code","position":"aD","content":{"language":"javascript","code":"const cart = new EventTarget();\nconst controller = new AbortController();\n\ncart.addEventListener(\"add\", (e) => console.log(\"added\", e.detail.item), { signal: controller.signal });\ncart.addEventListener(\"add\", () => console.log(\"first add only\"), { once: true });\ncart.addEventListener(\"checkout\", (e) => {\n  e.preventDefault();\n  console.log(\"checkout blocked by listener\");\n});\n\ncart.dispatchEvent(new CustomEvent(\"add\", { detail: { item: \"book\" } }));\ncart.dispatchEvent(new CustomEvent(\"add\", { detail: { item: \"pen\" } }));\ncontroller.abort();                                     // removes the first listener\ncart.dispatchEvent(new CustomEvent(\"add\", { detail: { item: \"lamp\" } }));\n\nconst ok = cart.dispatchEvent(new Event(\"checkout\", { cancelable: true }));\nconsole.log(\"dispatch returned\", ok);","filename":"JavaScript"},"revision":1},{"id":"2845ae02-d502-7205-893a-b21f91cc6a76","type":"code","position":"aE","content":{"language":"text","code":"added book\nfirst add only\nadded pen\ncheckout blocked by listener\ndispatch returned false","filename":"Output"},"revision":1},{"id":"020a7e3d-f67e-7326-be15-0a73170c756d","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is event delegation?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Attaching a single listener to a common ancestor and using "},{"type":"text","text":"event.target","marks":[{"type":"code"}]},{"type":"text","text":" (often with "},{"type":"text","text":"closest","marks":[{"type":"code"}]},{"type":"text","text":") to find which child triggered the event. It relies on bubbling and works for elements added after the listener was registered."}]}]}},"revision":1},{"id":"fef9bcac-ab55-7980-8ac8-9d622cb5d6fc","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"target vs currentTarget?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"target","marks":[{"type":"code"}]},{"type":"text","text":" is where the event originated (e.g. an "},{"type":"text","text":"<span>","marks":[{"type":"code"}]},{"type":"text","text":" inside a button); "},{"type":"text","text":"currentTarget","marks":[{"type":"code"}]},{"type":"text","text":" is the element the currently running listener is attached to (the button or the delegating parent)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
