SELECT '8fecfb7d-5cd9-73e7-a21d-9810f94b7c47', '2f382239-3c39-7c13-ab1c-199196641acb', 1, 'PUBLISHED', 'Error Handling & Custom Errors', '[{"id":"2536b5c7-33d9-74de-b011-8c10c6d8e4e8","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Throw "},{"type":"text","text":"Error","marks":[{"type":"code"}]},{"type":"text","text":" objects (never strings), catch where you can actually do something about it, and give your own failures meaningful classes."}]}]}},"revision":1},{"id":"fe1f5898-c10f-732b-b32e-7d7788737816","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"try / catch / finally"}]},"revision":1},{"id":"1af42cb1-0d97-7f31-9eed-350cee202a13","type":"code","position":"a2","content":{"language":"javascript","code":"function parseAge(input) {\n  const n = Number(input);\n  if (!Number.isInteger(n) || n < 0) throw new RangeError(`invalid age: ${input}`);\n  return n;\n}\nfor (const input of [\"42\", \"-3\", \"abc\"]) {\n  try {\n    console.log(\"age\", parseAge(input));\n  } catch (err) {\n    console.log(err.name, \"-\", err.message);\n  } finally {\n    console.log(\"  checked\", JSON.stringify(input));\n  }\n}","filename":"JavaScript"},"revision":1},{"id":"519e0512-8bbd-78ed-9e59-ec96e47c8f2b","type":"code","position":"a3","content":{"language":"text","code":"age 42\n  checked \"42\"\nRangeError - invalid age: -3\n  checked \"-3\"\nRangeError - invalid age: abc\n  checked \"abc\"","filename":"Output"},"revision":1},{"id":"5f39d2c8-c606-7662-b6da-ecc97dac86ba","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Built-in error types"}]},"revision":1},{"id":"e0e86d85-7be3-7979-85f1-689a123c74b1","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"Thrown when"}]],[[{"type":"text","text":"SyntaxError","marks":[{"type":"code"}]}],[{"type":"text","text":"Code (or "},{"type":"text","text":"JSON.parse","marks":[{"type":"code"}]},{"type":"text","text":" input) cannot be parsed"}]],[[{"type":"text","text":"ReferenceError","marks":[{"type":"code"}]}],[{"type":"text","text":"An undeclared variable, or a TDZ access"}]],[[{"type":"text","text":"TypeError","marks":[{"type":"code"}]}],[{"type":"text","text":"A value is the wrong type: calling a non-function, reading a property of "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":", writing a read-only property"}]],[[{"type":"text","text":"RangeError","marks":[{"type":"code"}]}],[{"type":"text","text":"A number out of range: "},{"type":"text","text":"new Array(-1)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"toFixed(200)","marks":[{"type":"code"}]},{"type":"text","text":", stack overflow"}]],[[{"type":"text","text":"URIError","marks":[{"type":"code"}]}],[{"type":"text","text":"decodeURIComponent(''%'')","marks":[{"type":"code"}]}]],[[{"type":"text","text":"AggregateError","marks":[{"type":"code"}]}],[{"type":"text","text":"Several errors at once ("},{"type":"text","text":"Promise.any","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"EvalError","marks":[{"type":"code"}]}],[{"type":"text","text":"Legacy, practically unused"}]]]},"revision":1},{"id":"74a3538c-305d-77fc-99c3-1f5280721481","type":"code","position":"a6","content":{"language":"javascript","code":"const attempts = [\n  () => null.name,\n  () => undefinedVariable,\n  () => (1).toFixed(500),\n  () => decodeURIComponent(\"%\"),\n  () => JSON.parse(\"{bad json}\"),\n];\nfor (const fn of attempts) {\n  try { fn(); } catch (e) { console.log(`${e.name}: ${e.message}`); }\n}","filename":"JavaScript"},"revision":1},{"id":"73df37f6-6b56-7a5a-b211-edb5ffa05d2b","type":"code","position":"a7","content":{"language":"text","code":"TypeError: Cannot read properties of null (reading ''name'')\nReferenceError: undefinedVariable is not defined\nRangeError: toFixed() digits argument must be between 0 and 100\nURIError: URI malformed\nSyntaxError: Expected property name or ''}'' in JSON at position 1 (line 1 column 2)","filename":"Output"},"revision":1},{"id":"a64e6bce-7980-7bd4-b509-fc7de13e4730","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Custom error classes"}]},"revision":1},{"id":"9cfeb454-88dd-79ea-9492-96e823166383","type":"code","position":"a9","content":{"language":"javascript","code":"class AppError extends Error {\n  constructor(message, options) {\n    super(message, options);            // options.cause (ES2022)\n    this.name = this.constructor.name;\n  }\n}\nclass NotFoundError extends AppError {\n  constructor(resource, id) {\n    super(`${resource} ${id} not found`);\n    this.status = 404;\n  }\n}\nclass DatabaseError extends AppError {}\n\nfunction findUser(id) {\n  try {\n    throw new Error(\"connection reset\");        // low-level failure\n  } catch (cause) {\n    throw new DatabaseError(`could not load user ${id}`, { cause });\n  }\n}\ntry {\n  findUser(7);\n} catch (e) {\n  console.log(e.name, \"|\", e.message, \"|\", e.cause.message);\n  console.log(e instanceof DatabaseError, e instanceof AppError, e instanceof Error);\n}\nconst nf = new NotFoundError(\"Order\", 42);\nconsole.log(nf.name, nf.status, nf.message);","filename":"JavaScript"},"revision":1},{"id":"61e6b7c6-efac-761b-be9e-95d79a4c5492","type":"code","position":"aA","content":{"language":"text","code":"DatabaseError | could not load user 7 | connection reset\ntrue true true\nNotFoundError 404 Order 42 not found","filename":"Output"},"revision":1},{"id":"01d1cdb3-85a9-75a2-8401-6f510e8b6417","type":"callout","position":"aB","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Wrap low-level errors with "},{"type":"text","text":"{ cause }","marks":[{"type":"code"}]},{"type":"text","text":" so logs ke