SELECT '8442fc67-8c36-731b-ae43-a3661eb69d27', 'e778be0f-5072-7f26-826f-10bd444316d4', 1, 'PUBLISHED', 'The Event Loop', '[{"id":"b1f52a96-d4c1-7838-a0e4-21fae01c7b7f","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One thread, one call stack — and a loop that, whenever the stack is empty, drains "},{"type":"text","text":"all","marks":[{"type":"italic"}]},{"type":"text","text":" microtasks and then takes the next macrotask. Predicting output order is a top interview skill."}]}]}},"revision":1},{"id":"225c52c8-c908-708f-b86a-5964c8069cb1","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The moving parts"}]},"revision":1},{"id":"925e078e-a10f-7763-8d3d-4c47b1330303","type":"callout","position":"a2","content":{"variant":"note","title":"Call stack","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Where synchronous code runs, one frame at a time. Nothing else runs until it is empty."}]}]}},"revision":1},{"id":"44b66e2d-a848-732b-bb27-478eab0472e3","type":"callout","position":"a3","content":{"variant":"note","title":"Web / runtime APIs","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Timers, network, file I/O, DOM events — handled outside the JS thread by the browser or libuv (Node)."}]}]}},"revision":1},{"id":"bc74e091-861e-78e9-91e5-cef5fc6c00d6","type":"callout","position":"a4","content":{"variant":"note","title":"Macrotask (task) queue","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"setTimeout","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"setInterval","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"setImmediate","marks":[{"type":"code"}]},{"type":"text","text":", I/O callbacks, UI events, "},{"type":"text","text":"MessageChannel","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"35323f87-fdfb-7350-a8f6-b88c2542ef67","type":"callout","position":"a5","content":{"variant":"note","title":"Microtask queue","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Promise reactions ("},{"type":"text","text":"then","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"catch","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":", code after "},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":"), "},{"type":"text","text":"queueMicrotask","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"MutationObserver","marks":[{"type":"code"}]},{"type":"text","text":". Node''s "},{"type":"text","text":"process.nextTick","marks":[{"type":"code"}]},{"type":"text","text":" has its own even-higher-priority queue."}]}]}},"revision":1},{"id":"bf95f1d0-9fbb-7eae-a14f-5a67a35ec754","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"One turn of the loop"}]},"revision":1},{"id":"bd3007cf-0ee6-7b16-8ff2-bb88544a378e","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Run a task","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Take the oldest macrotask (the initial script is the first) and run it to completion."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Drain microtasks","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Run "},{"type":"text","text":"every","marks":[{"type":"bold"}]},{"type":"text","text":" microtask — including ones queued while draining — until the queue is empty."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Render (browsers)","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If it''s time for a frame: "},{"type":"text","text":"requestAnimationFrame","marks":[{"type":"code"}]},{"type":"text","text":" callbacks, style, layout, paint."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Repeat","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Pick the next macrotask."}]}]}]}]}},"revision":1},{"id":"a33666c4-5d74-7529-ac71-39fe735d702a","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Predict the output"}]},"revision":1},{"id":"ce5194dc-4b7d-796a-95ee-a7fb324306ae","type":"code","position":"a9","content":{"language":"javascript","code":"console.log(\"1: sync start\");\nsetTimeout(() => console.log(\"6: timeout (macrotask)\"), 0);\nPromise.resolve()\n  .then(() => console.log(\"3: promise then (microtask)\"))\n  .then(() => console.log(\"5: chained then (microtask)\"));\nqueueMicrotask(() => console.log(\"4: queueMicrotask\"));\nconsole.log(\"2: sync end\");","filename":"JavaScript"},"revision":1},{"id":"cdbd17c2-b9ee-7cc5-ae75-815601d393f8","type":"code","position":"aA","content":{"language":"text","code":"1: sync start\n2: sync end\n3: promise then (microtask)\n4: queueMicrotask\n5: chained then (microtask)\n6: timeout (macrotask)","filename":"Output"},"revision":1},{"id":"d17a9fdb-f5e3-73f9-b5ab-2b7b86b09d5e","type":"callout","position":"aB","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"setTimeout(fn, 0)","marks":[{"type":"code"}]},{"type":"text","text":" never runs before microtasks queued in the same task. "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" means “as soon as possible after at least 0 ms”, not “now”."}]}]}},"revision":1},{"id":"16d8affe-c653-74d6-9187-26a4d7947d62","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"async/await in the ordering"}]},"revision":1},{"id":"b2404a38-2bb0-7f3f-a94d-735598eb94fe","type":"code","position":"aD","content":{"language":"javascript","code":"async function task() {\n  console.log(\"B: task starts (sync part)\");\n  await null;                               // everything after this is a microtask\n  console.log(\"E: task resumes after await\");\n}\nconsole.log(\"A: script start\");\nsetTimeout(() => console.log(\"G: timeout\"), 0);\ntask();\nnew Promise((resolve) => {\n  console.log(\"C: executor runs synchronously\");\n  resolve();\n}).then(() => console.log(\"F: then\"));\nconsole.log(\"D: script end\");","filename":"JavaScript"},"revision":1},{"id":"55dba7de-2287-776c-ad53-f9d241099240","type":"code","position":"aE","content":{"language":"text","code":"A: script start\nB: task starts (sync part)\nC: executor runs synchronously\nD: script end\nE: task resumes after await\nF: then\nG: timeout","filename":"Output"},"revision":1},{"id":"cc7b6499-46ee-743d-a27f-2b7979bda60e","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Microtasks can starve the loop"}]},"revision":1},{"id":"6a8b0085-767d-72cd-926d-8005e8bbc782","type":"code","position":"aG","content":{"language":"javascript","code":"let count = 0;\nsetTimeout(() => console.log(\"timeout finally runs, microtasks ran:\", count), 0);\nfunction spin() {\n  if (++count < 1000) queueMicrotask(spin);   // keeps refilling the queue\n}\nqueueMicrotask(spin);","filename":"JavaScript"},"revision":1},{"id":"4a9f60fc-f5f0-753f-9049-db2c644de9d0","type":"code","position":"aH","content":{"language":"text","code":"timeout finally runs, microtasks ran: 1000","filename":"Output"},"revision":1},{"id":"349a3a56-2df7-7db1-bbff-b4334f850b7f","type":"callout","position":"aI","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Because the microtask queue is drained completely, an endless chain of microtasks blocks timers, I/O and rendering just like a "},{"type":"text","text":"while(true)","marks":[{"type":"code"}]},{"type":"text","text":" loop. Long synchronous work does the same — split it up or move it to a Worker."}]}]}},"revision":1},{"id":"a4f20e15-af5b-726d-94bd-6a98ed5f7c9f","type":"heading","position":"aJ","content":{"level":1,"content":[{"type":"text","text":"Node specifics: nextTick, setImmediate"}]},"revision":1},{"id":"c2b701b1-3d55-7966-b959-7768ba66b0fb","type":"table","position":"aK","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Node phase / queue"}],[{"type":"text","text":"Runs"}]],[[{"type":"text","text":"process.nextTick","marks":[{"type":"code"}]},{"type":"text","text":" queue"}],[{"type":"text","text":"After the current operation, before promise microtasks (from CommonJS/callbacks)"}]],[[{"type":"text","text":"Promise microtasks"}],[{"type":"text","text":"Right after the nextTick queue"}]],[[{"type":"text","text":"timers"}],[{"type":"text","text":"Expired "},{"type":"text","text":"setTimeout","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"setInterval","marks":[{"type":"code"}]}]],[[{"type":"text","text":"poll"}],[{"type":"text","text":"I/O callbacks (fs, network)"}]],[[{"type":"text","text":"check"}],[{"type":"text","text":"setImmediate","marks":[{"type":"code"}]}]],[[{"type":"text","text":"close"}],[{"type":"text","text":"''close''","marks":[{"type":"code"}]},{"type":"text","text":" events"}]]]},"revision":1},{"id":"1b6f2520-0f66-7931-a750-1b7aa283ee3c","type":"code","position":"aL","content":{"language":"javascript","code":"setTimeout(() => {\n  console.log(\"inside a timer callback:\");\n  setTimeout(() => console.log(\"  4. setTimeout 0 (next timers phase)\"), 0);\n  setImmediate(() => console.log(\"  3. setImmediate (check phase comes first)\"));\n  Promise.resolve().then(() => console.log(\"  2. promise microtask\"));\n  process.nextTick(() => console.log(\"  1. process.nextTick\"));\n}, 0);","filename":"JavaScript"},"revision":1},{"id":"d30554ad-8568-7e3b-b201-c85d9f96a23a","type":"code","position":"aM","content":{"language":"text","code":"inside a timer callback:\n  1. process.nextTick\n  2. promise microtask\n  3. setImmediate (check phase comes first)\n  4. setTimeout 0 (next timers phase)","filename":"Output"},"revision":1},{"id":"899cc696-d425-7df9-be84-d964018c41ca","type":"callout","position":"aN","content":{"variant":"note","title":"ESM subtlety","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"At the top level of an "},{"type":"text","text":"ES module","marks":[{"type":"bold"}]},{"type":"text","text":" the module body itself runs as part of a promise job, so there a "},{"type":"text","text":".then","marks":[{"type":"code"}]},{"type":"text","text":" callback can run before a "},{"type":"text","text":"process.nextTick","marks":[{"type":"code"}]},{"type":"text","text":" — one reason not to depend on nextTick-vs-promise ordering."}]}]}},"revision":1},{"id":"1db1b7a6-61b7-712f-ad0f-51a61ac955e2","type":"question","position":"aO","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between microtasks and macrotasks?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Macrotasks (timers, I/O, events) are taken one per loop turn. Microtasks (promise reactions, "},{"type":"text","text":"queueMicrotask","marks":[{"type":"code"}]},{"type":"text","text":") run right after the current task and the whole queue is drained before the next macrotask or render. So promise callbacks always beat a "},{"type":"text","text":"setTimeout(…, 0)","marks":[{"type":"code"}]},{"type":"text","text":" scheduled at the same time."}]}]}},"revision":1},{"id":"982efdbd-c329-748d-bb3f-d55654a432d2","type":"question","position":"aP","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If JavaScript is single-threaded, how does it do async work?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The engine is single-threaded, but the runtime is not: timers, network and disk I/O run in the browser or libuv thread pool. When they finish, their callbacks are queued, and the event loop runs them on the main thread when the call stack is empty."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
