SELECT '1dfbed2f-bf95-746a-b357-f659ae1067d2', 'a7a86837-5f24-7304-8f49-634c32728773', 1, 'PUBLISHED', 'Currying, Composition & Memoization', '[{"id":"4184d869-c6bc-786f-bfbd-c5a45051aecb","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Functional techniques built from closures and higher-order functions — and staple interview implementations."}]}]}},"revision":1},{"id":"86578866-8018-71b3-b692-304ddd602538","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Currying"}]},"revision":1},{"id":"f88d025b-8960-7fe4-a6cc-53447be38b9c","type":"callout","position":"a2","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Currying","marks":[{"type":"bold"}]},{"type":"text","text":" — transforming "},{"type":"text","text":"f(a, b, c)","marks":[{"type":"code"}]},{"type":"text","text":" into "},{"type":"text","text":"f(a)(b)(c)","marks":[{"type":"code"}]},{"type":"text","text":" — a chain of single-argument functions. "},{"type":"text","text":"Partial application","marks":[{"type":"italic"}]},{"type":"text","text":" is the looser idea of fixing some arguments now and the rest later."}]}]}},"revision":1},{"id":"f67ad252-9f5f-7ef1-8e93-8b24d96c333b","type":"code","position":"a3","content":{"language":"javascript","code":"function curry(fn) {\n  return function curried(...args) {\n    return args.length >= fn.length\n      ? fn.apply(this, args)\n      : (...more) => curried.apply(this, [...args, ...more]);\n  };\n}\nconst volume = (l, w, h) => l * w * h;\nconst cv = curry(volume);\nconsole.log(cv(2)(3)(4), cv(2, 3)(4), cv(2)(3, 4), cv(2, 3, 4));\n\nconst log = curry((level, scope, msg) => `[${level}] ${scope}: ${msg}`);\nconst warnDb = log(\"WARN\")(\"db\");\nconsole.log(warnDb(\"slow query\"));","filename":"JavaScript"},"revision":1},{"id":"376eba15-952d-7af5-af1e-094e9728e5ec","type":"code","position":"a4","content":{"language":"text","code":"24 24 24 24\n[WARN] db: slow query","filename":"Output"},"revision":1},{"id":"fc61f2fe-d879-7c75-a950-be889a07763a","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Infinite currying: sum(1)(2)(3)()"}]},"revision":1},{"id":"e8580e7e-309c-7c81-9be5-07bc1bf3a84e","type":"code","position":"a6","content":{"language":"javascript","code":"const sum = (a) => (b) => (b === undefined ? a : sum(a + b));\nconsole.log(sum(1)(2)(3)(4)());","filename":"JavaScript"},"revision":1},{"id":"363241e3-cfce-7ac4-8adf-980e14ee6669","type":"code","position":"a7","content":{"language":"text","code":"10","filename":"Output"},"revision":1},{"id":"a6215b5a-09aa-72de-b874-07a12b09c9bd","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Composition and pipe"}]},"revision":1},{"id":"799131fb-21f4-7f93-aa50-af3c69a1abbb","type":"code","position":"a9","content":{"language":"javascript","code":"const compose = (...fns) => (x) => fns.reduceRight((acc, f) => f(acc), x);\nconst pipe = (...fns) => (x) => fns.reduce((acc, f) => f(acc), x);\n\nconst trim = (s) => s.trim();\nconst lower = (s) => s.toLowerCase();\nconst slugify = (s) => s.replace(/\\s+/g, \"-\");\n\nconsole.log(pipe(trim, lower, slugify)(\"  Hello Big World \"));\nconsole.log(compose(slugify, lower, trim)(\"  Hello Big World \"));","filename":"JavaScript"},"revision":1},{"id":"b1af8690-0eb1-75a2-8b1e-da9c330cc242","type":"code","position":"aA","content":{"language":"text","code":"hello-big-world\nhello-big-world","filename":"Output"},"revision":1},{"id":"fa1c7dbe-336d-7400-b840-b007e78a11cb","type":"callout","position":"aB","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"pipe","marks":[{"type":"code"}]},{"type":"text","text":" runs left → right (reads like a recipe); "},{"type":"text","text":"compose","marks":[{"type":"code"}]},{"type":"text","text":" right → left (mirrors maths: "},{"type":"text","text":"f(g(x))","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"3a247616-8b4a-70fb-8ba6-195af8def004","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Memoization"}]},"revision":1},{"id":"021cc348-5f77-7e87-bfbf-139bd93364fc","type":"code","position":"aD","content":{"language":"javascript","code":"function memoize(fn, keyFn = (...args) => JSON.stringify(args)) {\n  const cache = new Map();\n  return function (...args) {\n    const key = keyFn(...args);\n    if (cache.has(key)) return cache.get(key);\n    const result = fn.apply(this, args);\n    cache.set(key, result);\n    return result;\n  };\n}\nlet calls = 0;\nconst slowSquare = (n) => { calls++; return n * n; };\nconst fastSquare = memoize(slowSquare);\nconsole.log(fastSquare(9), fastSquare(9), fastSquare(3), \"calls:\", calls);\n\nconst fib = memoize((n) => (n < 2 ? n : fib(n - 1) + fib(n - 2)));\nconsole.log(fib(90));","filename":"JavaScript"},"revision":1},{"id":"ce664570-ae7d-7200-897a-f96db21606c8","type":"code","position":"aE","content":{"language":"text","code":"81 81 9 calls: 2\n2880067194370816000","filename":"Output"},"revision":1},{"id":"cbe6a57a-e602-7448-bfe3-4f7eddba1142","type":"callout","position":"aF","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Memoize only "},{"type":"text","text":"pure","marks":[{"type":"bold"}]},{"type":"text","text":" functions. An unbounded cache is a memory leak — cap it (LRU) or key it with a "},{"type":"text","text":"WeakMap","marks":[{"type":"code"}]},{"type":"text","text":" when arguments are objects."}]}]}},"revision":1},{"id":"d3afb454-e0d3-7d2a-b02a-f89d1e00a90b","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"once, partial and friends"}]},"revision":1},{"id":"ae3b495f-9787-736b-ad49-913a96ef3295","type":"code","position":"aH","content":{"language":"javascript","code":"const partial = (fn, ...preset) => (...later) => fn(...preset, ...later);\nconst greet = (greeting, name) => `${greeting}, ${name}!`;\nconsole.log(partial(greet, \"Welcome\")(\"Mei\"));\n\nconst not = (pred) => (...args) => !pred(...args);\nconst isEven = (n) => n % 2 === 0;\nconsole.log([1, 2, 3, 4].filter(not(isEven)));\n\nconst tap = (fn) => (x) => { fn(x); return x; };\nconsole.log([1, 2].map(tap((x) => console.log(\"saw\", x))));","filename":"JavaScript"},"revision":1},{"id":"74e2c9f6-f1df-7f75-86be-34db93a75766","type":"code","position":"aI","content":{"language":"text","code":"Welcome, Mei!\n[ 1, 3 ]\nsaw 1\nsaw 2\n[ 1, 2 ]","filename":"Output"},"revision":1},{"id":"cfddaec0-2039-78a1-8845-8df3f56fca9a","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Implement a curry function."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Return a function that collects arguments; when it has at least "},{"type":"text","text":"fn.length","marks":[{"type":"code"}]},{"type":"text","text":" of them, call "},{"type":"text","text":"fn","marks":[{"type":"code"}]},{"type":"text","text":", otherwise return another function that appends further arguments (see the implementation above)."}]}]}},"revision":1},{"id":"4885c17e-791c-756a-8f20-f7f4a176cc87","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is memoization?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Caching a function''s results keyed by its arguments so repeated calls with the same input return instantly. It trades memory for speed and is only correct for pure functions."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
