SELECT '436fe806-f732-7aa3-b712-a743b2f0523e', '3ee5a4a6-f773-7636-b47d-f4691ccfbec0', 1, 'PUBLISHED', 'Functions: Declarations, Expressions & Arrows', '[{"id":"7c7c5724-946e-76db-b5f9-eb3489f3111a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Functions are first-class objects: create them three ways, pass them around, return them — and pick arrows or regular functions for the right reasons."}]}]}},"revision":1},{"id":"e0703457-b511-7927-8f8a-ba22ec1d34d9","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Three ways to define a function"}]},"revision":1},{"id":"4cf49353-1c49-741c-a697-e08df9a9a849","type":"code","position":"a2","content":{"language":"javascript","code":"// 1. Declaration — hoisted completely\nfunction add(a, b) {\n  return a + b;\n}\n// 2. Expression — a value assigned to a variable (optionally named)\nconst multiply = function mul(a, b) {\n  return a * b;\n};\n// 3. Arrow function (ES2015) — concise, lexical `this`\nconst square = (x) => x * x;\nconst makePoint = (x, y) => ({ x, y });   // wrap object literals in ( )\n\nconsole.log(add(2, 3), multiply(2, 3), square(4), makePoint(1, 2));\nconsole.log(multiply.name, square.name, add.length);","filename":"JavaScript"},"revision":1},{"id":"ae5697c5-de0a-7aaa-9ed7-162ea29fc818","type":"code","position":"a3","content":{"language":"text","code":"5 6 16 { x: 1, y: 2 }\nmul square 2","filename":"Output"},"revision":1},{"id":"7db386e7-d18c-74f3-8bbd-e6e36636be46","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Declarations are hoisted, expressions are not"}]},"revision":1},{"id":"3cff1244-93c6-7989-a222-b405954a1c6a","type":"code","position":"a5","content":{"language":"javascript","code":"console.log(early());          // works: whole declaration is hoisted\nfunction early() { return \"declared\"; }\n\ntry {\n  late();\n} catch (e) {\n  console.log(e.name + \": \" + e.message);\n}\nconst late = () => \"expression\";","filename":"JavaScript"},"revision":1},{"id":"2a15ff72-27dc-7f78-8144-b0762b92ae28","type":"code","position":"a6","content":{"language":"text","code":"declared\nReferenceError: Cannot access ''late'' before initialization","filename":"Output"},"revision":1},{"id":"cd85dfea-2626-758d-a867-ad64a300fdc7","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Arrow vs regular functions"}]},"revision":1},{"id":"08a55d70-6ab2-7dab-8f4b-796896b55401","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Regular "},{"type":"text","text":"function","marks":[{"type":"code"}]}],[{"type":"text","text":"Arrow "},{"type":"text","text":"=>","marks":[{"type":"code"}]}]],[[{"type":"text","text":"this","marks":[{"type":"code"}]}],[{"type":"text","text":"Set by "},{"type":"text","text":"how it is called","marks":[{"type":"italic"}]}],[{"type":"text","text":"Inherited from the enclosing scope (lexical)"}]],[[{"type":"text","text":"arguments","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No (use rest "},{"type":"text","text":"...args","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Can be used with "},{"type":"text","text":"new","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No — TypeError"}]],[[{"type":"text","text":"prototype","marks":[{"type":"code"}]},{"type":"text","text":" property"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"Hoisting"}],[{"type":"text","text":"Declarations are hoisted"}],[{"type":"text","text":"Like any "},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":" — TDZ"}]],[[{"type":"text","text":"Best for"}],[{"type":"text","text":"Methods, constructors, generators"}],[{"type":"text","text":"Callbacks, short transforms, keeping outer "},{"type":"text