Coercion surprises
console.log([] == ![], "b" + "a" + +"a" + "a");
console.log(null >= 0, null > 0, null == 0);
console.log([1, 2, 3] + [4, 5], typeof (1 + "1" - 1));
console.log(Math.max() < Math.min(), 0.1 * 3, 9007199254740992 + 1);
