t":{"level":1,"content":[{"type":"text","text":"The "},{"type":"text","text":"parseInt","marks":[{"type":"code"}]},{"type":"text","text":" trap"}]},"revision":1},{"id":"e020ee1e-dee4-7ed0-b988-e6c3a037d1e2","type":"code","position":"aC","content":{"language":"javascript","code":"console.log([\"1\", \"2\", \"3\"].map(parseInt));\nconsole.log([\"1\", \"2\", \"3\"].map(Number));\nconsole.log([\"1\", \"2\", \"3\"].map((s) => parseInt(s, 10)));","filename":"JavaScript"},"revision":1},{"id":"084947ee-60ea-730e-b080-d01b27f6e522","type":"code","position":"aD","content":{"language":"text","code":"[ 1, NaN, NaN ]\n[ 1, 2, 3 ]\n[ 1, 2, 3 ]","filename":"Output"},"revision":1},{"id":"88e81ea7-cb17-7afe-ad0d-d697fc760c84","type":"callout","position":"aE","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":" calls its callback with "},{"type":"text","text":"(element, index, array)","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"parseInt","marks":[{"type":"code"}]},{"type":"text","text":" treats the index as the radix: "},{"type":"text","text":"parseInt(''2'', 1)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"NaN","marks":[{"type":"code"}]},{"type":"text","text":". Wrap callbacks whose extra parameters mean something else."}]}]}},"revision":1},{"id":"88ba4877-4147-7e14-b2b2-95ba33e4a111","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a callback function?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A function passed as an argument to another function, to be called by it — either synchronously (array methods) or later (timers, events, I/O)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+