SELECT '22da44be-6ccd-74be-a860-5d586ba89330', 'fa1e7cc2-4031-7c90-8327-8d555f772d79', 1, 'PUBLISHED', 'How JavaScript Runs', '[{"id":"8f5bf6db-8f19-748e-a971-cb158b04aa4f","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Source text → tokens → AST → bytecode → optimised machine code. One call stack, one heap, and an event loop that feeds it work."}]}]}},"revision":1},{"id":"4b96bee5-186c-7021-aedb-b1266d273d90","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The pipeline inside V8"}]},"revision":1},{"id":"242e8c15-e6ba-7dbd-8631-f910186f210d","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Source code → Parser → AST → Ignition (bytecode) → TurboFan (optimised machine code)"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Parse","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The source is tokenised and turned into an "},{"type":"text","text":"Abstract Syntax Tree","marks":[{"type":"bold"}]},{"type":"text","text":". Syntax errors are found here — before a single line runs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Interpret","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Ignition","marks":[{"type":"bold"}]},{"type":"text","text":" interpreter compiles the AST to compact bytecode and starts running it immediately (fast startup)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Profile","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"While running, the engine records which functions are "},{"type":"text","text":"hot","marks":[{"type":"italic"}]},{"type":"text","text":" and which types they see."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Optimise (JIT)","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Hot functions are compiled by "},{"type":"text","text":"TurboFan","marks":[{"type":"bold"}]},{"type":"text","text":" (and the mid-tier Maglev) into machine code specialised for the observed types."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deoptimise","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"If an assumption breaks (a function that always saw numbers suddenly gets a string), the engine throws the optimised code away and falls back to bytecode."}]}]}]}]}},"revision":1},{"id":"0c17282f-a239-71e8-bcfd-a5e0429d230d","type":"callout","position":"a3","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JIT (Just-In-Time) compilation","marks":[{"type":"bold"}]},{"type":"text","text":" — compiling code to machine code "},{"type":"text","text":"while the program runs","marks":[{"type":"italic"}]},{"type":"text","text":", using runtime type feedback — so JavaScript is neither purely interpreted nor ahead-of-time compiled."}]}]}},"revision":1},{"id":"da30f835-8f4f-7f86-9377-a89d38553c3e","type":"callout","position":"a4","content":{"variant":"note","title":"Performance tip","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Write "},{"type":"text","text":"monomorphic","marks":[{"type":"italic"}]},{"type":"text","text":" code: keep the same object shapes and argument types in hot paths. Mixing types in one function ("},{"type":"text","text":"add(1, 2)","marks":[{"type":"code"}]},{"type":"text","text":" then "},{"type":"text","text":"add(''a'', ''b'')","marks":[{"type":"code"}]},{"type":"text","text":") makes it polymorphic and slower."}]}]}},"revision":1},{"id":"c9520ab2-616f-7854-b1e7-65a9ef4881a0","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Memory: stack and heap"}]},"revision":1},{"id":"bd5f7bf2-2494-7c96-aca8-5a64be84d25f","type":"callout","position":"a6","content":{"variant":"note","title":"Call stack","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A LIFO stack of "},{"type":"text","text":"execution contexts","marks":[{"type":"bold"}]},{"type":"text","text":" — one frame per running function call, holding its local variables and where to return to."}]}]}},"revision":1},{"id":"e0c68ada-4b10-7abd-a604-38055b4561b9","type":"callout","position":"a7","content":{"variant":"note","title":"Heap","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A large unstructured region where objects, arrays and closures live. Managed automatically by the "},{"type":"text","text":"garbage collector","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ecd81ed8-20f6-7f63-80ca-df1febf491cd","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Execution contexts"}]},"revision":1},{"id":"0e7d7f87-9bdf-7135-9282-7a46621d309f","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every time code runs it gets an "},{"type":"text","text":"execution context","marks":[{"type":"bold"}]},{"type":"text","text":". There is one "},{"type":"text","text":"global","marks":[{"type":"italic"}]},{"type":"text","text":" context, plus one new context per function call. Each context is created in two phases:"}]}]}},"revision":1},{"id":"0c7f2647-4d8e-7aa9-9657-31b480602e51","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Phase"}],[{"type":"text","text":"What happens"}]],[[{"type":"text","text":"Creation","marks":[{"type":"bold"}]},{"type":"text","text":" (memory)"}],[{"type":"text","text":"Scope is set up; "},{"type":"text","text":"var","marks":[{"type":"code"}]},{"type":"text","text":" names are created as "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":", function declarations are stored in full, "},{"type":"text","text":"let","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"class","marks":[{"type":"code"}]},{"type":"text","text":" names are created but "},{"type":"text","text":"uninitialised","marks":[{"type":"italic"}]},{"type":"text","text":" (TDZ). "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" is determined."}]],[[{"type":"text","text":"Execution","marks":[{"type":"bold"}]}],[{"type":"text","text":"Code runs line by line; assignments fill in the values."}]]]},"revision":1},{"id":"59eca72e-b81c-7bc1-804b-44b9ef8f6403","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"The call stack in action"}]},"revision":1},{"id":"0eff9c61-ab00-789b-8e9b-cbf02ce6caa8","type":"code","position":"aC","content":{"language":"javascript","code":"function third() {\n  console.log(\"3. in third — stack: global → first → second → third\");\n}\nfunction second() {\n  console.log(\"2. in second\");\n  third();\n  console.log(\"4. back in second\");\n}\nfunction first() {\n  console.log(\"1. in first\");\n  second();\n  console.log(\"5. back in first\");\n}\nfirst();","filename":"JavaScript"},"revision":1},{"id":"734311ab-df8a-75a3-8f41-3f3f530d7139","type":"code","position":"aD","content":{"language":"text","code":"1. in first\n2. in second\n3. in third — stack: global → first → second → third\n4. back in second\n5. back in first","filename":"Output"},"revision":1},{"id":"7ebbcbf0-f940-7470-a498-ca51d729e483","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If functions call each other without end, the stack overflows:"}]}]}},"revision":1},{"id":"904a3f58-0ad1-7d90-8530-c8fea3d54ded","type":"code","position":"aF","content":{"language":"javascript","code":"function forever(n) {\n  return forever(n + 1);\n}\ntry {\n  forever(0);\n} catch (e) {\n  console.log(e.name + \": \" + e.message);\n}","filename":"JavaScript"},"revision":1},{"id":"5923ccac-2335-731f-a35f-fbc2057404cf","type":"code","position":"aG","content":{"language":"text","code":"RangeError: Maximum call stack size exceeded","filename":"Output"},"revision":1},{"id":"55efb359-3f87-7d80-8280-579a5b96287a","type":"heading","position":"aH","content":{"level":1,"content":[{"type":"text","text":"Single-threaded, yet non-blocking"}]},"revision":1},{"id":"850d4074-5111-7136-b185-740bd5eeb17a","type":"text","position":"aI","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JavaScript runs your code on "},{"type":"text","text":"one thread","marks":[{"type":"bold"}]},{"type":"text","text":". Slow work (network, disk, timers) is handed to the runtime; when it finishes, a callback is queued and the "},{"type":"text","text":"event loop","marks":[{"type":"bold"}]},{"type":"text","text":" pushes it onto the stack once the stack is empty. See "},{"type":"text","text":"The Event Loop","marks":[{"type":"italic"}]},{"type":"text","text":" topic for the full picture."}]},{"type":"paragraph","content":[{"type":"text","text":"Call stack → Runtime APIs (timers, I/O) → Task queues → Event loop → back to stack"}]}]}},"revision":1},{"id":"0d61e744-0461-7811-868d-d1f18f995270","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is JavaScript interpreted or compiled?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both. Modern engines parse to bytecode and interpret it for fast startup, then JIT-compile hot functions to optimised machine code using runtime type feedback — and can deoptimise if assumptions break."}]}]}},"revision":1},{"id":"1051d5d0-6637-7213-bbaa-fe70482b2d6b","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is an execution context?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The environment a piece of code runs in: its variable environment (scope), the outer-scope reference (scope chain), and the value of "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":". A global context is created first, then one per function call, pushed onto the call stack."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
