SELECT 'e9875f87-5058-7e7b-93e2-0911c9d0cc22', '909f757a-ef20-7427-9584-84b3e93a20f0', 1, 'PUBLISHED', 'IIFE, Recursion & Pure Functions', '[{"id":"3d3a3978-9eff-71cb-8937-89b1b5ec79fb","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three function ideas that show up constantly: run-once scopes, functions that call themselves, and functions with no side effects."}]}]}},"revision":1},{"id":"80798c77-3d63-71f3-9699-45dd890c8c71","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"IIFE — Immediately Invoked Function Expression"}]},"revision":1},{"id":"418d0107-e00f-7589-a8f3-f8ab3f07abd6","type":"code","position":"a2","content":{"language":"javascript","code":"const config = (() => {\n  const env = \"production\";            // not visible outside\n  return { env, debug: env !== \"production\" };\n})();\nconsole.log(config);\n\n(function named() {\n  console.log(\"runs immediately\");\n})();","filename":"JavaScript"},"revision":1},{"id":"d6dec544-ae90-766b-ba75-b1416324b11d","type":"code","position":"a3","content":{"language":"text","code":"{ env: ''production'', debug: false }\nruns immediately","filename":"Output"},"revision":1},{"id":"97222217-376d-7c18-b3cc-07e26d422957","type":"callout","position":"a4","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"IIFEs were the pre-module way to avoid polluting the global scope. Today ES modules and block scope cover most uses; you still see them for one-off "},{"type":"text","text":"async","marks":[{"type":"code"}]},{"type":"text","text":" setup: "},{"type":"text","text":"(async () => { … })()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"0e2395b3-b5f5-7d67-b0e8-3a176444b9c3","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Recursion"}]},"revision":1},{"id":"6f569a2f-575c-7e0a-b0f4-31db9b268fd4","type":"code","position":"a6","content":{"language":"javascript","code":"const factorial = (n) => (n <= 1 ? 1 : n * factorial(n - 1));\nconst flatten = (arr) =>\n  arr.reduce((acc, x) => (Array.isArray(x) ? acc.concat(flatten(x)) : acc.concat(x)), []);\nfunction fib(n, memo = {}) {\n  if (n <= 1) return n;\n  return (memo[n] ??= fib(n - 1, memo) + fib(n - 2, memo));\n}\nconsole.log(factorial(5), flatten([1, [2, [3, [4]]]]), fib(50));","filename":"JavaScript"},"revision":1},{"id":"2925b243-5a34-73a9-9c9c-0e3c6fbcd746","type":"code","position":"a7","content":{"language":"text","code":"120 [ 1, 2, 3, 4 ] 12586269025","filename":"Output"},"revision":1},{"id":"53ff12e1-4987-7628-8b4d-d7407abfcbcc","type":"callout","position":"a8","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"There is no practical tail-call optimisation in V8 or SpiderMonkey (only Safari implements it). Deep recursion (≈10k frames) throws "},{"type":"text","text":"RangeError: Maximum call stack size exceeded","marks":[{"type":"code"}]},{"type":"text","text":" — convert to a loop or an explicit stack."}]}]}},"revision":1},{"id":"b8660a20-3883-7a7e-9634-b72498c5a02b","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Pure functions and side effects"}]},"revision":1},{"id":"49f2a2d8-29ea-7ac3-aa19-99fb0aa8683f","type":"callout","position":"aA","content":{"variant":"note","title":"Pure","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Same input → same output, and no side effects (no mutation of arguments/globals, no I/O). Easy to test, cache and reason about."}]}]}},"revision":1},{"id":"bfb7fe77-44d8-7254-a2cd-1691e572c13d","type":"callout","position":"aB","content":{"variant":"note","title":"Impure","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reads or writes outside state: "},{"type":"text","text":"Math.random()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Date.now()","marks":[{"type":"code"}]},{"type":"text","text":", DOM, network, mutating a parameter."}]}]}},"revision":1},{"id":"db333d5c-d4aa-7d4a-ae6f-96416d1006f8","type":"code","position":"aC","content":{"language":"javascript","code":"const addItemImpure = (cart, item) => { cart.push(item); return cart; };\nconst addItemPure = (cart, item) => [...cart, item];\n\nconst cart = [\"apple\"];\nconst next = addItemPure(cart, \"pear\");\nconsole.log(cart, next);\naddItemImpure(cart, \"plum\");\nconsole.log(cart);","filename":"JavaScript"},"revision":1},{"id":"188b17fe-de10-7698-9050-95c050ed7431","type":"code","position":"aD","content":{"language":"text","code":"[ ''apple'' ] [ ''apple'', ''pear'' ]\n[ ''apple'', ''plum'' ]","filename":"Output"},"revision":1},{"id":"79d629bf-a17c-70e8-81d8-5b28789d2db1","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a pure function and why does it matter?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A function whose output depends only on its inputs and that causes no observable side effects. Pure functions are predictable, trivially testable, safe to memoize and parallelise, and are the basis of React reducers and Redux."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
