SELECT 'f6137c3a-8201-78b1-9986-45090480a6fa', 'd97d12d7-0b92-757f-8611-83203bde9702', 1, 'PUBLISHED', 'Inheritance: extends & super', '[{"id":"b3d17844-df7c-7f7f-abb6-86509d2ee997","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"extends","marks":[{"type":"code"}]},{"type":"text","text":" sets up the prototype chain between two classes; "},{"type":"text","text":"super","marks":[{"type":"code"}]},{"type":"text","text":" calls the parent''s constructor and methods."}]}]}},"revision":1},{"id":"bcb31264-4d36-71c9-8e0e-4659873fda92","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Extending a class"}]},"revision":1},{"id":"135c6843-3415-79df-a836-02e5f5159246","type":"code","position":"a2","content":{"language":"javascript","code":"class Shape {\n  constructor(name) { this.name = name; }\n  area() { return 0; }\n  toString() { return `${this.name} with area ${this.area().toFixed(2)}`; }\n  static create(...args) { return new this(...args); }   // `this` = the called class\n}\nclass Circle extends Shape {\n  constructor(r) {\n    super(\"Circle\");           // must come before using `this`\n    this.r = r;\n  }\n  area() { return Math.PI * this.r ** 2; }                // override\n}\nclass Square extends Shape {\n  constructor(side) { super(\"Square\"); this.side = side; }\n  area() { return this.side ** 2; }\n  toString() { return \"■ \" + super.toString(); }          // extend parent method\n}\n\nconst shapes = [new Circle(1), Square.create(2)];\nfor (const s of shapes) console.log(String(s));\nconsole.log(shapes[1] instanceof Square, shapes[1] instanceof Shape);","filename":"JavaScript"},"revision":1},{"id":"87f13fb5-3005-7d80-8954-9fc5244cda7b","type":"code","position":"a3","content":{"language":"text","code":"Circle with area 3.14\n■ Square with area 4.00\ntrue true","filename":"Output"},"revision":1},{"id":"98c3b476-a721-73eb-9e39-c409c978ed7f","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Rules for super"}]},"revision":1},{"id":"85b1adc8-ed07-74be-9a63-c11c463e8af3","type":"code","position":"a5","content":{"language":"javascript","code":"class Parent {}\nclass Child extends Parent {\n  constructor() {\n    this.x = 1;       // before super() → error\n    super();\n  }\n}\ntry {\n  new Child();\n} catch (e) {\n  console.log(e.name + \": \" + e.message);\n}","filename":"JavaScript"},"revision":1},{"id":"e7c2b60a-b284-7555-8fb0-e39e66515f2f","type":"code","position":"a6","content":{"language":"text","code":"ReferenceError: Must call super constructor in derived class before accessing ''this'' or returning from derived constructor","filename":"Output"},"revision":1},{"id":"55c2d0ca-9d15-7945-a309-936c5afeaec8","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A subclass without its own "},{"type":"text","text":"constructor","marks":[{"type":"code"}]},{"type":"text","text":" gets "},{"type":"text","text":"constructor(...args) { super(...args); }","marks":[{"type":"code"}]},{"type":"text","text":" automatically."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"super(...)","marks":[{"type":"code"}]},{"type":"text","text":" only in constructors; "},{"type":"text","text":"super.method()","marks":[{"type":"code"}]},{"type":"text","text":" in any method (also static methods)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Parent fields are initialised when "},{"type":"text","text":"super()","marks":[{"type":"code"}]},{"type":"text","text":" returns; child fields right after."}]}]}]}]}},"revision":1},{"id":"cfa8d2fb-2197-7c0d-a35e-0d9f76fdc958","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Polymorphism and the chain"}]},"revision":1},{"id":"aa0f5660-095f-797f-bbe4-8c70b18868ed","type":"code","position":"a9","content":{"language":"javascript","code":"class Animal { speak() { return \"...\"; } }\nclass Dog extends Animal { speak() { return \"Woof\"; } }\nclass Puppy extends Dog { speak() { return super.speak() + \" (squeaky)\"; } }\n\nfor (const a of [new Animal(), new Dog(), new Puppy()]) {\n  console.log(a.constructor.name.padEnd(6), a.speak());\n}\nconsole.log(Object.getPrototypeOf(Puppy) === Dog);                    // static inheritance\nconsole.log(Object.getPrototypeOf(Puppy.prototype) === Dog.prototype); // instance inheritance","filename":"JavaScript"},"revision":1},{"id":"72569ffa-a9c2-706a-bbfc-ec3167f99b20","type":"code","position":"aA","content":{"language":"text","code":"Animal ...\nDog    Woof\nPuppy  Woof (squeaky)\ntrue\ntrue","filename":"Output"},"revision":1},{"id":"125c0422-2c1b-7e59-b495-d5aff4beeacb","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Extending built-ins"}]},"revision":1},{"id":"8c210106-7e86-7eee-b4f6-c8276bfb2434","type":"code","position":"aC","content":{"language":"javascript","code":"class Stack extends Array {\n  peek() { return this.at(-1); }\n}\nconst s = Stack.from([1, 2, 3]);\ns.push(4);\nconsole.log(s.peek(), s.length, s instanceof Array);\nconsole.log(s.map((x) => x * 2) instanceof Stack);   // derived methods return Stack\n\nclass ValidationError extends Error {\n  constructor(field) {\n    super(`${field} is invalid`);\n    this.name = \"ValidationError\";\n    this.field = field;\n  }\n}\nconst err = new ValidationError(\"email\");\nconsole.log(err.name, err.message, err instanceof Error);","filename":"JavaScript"},"revision":1},{"id":"a6896850-d26b-765e-8f65-4597dd2954fa","type":"code","position":"aD","content":{"language":"text","code":"4 4 true\ntrue\nValidationError email is invalid true","filename":"Output"},"revision":1},{"id":"181f5310-bd89-7783-b00b-3c939df09bc5","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Composition over inheritance"}]},"revision":1},{"id":"4634627c-b207-7608-b07f-3aa366cd479f","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Deep hierarchies are brittle. Often it is simpler to "},{"type":"text","text":"compose","marks":[{"type":"bold"}]},{"type":"text","text":" behaviours: build objects from small functions or "},{"type":"text","text":"mixins","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"724be8f3-0925-7070-9d7a-20521792943d","type":"code","position":"aG","content":{"language":"javascript","code":"const canFly = (Base) => class extends Base { fly() { return `${this.name} flies`; } };\nconst canSwim = (Base) => class extends Base { swim() { return `${this.name} swims`; } };\nclass Creature { constructor(name) { this.name = name; } }\nclass Duck extends canSwim(canFly(Creature)) {}\n\nconst d = new Duck(\"Donald\");\nconsole.log(d.fly(), \"/\", d.swim());\n\n// object composition with plain functions\nconst withLogger = (obj) => ({ ...obj, log: (msg) => `[${obj.name}] ${msg}` });\nconst service = withLogger({ name: \"api\" });\nconsole.log(service.log(\"started\"));","filename":"JavaScript"},"revision":1},{"id":"d76afaf5-8a29-770c-96a9-4ccb2b027c51","type":"code","position":"aH","content":{"language":"text","code":"Donald flies / Donald swims\n[api] started","filename":"Output"},"revision":1},{"id":"eb8914f7-9b08-7a87-9375-1b808d2989d5","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why must super() be called before this in a derived constructor?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In a derived class the parent constructor is responsible for creating the object. Until "},{"type":"text","text":"super()","marks":[{"type":"code"}]},{"type":"text","text":" runs there is no "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" to use, so accessing it throws a "},{"type":"text","text":"ReferenceError","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"a069082a-1022-7c40-97c5-629225273f86","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does JavaScript support multiple inheritance?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No — an object has exactly one prototype. You get similar results with mixins (functions that take a class and return an extended class), "},{"type":"text","text":"Object.assign","marks":[{"type":"code"}]},{"type":"text","text":" of method objects, or composition."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
