SELECT '588301e1-d72a-71c5-ab54-97093c9c7fac', '1f74eba1-3c7f-72d5-8f05-98bd2d791afa', 1, 'PUBLISHED', 'JavaScript Interview Q&A', '[{"id":"989f51c0-c9dc-7130-90e9-ec8cf1a1e985","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rapid-fire questions from junior to senior level. Expand each for a crisp, interview-ready answer; follow the topic links in your head to go deeper."}]}]}},"revision":1},{"id":"c25817fe-032c-7233-8c10-e1e0105dc300","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Fundamentals"}]},"revision":1},{"id":"d6d62ccf-eb37-7944-99ab-c5e965eeaf9e","type":"question","position":"a2","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the data types in JavaScript?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Seven primitives — "},{"type":"text","text":"number","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"bigint","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"string","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"boolean","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"symbol","marks":[{"type":"code"}]},{"type":"text","text":" — and "},{"type":"text","text":"object","marks":[{"type":"code"}]},{"type":"text","text":" (which includes arrays, functions, dates, maps…). Primitives are immutable and compared by value; objects are compared by reference."}]}]}},"revision":1},{"id":"5a9613ba-51f6-7b2e-8258-df39134e5e21","type":"question","position":"a3","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"var vs let vs const?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"var","marks":[{"type":"code"}]},{"type":"text","text":": function scope, hoisted as "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":", re-declarable. "},{"type":"text","text":"let","marks":[{"type":"code"}]},{"type":"text","text":": block scope, TDZ, reassignable. "},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":": block scope, TDZ, no reassignment (object contents still mutable)."}]}]}},"revision":1},{"id":"2440ba72-c1f5-7850-81fe-b0bbcc875927","type":"question","position":"a4","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the temporal dead zone?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The span between entering a scope and the line where a "},{"type":"text","text":"let","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"class","marks":[{"type":"code"}]},{"type":"text","text":" is declared. The binding exists (it is hoisted) but is uninitialised; any access throws "},{"type":"text","text":"ReferenceError","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"815badf5-06b9-7329-a204-d9c2af18e532","type":"question","position":"a5","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"null vs undefined?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":" means a value was never assigned (missing variable value, property, argument or return). "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" is an explicit “empty” set by the programmer. "},{"type":"text","text":"null == undefined","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"===","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"false","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"typeof null","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"\"object\"","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"c6555e3a-8fee-7e2d-95c1-917e9ae06fd5","type":"question","position":"a6","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"== vs ===?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"===","marks":[{"type":"code"}]},{"type":"text","text":" compares type and value with no conversion. "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" coerces operands first (e.g. "},{"type":"text","text":"''1'' == 1","marks":[{"type":"code"}]},{"type":"text","text":"). Use "},{"type":"text","text":"===","marks":[{"type":"code"}]},{"type":"text","text":", except "},{"type":"text","text":"x == null","marks":[{"type":"code"}]},{"type":"text","text":" to test for null-or-undefined."}]}]}},"revision":1},{"id":"9f81a3f9-c10c-7dc5-851a-a042d7df7da3","type":"question","position":"a7","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is NaN and how do you test for it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"“Not a Number”, a "},{"type":"text","text":"number","marks":[{"type":"code"}]},{"type":"text","text":" value produced by invalid maths ("},{"type":"text","text":"0/0","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Number(''x'')","marks":[{"type":"code"}]},{"type":"text","text":"). It is not equal to itself, so use "},{"type":"text","text":"Number.isNaN(x)","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Object.is(x, NaN)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ab85cde2-0baf-76d0-bc72-f97ae63782f5","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Functions & scope"}]},"revision":1},{"id":"984287b0-29cb-781b-9650-5fd897c117c6","type":"question","position":"a9","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a closure?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A function plus the lexical environment it was created in. Inner functions keep access to outer variables after the outer function returns — used for private state, factories, memoization, and callbacks."}]}]}},"revision":1},{"id":"48e2f658-ff63-735a-b097-3cedeb6c7af0","type":"question","position":"aA","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is hoisting?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Declarations are processed before code runs: function declarations are fully available, "},{"type":"text","text":"var","marks":[{"type":"code"}]},{"type":"text","text":"s are "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"let","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"class","marks":[{"type":"code"}]},{"type":"text","text":" sit in the TDZ."}]}]}},"revision":1},{"id":"4917c409-a315-79af-abfc-884d40aec8e5","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain this in JavaScript."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Determined at call time: "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":" → new object; "},{"type":"text","text":"call/apply/bind","marks":[{"type":"code"}]},{"type":"text","text":" → given object; "},{"type":"text","text":"obj.fn()","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"obj","marks":[{"type":"code"}]},{"type":"text","text":"; plain call → "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":" (strict) or global (sloppy). Arrow functions inherit "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" lexically."}]}]}},"revision":1},{"id":"388c038a-afe9-7b25-9aee-b9a4a84e9a94","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"call vs apply vs bind?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"call(this, a, b)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"apply(this, [a, b])","marks":[{"type":"code"}]},{"type":"text","text":" invoke immediately; "},{"type":"text","text":"bind(this, a)","marks":[{"type":"code"}]},{"type":"text","text":" returns a new permanently bound function."}]}]}},"revision":1},{"id":"2d657b88-5987-717f-a54d-56a555a915a3","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrow functions vs regular functions?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrows have lexical "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"arguments","marks":[{"type":"code"}]},{"type":"text","text":", cannot be constructors, have no "},{"type":"text","text":"prototype","marks":[{"type":"code"}]},{"type":"text","text":", and are always expressions. Regular functions get a dynamic "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" and can be used with "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"e4df25fc-b2c9-7d61-bb87-ea8ecca18387","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are higher-order functions?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Functions that take functions as arguments or return functions — "},{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"filter","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"reduce","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"setTimeout","marks":[{"type":"code"}]},{"type":"text","text":", decorators like "},{"type":"text","text":"debounce","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"memoize","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"2a7481a8-01df-7618-9cfd-93606180f5c3","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Currying vs partial application?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Currying turns an n-ary function into n unary functions "},{"type":"text","text":"f(a)(b)(c)","marks":[{"type":"code"}]},{"type":"text","text":". Partial application fixes some arguments and returns a function taking the rest ("},{"type":"text","text":"bind","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"partial","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"8fe512d2-2d5a-736f-8e01-03ad484b4105","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Objects & prototypes"}]},"revision":1},{"id":"a99ccb93-b673-70b1-8b34-2b4830f7e92e","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does prototypal inheritance work?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every object links to a prototype. Missing properties are looked up along the chain until "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"class","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"extends","marks":[{"type":"code"}]},{"type":"text","text":" builds these chains; methods are shared through "},{"type":"text","text":"Class.prototype","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"793bc949-9112-7d4e-941c-9dc5c8ca9dae","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does the new keyword do?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Creates an object, links it to "},{"type":"text","text":"Ctor.prototype","marks":[{"type":"code"}]},{"type":"text","text":", runs the constructor with "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" bound to it, and returns it (unless the constructor returns another object)."}]}]}},"revision":1},{"id":"41da959a-edd9-7035-80d5-e0ead6a214b4","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you deep-copy an object?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"structuredClone(obj)","marks":[{"type":"code"}]},{"type":"text","text":" (handles Dates, Maps, Sets, cycles; not functions or class prototypes). "},{"type":"text","text":"JSON.parse(JSON.stringify(obj))","marks":[{"type":"code"}]},{"type":"text","text":" only for JSON-safe data. Spread and "},{"type":"text","text":"Object.assign","marks":[{"type":"code"}]},{"type":"text","text":" are shallow."}]}]}},"revision":1},{"id":"b029cea9-8e8c-7b2d-8251-cbfcbf765aa1","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Object.freeze vs Object.seal?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both stop adding/removing properties; "},{"type":"text","text":"freeze","marks":[{"type":"code"}]},{"type":"text","text":" also makes values read-only. Both are shallow."}]}]}},"revision":1},{"id":"e907607e-5c31-7c0b-ae5b-89ce4a848426","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Map vs Object, Set vs Array?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Map","marks":[{"type":"code"}]},{"type":"text","text":": any key type, insertion order, "},{"type":"text","text":"size","marks":[{"type":"code"}]},{"type":"text","text":", fast frequent updates, no prototype keys. "},{"type":"text","text":"Set","marks":[{"type":"code"}]},{"type":"text","text":": unique values with O(1) "},{"type":"text","text":"has","marks":[{"type":"code"}]},{"type":"text","text":", versus an array''s O(n) "},{"type":"text","text":"includes","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"4ed2bbd5-f675-75e8-9ba9-6d99aba6b845","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are WeakMap and WeakSet for?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Associating data with objects without preventing their garbage collection — private data, caches, “visited” marks. Keys must be objects; they are not iterable."}]}]}},"revision":1},{"id":"19ad725b-e818-75b9-8563-fac9ad8c8b60","type":"heading","position":"aN","content":{"level":1,"content":[{"type":"text","text":"Asynchronous JavaScript"}]},"revision":1},{"id":"8df9b007-5e28-7494-a2d9-395a44b42454","type":"question","position":"aO","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain the event loop."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JS runs on one call stack. Async work is delegated to the runtime; completions queue callbacks. When the stack is empty the loop drains all microtasks (promise reactions), then runs the next macrotask (timer, I/O, event), and in browsers may render between tasks."}]}]}},"revision":1},{"id":"8957a9ea-e1fa-7441-a30a-e4e8dacdd3cc","type":"question","position":"aP","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Microtask vs macrotask?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Microtasks: promise "},{"type":"text","text":"then","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"catch","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":" continuations, "},{"type":"text","text":"queueMicrotask","marks":[{"type":"code"}]},{"type":"text","text":" — all run right after the current task. Macrotasks: "},{"type":"text","text":"setTimeout","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"setInterval","marks":[{"type":"code"}]},{"type":"text","text":", I/O, UI events — one per loop turn. Hence "},{"type":"text","text":"Promise.then","marks":[{"type":"code"}]},{"type":"text","text":" runs before "},{"type":"text","text":"setTimeout(…, 0)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"b61682ed-945a-7cd6-be6d-548586d5048e","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a Promise?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An object representing the eventual result of an async operation; pending → fulfilled/rejected, settled once. "},{"type":"text","text":"then","marks":[{"type":"code"}]},{"type":"text","text":" returns a new promise, enabling chaining and centralised error handling with "},{"type":"text","text":"catch","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"27c43a36-1252-727d-8e4e-2c69fcc38b80","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Promise.all vs allSettled vs race vs any?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"all","marks":[{"type":"code"}]},{"type":"text","text":": all fulfil or first rejection. "},{"type":"text","text":"allSettled","marks":[{"type":"code"}]},{"type":"text","text":": waits for all, reports each. "},{"type":"text","text":"race","marks":[{"type":"code"}]},{"type":"text","text":": first to settle. "},{"type":"text","text":"any","marks":[{"type":"code"}]},{"type":"text","text":": first to fulfil, "},{"type":"text","text":"AggregateError","marks":[{"type":"code"}]},{"type":"text","text":" if all reject."}]}]}},"revision":1},{"id":"d3586668-6d43-70e0-8f84-d081eb70842f","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does async/await relate to promises?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Syntax sugar: an "},{"type":"text","text":"async","marks":[{"type":"code"}]},{"type":"text","text":" function returns a promise; "},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":" pauses that function until a promise settles, resuming with its value or throwing its reason, so "},{"type":"text","text":"try/catch","marks":[{"type":"code"}]},{"type":"text","text":" works."}]}]}},"revision":1},{"id":"179d954a-6955-7c5d-b5ce-3714af044435","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you run async tasks in parallel vs in sequence?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Parallel: start them all, then "},{"type":"text","text":"await Promise.all([...])","marks":[{"type":"code"}]},{"type":"text","text":". Sequence: "},{"type":"text","text":"for…of","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":" inside. Never "},{"type":"text","text":"forEach","marks":[{"type":"code"}]},{"type":"text","text":" with an async callback."}]}]}},"revision":1},{"id":"2e7ad49b-94f6-7c07-b034-ebda6be4cff8","type":"question","position":"aU","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you cancel a fetch or other async work?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pass an "},{"type":"text","text":"AbortController","marks":[{"type":"code"}]},{"type":"text","text":"''s "},{"type":"text","text":"signal","marks":[{"type":"code"}]},{"type":"text","text":" to "},{"type":"text","text":"fetch","marks":[{"type":"code"}]},{"type":"text","text":" (or your own function), then call "},{"type":"text","text":"controller.abort()","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"AbortSignal.timeout(ms)","marks":[{"type":"code"}]},{"type":"text","text":" gives a ready-made timeout signal."}]}]}},"revision":1},{"id":"aa0e8372-f9fb-7bb5-9d81-1eeed539da76","type":"heading","position":"aV","content":{"level":1,"content":[{"type":"text","text":"Browser & performance"}]},"revision":1},{"id":"27862252-52c7-7971-a827-df5ee051af25","type":"question","position":"aW","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is event delegation?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One listener on a parent handles events from many children via bubbling and "},{"type":"text","text":"event.target.closest(...)","marks":[{"type":"code"}]},{"type":"text","text":" — fewer listeners and it works for elements added later."}]}]}},"revision":1},{"id":"04fadb37-2193-7262-830a-854d068bfc1c","type":"question","position":"aX","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Event bubbling vs capturing?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Events travel from window down to the target (capture), then back up (bubble). Listeners run in the bubble phase unless registered with "},{"type":"text","text":"{ capture: true }","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"stopPropagation()","marks":[{"type":"code"}]},{"type":"text","text":" halts the journey."}]}]}},"revision":1},{"id":"502c6e5a-1153-76e1-a12b-33c513e8a55e","type":"question","position":"aY","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Debounce vs throttle?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Debounce runs once after activity stops for N ms (search input). Throttle runs at most once every N ms during activity (scroll)."}]}]}},"revision":1},{"id":"110b4ed0-6099-73db-9adb-1672c74af3f4","type":"question","position":"aZ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What causes memory leaks in JavaScript?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Anything that keeps unused objects reachable: uncleared intervals, listeners never removed, unbounded caches, closures holding big data, detached DOM nodes referenced from JS, accidental globals."}]}]}},"revision":1},{"id":"ea49fc3a-475f-7698-82e1-572b74368d84","type":"question","position":"aa","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"localStorage vs sessionStorage vs cookies?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"localStorage persists, sessionStorage is per-tab; both ~5 MB, JS-only. Cookies are small, sent with requests, and can be HttpOnly — use them for auth."}]}]}},"revision":1},{"id":"717e0b52-9c11-7a9b-a0bd-331262c6e27d","type":"question","position":"ab","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is CORS?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A browser mechanism that lets servers opt in to cross-origin reads via "},{"type":"text","text":"Access-Control-Allow-*","marks":[{"type":"code"}]},{"type":"text","text":" headers, with preflight "},{"type":"text","text":"OPTIONS","marks":[{"type":"code"}]},{"type":"text","text":" requests for non-simple requests. It protects users; it is enforced by browsers, not servers."}]}]}},"revision":1},{"id":"c01c3c17-acc3-78b2-9d45-00bee81ba862","type":"heading","position":"ac","content":{"level":1,"content":[{"type":"text","text":"Modules, tooling & modern JS"}]},"revision":1},{"id":"c5295468-a9bd-77b6-89ee-806046156ac4","type":"question","position":"ad","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ES modules vs CommonJS?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ESM: static "},{"type":"text","text":"import","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"export","marks":[{"type":"code"}]},{"type":"text","text":", live bindings, async loading, top-level await, strict by default, tree-shakable. CJS: runtime "},{"type":"text","text":"require","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"module.exports","marks":[{"type":"code"}]},{"type":"text","text":" object, synchronous, Node-specific."}]}]}},"revision":1},{"id":"af39de47-b9dd-730f-bdd0-92e2b8fa48c8","type":"question","position":"ae","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is strict mode?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A safer JS variant: undeclared assignments throw, "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":" in plain calls, silent failures become errors, "},{"type":"text","text":"with","marks":[{"type":"code"}]},{"type":"text","text":" is banned. Automatic in modules and classes."}]}]}},"revision":1},{"id":"d5b4d06e-24d0-7287-9fa4-c773509b30f0","type":"question","position":"af","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a polyfill vs a transpiler?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A polyfill adds a missing built-in API at runtime (e.g. "},{"type":"text","text":"Array.prototype.flat","marks":[{"type":"code"}]},{"type":"text","text":"). A transpiler (Babel, TypeScript) rewrites new "},{"type":"text","text":"syntax","marks":[{"type":"italic"}]},{"type":"text","text":" into older syntax at build time."}]}]}},"revision":1},{"id":"0befee30-961e-72a8-97ee-b9719bed40b2","type":"question","position":"ag","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why use TypeScript?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Static types catch errors at compile time, power editor autocompletion and safe refactoring, and document intent. It compiles to plain JavaScript; types disappear at runtime."}]}]}},"revision":1},{"id":"11f2b37c-7d26-7e56-b120-b96ec6eb307b","type":"question","position":"ah","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are generators used for?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Functions that can pause with "},{"type":"text","text":"yield","marks":[{"type":"code"}]},{"type":"text","text":" — lazy/infinite sequences, custom iterators, two-way coroutines, and (async generators) streaming data such as paginated APIs."}]}]}},"revision":1},{"id":"cd40a79f-26c4-7c49-94de-6a5ff0180c14","type":"question","position":"ai","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a Proxy?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A wrapper that intercepts operations (get, set, has, delete, apply…) on a target object — used for validation, reactivity (Vue 3), logging and virtual properties. "},{"type":"text","text":"Reflect","marks":[{"type":"code"}]},{"type":"text","text":" supplies the default behaviour."}]}]}},"revision":1},{"id":"dfc7ed01-af26-724a-a31e-883d1baca669","type":"heading","position":"aj","content":{"level":1,"content":[{"type":"text","text":"How to answer well"}]},"revision":1},{"id":"e16d61cd-3e0c-7137-b2dc-8c1722112566","type":"text","position":"ak","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Define","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"One precise sentence (“A closure is…”)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Show","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"A 3–5 line example — ideally one you can run in your head."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain the why","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Mention the underlying mechanism (scope chain, prototype chain, event loop)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Trade-offs & pitfalls","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"When not to use it, the common bug, the modern alternative."}]}]}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
