INSERT INTO "notes"."Card" ("id", "noteId", "position", "type", "content", "revision", "createdAt", "updatedAt")
SELECT c.id::uuid, '1f74eba1-3c7f-72d5-8f05-98bd2d791afa', c.position, c.type::"notes"."CardType", c.content::jsonb, 1, TIMESTAMPTZ '2026-10-07 03:23:53+00', TIMESTAMPTZ '2026-10-07 03:23:53+00'
FROM (VALUES
  ('989f51c0-c9dc-7130-90e9-ec8cf1a1e985', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rapid-fire questions from junior to senior level. Expand each for a crisp, interview-ready answer; follow the topic links in your head to go deeper."}]}]}}'),
  ('c25817fe-032c-7233-8c10-e1e0105dc300', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"Fundamentals"}]}'),
  ('d6d62ccf-eb37-7944-99ab-c5e965eeaf9e', 'a2', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the data types in JavaScript?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Seven primitives — "},{"type":"text","text":"number","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"bigint","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"string","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"boolean","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"symbol","marks":[{"type":"code"}]},{"type":"text","text":" — and "},{"type":"text","text":"object","marks":[{"type":"code"}]},{"type":"text","text":" (which includes arrays, functions, dates, maps…). Primitives are immutable and compared by value; objects are compared by reference."}]}]}}'),
  ('5a9613ba-51f6-7b2e-8258-df39134e5e21', 'a3', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"var vs let vs const?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"var","marks":[{"type":"code"}]},{"type":"text","text":": function scope, hoisted as "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":", re-declarable. "},{"type":"text","text":"let","marks":[{"type":"code"}]},{"type":"text","text":": block scope, TDZ, reassignable. "},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":": block scope, TDZ, no reassignment (object contents still mutable)."}]}]}}'),
  ('2440ba72-c1f5-7850-81fe-b0bbcc875927', 'a4', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the temporal dead zone?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The span between entering a scope and the line where a "},{"type":"text","text":"let","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"class","marks":[{"type":"code"}]},{"type":"text","text":" is declared. The binding exists (it is hoisted) but is uninitialised; any access throws "},{"type":"text","text":"ReferenceError","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('815badf5-06b9-7329-a204-d9c2af18e532', 'a5', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"null vs undefined?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":" means a value was never assigned (missing variable value, property, argument or return). "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":" is an explicit “empty” set by the programmer. "},{"type":"text","text":"null == undefined","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"true","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"===","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"false","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"typeof null","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"\"object\"","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('c6555e3a-8fee-7e2d-95c1-917e9ae06fd5', 'a6', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"== vs ===?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"===","marks":[{"type":"code"}]},{"type":"text","text":" compares type and value with no conversion. "},{"type":"text","text":"==","marks":[{"type":"code"}]},{"type":"text","text":" coerces operands first (e.g. "},{"type":"text","text":"''1'' == 1","marks":[{"type":"code"}]},{"type":"text","text":"). Use "},{"type":"text","text":"===","marks":[{"type":"code"}]},{"type":"text","text":", except "},{"type":"text","text":"x == null","marks":[{"type":"code"}]},{"type":"text","text":" to test for null-or-undefined."}]}]}}'),
  ('9f81a3f9-c10c-7dc5-851a-a042d7df7da3', 'a7', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is NaN and how do you test for it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"“Not a Number”, a "},{"type":"text","text":"number","marks":[{"type":"code"}]},{"type":"text","text":" value produced by invalid maths ("},{"type":"text","text":"0/0","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Number(''x'')","marks":[{"type":"code"}]},{"type":"text","text":"). It is not equal to itself, so use "},{"type":"text","text":"Number.isNaN(x)","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"Object.is(x, NaN)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('ab85cde2-0baf-76d0-bc72-f97ae63782f5', 'a8', 'heading', '{"level":1,"content":[{"type":"text","text":"Functions & scope"}]}'),
  ('984287b0-29cb-781b-9650-5fd897c117c6', 'a9', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a closure?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A function plus the lexical environment it was created in. Inner functions keep access to outer variables after the outer function returns — used for private state, factories, memoization, and callbacks."}]}]}}'),
  ('48e2f658-ff63-735a-b097-3cedeb6c7af0', 'aA', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is hoisting?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Declarations are processed before code runs: function declarations are fully available, "},{"type":"text","text":"var","marks":[{"type":"code"}]},{"type":"text","text":"s are "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"let","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"const","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"class","marks":[{"type":"code"}]},{"type":"text","text":" sit in the TDZ."}]}]}}'),
  ('4917c409-a315-79af-abfc-884d40aec8e5', 'aB', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain this in JavaScript."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Determined at call time: "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":" → new object; "},{"type":"text","text":"call/apply/bind","marks":[{"type":"code"}]},{"type":"text","text":" → given object; "},{"type":"text","text":"obj.fn()","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"obj","marks":[{"type":"code"}]},{"type":"text","text":"; plain call → "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":" (strict) or global (sloppy). Arrow functions inherit "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" lexically."}]}]}}'),
  ('388c038a-afe9-7b25-9aee-b9a4a84e9a94', 'aC', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"call vs apply vs bind?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"call(this, a, b)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"apply(this, [a, b])","marks":[{"type":"code"}]},{"type":"text","text":" invoke immediately; "},{"type":"text","text":"bind(this, a)","marks":[{"type":"code"}]},{"type":"text","text":" returns a new permanently bound function."}]}]}}'),
  ('2d657b88-5987-717f-a54d-56a555a915a3', 'aD', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrow functions vs regular functions?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Arrows have lexical "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"arguments","marks":[{"type":"code"}]},{"type":"text","text":", cannot be constructors, have no "},{"type":"text","text":"prototype","marks":[{"type":"code"}]},{"type":"text","text":", and are always expressions. Regular functions get a dynamic "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" and can be used with "},{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('e4df25fc-b2c9-7d61-bb87-ea8ecca18387', 'aE', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are higher-order functions?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Functions that take functions as arguments or return functions — "},{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"filter","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"reduce","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"setTimeout","marks":[{"type":"code"}]},{"type":"text","text":", decorators like "},{"type":"text","text":"debounce","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"memoize","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('2a7481a8-01df-7618-9cfd-93606180f5c3', 'aF', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Currying vs partial application?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Currying turns an n-ary function into n unary functions "},{"type":"text","text":"f(a)(b)(c)","marks":[{"type":"code"}]},{"type":"text","text":". Partial application fixes some arguments and returns a function taking the rest ("},{"type":"text","text":"bind","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"partial","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}}'),
  ('8fe512d2-2d5a-736f-8e01-03ad484b4105', 'aG', 'heading', '{"level":1,"content":[{"type":"text","text":"Objects & prototypes"}]}'),
  ('a99ccb93-b673-70b1-8b34-2b4830f7e92e', 'aH', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does prototypal inheritance work?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every object links to a prototype. Missing properties are looked up along the chain until "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"class","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"extends","marks":[{"type":"code"}]},{"type":"text","text":" builds these chains; methods are shared through "},{"type":"text","text":"Class.prototype","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('793bc949-9112-7d4e-941c-9dc5c8ca9dae', 'aI', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does the new keyword do?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Creates an object, links it to "},{"type":"text","text":"Ctor.prototype","marks":[{"type":"code"}]},{"type":"text","text":", runs the constructor with "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":" bound to it, and returns it (unless the constructor returns another object)."}]}]}}'),
  ('41da959a-edd9-7035-80d5-e0ead6a214b4', 'aJ', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you deep-copy an object?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"structuredClone(obj)","marks":[{"type":"code"}]},{"type":"text","text":" (handles Dates, Maps, Sets, cycles; not functions or class prototypes). "},{"type":"text","text":"JSON.parse(JSON.stringify(obj))","marks":[{"type":"code"}]},{"type":"text","text":" only for JSON-safe data. Spread and "},{"type":"text","text":"Object.assign","marks":[{"type":"code"}]},{"type":"text","text":" are shallow."}]}]}}'),
  ('b029cea9-8e8c-7b2d-8251-cbfcbf765aa1', 'aK', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Object.freeze vs Object.seal?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both stop adding/removing properties; "},{"type":"text","text":"freeze","marks":[{"type":"code"}]},{"type":"text","text":" also makes values read-only. Both are shallow."}]}]}}'),
  ('e907607e-5c31-7c0b-ae5b-89ce4a848426', 'aL', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Map vs Object, Set vs Array?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Map","marks":[{"type":"code"}]},{"type":"text","text":": any key type, insertion order, "},{"type":"text","text":"size","marks":[{"type":"code"}]},{"type":"text","text":", fast frequent updates, no prototype keys. "},{"type":"text","text":"Set","marks":[{"type":"code"}]},{"type":"text","text":": unique values with O(1) "},{"type":"text","text":"has","marks":[{"type":"code"}]},{"type":"text","text":", versus an array''s O(n) "},{"type":"text","text":"includes","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('4ed2bbd5-f675-75e8-9ba9-6d99aba6b845', 'aM', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are WeakMap and WeakSet for?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Associating data with objects without preventing their garbage collection — private data, caches, “visited” marks. Keys must be objects; they are not iterable."}]}]}}'),
  ('19ad725b-e818-75b9-8563-fac9ad8c8b60', 'aN', 'heading', '{"level":1,"content":[{"type":"text","text":"Asynchronous JavaScript"}]}'),
  ('8df9b007-5e28-7494-a2d9-395a44b42454', 'aO', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Explain the event loop."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JS runs on one call stack. Async work is delegated to the runtime; completions queue callbacks. When the stack is empty the loop drains all microtasks (promise reactions), then runs the next macrotask (timer, I/O, event), and in browsers may render between tasks."}]}]}}'),
  ('8957a9ea-e1fa-7441-a30a-e4e8dacdd3cc', 'aP', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Microtask vs macrotask?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Microtasks: promise "},{"type":"text","text":"then","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"catch","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"finally","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":" continuations, "},{"type":"text","text":"queueMicrotask","marks":[{"type":"code"}]},{"type":"text","text":" — all run right after the current task. Macrotasks: "},{"type":"text","text":"setTimeout","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"setInterval","marks":[{"type":"code"}]},{"type":"text","text":", I/O, UI events — one per loop turn. Hence "},{"type":"text","text":"Promise.then","marks":[{"type":"code"}]},{"type":"text","text":" runs before "},{"type":"text","text":"setTimeout(…, 0)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('b61682ed-945a-7cd6-be6d-548586d5048e', 'aQ', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a Promise?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An object representing the eventual result of an async operation; pending → fulfilled/rejected, settled once. "},{"type":"text","text":"then","marks":[{"type":"code"}]},{"type":"text","text":" returns a new promise, enabling chaining and centralised error handling with "},{"type":"text","text":"catch","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
