ext":"const","marks":[{"type":"code"}]},{"type":"text","text":", arrows, classes, modules, promises, destructuring, "},{"type":"text","text":"Map","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"Set","marks":[{"type":"code"}]},{"type":"text","text":"."}]],[[{"type":"text","text":"2016 →"}],[{"type":"text","text":"Yearly editions: "},{"type":"text","text":"async","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":" (2017), "},{"type":"text","text":"?.","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"??","marks":[{"type":"code"}]},{"type":"text","text":" (2020), top-level "},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":" (2022), "},{"type":"text","text":"toSorted","marks":[{"type":"code"}]},{"type":"text","text":" (2023), "},{"type":"text","text":"Object.groupBy","marks":[{"type":"code"}]},{"type":"text","text":" (2024)…"}]]]},"revision":1},{"id":"f85d826a-ea3d-73fa-b4ab-485c7d53498b","type":"callout","position":"a9","content":{"variant":"note","title":"Name","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JavaScript","marks":[{"type":"italic"}]},{"type":"text","text":" has nothing to do with "},{"type":"text","text":"Java","marks":[{"type":"italic"}]},{"type":"text","text":" — the name was a 1995 marketing decision. ECMAScript is the spec; JavaScript is the most famous implementation of it."}]}]}},"revision":1},{"id":"1e8edcb4-3c1b-7e46-93a1-11d0986edf8c","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Engines and runtimes"}]},"revision":1},{"id":"e4b814e0-40ae-7d91-89a2-b948a6f7f6a6","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An "},{"type":"text","text":"engine","marks":[{"type":"bold"}]},{"type":"text","text":" parses and executes Ja