SELECT '343067f7-f51a-79d4-81fd-a35387d73f0b', '8dfa2fd2-9785-7b00-9972-a3edddb23067', 1, 'PUBLISHED', 'Iterators & Iterables', '[{"id":"fd38c988-7a2a-75f7-b4db-278e4064f017","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The iteration protocols are what make "},{"type":"text","text":"for…of","marks":[{"type":"code"}]},{"type":"text","text":", spread, destructuring, "},{"type":"text","text":"Array.from","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"Promise.all","marks":[{"type":"code"}]},{"type":"text","text":" work on any collection — including your own."}]}]}},"revision":1},{"id":"fc78dcef-06a4-77eb-a675-d3d70d867b94","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The two protocols"}]},"revision":1},{"id":"a0fdd533-7a21-7cf6-ae97-974cdce55b25","type":"callout","position":"a2","content":{"variant":"note","title":"Iterable","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An object with a "},{"type":"text","text":"[Symbol.iterator]()","marks":[{"type":"code"}]},{"type":"text","text":" method that returns an iterator. Arrays, strings, Maps, Sets, "},{"type":"text","text":"arguments","marks":[{"type":"code"}]},{"type":"text","text":", NodeLists and generators are iterable. Plain objects are "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ee3b8c03-7154-7ccd-9459-6a0f1254cf93","type":"callout","position":"a3","content":{"variant":"note","title":"Iterator","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An object with a "},{"type":"text","text":"next()","marks":[{"type":"code"}]},{"type":"text","text":" method returning "},{"type":"text","text":"{ value, done }","marks":[{"type":"code"}]},{"type":"text","text":". Optional "},{"type":"text","text":"return()","marks":[{"type":"code"}]},{"type":"text","text":" is called on early exit ("},{"type":"text","text":"break","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"f6a3fa3a-af34-7368-a9b5-c016ded77e17","type":"code","position":"a4","content":{"language":"javascript","code":"const arr = [\"a\", \"b\"];\nconst it = arr[Symbol.iterator]();\nconsole.log(it.next(), it.next(), it.next());\ntry {\n  for (const x of { a: 1 }) {}\n} catch (e) {\n  console.log(e.message);\n}","filename":"JavaScript"},"revision":1},{"id":"d400f2e8-8ada-79e9-912c-d1c20d879e27","type":"code","position":"a5","content":{"language":"text","code":"{ value: ''a'', done: false } { value: ''b'', done: false } { value: undefined, done: true }\n{(intermediate value)} is not iterable","filename":"Output"},"revision":1},{"id":"db0ef749-b5e1-725b-9c59-917acddcd9bc","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"A custom iterable"}]},"revision":1},{"id":"ec1dd9cb-8f7c-7bd1-a48d-74bae2b831ca","type":"code","position":"a7","content":{"language":"javascript","code":"class Range {\n  constructor(start, end, step = 1) { Object.assign(this, { start, end, step }); }\n  [Symbol.iterator]() {\n    let current = this.start;\n    const { end, step } = this;\n    return {\n      next: () =>\n        current <= end ? { value: (current += step) - step, done: false } : { value: undefined, done: true },\n      [Symbol.iterator]() { return this; },   // iterators are usually iterable too\n    };\n  }\n}\nconst r = new Range(1, 10, 3);\nconsole.log([...r]);\nconst [first, second] = r;\nconsole.log(first, second, Math.max(...r), Array.from(r, (n) => n * 10));\nfor (const n of new Range(1, 3)) console.log(n);","filename":"JavaScript"},"revision":1},{"id":"a901f0b0-d1c9-769c-8795-65772b3af797","type":"code","position":"a8","content":{"language":"text","code":"[ 1, 4, 7, 10 ]\n1 4 10 [ 10, 40, 70, 100 ]\n1\n2\n3","filename":"Output"},"revision":1},{"id":"bc2e13e3-30a0-7d44-9fc9-553d18f415f7","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Iterators are lazy and one-shot"}]},"revision":1},{"id":"73ba2379-f7a4-7729-9b3d-9a680d03502d","type":"code","position":"aA","content":{"language":"javascript","code":"const it = [1, 2, 3].values();\nconsole.log([...it], [...it]);          // second spread: already exhausted\nconst m = new Map([[\"x\", 1], [\"y\", 2]]);\nconsole.log(m.entries().next().value);","filename":"JavaScript"},"revision":1},{"id":"1e00931b-7f5b-73f3-bf8f-39b06a0eaa3c","type":"code","position":"aB","content":{"language":"text","code":"[ 1, 2, 3 ] []\n[ ''x'', 1 ]","filename":"Output"},"revision":1},{"id":"2a07103c-74b8-73ef-b964-bc43b1a5d071","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Iterator helpers (ES2025, Node 22+)"}]},"revision":1},{"id":"ffca5edf-10f3-7bc3-b7b9-28921ae3be53","type":"code","position":"aD","content":{"language":"javascript","code":"function* naturals() { let n = 1; while (true) yield n++; }   // infinite!\nconst firstSquaresOfEvens = naturals()\n  .filter((n) => n % 2 === 0)\n  .map((n) => n * n)\n  .take(4)\n  .toArray();\nconsole.log(firstSquaresOfEvens);\nconsole.log(Iterator.from([5, 6, 7]).drop(1).reduce((a, b) => a + b, 0));","filename":"JavaScript"},"revision":1},{"id":"87112ec5-6eba-7e9f-a730-f71ef233bc5a","type":"code","position":"aE","content":{"language":"text","code":"[ 4, 16, 36, 64 ]\n13","filename":"Output"},"revision":1},{"id":"bb3084a4-8372-7bcb-a737-8ff1a44bb856","type":"callout","position":"aF","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Iterator helpers are "},{"type":"text","text":"lazy","marks":[{"type":"bold"}]},{"type":"text","text":": nothing is computed until "},{"type":"text","text":"toArray()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"for…of","marks":[{"type":"code"}]},{"type":"text","text":" or a reducer pulls values — so they work on infinite sequences where array methods cannot."}]}]}},"revision":1},{"id":"f2acefa0-54f3-73b1-9a0a-cda730545876","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you make an object iterable?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Give it a "},{"type":"text","text":"[Symbol.iterator]","marks":[{"type":"code"}]},{"type":"text","text":" method that returns an object with "},{"type":"text","text":"next()","marks":[{"type":"code"}]},{"type":"text","text":" returning "},{"type":"text","text":"{ value, done }","marks":[{"type":"code"}]},{"type":"text","text":" — or, easiest, make "},{"type":"text","text":"[Symbol.iterator]","marks":[{"type":"code"}]},{"type":"text","text":" a generator: "},{"type":"text","text":"*[Symbol.iterator]() { yield* this.items; }","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
