SELECT '568820af-5d1d-76ab-973c-7d7e649ab2ee', 'f00de255-0837-7392-aa8d-eac9a9d1e093', 1, 'PUBLISHED', 'JSON', '[{"id":"bfcea524-5a3e-725f-9e22-f89dc2d741d1","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JSON is a text format for data, borrowed from JavaScript literal syntax. "},{"type":"text","text":"JSON.stringify","marks":[{"type":"code"}]},{"type":"text","text":" serialises, "},{"type":"text","text":"JSON.parse","marks":[{"type":"code"}]},{"type":"text","text":" deserialises — each with a hook for customisation."}]}]}},"revision":1},{"id":"90afffee-e2ed-759c-98b6-fe47d1a994e7","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"JSON vs JavaScript objects"}]},"revision":1},{"id":"d119d292-8b50-77c0-a590-d2ae564625eb","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"JSON"}],[{"type":"text","text":"JavaScript object literal"}]],[[{"type":"text","text":"Keys "},{"type":"text","text":"must","marks":[{"type":"bold"}]},{"type":"text","text":" be double-quoted strings"}],[{"type":"text","text":"Keys can be bare identifiers"}]],[[{"type":"text","text":"Strings in double quotes only"}],[{"type":"text","text":"''single''","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"\"double\"","marks":[{"type":"code"}]},{"type":"text","text":" and backtick templates"}]],[[{"type":"text","text":"Values: string, number, boolean, "},{"type":"text","text":"null","marks":[{"type":"code"}]},{"type":"text","text":", object, array"}],[{"type":"text","text":"Also functions, "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":", symbols, BigInt, Date, Map…"}]],[[{"type":"text","text":"No trailing commas, no comments"}],[{"type":"text","text":"Trailing commas allowed"}]]]},"revision":1},{"id":"2a9187c5-d162-764d-9fd2-4457cd8cd650","type":"heading","position":"a3","content":{