SELECT '676e797a-675c-70f9-b548-4460265ef4ee', '3d1c6ad2-8ebb-71ba-8f3f-b60cb1f34a93', 1, 'PUBLISHED', 'Garbage Collection & Memory Leaks', '[{"id":"1f99cba4-dc89-7328-98c0-8ca191895ea6","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JavaScript frees memory automatically once objects become unreachable. Leaks happen when you "},{"type":"text","text":"accidentally keep them reachable","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"d056229d-c748-7d2e-8c0c-031f3caf79e3","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Reachability"}]},"revision":1},{"id":"7f04f84d-f100-77a6-b1d4-4549a32d1c85","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The collector starts from "},{"type":"text","text":"roots","marks":[{"type":"bold"}]},{"type":"text","text":" — globals, the current call stack, active closures, pending callbacks — and marks everything reachable from them. Anything not marked is garbage, even if it points to other garbage (so cycles are fine)."}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mark","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Traverse from the roots and mark every reachable object."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sweep / compact","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Reclaim unmarked memory; optionally move live objects together."}]}]}]}]}},"revision":1},{"id":"bbb06d70-a056-788d-a6f0-60c3328b0f02","type":"callout","position":"a3","content":{"variant":"note","title":"Young generation","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"New objects are allocated here. Most die young, so it is collected often and cheaply ("},{"type":"text","text":"scavenge","marks":[{"type":"italic"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"6de1abe7-b5b1-7a27-a446-4642a22613a0","type":"callout","position":"a4","content":{"variant":"note","title":"Old generation","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Objects that survive a few collections are promoted. Collected less often with incremental / concurrent mark-sweep-compact."}]}]}},"revision":1},{"id":"9c7f8b74-dd7d-7eba-b467-efc1b98121bc","type":"callout","position":"a5","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"V8''s collector ("},{"type":"text","text":"Orinoco","marks":[{"type":"italic"}]},{"type":"text","text":") is generational, incremental and mostly concurrent, keeping pauses short. You cannot trigger GC from normal code ("},{"type":"text","text":"node --expose-gc","marks":[{"type":"code"}]},{"type":"text","text":" gives "},{"type":"text","text":"global.gc()","marks":[{"type":"code"}]},{"type":"text","text":" for experiments)."}]}]}},"revision":1},{"id":"2524aed4-fef3-7e57-ac0a-a7415103d816","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Common leaks"}]},"revision":1},{"id":"a3404891-cee8-725a-ac35-26f0319d161b","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Leak"}],[{"type":"text","text":"Why it stays reachable"}],[{"type":"text","text":"Fix"}]],[[{"type":"text","text":"Forgotten timers"}],[{"type":"text","text":"setInterval","marks":[{"type":"code"}]},{"type":"text","text":" callback (and everything it closes over) is referenced by the timer"}],[{"type":"text","text":"clearInterval","marks":[{"type":"code"}]},{"type":"text","text":" on cleanup"}]],[[{"type":"text","text":"Event listeners"}],[{"type":"text","text":"Listener closures on long-lived targets (window, document, emitters)"}],[{"type":"text","text":"removeEventListener","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"{ signal }","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"{ once: true }","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Unbounded caches / Maps"}],[{"type":"text","text":"Keys and values are held strongly forever"}],[{"type":"text","text":"LRU limit, "},{"type":"text","text":"WeakMap","marks":[{"type":"code"}]},{"type":"text","text":", TTL"}]],[[{"type":"text","text":"Closures capturing big data"}],[{"type":"text","text":"A small long-lived function keeps a huge outer variable alive"}],[{"type":"text","text":"Copy only what''s needed; null out references"}]],[[{"type":"text","text":"Detached DOM nodes"}],[{"type":"text","text":"Removed from the page but still referenced from JS"}],[{"type":"text","text":"Drop references; use "},{"type":"text","text":"WeakMap","marks":[{"type":"code"}]},{"type":"text","text":" for per-node data"}]],[[{"type":"text","text":"Accidental globals"}],[{"type":"text","text":"Sloppy-mode "},{"type":"text","text":"x = …","marks":[{"type":"code"}]},{"type":"text","text":" creates a global root"}],[{"type":"text","text":"Strict mode / modules"}]]]},"revision":1},{"id":"7fb0eb0b-d594-71d7-9d28-a23443f72c2e","type":"code","position":"a8","content":{"language":"javascript","code":"import { EventEmitter } from \"node:events\";\nconst bus = new EventEmitter();\n\nfunction subscribeLeaky() {\n  const bigBuffer = new Array(1e5).fill(\"*\");      // captured by the listener below\n  bus.on(\"tick\", () => bigBuffer.length);\n}\nfor (let i = 0; i < 3; i++) subscribeLeaky();\nconsole.log(\"listeners after 3 leaky subscribes:\", bus.listenerCount(\"tick\"));\n\nfunction subscribeClean(signal) {\n  const handler = () => {};\n  bus.on(\"tock\", handler);\n  signal.addEventListener(\"abort\", () => bus.off(\"tock\", handler));\n}\nconst ac = new AbortController();\nsubscribeClean(ac.signal);\nac.abort();                                       // component unmounted\nconsole.log(\"listeners after cleanup:\", bus.listenerCount(\"tock\"));","filename":"JavaScript"},"revision":1},{"id":"e809c956-b2e9-7e37-90b9-e4f9a7a3cd50","type":"code","position":"a9","content":{"language":"text","code":"listeners after 3 leaky subscribes: 3\nlisteners after cleanup: 0","filename":"Output"},"revision":1},{"id":"d45ea4e1-f2ea-7264-b8b9-8088b24c3d4e","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Measuring"}]},"revision":1},{"id":"94a73af7-0297-7469-a420-4080c8bcc025","type":"code","position":"aB","content":{"language":"javascript","code":"const before = process.memoryUsage().heapUsed;\nlet data = Array.from({ length: 200_000 }, (_, i) => ({ i }));\nconst during = process.memoryUsage().heapUsed;\nconsole.log(\"grew by more than 5 MB:\", during - before > 5 * 1024 * 1024);\ndata = null;   // now unreachable — eligible for collection","filename":"JavaScript"},"revision":1},{"id":"4d717a39-d0a2-71da-8fd0-96f8991f9a63","type":"code","position":"aC","content":{"language":"text","code":"grew by more than 5 MB: true","filename":"Output"},"revision":1},{"id":"556ca90f-3c8b-7643-bc4e-0756a6f56259","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Browser: DevTools → "},{"type":"text","text":"Memory","marks":[{"type":"bold"}]},{"type":"text","text":" → heap snapshots (compare two) and the allocation timeline; look for growing "},{"type":"text","text":"Detached","marks":[{"type":"italic"}]},{"type":"text","text":" elements."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Node: "},{"type":"text","text":"process.memoryUsage()","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"node --inspect","marks":[{"type":"code"}]},{"type":"text","text":" + Chrome DevTools, "},{"type":"text","text":"--heapsnapshot-signal","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"v8.writeHeapSnapshot()","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"f8a3e0d3-1f10-7889-ac18-82785c682cf3","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does garbage collection work in JavaScript?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Engines use tracing mark-and-sweep: starting from roots (globals, stack, closures) they mark reachable objects and reclaim the rest. V8 is generational — frequent cheap collection of the young generation, rarer mark-compact of the old — and does much of the work incrementally and concurrently."}]}]}},"revision":1},{"id":"f0a63d16-e2ba-7e97-901b-3adb8389680e","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can circular references cause memory leaks?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Not with mark-and-sweep: a cycle that is unreachable from the roots is collected. (They did leak with old reference-counting collectors, e.g. IE6 DOM/JS cycles.)"}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
