SELECT 'aadc10a6-41cb-7f50-b9bf-4739f801c8a1', '3cc5c060-a76b-7480-bc66-d2cfe9169916', 1, 'PUBLISHED', 'Modules: ESM vs CommonJS', '[{"id":"2689b320-0668-72b7-a19c-f0bc3a96de15","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Modules give each file its own scope and explicit imports/exports. JavaScript has two systems: standard "},{"type":"text","text":"ES modules","marks":[{"type":"bold"}]},{"type":"text","text":" and Node''s older "},{"type":"text","text":"CommonJS","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"1086566a-3c12-72b2-a73a-9bc82f9baaaa","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"ES module syntax"}]},"revision":1},{"id":"c90130f5-34e1-7154-96b5-27ef3f851213","type":"code","position":"a2","content":{"language":"javascript","code":"// math.js\nexport const PI = 3.14159;\nexport function area(r) { return PI * r * r; }\nexport default class Calculator { /* ... */ }\n\n// app.js\nimport Calculator, { PI, area as circleArea } from \"./math.js\";\nimport * as math from \"./math.js\";\nexport { circleArea };                    // re-export\nexport * from \"./other.js\";\nconst { heavy } = await import(\"./heavy.js\");   // dynamic import (returns a promise)","filename":"JavaScript"},"revision":1},{"id":"6dc26feb-9ed8-73fe-90ae-97f181435819","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Exports are "},{"type":"text","text":"live bindings","marks":[{"type":"italic"}]},{"type":"text","text":", which a runnable demo can show by importing an inline module from a "},{"type":"text","text":"data:","marks":[{"type":"code"}]},{"type":"text","text":" URL:"}]}]}},"revision":1},{"id":"ba20919a-b0ff-7279-a6e7-6e02c63fb664","type":"code","position":"a4","content":{"language":"javascript","code":"const source = `\n  export let count = 0;\n  export function increment() { count++; }\n  export default \"the default export\";\n`;\nconst mod = await import(\"data:text/javascript,\" + encodeURIComponent(source));\nconsole.log(mod.default, mod.count);\nmod.increment();\nconsole.log(mod.count);                   // live binding: sees the update\ntry {\n  mod.count = 99;                         // importers cannot assign\n} catch (e) {\n  console.log(e.name);\n}\nconsole.log(Object.keys(mod));","filename":"JavaScript"},"revision":1},{"id":"aec67883-81ab-73c9-a7ca-54ccc9e502da","type":"code","position":"a5","content":{"language":"text","code":"the default export 0\n1\nTypeError\n[ ''count'', ''default'', ''increment'' ]","filename":"Output"},"revision":1},{"id":"9c146f91-b5a5-71a7-8d94-767844256bbc","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"ESM vs CommonJS"}]},"revision":1},{"id":"fd8adcdb-b1ce-78ab-98ca-edfb8967ccc3","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"ES modules (ESM)"}],[{"type":"text","text":"CommonJS (CJS)"}]],[[{"type":"text","text":"Syntax"}],[{"type":"text","text":"import","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"export","marks":[{"type":"code"}]}],[{"type":"text","text":"require()","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"module.exports","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Loading"}],[{"type":"text","text":"Static graph, parsed before running; async-capable"}],[{"type":"text","text":"Synchronous, at runtime"}]],[[{"type":"text","text":"Top-level "},{"type":"text","text":"await","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"Bindings"}],[{"type":"text","text":"Live, read-only"}],[{"type":"text","text":"A copied value ("},{"type":"text","text":"exports","marks":[{"type":"code"}]},{"type":"text","text":" object)"}]],[[{"type":"text","text":"Strict mode"}],[{"type":"text","text":"Always"}],[{"type":"text","text":"Only with "},{"type":"text","text":"\"use strict\"","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Top-level "},{"type":"text","text":"this","marks":[{"type":"code"}]}],[{"type":"text","text":"undefined","marks":[{"type":"code"}]}],[{"type":"text","text":"module.exports","marks":[{"type":"code"}]}]],[[{"type":"text","text":"File detection in Node"}],[{"type":"text","text":".mjs","marks":[{"type":"code"}]},{"type":"text","text":", or "},{"type":"text","text":".js","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"\"type\": \"module\"","marks":[{"type":"code"}]}],[{"type":"text","text":".cjs","marks":[{"type":"code"}]},{"type":"text","text":", or "},{"type":"text","text":".js","marks":[{"type":"code"}]},{"type":"text","text":" by default"}]],[[{"type":"text","text":"__dirname","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"require","marks":[{"type":"code"}]}],[{"type":"text","text":"Not defined — use "},{"type":"text","text":"import.meta.dirname","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"createRequire","marks":[{"type":"code"}]}],[{"type":"text","text":"Available"}]],[[{"type":"text","text":"Tree-shaking"}],[{"type":"text","text":"Yes (static analysis)"}],[{"type":"text","text":"Hard"}]]]},"revision":1},{"id":"20317c9b-42f1-7353-b3b8-8a38c73debb0","type":"code","position":"a8","content":{"language":"javascript","code":"import { createRequire } from \"node:module\";\nimport path from \"node:path\";\n\nconst require = createRequire(import.meta.url);     // CJS require inside ESM\nconst os = require(\"node:os\");\nconsole.log(typeof os.platform, typeof require.resolve);\nconsole.log(path.basename(import.meta.filename), import.meta.url.startsWith(\"file://\"));\nconsole.log(typeof __dirname, typeof module, this);","filename":"JavaScript"},"revision":1},{"id":"564bce1d-b4ea-7a32-b2af-7034d82b5cfe","type":"code","position":"a9","content":{"language":"text","code":"function function\nmain.mjs true\nundefined undefined undefined","filename":"Output"},"revision":1},{"id":"612fcad1-f73d-77f9-b420-0807dedc980c","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"CommonJS for reference"}]},"revision":1},{"id":"bdd79d0f-01b7-74e9-a4cb-ff8d66eb87a6","type":"code","position":"aB","content":{"language":"javascript","code":"// counter.cjs\nlet count = 0;\nmodule.exports = { count, increment() { count++; } };\n\n// app.cjs\nconst counter = require(\"./counter.cjs\");\ncounter.increment();\nconsole.log(counter.count);   // 0 — a copy was exported, not a live binding","filename":"JavaScript"},"revision":1},{"id":"e0032d97-ef5c-718e-a5fd-bf0a404475a1","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Module facts worth knowing"}]},"revision":1},{"id":"2f34e0b6-8187-7cc9-89ce-96e6dea60500","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A module is evaluated "},{"type":"text","text":"once","marks":[{"type":"bold"}]},{"type":"text","text":", then cached — every importer gets the same instance (natural singletons)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Imports are hoisted and resolved before the module body runs; circular imports see TDZ bindings until the other module finishes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"In browsers: "},{"type":"text","text":"<script type=\"module\">","marks":[{"type":"code"}]},{"type":"text","text":" is deferred by default, runs in strict mode and needs full URLs or an import map."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dynamic "},{"type":"text","text":"import()","marks":[{"type":"code"}]},{"type":"text","text":" enables code splitting and lazy loading; it works in CJS too."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"require(esm)","marks":[{"type":"code"}]},{"type":"text","text":" is supported in modern Node (22+) for ES modules without top-level "},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"651ccc11-7639-7669-8ed9-85a9953433e1","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the main differences between CommonJS and ES modules?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ESM uses static "},{"type":"text","text":"import","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"export","marks":[{"type":"code"}]},{"type":"text","text":", is analysed before execution (enabling tree-shaking and top-level await), exports live read-only bindings and is always strict. CJS uses synchronous runtime "},{"type":"text","text":"require","marks":[{"type":"code"}]},{"type":"text","text":", exports a plain object (copied values), and has "},{"type":"text","text":"__dirname","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"module","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
