SELECT 'fb88d550-1880-7e5d-8fd4-6b80d985f1df', '28232e7d-1d2f-76b6-814e-06c4142adaca', 1, 'PUBLISHED', 'EventEmitter & Streams', '[{"id":"da4ec7ad-681d-76af-b2f2-c4b9dd389893","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Most of Node is built on two ideas: objects that emit named events, and streams that move data in chunks instead of loading everything into memory."}]}]}},"revision":1},{"id":"f205031b-bfa5-79b8-ab38-8f366b2766f4","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"EventEmitter"}]},"revision":1},{"id":"444ae2cb-5fb3-74a9-b45d-6e594ee2f7ce","type":"code","position":"a2","content":{"language":"javascript","code":"import { EventEmitter, once } from \"node:events\";\n\nclass Order extends EventEmitter {\n  place(item) {\n    this.emit(\"placed\", { item, at: \"12:00\" });\n    if (item === \"unknown\") this.emit(\"error\", new Error(\"no such item\"));\n  }\n}\nconst order = new Order();\norder.on(\"placed\", ({ item }) => console.log(\"email: placed\", item));\norder.once(\"placed\", () => console.log(\"analytics: first order only\"));\norder.on(\"error\", (err) => console.log(\"handled error:\", err.message));\n\norder.place(\"book\");\norder.place(\"unknown\");\nconsole.log(order.listenerCount(\"placed\"), order.eventNames());\n\nsetTimeout(() => order.emit(\"shipped\", \"TRACK-1\"), 5);\nconst [tracking] = await once(order, \"shipped\");      // promise-based wait\nconsole.log(\"shipped with\", tracking);","filename":"JavaScript"},"revision":1},{"id":"557458d4-6a75-7e44-9416-5b262314aeb0","type":"code","position":"a3","content":{"language":"text","code":"email: placed book\nanalytics: first order only\nemail: placed unknown\nhandled error: no such item\n1 [ ''placed'', ''error'' ]\nshipped with TRACK-1","filename":"Output"},"revision":1},{"id":"5ff93f57-9e54-734a-8085-14f608d2f351","type":"callout","position":"a4","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Emitting "},{"type":"text","text":"''error''","marks":[{"type":"code"}]},{"type":"text","text":" with no "},{"type":"text","text":"''error''","marks":[{"type":"code"}]},{"type":"text","text":" listener "},{"type":"text","text":"throws","marks":[{"type":"bold"}]},{"type":"text","text":" and crashes the process. Listeners run "},{"type":"text","text":"synchronously","marks":[{"type":"bold"}]},{"type":"text","text":", in registration order, inside "},{"type":"text","text":"emit","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"499a836c-60f9-7598-aef9-ff2425350e60","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Streams"}]},"revision":1},{"id":"fd502d03-f4a3-7f39-a6f4-a6a27eef5e93","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Type"}],[{"type":"text","text":"Examples"}]],[[{"type":"text","text":"Readable"}],[{"type":"text","text":"fs.createReadStream","marks":[{"type":"code"}]},{"type":"text","text":", HTTP request (server side), "},{"type":"text","text":"process.stdin","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Writable"}],[{"type":"text","text":"fs.createWriteStream","marks":[{"type":"code"}]},{"type":"text","text":", HTTP response, "},{"type":"text","text":"process.stdout","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Duplex"}],[{"type":"text","text":"TCP socket"}]],[[{"type":"text","text":"Transform"}],[{"type":"text","text":"zlib.createGzip()","marks":[{"type":"code"}]},{"type":"text","text":", encryption, parsers"}]]]},"revision":1},{"id":"177669ac-0919-7139-beab-51c3d8195112","type":"code","position":"a7","content":{"language":"javascript","code":"import { Readable, Transform, Writable } from \"node:stream\";\nimport { pipeline } from \"node:stream/promises\";\n\nconst source = Readable.from([\"alpha\\n\", \"beta\\n\", \"gamma\\n\"]);\nconst upper = new Transform({\n  transform(chunk, _enc, callback) {\n    callback(null, chunk.toString().toUpperCase());\n  },\n});\nconst collected = [];\nconst sink = new Writable({\n  write(chunk, _enc, callback) {\n    collected.push(chunk.toString().trim());\n    callback();\n  },\n});\nawait pipeline(source, upper, sink);     // handles back-pressure and errors\nconsole.log(collected);","filename":"JavaScript"},"revision":1},{"id":"13d3f2c1-a1a2-7d37-b667-3b0d37218411","type":"code","position":"a8","content":{"language":"text","code":"[ ''ALPHA'', ''BETA'', ''GAMMA'' ]","filename":"Output"},"revision":1},{"id":"892be643-d08d-7c40-bab4-de9dbb1b6f51","type":"callout","position":"a9","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Back-pressure","marks":[{"type":"bold"}]},{"type":"text","text":": when the consumer is slower than the producer, "},{"type":"text","text":"pipeline","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"pipe","marks":[{"type":"code"}]},{"type":"text","text":" pause the source so memory stays bounded — the reason to stream a 10 GB file instead of "},{"type":"text","text":"readFile","marks":[{"type":"code"}]},{"type":"text","text":"-ing it."}]}]}},"revision":1},{"id":"61dc5fab-cdb5-786d-8df3-8902cf4948b4","type":"question","position":"aA","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why use streams instead of reading a whole file?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Streams process data chunk by chunk, so memory use stays constant regardless of size, work starts before all data arrives, and back-pressure keeps fast producers from overwhelming slow consumers."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
