SELECT '5b3753e4-504f-76a4-8551-fc56d81fd864', '9ce5efb0-2739-7971-b1a9-e9e134ebda2f', 1, 'PUBLISHED', 'Node.js Essentials', '[{"id":"e870897a-e2ac-79a9-8762-2179b2d355f3","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Node.js is V8 plus libuv plus a standard library for files, networking, processes and streams — JavaScript outside the browser."}]}]}},"revision":1},{"id":"3ca38e19-3d38-701f-839a-029866abf67d","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Architecture"}]},"revision":1},{"id":"d1b1c7f9-9686-7664-98c5-d344772c67f6","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Your JS → V8 (executes) → Node bindings → libuv (event loop + thread pool) → OS"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Network I/O is non-blocking at the OS level; file-system, DNS lookups, crypto and zlib use libuv''s thread pool (4 threads by default)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"One JS thread per process; scale with "},{"type":"text","text":"cluster","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"worker_threads","marks":[{"type":"code"}]},{"type":"text","text":", or multiple processes behind a load balancer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Globals: "},{"type":"text","text":"process","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Buffer","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"globalThis","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"setImmediate","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"structuredClone","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"fetch","marks":[{"type":"code"}]},{"type":"text","text":"; no "},{"type":"text","text":"window","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"document","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]}]}},"revision":1},{"id":"82d74d36-4b22-79fe-9e83-0bfee1f99305","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"path and process"}]},"revision":1},{"id":"8b70d8be-a497-7596-a7fe-6aad82454cb9","type":"code","position":"a4","content":{"language":"javascript","code":"import path from \"node:path\";\nconst file = \"/home/asha/projects/app/src/index.test.js\";\nconsole.log(path.basename(file), path.extname(file), path.dirname(file));\nconsole.log(path.join(\"/a/b\", \"../c\", \"d.txt\"), path.resolve(\"/root\", \"x\", \"..\", \"y\"));\nconsole.log(path.parse(\"/tmp/report.pdf\"));\nconsole.log(typeof process.argv, process.argv.length >= 2, process.platform.length > 0);\nconst port = Number(process.env.PORT ?? 3000);          // env vars are strings or undefined\nconsole.log(port, typeof process.exitCode);","filename":"JavaScript"},"revision":1},{"id":"7fbb285f-d737-7cbc-9fb6-43f870748db0","type":"code","position":"a5","content":{"language":"text","code":"index.test.js .js /home/asha/projects/app/src\n/a/c/d.txt /root/y\n{\n  root: ''/'',\n  dir: ''/tmp'',\n  base: ''report.pdf'',\n  ext: ''.pdf'',\n  name: ''report''\n}\nobject true true\n3000 undefined","filename":"Output"},"revision":1},{"id":"c6907658-300d-708b-9ac5-ba3e7dc11959","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"The fs module (promises API)"}]},"revision":1},{"id":"71a5002c-bd4f-7716-ba19-be772a971eca","type":"code","position":"a7","content":{"language":"javascript","code":"import { writeFile, readFile, appendFile, readdir, mkdir, rm, stat } from \"node:fs/promises\";\nimport { existsSync } from \"node:fs\";\n\nawait mkdir(\"data/logs\", { recursive: true });\nawait writeFile(\"data/logs/app.log\", \"started\\n\");\nawait appendFile(\"data/logs/app.log\", \"ready\\n\");\nconst text = await readFile(\"data/logs/app.log\", \"utf8\");\nconsole.log(text.trim().split(\"\\n\"));\nconsole.log(await readdir(\"data\"), (await stat(\"data/logs/app.log\")).size);\ntry {\n  await readFile(\"missing.txt\", \"utf8\");\n} catch (e) {\n  console.log(e.code);\n}\nawait rm(\"data\", { recursive: true });\nconsole.log(existsSync(\"data\"));","filename":"JavaScript"},"revision":1},{"id":"0c1a5585-78af-78cd-9a1d-d89fa127b0d0","type":"code","position":"a8","content":{"language":"text","code":"[ ''started'', ''ready'' ]\n[ ''logs'' ] 14\nENOENT\nfalse","filename":"Output"},"revision":1},{"id":"5b988db2-be62-7e60-8b5c-6005aff35820","type":"callout","position":"a9","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"node:fs/promises","marks":[{"type":"code"}]},{"type":"text","text":" with "},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":" in application code. The "},{"type":"text","text":"*Sync","marks":[{"type":"code"}]},{"type":"text","text":" variants block the event loop — fine in CLI scripts and at startup, harmful inside a server request handler."}]}]}},"revision":1},{"id":"d9de0eb3-e10f-7282-b722-3947c1f47437","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"A minimal HTTP server"}]},"revision":1},{"id":"b63642f4-e782-77d6-8e8e-e28361cce044","type":"code","position":"aB","content":{"language":"javascript","code":"import http from \"node:http\";\nconst server = http.createServer((req, res) => {\n  res.writeHead(200, { \"Content-Type\": \"application/json\" });\n  res.end(JSON.stringify({ method: req.method, path: req.url }));\n});\nserver.listen(0, async () => {\n  const { port } = server.address();\n  const body = await (await fetch(`http://localhost:${port}/hello?x=1`)).json();\n  console.log(body);\n  server.close();\n});","filename":"JavaScript"},"revision":1},{"id":"7718b167-3565-70aa-b393-f3e24ef04ddb","type":"code","position":"aC","content":{"language":"text","code":"{ method: ''GET'', path: ''/hello?x=1'' }","filename":"Output"},"revision":1},{"id":"215cdead-e7fb-7bd7-a30c-7bc0b2fd84c6","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"npm and package.json"}]},"revision":1},{"id":"7a417b91-e641-7960-8b26-d9ef5d45cd22","type":"code","position":"aE","content":{"language":"","code":"$ npm init -y                    # create package.json\n$ npm install express            # dependency  → \"dependencies\"\n$ npm install -D vitest          # dev-only    → \"devDependencies\"\n$ npm run test                   # run a script from \"scripts\"\n$ npx eslint .                   # run a package binary without installing globally\n$ npm ci                         # clean, exact install from package-lock.json (CI)","filename":"Terminal"},"revision":1},{"id":"ce65af9f-0b7f-7ae7-af46-7501b67c2d54","type":"table","position":"aF","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Version range"}],[{"type":"text","text":"Accepts"}]],[[{"type":"text","text":"\"4.18.2\"","marks":[{"type":"code"}]}],[{"type":"text","text":"Exactly that version"}]],[[{"type":"text","text":"\"^4.18.2\"","marks":[{"type":"code"}]}],[{"type":"text","text":">=4.18.2 <5.0.0","marks":[{"type":"code"}]},{"type":"text","text":" — minor + patch updates (npm''s default)"}]],[[{"type":"text","text":"\"~4.18.2\"","marks":[{"type":"code"}]}],[{"type":"text","text":">=4.18.2 <4.19.0","marks":[{"type":"code"}]},{"type":"text","text":" — patch updates only"}]]]},"revision":1},{"id":"76c92dfc-544c-757f-a7b6-34d9ed355b38","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is Node.js single-threaded?"}]}]},"answer":{"ty