SELECT '1c476cd5-ce4c-7286-b1ba-4d6319e24bbf', 'ba8fb5bf-dd20-7846-bb92-28b8810e42bc', 1, 'PUBLISHED', 'Object Static Methods', '[{"id":"c97fbc91-0649-70e8-a275-9d6c94412a4b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Object","marks":[{"type":"code"}]},{"type":"text","text":" constructor carries the toolbox for inspecting, copying, converting and grouping objects."}]}]}},"revision":1},{"id":"e454cb6b-b502-7ee0-8bb2-96bc803aecc8","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method"}],[{"type":"text","text":"Does"}]],[[{"type":"text","text":"Object.keys / values / entries(o)","marks":[{"type":"code"}]}],[{"type":"text","text":"Own enumerable string keys / values / "},{"type":"text","text":"[key, value]","marks":[{"type":"code"}]},{"type":"text","text":" pairs"}]],[[{"type":"text","text":"Object.fromEntries(iterable)","marks":[{"type":"code"}]}],[{"type":"text","text":"Pairs → object (inverse of "},{"type":"text","text":"entries","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"Object.assign(target, ...src)","marks":[{"type":"code"}]}],[{"type":"text","text":"Copy own enumerable props into "},{"type":"text","text":"target","marks":[{"type":"code"}]},{"type":"text","text":" (mutates, shallow)"}]],[[{"type":"text","text":"Object.create(proto, descriptors?)","marks":[{"type":"code"}]}],[{"type":"text","text":"New object with the given prototype"}]],[[{"type":"text","text":"Object.getPrototypeOf / setPrototypeOf","marks":[{"type":"code"}]}],[{"type":"text","text":"Read / change the prototype"}]],[[{"type":"text","text":"Object.defineProperty / defineProperties","marks":[{"type":"code"}]}],[{"type":"text","text":"Add props with explicit attributes"}]],[[{"type":"text","text":"Object.freeze / seal / preventExtensions","marks":[{"type":"code"}]}],[{"type":"text","text":"Restrict changes"}]],[[{"type":"text","text":"Object.hasOwn(o, k)","marks":[{"type":"code"}]}],[{"type":"text","text":"Own-property check (ES2022)"}]],[[{"type":"text","text":"Object.is(a, b)","marks":[{"type":"code"}]}],[{"type":"text","text":"SameValue equality"}]],[[{"type":"text","text":"Object.groupBy(items, fn)","marks":[{"type":"code"}]}],[{"type":"text","text":"Group into a null-prototype object (ES2024)"}]],[[{"type":"text","text":"Object.getOwnPropertyNames / getOwnPropertySymbols","marks":[{"type":"code"}]}],[{"type":"text","text":"Include non-enumerables / symbols"}]]]},"revision":1},{"id":"5a26b2fe-b72a-7fcf-bdc4-7964f78215a0","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"entries ⇄ fromEntries: transform an object"}]},"revision":1},{"id":"c3a2c88a-e42a-7d03-b2cc-a7f482f3e697","type":"code","position":"a3","content":{"language":"javascript","code":"const prices = { apple: 1.2, bread: 2.5, milk: 0.99 };\nconst doubled = Object.fromEntries(\n  Object.entries(prices).map(([k, v]) => [k, v * 2])\n);\nconsole.log(doubled);\nconst cheap = Object.fromEntries(Object.entries(prices).filter(([, v]) => v < 2));\nconsole.log(cheap);\nconsole.log(Object.fromEntries(new Map([[\"x\", 1]])));\nconsole.log(Object.fromEntries(new URLSearchParams(\"q=js&page=2\")));","filename":"JavaScript"},"revision":1},{"id":"0115480d-bec1-7921-b69e-b06205b7308b","type":"code","position":"a4","content":{"language":"text","code":"{ apple: 2.4, bread: 5, milk: 1.98 }\n{ apple: 1.2, milk: 0.99 }\n{ x: 1 }\n{ q: ''js'', page: ''2'' }","filename":"Output"},"revision":1},{"id":"d724b718-c06f-7581-8581-8f50e95466f0","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"assign vs spread"}]},"revision":1},{"id":"e88837ab-af14-70e0-b03c-ea659dda1960","type":"code","position":"a6","content":{"language":"javascript","code":"const defaults = { theme: \"light\", lang: \"en\" };\nconst user = { lang: \"hi\" };\nconst merged = Object.assign({}, defaults, user);\nconst spread = { ...defaults, ...user };\nconsole.log(merged, spread);\nObject.assign(defaults, { theme: \"dark\" });   // mutates the target\nconsole.log(defaults);","filename":"JavaScript"},"revision":1},{"id":"e73cb9fc-35c9-7ae8-ac94-adbfd868c0bd","type":"code","position":"a7","content":{"language":"text","code":"{ theme: ''light'', lang: ''hi'' } { theme: ''light'', lang: ''hi'' }\n{ theme: ''dark'', lang: ''en'' }","filename":"Output"},"revision":1},{"id":"ee6e3800-c6d2-7a14-838a-351de07b2dae","type":"callout","position":"a8","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Later sources win. "},{"type":"text","text":"Object.assign","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"invokes setters","marks":[{"type":"italic"}]},{"type":"text","text":" on the target; spread defines fresh properties. Both are shallow copies."}]}]}},"revision":1},{"id":"0fa9f3e5-3b3c-7fdb-acc2-ff30bc2f9a86","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Object.groupBy (ES2024)"}]},"revision":1},{"id":"740f0651-755a-7925-be5f-70036a777b38","type":"code","position":"aA","content":{"language":"javascript","code":"const inventory = [\n  { name: \"asparagus\", type: \"veg\", qty: 5 },\n  { name: \"banana\", type: \"fruit\", qty: 0 },\n  { name: \"goat\", type: \"meat\", qty: 23 },\n  { name: \"cherry\", type: \"fruit\", qty: 5 },\n];\nconst byType = Object.groupBy(inventory, ({ type }) => type);\nconsole.log(Object.keys(byType), byType.fruit.length);\nconst stock = Map.groupBy(inventory, ({ qty }) => (qty > 0 ? \"ok\" : \"restock\"));\nconsole.log(stock.get(\"restock\"));","filename":"JavaScript"},"revision":1},{"id":"cb192e3b-0515-7ea2-b024-f6b67de81d1e","type":"code","position":"aB","content":{"language":"text","code":"[ ''veg'', ''fruit'', ''meat'' ] 2\n[ { name: ''banana'', type: ''fruit'', qty: 0 } ]","filename":"Output"},"revision":1},{"id":"ae052e46-0b42-7f5f-b775-64a5ff1352d8","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Object.create"}]},"revision":1},{"id":"ab687ca9-cd91-7423-83f3-9c9864fa7be4","type":"code","position":"aD","content":{"language":"javascript","code":"const animal = { speak() { return `${this.name} makes a sound`; } };\nconst dog = Object.create(animal);\ndog.name = \"Rex\";\nconsole.log(dog.speak(), Object.getPrototypeOf(dog) === animal);\nconst dict = Object.create(null);          // no prototype at all\ndict.key = \"v\";\nconsole.log(\"toString\" in dict, dict);","filename":"JavaScript"},"revision":1},{"id":"d57d0fc0-4d6d-7419-be36-03bd91dc3f6f","type":"code","position":"aE","content":{"language":"text","code":"Rex makes a sound true\nfalse [Object: null prototype] { key: ''v'' }","filename":"Output"},"revision":1},{"id":"3919ff68-e5b9-7be7-a413-53c992829943","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Object.keys vs Object.getOwnPropertyNames vs Reflect.ownKeys?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Object.keys","marks":[{"type":"code"}]},{"type":"text","text":" → own "},{"type":"text","text":"enumerable","marks":[{"type":"bold"}]},{"type":"text","text":" string keys. "},{"type":"text","text":"getOwnPropertyNames","marks":[{"type":"code"}]},{"type":"text","text":" → own string keys including non-enumerable. "},{"type":"text","text":"Reflect.ownKeys","marks":[{"type":"code"}]},{"type":"text","text":" → all own keys, strings and symbols, enumerable or not."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
