SELECT '8d9187c0-fbc2-70ac-a750-fdd7b03c8f1a', '7ecd5275-4e2e-764a-b689-bca0fb8b920b', 1, 'PUBLISHED', 'Objects', '[{"id":"f666082d-ab76-7b00-8c3d-ec68bbc34104","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Objects are collections of key → value properties. Keys are strings or symbols; values can be anything, including functions (methods)."}]}]}},"revision":1},{"id":"9ff22711-5987-7fd3-82a3-dd16167fa9d6","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Object literals, modern syntax"}]},"revision":1},{"id":"4ec21c84-1ec7-74b2-afda-ee09753769f1","type":"code","position":"a2","content":{"language":"javascript","code":"const name = \"Asha\", age = 28;\nconst field = \"email\";\nconst user = {\n  name,                                  // shorthand for name: name\n  age,\n  [field]: \"asha@example.com\",           // computed key\n  [`is${\"Admin\"}`]: false,\n  \"full name\": \"Asha Rao\",               // any string can be a key\n  greet() { return `Hi, ${this.name}`; },  // method shorthand\n};\nconsole.log(user);\nconsole.log(user.greet(), user[\"full name\"], user[field]);","filename":"JavaScript"},"revision":1},{"id":"cd8109dd-7418-7e7b-aca4-69eb89b0617c","type":"code","position":"a3","content":{"language":"text","code":"{\n  name: ''Asha'',\n  age: 28,\n  email: ''asha@example.com'',\n  isAdmin: false,\n  ''full name'': ''Asha Rao'',\n  greet: [Function: greet]\n}\nHi, Asha Asha Rao asha@example.com","filename":"Output"},"revision":1},{"id":"891d2941-47d8-70fc-ba71-4ce9c2db2ab2","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Reading, writing, deleting, checking"}]},"revision":1},{"id":"cd13cb27-876e-75a8-bac1-13932403ec35","type":"code","position":"a5","content":{"language":"javascript","code":"const car = { brand: \"Tata\", year: 2020 };\ncar.color = \"red\";           // add\ncar.year = 2021;             // update\ndelete car.brand;            // remove\nconsole.log(car);\nconsole.log(\"color\" in car, Object.hasOwn(car, \"color\"), car.speed);\nconsole.log(\"toString\" in car, Object.hasOwn(car, \"toString\"));","filename":"JavaScript"},"revision":1},{"id":"cbf5bc3f-0759-7b30-abfe-b5d231a846c7","type":"code","position":"a6","content":{"language":"text","code":"{ year: 2021, color: ''red'' }\ntrue true undefined\ntrue false","filename":"Output"},"revision":1},{"id":"477959c3-3bf1-74e8-b038-3ab4184ef4f6","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Check"}],[{"type":"text","text":"Own props"}],[{"type":"text","text":"Inherited props"}],[{"type":"text","text":"Value "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":" counts?"}]],[[{"type":"text","text":"obj.key !== undefined","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No — misses explicit "},{"type":"text","text":"undefined","marks":[{"type":"code"}]}]],[[{"type":"text","text":"''key'' in obj","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Object.hasOwn(obj, ''key'')","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes"}]]]},"revision":1},{"id":"36e00a52-7930-7df5-b7ec-10846a24a73c","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Keys are strings (or symbols)"}]},"revision":1},{"id":"08b3813f-70ef-77e8-8fcd-5b7c82d40409","type":"code","position":"a9","content":{"language":"javascript","code":"const obj = {};\nobj[1] = \"number key\";\nobj[{}] = \"object key\";\nconsole.log(Object.keys(obj), obj[\"1\"]);\nconst order = { b: 1, 2: \"two\", a: 2, 1: \"one\" };\nconsole.log(Object.keys(order));","filename":"JavaScript"},"revision":1},{"id":"88d9d16b-dd5e-7f8a-88a8-ffb9a245c7ce","type":"code","position":"aA","content":{"language":"text","code":"[ ''1'', ''[object Object]'' ] number key\n[ ''1'', ''2'', ''b'', ''a'' ]","filename":"Output"},"revision":1},{"id":"f03fe755-444f-7e7d-8405-2ddaa8e42512","type":"callout","position":"aB","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Property order: integer-like keys first in ascending order, then string keys in insertion order, then symbols. Need real non-string keys? Use a "},{"type":"text","text":"Map","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"37687871-8109-78b1-aabe-e229b10e4ed2","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Getters and setters"}]},"revision":1},{"id":"53ea1c94-ec89-7deb-80e0-71271a0152c7","type":"code","position":"aD","content":{"language":"javascript","code":"const temperature = {\n  celsius: 25,\n  get fahrenheit() {\n    return this.celsius * 9 / 5 + 32;\n  },\n  set fahrenheit(f) {\n    this.celsius = Math.round((f - 32) * 5 / 9);\n  },\n};\nconsole.log(temperature.fahrenheit);\ntemperature.fahrenheit = 212;\nconsole.log(temperature.celsius, temperature);","filename":"JavaScript"},"revision":1},{"id":"1e2433a8-63f8-7873-870b-a0105dcd78b4","type":"code","position":"aE","content":{"language":"text","code":"77\n100 { celsius: 100, fahrenheit: [Getter/Setter] }","filename":"Output"},"revision":1},{"id":"a8bff94d-179f-7f9d-9cfa-2b94ff360285","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Iterating an object"}]},"revision":1},{"id":"b0d45b16-24e6-7587-9d85-21583dafd6ee","type":"code","position":"aG","content":{"language":"javascript","code":"const scores = { math: 90, art: 75, music: 88 };\nfor (const [subject, score] of Object.entries(scores)) {\n  console.log(`${subject.padEnd(6)} ${score}`);\n}\nconst total = Object.values(scores).reduce((a, b) => a + b, 0);\nconsole.log(total, Object.keys(scores).length);","filename":"JavaScript"},"revision":1},{"id":"15360a9a-64af-7ee7-aaf6-226291249d33","type":"code","position":"aH","content":{"language":"text","code":"math   90\nart    75\nmusic  88\n253 3","filename":"Output"},"revision":1},{"id":"4bb19851-f048-72a6-804a-4bbfce2f2c94","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you check if an object is empty?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Object.keys(obj).length === 0","marks":[{"type":"code"}]},{"type":"text","text":" (own enumerable string keys). For a stricter check include symbols and non-enumerables: "},{"type":"text","text":"Reflect.ownKeys(obj).length === 0","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"50e46f2c-4620-7c90-ad54-384f9c373f9e","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Difference between dot and bracket notation?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Dot needs a valid identifier known when writing the code ("},{"type":"text","text":"obj.name","marks":[{"type":"code"}]},{"type":"text","text":"). Brackets take any expression evaluated at runtime ("},{"type":"text","text":"obj[key]","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"obj[''full name'']","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"obj[sym]","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
