SELECT 'e847b7cf-2e3a-76bb-93b5-a5faaf3d936c', '6c4e2a80-7a5d-7a8a-9e69-d6a8998157f1', 1, 'PUBLISHED', 'Parameters, Defaults & Rest', '[{"id":"fad80240-1cb4-7122-93f2-9abfa1a7d24a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JavaScript never checks argument counts: missing ones are "},{"type":"text","text":"undefined","marks":[{"type":"code"}]},{"type":"text","text":", extras are ignored — defaults, rest parameters and destructuring make that manageable."}]}]}},"revision":1},{"id":"e77cd45b-c61d-7f36-aeae-6c8a9232a0d4","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Missing and extra arguments"}]},"revision":1},{"id":"4561a962-8b7e-77c4-974d-4d665ce2f527","type":"code","position":"a2","content":{"language":"javascript","code":"function show(a, b) {\n  console.log(a, b, arguments.length);\n}\nshow(1);\nshow(1, 2, 3);","filename":"JavaScript"},"revision":1},{"id":"f398bb01-4daa-7f98-b7e9-ce85d2e10d66","type":"code","position":"a3","content":{"language":"text","code":"1 undefined 1\n1 2 3","filename":"Output"},"revision":1},{"id":"67601e8d-ca7b-735f-8dd2-1dd3ab79f333","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Default parameters"}]},"revision":1},{"id":"48d1cf75-7d3c-76ca-9134-468de0d9bf17","type":"code","position":"a5","content":{"language":"javascript","code":"function greet(name = \"guest\", greeting = `Hello, ${name}`) {\n  return greeting;\n}\nconsole.log(greet());\nconsole.log(greet(\"Asha\"));\nconsole.log(greet(undefined, \"Hey\"));   // undefined triggers the default\nconsole.log(greet(null));               // null does not","filename":"JavaScript"},"revision":1},{"id":"371848ef-ad07-71ad-b7d5-127e1fd49d07","type":"code","position":"a6","content":{"language":"text","code":"Hello, guest\nHello, Asha\nHey\nHello, null","filename":"Output"},"revision":1},{"id":"cd3be3f4-a841-7e78-9aef-b0d92f52ab56","type":"callout","position":"a7","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Defaults are evaluated "},{"type":"text","text":"at call time","marks":[{"type":"bold"}]},{"type":"text","text":", left to right, and can refer to earlier parameters. A fresh "},{"type":"text","text":"[]","marks":[{"type":"code"}]},{"type":"text","text":" default is created on every call — no Python-style shared mutable default."}]}]}},"revision":1},{"id":"06a3aa52-2083-7550-b356-b3932a5ef14d","type":"code","position":"a8","content":{"language":"javascript","code":"function append(item, list = []) {\n  list.push(item);\n  return list;\n}\nconsole.log(append(1), append(2));\nlet counter = 0;\nconst next = (id = ++counter) => id;\nconsole.log(next(), next(), next(99), next());","filename":"JavaScript"},"revision":1},{"id":"bfe3b45d-22ab-7ead-bd6e-999c790373e5","type":"code","position":"a9","content":{"language":"text","code":"[ 1 ] [ 2 ]\n1 2 99 3","filename":"Output"},"revision":1},{"id":"b72c95cf-5810-7602-9578-d8e4cb0183f1","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Rest parameters vs "},{"type":"text","text":"arguments","marks":[{"type":"code"}]}]},"revision":1},{"id":"0322277b-f269-7d92-8cee-f1cf8083b5be","type":"code","position":"aB","content":{"language":"javascript","code":"function oldStyle() {\n  console.log(Array.isArray(arguments), Array.from(arguments));\n}\nfunction modern(first, ...rest) {\n  console.log(first, rest, Array.isArray(rest));\n}\noldStyle(1, 2);\nmodern(1, 2, 3);\nmodern(1);","filename":"JavaScript"},"revision":1},{"id":"35e55a56-a769-7699-904d-5094b2748961","type":"code","position":"aC","content":{"language":"text","code":"false [ 1, 2 ]\n1 [ 2, 3 ] true\n1 [] true","filename":"Output"},"revision":1},{"id":"cc01b317-1735-7d23-a1a8-3bf512bdffd1","type":"table","position":"aD","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"arguments","marks":[{"type":"code"}]}],[{"type":"text","text":"...rest","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Type"}],[{"type":"text","text":"Array-like object (no "},{"type":"text","text":"map","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"Real array"}]],[[{"type":"text","text":"In arrow functions"}],[{"type":"text","text":"Not available"}],[{"type":"text","text":"Works"}]],[[{"type":"text","text":"Contains"}],[{"type":"text","text":"All arguments"}],[{"type":"text","text":"Only the "},{"type":"text","text":"remaining","marks":[{"type":"italic"}]},{"type":"text","text":" ones"}]],[[{"type":"text","text":"Position"}],[{"type":"text","text":"—"}],[{"type":"text","text":"Must be the last parameter"}]]]},"revision":1},{"id":"a50d074c-889a-79d9-a28c-8cb70a4e25fe","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Named options via destructuring"}]},"revision":1},{"id":"dc9acbde-b353-7ae0-9946-8657c5400963","type":"code","position":"aF","content":{"language":"javascript","code":"function createUser({ name, role = \"viewer\", active = true } = {}) {\n  return `${name} (${role}${active ? \"\" : \", inactive\"})`;\n}\nconsole.log(createUser({ name: \"Ravi\" }));\nconsole.log(createUser({ name: \"Mei\", role: \"admin\", active: false }));\nconsole.log(createUser());","filename":"JavaScript"},"revision":1},{"id":"e0a09ed2-b4f4-7272-bff5-0ac527cade7e","type":"code","position":"aG","content":{"language":"text","code":"Ravi (viewer)\nMei (admin, inactive)\nundefined (viewer)","filename":"Output"},"revision":1},{"id":"67f9f8e1-57fb-73d7-a7be-338758f75846","type":"callout","position":"aH","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use an options object for functions with more than 2–3 parameters: call sites become self-documenting and argument order stops mattering."}]}]}},"revision":1},{"id":"ee64f44e-2af7-715c-b03a-0be51c97a7eb","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the arguments object?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An array-like object available inside regular (non-arrow) functions holding every argument passed. It has "},{"type":"text","text":"length","marks":[{"type":"code"}]},{"type":"text","text":" and indices but no array methods. Prefer rest parameters in modern code."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
