SELECT 'b86117f5-28b4-7eed-bac7-e36c7856f540', 'e2d20395-a57c-78af-85f2-1330aa8f94e8', 1, 'PUBLISHED', 'Polyfills: Implement It Yourself', '[{"id":"6ab53ec7-9251-7501-9b8d-75640f16e114","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-implementing built-ins is the classic way interviewers test understanding of "},{"type":"text","text":"this","marks":[{"type":"code"}]},{"type":"text","text":", prototypes, closures and promises. Each implementation below is tested against the real thing."}]}]}},"revision":1},{"id":"ec71b8cb-4784-7416-9ebe-781bcdb7b9d1","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Array.prototype.map / filter / reduce"}]},"revision":1},{"id":"508b79e6-23c6-7d52-8151-492823e54ac3","type":"code","position":"a2","content":{"language":"javascript","code":"Array.prototype.myMap = function (callback, thisArg) {\n  if (typeof callback !== \"function\") throw new TypeError(callback + \" is not a function\");\n  const result = new Array(this.length);\n  for (let i = 0; i < this.length; i++) {\n    if (i in this) result[i] = callback.call(thisArg, this[i], i, this);   // skip holes\n  }\n  return result;\n};\nArray.prototype.myFilter = function (callback, thisArg) {\n  const result = [];\n  for (let i = 0; i < this.length; i++) {\n    if (i in this && callback.call(thisArg, this[i], i, this)) result.push(this[i]);\n  }\n  return result;\n};\nArray.prototype.myReduce = function (callback, ...init) {\n  let i = 0, acc;\n  if (init.length) acc = init[0];\n  else {\n    while (i < this.length && !(i in this)) i++;\n    if (i >= this.length) throw new TypeError(\"Reduce of empty array with no initial value\");\n    acc = this[i++];\n  }\n  for (; i < this.length; i++) if (i in this) acc = callback(acc, this[i], i, this);\n  return acc;\n};\n\nconst nums = [1, 2, 3, 4];\nconsole.log(nums.myMap((n) => n * 2), nums.map((n) => n * 2));\nconsole.log(nums.myFilter((n) => n % 2), nums.myReduce((a, b) => a + b), nums.myReduce((a, b) => a + b, 10));\nconsole.log([1, , 3].myMap((x) => x), [1, , 3].map((x) => x));","filename":"JavaScript"},"revision":1},{"id":"e70fc51e-4fb7-7afc-8dbd-e4bd8df2e48d","type":"code","position":"a3","content":{"language":"text","code":"[ 2, 4, 6, 8 ] [ 2, 4, 6, 8 ]\n[ 1, 3 ] 10 20\n[ 1, <1 empty item>, 3 ] [ 1, <1 empty item>, 3 ]","filename":"Output"},"revision":1},{"id":"e8723e3a-5616-7f61-87ca-188f88f6c622","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Function.prototype.bind / call"}]},"revision":1},{"id":"355a69cf-43b6-7925-a73a-3a178481714b","type":"code","position":"a5","content":{"language":"javascript","code":"Function.prototype.myCall = function (context, ...args) {\n  context = context ?? globalThis;\n  const key = Symbol(\"fn\");                 // unique key: no clash with existing props\n  context[key] = this;\n  try {\n    return context[key](...args);           // implicit binding does the work\n  } finally {\n    delete context[key];\n  }\n};\nFunction.prototype.myBind = function (context, ...preset) {\n  const fn = this;\n  function bound(...later) {\n    // when called with `new`, ignore the bound context\n    return new.target ? new fn(...preset, ...later) : fn.apply(context, [...preset, ...later]);\n  }\n  bound.prototype = Object.create(fn.prototype);\n  return bound;\n};\n\nfunction intro(greeting, mark) { return `${greeting}, ${this.name}${mark}`; }\nconst asha = { name: \"Asha\" };\nconsole.log(intro.myCall(asha, \"Hello\", \"!\"));\nconsole.log(intro.myBind(asha, \"Hi\")(\"?\"), Object.keys(asha));\n\nfunction Point(x, y) { this.x = x; this.y = y; }\nconst PointAtX1 = Point.myBind(null, 1);\nconst p = new PointAtX1(2);\nconsole.log(p.x, p.y, p instanceof Point);","filename":"JavaScript"},"revision":1},{"id":"c7bbab5a-7db1-7297-b4ca-499e9e8a59f5","type":"code","position":"a6","content":{"language":"text","code":"Hello, Asha!\nHi, Asha? [ ''name'' ]\n1 2 true","filename":"Output"},"revision":1},{"id":"a166aa74-2a8d-706e-8adb-3127a50e5e90","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Promise.all and Promise.allSettled"}]},"revision":1},{"id":"20d5cb99-a45f-7f15-946f-86278bdcf89d","type":"code","position":"a8","content":{"language":"javascript","code":"function promiseAll(iterable) {\n  return new Promise((resolve, reject) => {\n    const items = [...iterable];\n    const results = new Array(items.length);\n    let remaining = items.length;\n    if (remaining === 0) return resolve(results);\n    items.forEach((item, i) => {\n      Promise.resolve(item).then((value) => {\n        results[i] = value;                 // keep INPUT order, not finish order\n        if (--remaining === 0) resolve(results);\n      }, reject);                           // first rejection wins\n    });\n  });\n}\nconst promiseAllSettled = (iterable) =>\n  promiseAll([...iterable].map((p) =>\n    Promise.resolve(p).then(\n      (value) => ({ status: \"fulfilled\", value }),\n      (reason) => ({ status: \"rejected\", reason })\n    )));\n\nconst delay = (ms, v) => new Promise((r) => setTimeout(() => r(v), ms));\nconsole.log(await promiseAll([delay(20, \"slow\"), delay(5, \"fast\"), 3]));\nconsole.log(await promiseAll([]));\nawait promiseAll([delay(5, 1), Promise.reject(new Error(\"fail\"))]).catch((e) => console.log(e.message));\nconsole.log(await promiseAllSettled([1, Promise.reject(\"no\")]));","filename":"JavaScript"},"revision":1},{"id":"9b11ff2f-561d-726d-83d2-2fb4dcccf6ce","type":"code","position":"a9","content":{"language":"text","code":"[ ''slow'', ''fast'', 3 ]\n[]\nfail\n[\n  { status: ''fulfilled'', value: 1 },\n  { status: ''rejected'', reason: ''no'' }\n]","filename":"Output"},"revision":1},{"id":"f1830359-b8f6-7207-9280-c6fdafed7ddc","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Promise.race and a mini Promise"}]},"revision":1},{"id":"a01d5087-2ccf-7980-812f-a7355f33d7cd","type":"code","position":"aB","content":{"language":"javascript","code":"const promiseRace = (iterable) =>\n  new Promise((resolve, reject) => {\n    for (const p of iterable) Promise.resolve(p).then(resolve, reject);\n  });\n\nclass MyPromise {\n  #state = \"pending\"; #value; #handlers = [];\n  constructor(executor) {\n    const settle = (state) => (value) => {\n      if (this.#state !== \"pending\") return;\n      if (state === \"fulfilled\" && value && typeof value.then === \"function\") {\n        return value.then(settle(\"fulfilled\"), settle(\"rejected\"));   // adopt thenables\n      }\n      this.#state = state; this.#value = value;\n      this.#handlers.forEach((h) => h());\n    };\n    try { executor(settle(\"fulfilled\"), settle(\"rejected\")); } catch (e) { settle(\"rejected\")(e); }\n  }\n  then(onFul, onRej) {\n    return new MyPromise((resolve, reject) => {\n      const run = () => queueMicrotask(() => {\n        const cb = this.#state === \"fulfilled\" ? onFul : onRej;\n        if (typeof cb !== \"function\") return (this.#state === \"fulfilled\" ? resolve : reject)(this.#value);\n        try { resolve(cb(this.#value)); } catch (e) { reject(e); }\n      });\n      this.#state === \"pending\" ? this.#handlers.push(run) : run();\n    });\n  }\n  catch(onRej) { return this.then(undefined, onRej); }\n}\n\nconsole.log(await promiseRace([new Promise((r) => setTimeout(r, 20, \"slow\")), \"instant\"]));\nnew MyPromise((res) => setTimeout(res, 5, 2))\n  .then((v) => v * 10)\n  .then((v) => { throw new Error(`boom at ${v}`); })\n  .catch((e) => e.message)\n  .then((msg) => console.log(\"MyPromise chain:\", msg));\nconst value = await new MyPromise((res) => res(new MyPromise((r) => r(\"adopted\"))));\nconsole.log(value);","filename":"JavaScript"},"revision":1},{"id":"6e5bc84f-0f9a-7828-891f-9220330bc308","type":"code","position":"aC","content":{"language":"text","code":"instant\nadopted\nMyPromise chain: boom at 20","filename":"Output"},"revision":1},{"id":"e08044d0-ec3d-72e8-9e6b-ce2ef88bfb3b","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Deep clone, deep equal, flatten"}]},"revision":1},{"id":"e9db28f6-81cd-7a58-a44e-e075423c4035","type":"code","position":"aE","content":{"language":"javascript","code":"function deepClone(value, seen = new WeakMap()) {\n  if (value === null || typeof value !== \"object\") return value;\n  if (value instanceof Date) return new Date(value);\n  if (value instanceof RegExp) return new RegExp(value.source, value.flags);\n  if (seen.has(value)) return seen.get(value);            // handle cycles\n  if (value instanceof Map) {\n    const m = new Map(); seen.set(value, m);\n    value.forEach((v, k) => m.set(deepClone(k, seen), deepClone(v, seen)));\n    return m;\n  }\n  const copy = Array.isArray(value) ? [] : Object.create(Object.getPrototypeOf(value));\n  seen.set(value, copy);\n  for (const key of Reflect.ownKeys(value)) copy[key] = deepClone(value[key], seen);\n  return copy;\n}\nfunction deepEqual(a, b) {\n  if (Object.is(a, b)) return true;\n  if (typeof a !== \"object\" || typeof b !== \"object\" || !a || !b) return false;\n  if (Object.getPrototypeOf(a) !== Object.getPrototypeOf(b)) return false;\n  const ka = Reflect.ownKeys(a), kb = Reflect.ownKeys(b);\n  return ka.length === kb.length && ka.every((k) => deepEqual(a[k], b[k]));\n}\nconst flatten = (arr, depth = Infinity) =>\n  depth < 1 ? arr.slice() : arr.reduce((acc, x) => acc.concat(Array.isArray(x) ? flatten(x, depth - 1) : [x]), []);\n\nconst src = { d: new Date(0), list: [1, { two: 2 }], map: new Map([[\"k\", [1]]]) };\nsrc.self = src;\nconst copy = deepClone(src);\nconsole.log(copy.self === copy, copy.list[1] !== src.list[1], copy.map.get(\"k\"));\nconsole.log(deepEqual({ a: [1, { b: 2 }] }, { a: [1, { b: 2 }] }), deepEqual([1], { 0: 1 }));\nconsole.log(flatten([1, [2, [3, [4]]]]), flatten([1, [2, [3]]], 1));","filename":"JavaScript"},"revision":1},{"id":"3ba7b590-dde4-7b3c-a17d-c1fc650e0189","type":"code","position":"aF","content":{"language":"text","code":"true true [ 1 ]\ntrue false\n[ 1, 2, 3, 4 ] [ 1, 2, [ 3 ] ]","filename":"Output"},"revision":1},{"id":"bb49427a-481b-7bb3-ac55-d2099e2df60e","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"A tiny EventEmitter"}]},"revision":1},{"id":"866d4dfa-f18f-74f1-a993-2b5b6edba7ad","type":"code","position":"aH","content":{"language":"javascript","code":"class Emitter {\n  #events = new Map();\n  on(name, fn) {\n    (this.#events.get(name) ?? this.#events.set(name, []).get(name)).push(fn);\n    return () => this.off(name, fn);        // return an unsubscribe function\n  }\n  off(name, fn) {\n    this.#events.set(name, (this.#events.get(name) ?? []).filter((f) => f !== fn && f.original !== fn));\n  }\n  once(name, fn) {\n    const wrapper = (...args) => { this.off(name, wrapper); fn(...args); };\n    wrapper.original = fn;\n    return this.on(name, wrapper);\n  }\n  emit(name, ...args) {\n    const list = [...(this.#events.get(name) ?? [])];   // copy: listeners may unsubscribe\n    list.forEach((fn) => fn(...args));\n    return list.length > 0;\n  }\n}\nconst e = new Emitter();\nconst unsubscribe = e.on(\"msg\", (m) => console.log(\"A got\", m));\ne.once(\"msg\", (m) => console.log(\"B (once) got\", m));\ne.emit(\"msg\", 1);\ne.emit(\"msg\", 2);\nunsubscribe();\nconsole.log(e.emit(\"msg\", 3));","filename":"JavaScript"},"revision":1},{"id":"d6a4c7e7-b110-7849-b686-7e59b7c430c3","type":"code","position":"aI","content":{"language":"text","code":"A got 1\nB (once) got 1\nA got 2\nfalse","filename":"Output"},"revision":1},{"id":"b0bfb37f-a572-7806-84c6-9f2a199c158e","type":"callout","position":"aJ","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Real polyfills check "},{"type":"text","text":"if (!Array.prototype.x)","marks":[{"type":"code"}]},{"type":"text","text":" before defining, use "},{"type":"text","text":"Object.defineProperty","marks":[{"type":"code"}]},{"type":"text","text":" to stay non-enumerable, and follow the spec''s edge cases. In production, use core-js rather than hand-written versions."}]}]}},"revision":1},{"id":"2adc16bf-ecae-7b83-94cb-4e848cc3b52d","type":"question","position":"aK","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does a correct Promise.all polyfill need a counter instead of checking results.length?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Results are written by index as promises settle in any order; assigning "},{"type":"text","text":"results[2]","marks":[{"type":"code"}]},{"type":"text","text":" first makes "},{"type":"text","text":"length","marks":[{"type":"code"}]},{"type":"text","text":" 3 immediately. A countdown of pending items is the reliable completion signal."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
