  ('ec71b8cb-4784-7416-9ebe-781bcdb7b9d1', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"Array.prototype.map / filter / reduce"}]}'),
  ('508b79e6-23c6-7d52-8151-492823e54ac3', 'a2', 'code', '{"language":"javascript","code":"Array.prototype.myMap = function (callback, thisArg) {\n  if (typeof callback !== \"function\") throw new TypeError(callback + \" is not a function\");\n  const result = new Array(this.length);\n  for (let i = 0; i < this.length; i++) {\n    if (i in this) result[i] = callback.call(thisArg, this[i], i, this);   // skip holes\n  }\n  return result;\n};\nArray.prototype.myFilter = function (callback, thisArg) {\n  const result = [];\n  for (let i = 0; i < this.length; i++) {\n    if (i in this && callback.call(thisArg, this[i], i, this)) result.push(this[i]);\n  }\n  return result;\n};\nArray.prototype.myReduce = function (callback, ...init) {\n  let i = 0, acc;\n  if (init.length) acc = init[0];\n  else {\n    while (i < this.length && !(i in this)) i++;\n    if (i >= this.length) throw new TypeError(\"Reduce of empty array with no initial value\");\n    acc = this[i++];\n  }\n  for (; i < this.length; i++) if (i in this) acc = callback(acc, this[i], i, this);\n  return acc;\n};\n\nconst nums = [1, 2, 3, 4];\nconsole.log(nums.myMap((n) => n * 2), nums.map((n) => n * 2));\nconsole.log(nums.myFilter((n) => n % 2), nums.myReduce((a, b) => a + b), nums.myReduce((a, b) => a + b, 10));\nconsole.log([1, , 3].myMap((x) => x), [1, , 3].map((x) => x));","filename":"JavaScript"}'),
  ('e70fc51e-4fb7-7afc-8dbd-e4bd8df2e48d', 'a3', 'code', '{"language":"text","code":"[ 2, 4, 6, 8 ] [ 2, 4, 6, 8 ]\n[ 1, 3 ] 10 20\n[ 1, <1 empty item>, 3 ] [ 1, <1 empty item>, 3 ]","filename":"Output"}'),
  ('e8723e3a-5616-7f61-87ca-188f88f6c622', 'a4', 'heading', '{"level":1,"content":[{"type":"text","text":"Function.prototype.bind / call"}]}'),
  ('355a69cf-43b6-7925-a73a-3a178481714b', 'a5', 'code', '{"language":"javascript","code":"Function.prototype.myCall = function (context, ...args) {\n  context = context ?? globalThis;\n  const key = Symbol(\"fn\");                 // unique key: no clash with existing props\n  context[key] = this;\n  try {\n    return context[key](...args);           // implicit binding does the work\n  } finally {\n    delete context[key];\n  }\n};\nFunction.prototype.myBind = function (context, ...preset) {\n  const fn = this;\n  function bound(...later) {\n    // when called with `new`, ignore the bound context\n    return new.target ? new fn(...preset, ...later) : fn.apply(context, [...preset, ...later]);\n  }\n  bound.prototype = Object.create(fn.prototype);\n  return bound;\n};\n\nfunction intro(greeting, mark) { return `${greeting}, ${this.name}${mark}`; }\nconst asha = { name: \"Asha\" };\nconsole.log(intro.myCall(asha, \"Hello\", \"!\"));\nconsole.log(intro.myBind(asha, \"Hi\")(\"?\"), Object.keys(asha));\n\nfunction Point(x, y) { this.x = x; this.y = y; }\nconst PointAtX1 = Point.myBind(null, 1);\nconst p = new PointAtX1(2);\nconsole.log(p.x, p.y, p instanceof Point);","filename":"JavaScript"}'),
  ('c7bbab5a-7db1-7297-b4ca-499e9e8a59f5', 'a6', 'code', '{"language":"text","code":"Hello, Asha!\nHi, Asha? [ ''name'' ]\n1 2 true","filename":"Output"}'),
  ('a166aa74-2a8d-706e-8adb-3127a50e5e90', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"Promise.all and Promise.allSettled"}]}'),
  ('20d5cb99-a45f-7f15-946f-86278bdcf89d', 'a8', 'code', '{"language":"javascript","code":"function promiseAll(iterable) {\n  return new Promise((resolve, reject) => {\n    const items = [...iterable];\n    const results = new Array(items.length);\n    let remaining = items.length;\n    if (remaining === 0) return resolve(results);\n    items.forEach((item, i) => {\n      Promise.resolve(item).then((value) => {\n        results[i] = value;                 // keep INPUT order, not finish order\n        if (--remaining === 0) resolve(results);\n      }, reject);                           // first rejection wins\n    });\n  });\n}\nconst promiseAllSettled = (iterable) =>\n  promiseAll([...iterable].map((p) =>\n    Promise.resolve(p).then(\n      (value) => ({ status: \"fulfilled\", value }),\n      (reason) => ({ status: \"rejected\", reason })\n    )));\n\nconst delay = (ms, v) => new Promise((r) => setTimeout(() => r(v), ms));\nconsole.log(await promiseAll([delay(20, \"slow\"), delay(5, \"fast\"), 3]));\nconsole.log(await promiseAll([]));\nawait promiseAll([delay(5, 1), Promise.reject(new Error(\"fail\"))]).catch((e) => console.log(e.message));\nconsole.log(await promiseAllSettled([1, Promise.reject(\"no\")]));","filename":"JavaScript"}'),
