text","text":"typeof","marks":[{"type":"code"}]},{"type":"text","text":" runs."}]}]}},"revision":1},{"id":"21f6cde0-ac45-7b62-91e5-4ef076ada7c5","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"2. Closures in loops"}]},"revision":1},{"id":"33d78e7b-8e65-7477-a03a-bb3afc0dd29f","type":"code","position":"a6","content":{"language":"javascript","code":"const fns = [];\nfor (var i = 0; i < 3; i++) fns.push(() => i);\nconst fns2 = [];\nfor (let i = 0; i < 3; i++) fns2.push(() => i);\nconsole.log(fns.map((f) => f()), fns2.map((f) => f()));","filename":"JavaScript"},"revision":1},{"id":"531a1347-effd-7796-90dc-09b43001c960","type":"code","position":"a7","content":{"language":"text","code":"[ 3, 3, 3 ] [ 0, 1, 2 ]","filename":"Output"},"revision":1},{"id":"2b682c48-b521-706b-ac55-b9bce44f07ef","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"3. this"}]},"revision":1},{"id":"09e621ad-f79d-7ce4-a39e-a94799e0c2d8","type":"code","position":"a9","content":{"language":"javascript","code":"const obj = {\n  name: \"obj\",\n  regular() { return this.name; },\n  arrow: () => typeof this,\n  nested() {\n    const inner = () => this.name;     // arrow borrows nested()''s this\n    function plain() { return this; }  // plain call → undefined (strict)\n    return [inner(), plain()];\n  },\n};\nconst { regular } = obj;\nconsole.log(obj.regular(), obj.arrow(), obj.nested());\ntry { regular(); } catch (e) { console.log(e.constructor.name); }","filename":"JavaScript"},"revision":1},{"id":"f1d78e45-d586-7735-935e-4197db8aa4ab","type":"code","position":"aA","content":{"language":"text","code":"obj undefined [ ''obj'', undefined ]\nTypeError","filename":"Output"},"revision":1},{"id":"90442f89-93c2-7cdc-b896-ae8babf0bac9","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"4. Event loop ordering"}]},"revision":1},{"id":"06d5e245-9303-760b-9a9b-462174827ba6","type":"code","position":"aC","content":{"language":"javascript","code":"console.log(1);\nsetTimeout(() => console.log(2), 0);\nPromise.resolve().then(() => {\n  console.log(3);\n  setTimeout(() => console.log(4), 0);\n  Promise.resolve().then(() => console.log(5));\n});\n(async () => {\n  console.log(6);\n  await undefined;\n  console.log(7);\n})();\nconsole.log(8);","filename":"JavaScript"},"revision":1},{"id":"cf0e20d7-a28a-7853-b9ac-dc086289a2e1","type":"code","position":"aD","content":{"language":"text","code":"1\n6\n8\n3\n7\n5\n2\n4","filename":"Output"},"revision":1},{"id":"3726a2f9-dfa1-7699-bb40-2e22b917e620","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sync first (1, 6, 8). Then microtasks in queue order: the "},{"type":"text","text":"then","marks":[{"type":"code"}]},{"type":"text","text":" (3, which queues 5 and timer 4), the "},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":" continuation (7), then 5. Finally macrotasks in order: 2, then 4."}]}]}},"revision":1},{"id":"26bcc9ca-2562-792f-ba69-f1410ac2dce5","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"5. Coercion"}]},"revision":1},{"id":"7ee71583-f883-73e1-b288-a28a68928727","type":"code","position":"aG","content":{"language":"javascript","code":"console.log(1 < 2 < 3, 3 > 2 > 1);\nconsole.log(\"5\" + 3, \"5\" - 3, \"5\" * \"2\", true + true);\nconsole.log([] + null + 1, [2] * [3], {} + []);\nconsole.log(0 || null || \"\" || undefined, 1 && \"a\" && 0);","filename":"JavaScript"},"revision":1},{"id":"ceb3450b-4fe2-786b-85b4-1ca443687b96","type":"code","position":"aH","content":{"language":"text","code":"true false\n53 2 10 2\nnull1 6 [object Object]\nundefined 0","filename":"Output"},"revision":1},{"id":"856a68e0-8651-760d-8d85-e6943920a4d6","type":"text","position":"aI","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"3 > 2 > 1","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"true > 1","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"1 > 1","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"false","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"[] + null + 1","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"\"\" + \"null\"","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"\"null\" + 1","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"||","marks":[{"type":"code"}]},{"type":"text","text":" returns the last operand when all are falsy; "},{"type":"text","text":"&&","marks":[{"type":"code"}]},{"type":"text","text":" returns the first falsy one."}]}]}},"revision":1},{"id":"b96d49fb-795f-7787-b448-e12e49ba09c7","type":"heading","position":"aJ","content":{"level":1,"content":[{"type":"text","text":"6. References and copies"}]},"revision":1},{"id":"48d4fb52-ef9d-7771-a63c-fb4ec395c630","type":"code","position":"aK","content":{"language":"javascript","code":"let a = { n: 1 };\nlet b = a;\na.n = 2;\na = { n: 3 };\nconsole.log(b.n);\n\nconst arr = [1, 2, 3];\nconst copy = arr;\ncopy.push(4);\nconst spread = [...arr];\nspread.push(5);\nconsole.log(arr.length, spread.length);\n\nfunction change(o) { o.value = \"changed\"; o = { value: \"replaced\" }; }\nconst item = { value: \"original\" };\nchange(item);\nconsole.log(item.value);","filename":"JavaScript"},"revision":1},{"id":"6ef05df7-ede1-75fa-acea-9e5e58b7718c","type":"code","position":"aL","content":{"language":"text","code":"2\n4 5\nchanged","filename":"Output"},"revision":1},{"id":"1ddfecd7-2c7f-7dcd-85b3-e062dccf00aa","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"7. Promises"}]},"revision":1},{"id":"f8845e7e-2c33-7c92-8f73-e2fed34a1ab7","type":"code","position":"aN","content":{"language":"javascript","code":"const p = new Promise((resolve, reject) => {\n  console.log(\"A\");\n  resolve(\"B\");\n  reject(\"C\");\n  console.log(\"D\");\n});\np.then(console.log).catch(() => console.log(\"never\"));\nPromise.reject(new Error(\"E\"))\n  .then(() => console.log(\"skipped\"))\n  .catch((e) => e.message)\n  .then((m) => console.log(m + \"!\"))\n  .finally(() => console.log(\"F\"));\nconsole.log(\"G\");","filename":"JavaScript"},"revision":1},{"id":"a5582e2d-c6bd-762c-88d5-fe450cd78cb4","type":"code","position":"aO","content":{"language":"text","code":"A\nD\nG\nB\nE!\nF","filename":"Output"},"revision":1},{"id":"0c12809e-1e0c-7eb7-8d7e-8420d81fbd97","type":"heading","position":"aP","content":{"level":1,"content":[{"type":"text","text":"8. Mixed bag"}]},"revision":1},{"id":"793ce479-7084-7946-a4c3-3b0aefbc5689","type":"code","position":"aQ","content":{"language":"javascript","code":"console.log(typeof typeof 1, typeof [] === typeof null);\nconsole.log([...\"abc\"].map(parseInt));\nconsole.log(0.1 + 0.2 == 0.3, 0.5 + 0.25 == 0.75);\nconst x = { a: 1 }, y = { a: 1 };\nconsole.log(x == y, JSON.stringify(x) === JSON.stringify(y));\nconsole.log([1, 2, 3].indexOf(3) > -1 ? \"found\" : \"missing\", [10, 1, 3].sort().join());\nfunction Foo() { return this; }\nconsole.log(new Foo() instanceof Foo, Foo());","filename":"JavaScript"},"revision":1},{"id":"d8063ead-8be1-7cdd-b165-e7d6927de3a8","type":"code","position":"aR","content":{"language":"text","code":"string true\n[ NaN, NaN, NaN ]\nfalse true\nfalse true\nfound 1,10,3\ntrue undefined","filename":"Output"},"revision":1},{"id":"e5602f9f-0adb-75cd-8e11-dde1a31205f2","type":"callout","position":"aS","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"parseInt(\"a\", 0)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"NaN","marks":[{"type":"code"}]},{"type":"text","text":" (radix 0 means default 10, but "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" is not a digit), then radix 1 is invalid, and "},{"type":"text","text":"\"c\"","marks":[{"type":"code"}]},{"type":"text","text":" isn''t a base-2 digit. "},{"type":"text","text":"0.5 + 0.25","marks":[{"type":"code"}]},{"type":"text","text":" is exact because both are powers of two."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
