SELECT '18b51ec3-90ad-7234-b4e0-a261a0103efe', '78e7814f-6b8b-7982-8b5e-31e4393324cd', 1, 'PUBLISHED', 'Primitives vs References', '[{"id":"a6da05a0-2df0-7cd6-a7e2-4b62d8e85a28","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Primitives are copied by value; objects are shared by reference. Almost every “why did my data change?” bug comes from this."}]}]}},"revision":1},{"id":"81bbc023-473c-78c4-9f98-e0a82234d1d0","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Copying a primitive"}]},"revision":1},{"id":"5c6a0ee6-62dc-7bf9-88b3-7324f81db8f4","type":"code","position":"a2","content":{"language":"javascript","code":"let a = 10;\nlet b = a;     // b gets its own copy of the value\nb = 20;\nconsole.log(a, b);","filename":"JavaScript"},"revision":1},{"id":"87ea6b87-45f5-70f0-8bed-b3a070319d02","type":"code","position":"a3","content":{"language":"text","code":"10 20","filename":"Output"},"revision":1},{"id":"e8c4c38b-b824-712b-a33b-cbb34023976e","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Copying an object reference"}]},"revision":1},{"id":"8331950f-ad28-7ca5-a7bc-0fdd28d22ef0","type":"code","position":"a5","content":{"language":"javascript","code":"const original = { score: 10 };\nconst alias = original;   // copies the *reference*, not the object\nalias.score = 99;\nconsole.log(original.score);\nconsole.log(original === alias);","filename":"JavaScript"},"revision":1},{"id":"a2beb0b5-2728-7e3d-95fe-5103b557b261","type":"code","position":"a6","content":{"language":"text","code":"99\ntrue","filename":"Output"},"revision":1},{"id":"50900e94-7838-700a-8a50-8c86d0bd1f87","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Primitives"}],[{"type":"text","text":"Objects (incl. arrays, functions)"}]],[[{"type":"text","text":"Stored as"}],[{"type":"text","text":"The value itself"}],[{"type":"text","text":"A reference to a heap object"}]],[[{"type":"text","text":"Assignment copies"}],[{"type":"text","text":"The value"}],[{"type":"text","text":"The reference"}]],[[{"type":"text","text":"===","marks":[{"type":"code"}]},{"type":"text","text":" compares"}],[{"type":"text","text":"Values"}],[{"type":"text","text":"Identity (same object?)"}]],[[{"type":"text","text":"Mutable?"}],[{"type":"text","text":"No — immutable"}],[{"type":"text","text":"Yes"}]]]},"revision":1},{"id":"1bcdf1cf-b375-799e-a12d-aebf03cea461","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Equality compares identity for objects"}]},"revision":1},{"id":"e62c6574-619c-7265-b04e-1331ab401fb9","type":"code","position":"a9","content":{"language":"javascript","code":"console.log(\"abc\" === \"abc\");\nconsole.log({ a: 1 } === { a: 1 });\nconsole.log([1, 2] === [1, 2]);\nconst arr = [1, 2];\nconsole.log(arr === arr);","filename":"JavaScript"},"revision":1},{"id":"ef6631f7-4ae5-7f33-ad76-ae67deea0c58","type":"code","position":"aA","content":{"language":"text","code":"true\nfalse\nfalse\ntrue","filename":"Output"},"revision":1},{"id":"a84a73e5-b13a-7ef4-a7f9-ef6994fddf71","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Passing to functions: always by value (of the reference)"}]},"revision":1},{"id":"dc258daf-c241-7037-ba37-ccaba33361a6","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"JavaScript is "},{"type":"text","text":"pass-by-value","marks":[{"type":"bold"}]},{"type":"text","text":". For objects the "},{"type":"text","text":"value","marks":[{"type":"italic"}]},{"type":"text","text":" being passed is a reference — so a function can mutate the caller''s object, but reassigning the parameter never affects the caller."}]}]}},"revision":1},{"id":"ee47c384-c1a0-796e-aec1-fe9cdc805a34","type":"code","position":"aD","content":{"language":"javascript","code":"function mutate(obj) {\n  obj.touched = true;   // changes the shared object\n}\nfunction reassign(obj) {\n  obj = { replaced: true };  // only rebinds the local parameter\n}\nconst data = {};\nmutate(data);\nreassign(data);\nconsole.log(data);","filename":"JavaScript"},"revision":1},{"id":"94368ce3-7a2c-7fd0-83e3-79680e628a81","type":"code","position":"aE","content":{"language":"text","code":"{ touched: true }","filename":"Output"},"revision":1},{"id":"f3417a73-5605-7bf2-adb5-526bcdb20698","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Primitives are immutable"}]},"revision":1},{"id":"f9a52372-04eb-7ce9-8c79-625a8aaa330c","type":"code","position":"aG","content":{"language":"javascript","code":"const s = \"hello\";\nconst upper = s.toUpperCase();   // returns a NEW string\nconsole.log(s, upper);\nconst t = \"cat\";\ntry {\n  t[0] = \"b\";                    // strings can''t change in place\n} catch (e) {\n  console.log(e.name + \": \" + e.message);\n}\nconsole.log(t);","filename":"JavaScript"},"revision":1},{"id":"ed2296f5-afc8-730a-ab51-c47d4490c438","type":"code","position":"aH","content":{"language":"text","code":"hello HELLO\nTypeError: Cannot assign to read only property ''0'' of string ''cat''\ncat","filename":"Output"},"revision":1},{"id":"c21e2355-0bc4-7108-8b25-3df25ebe7f11","type":"text","position":"aI","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In strict mode (every ES module) the assignment throws; in a sloppy script it is "},{"type":"text","text":"silently ignored","marks":[{"type":"italic"}]},{"type":"text","text":". Either way the string never changes."}]}]}},"revision":1},{"id":"fc15fdf3-3150-71a8-a87e-ee3e3b699400","type":"callout","position":"aJ","content":{"variant":"note","title":"Autoboxing","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Methods on primitives work because of "},{"type":"text","text":"autoboxing","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"text","text":"\"hi\".length","marks":[{"type":"code"}]},{"type":"text","text":" briefly wraps the string in a "},{"type":"text","text":"String","marks":[{"type":"code"}]},{"type":"text","text":" object, reads the property, and discards the wrapper."}]}]}},"revision":1},{"id":"29222112-834e-7f3b-934d-ce936ad559aa","type":"callout","position":"aK","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"To copy an object, use spread ("},{"type":"text","text":"{...obj}","marks":[{"type":"code"}]},{"type":"text","text":", shallow) or "},{"type":"text","text":"structuredClone(obj)","marks":[{"type":"code"}]},{"type":"text","text":" (deep) — see "},{"type":"text","text":"Immutability & Copying","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ec659a99-7075-75e9-aaeb-e692d1a6c21f","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is JavaScript pass-by-reference?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. It is always pass-by-value; for objects the value is a reference (sometimes called "},{"type":"text","text":"call by sharing","marks":[{"type":"italic"}]},{"type":"text","text":"). Mutating through the parameter is visible to the caller, but reassigning the parameter is not."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
