  ('7af79ba5-1d34-705b-81d1-929c6c88caa9', 'a2', 'code', '{"language":"javascript","code":"const ok = (ms, v) => new Promise((res) => setTimeout(() => res(v), ms));\nconst bad = (ms, msg) => new Promise((_, rej) => setTimeout(() => rej(new Error(msg)), ms));\n\nconsole.log(\"all:\", await Promise.all([ok(30, \"a\"), ok(10, \"b\"), 42]));\nawait Promise.all([ok(10, \"a\"), bad(5, \"db down\")]).catch((e) => console.log(\"all rejected:\", e.message));\n\nconst settled = await Promise.allSettled([ok(5, \"a\"), bad(5, \"nope\")]);\nconsole.log(settled.map((r) => (r.status === \"fulfilled\" ? r : { ...r, reason: r.reason.message })));\n\nconsole.log(\"race:\", await Promise.race([ok(20, \"slow\"), ok(5, \"fast\")]));\nconsole.log(\"any:\", await Promise.any([bad(5, \"x\"), ok(15, \"first success\")]));\ntry {\n  await Promise.any([bad(5, \"e1\"), bad(5, \"e2\")]);\n} catch (e) {\n  console.log(e.constructor.name, e.errors.map((x) => x.message));\n}","filename":"JavaScript"}'),
  ('419e9e1e-cac7-7cdb-88b2-2ed231c375a4', 'a3', 'code', '{"language":"text","code":"all: [ ''a'', ''b'', 42 ]\nall rejected: db down\n[\n  { status: ''fulfilled'', value: ''a'' },\n  { status: ''rejected'', reason: ''nope'' }\n]\nrace: fast\nany: first success\nAggregateError [ ''e1'', ''e2'' ]","filename":"Output"}'),
  ('938b7869-7a79-7673-a333-343abde45732', 'a4', 'callout', '{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Promise.all","marks":[{"type":"code"}]},{"type":"text","text":" rejects fast, but the other operations "},{"type":"text","text":"keep running","marks":[{"type":"bold"}]},{"type":"text","text":" — promises are not cancellable. Use an "},{"type":"text","text":"AbortController","marks":[{"type":"code"}]},{"type":"text","text":" if you need to stop them."}]}]}}'),
  ('ecf40671-6aec-7f97-8fbd-c20877eb59aa', 'a5', 'heading', '{"level":1,"content":[{"type":"text","text":"Pattern: timeout with race"}]}'),
  ('710885b7-877e-7f47-a99c-2e5b8ed7ddda', 'a6', 'code', '{"language":"javascript","code":"const timeout = (ms) => new Promise((_, rej) => setTimeout(() => rej(new Error(`timed out after ${ms}ms`)), ms));\nconst slowFetch = new Promise((res) => setTimeout(() => res(\"data\"), 50));\ntry {\n  await Promise.race([slowFetch, timeout(10)]);\n} catch (e) {\n  console.log(e.message);\n}","filename":"JavaScript"}'),
  ('f41994b9-e0cb-705d-be81-7b5c0c427dff', 'a7', 'code', '{"language":"text","code":"timed out after 10ms","filename":"Output"}'),
  ('8c700e50-223d-7c1b-a0d8-31f29942d89f', 'a8', 'heading', '{"level":1,"content":[{"type":"text","text":"Sequential vs parallel"}]}'),
  ('f97a9af5-d2d1-7380-b9b7-8070ecf3f668', 'a9', 'code', '{"language":"javascript","code":"const job = (id, log) => new Promise((res) => setTimeout(() => { log.push(id); res(id); }, 10 * (4 - id)));\n\nconst seq = [];\nfor (const id of [1, 2, 3]) await job(id, seq);          // one after another\nconsole.log(\"sequential finish order:\", seq);\n\nconst par = [];\nconst results = await Promise.all([1, 2, 3].map((id) => job(id, par)));  // all at once\nconsole.log(\"parallel finish order:\", par, \"results:\", results);","filename":"JavaScript"}'),
  ('aa6d34b7-77e8-7a63-955a-bcefcb38f0e4', 'aA', 'code', '{"language":"text","code":"sequential finish order: [ 1, 2, 3 ]\nparallel finish order: [ 3, 2, 1 ] results: [ 1, 2, 3 ]","filename":"Output"}'),
  ('06a82dce-c1ee-7c32-87e8-077022396f32', 'aB', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Promise.all vs Promise.allSettled?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"all","marks":[{"type":"code"}]},{"type":"text","text":" fails fast: it rejects with the first error and you lose the other results. "},{"type":"text","text":"allSettled","marks":[{"type":"code"}]},{"type":"text","text":" always waits for every promise and reports each outcome, so use it when partial success is acceptable (e.g. sending many notifications)."}]}]}}'),
  ('b185dee3-bd0f-74ef-96e3-6bcd255167fc', 'aC', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"race vs any?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"race","marks":[{"type":"code"}]},{"type":"text","text":" settles with the first promise to settle, success or failure. "},{"type":"text","text":"any","marks":[{"type":"code"}]},{"type":"text","text":" ignores rejections and fulfils with the first success; it rejects only if all reject (with an "},{"type":"text","text":"AggregateError","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}}')
