SELECT '1aa67022-b281-7888-aa07-f4839f93a6a3', '6a07913f-0ace-77df-803b-259267aefa3b', 1, 'PUBLISHED', 'Promises', '[{"id":"8182846d-f9a7-7ab1-b1f8-7a958b5c85a4","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Promise is an object representing a value that will be available later — or an error. It is the foundation of modern async JavaScript."}]}]}},"revision":1},{"id":"04fc4c7a-1611-7472-a3f4-3baa3bd60e91","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Promise","marks":[{"type":"bold"}]},{"type":"text","text":" — an object in one of three states: "},{"type":"text","text":"pending","marks":[{"type":"bold"}]},{"type":"text","text":", then either "},{"type":"text","text":"fulfilled","marks":[{"type":"bold"}]},{"type":"text","text":" with a value or "},{"type":"text","text":"rejected","marks":[{"type":"bold"}]},{"type":"text","text":" with a reason. Once settled it never changes."}]}]}},"revision":1},{"id":"55eee25f-19d6-7622-947d-b6ceedeab645","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Creating and consuming"}]},"revision":1},{"id":"8545bdb8-3516-79cd-b435-0ed78851239a","type":"code","position":"a3","content":{"language":"javascript","code":"const wait = (ms, value) => new Promise((resolve) => setTimeout(() => resolve(value), ms));\nconst fail = (msg) => new Promise((_, reject) => setTimeout(() => reject(new Error(msg)), 5));\n\nwait(10, \"done\").then((v) => console.log(\"fulfilled:\", v));\nfail(\"boom\")\n  .then(() => console.log(\"never runs\"))\n  .catch((err) => console.log(\"rejected:\", err.message))\n  .finally(() => console.log(\"finally: cleanup either way\"));","filename":"JavaScript"},"revision":1},{"id":"50b2fd23-1749-791c-a6c4-19d7b838fe2e","type":"code","position":"a4","content":{"language":"text","code":"rejected: boom\nfinally: cleanup either way\nfulfilled: done","filename":"Output"},"revision":1},{"id":"af4c0337-8415-7d34-9540-4cc7dfee0e49","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Chaining: every then returns a new promise"}]},"revision":1},{"id":"b6bce377-14c1-78ec-973b-d48b605a3185","type":"code","position":"a6","content":{"language":"javascript","code":"Promise.resolve(2)\n  .then((n) => n * 10)                         // return a value → next then gets it\n  .then((n) => new Promise((r) => setTimeout(() => r(n + 1), 5)))  // return a promise → waits\n  .then((n) => {\n    console.log(\"value:\", n);\n    throw new Error(\"oops\");                   // throw → skips to the next catch\n  })\n  .then(() => console.log(\"skipped\"))\n  .catch((e) => {\n    console.log(\"caught:\", e.message);\n    return \"recovered\";                        // catch can recover the chain\n  })\n  .then((v) => console.log(\"after catch:\", v));","filename":"JavaScript"},"revision":1},{"id":"c65a8c92-5df8-735f-b002-18e5d1e388d8","type":"code","position":"a7","content":{"language":"text","code":"value: 21\ncaught: oops\nafter catch: recovered","filename":"Output"},"revision":1},{"id":"1853a123-1bee-70dc-90b9-ef244824dbba","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Inside a "},{"type":"text","text":"then","marks":[{"type":"code"}]},{"type":"text","text":" handler you…"}],[{"type":"text","text":"The returned promise…"}]],[[{"type":"text","text":"return a value"}],[{"type":"text","text":"fulfils with that value"}]],[[{"type":"text","text":"return a promise/thenable"}],[{"type":"text","text":"adopts its eventual state"}]],[[{"type":"text","text":"throw"}],[{"type":"text","text":"rejects with the thrown error"}]],[[{"type":"text","text":"return nothing"}],[{"type":"text","text":"fulfils with "},{"type":"text","text":"undefined","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"9302af4c-b010-7582-a3f2-cf53afcdf769","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Common mistakes"}]},"revision":1},{"id":"5d63e614-9b42-7046-b547-fff62ebd7947","type":"code","position":"aA","content":{"language":"javascript","code":"const getData = () => Promise.resolve({ id: 1 });\n\n// 1. forgetting to return → the next then gets undefined\ngetData()\n  .then((d) => { getData(); })\n  .then((v) => console.log(\"forgot return:\", v));\n\n// 2. the executor runs synchronously; resolve only once\nconst p = new Promise((resolve) => {\n  console.log(\"executor runs now\");\n  resolve(\"first\");\n  resolve(\"second\");                 // ignored\n});\np.then((v) => console.log(\"settled with:\", v));","filename":"JavaScript"},"revision":1},{"id":"1f13922a-347b-7fb1-9204-86ef1f725781","type":"code","position":"aB","content":{"language":"text","code":"executor runs now\nsettled with: first\nforgot return: undefined","filename":"Output"},"revision":1},{"id":"524de1e3-c93f-74e9-b052-b01a6f983658","type":"callout","position":"aC","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An unhandled rejection crashes Node (since v15) and logs an error in browsers. Every promise chain needs a "},{"type":"text","text":".catch","marks":[{"type":"code"}]},{"type":"text","text":" at the end (or an "},{"type":"text","text":"await","marks":[{"type":"code"}]},{"type":"text","text":" inside "},{"type":"text","text":"try/catch","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"de24e615-b992-7593-9b38-f88ea3ac9a9f","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Promise.resolve / reject / withResolvers"}]},"revision":1},{"id":"6af9a966-6bb7-7aca-8e6f-bd4bb3350cb8","type":"code","position":"aE","content":{"language":"javascript","code":"console.log(await Promise.resolve(42));\nconst p = Promise.resolve(Promise.resolve(\"nested\"))