SELECT '34c89aeb-d690-7219-8286-db0ce0f9f05c', '101ce9a6-07e4-7ae7-a57e-3a37b3a29b74', 1, 'PUBLISHED', 'Proxy & Reflect', '[{"id":"c0e28ae9-e162-731c-88f9-b5a2328793cb","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"Proxy","marks":[{"type":"code"}]},{"type":"text","text":" wraps an object and intercepts fundamental operations — get, set, delete, "},{"type":"text","text":"in","marks":[{"type":"code"}]},{"type":"text","text":", function calls. "},{"type":"text","text":"Reflect","marks":[{"type":"code"}]},{"type":"text","text":" provides the default behaviour for each trap."}]}]}},"revision":1},{"id":"5d2d17bb-c120-7ab8-ad90-0bb7a7cdaf07","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Traps"}]},"revision":1},{"id":"2f95b7bb-d0e7-7da8-abab-19416f537ec3","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Trap"}],[{"type":"text","text":"Intercepts"}]],[[{"type":"text","text":"get(target, prop, receiver)","marks":[{"type":"code"}]}],[{"type":"text","text":"obj.prop","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"obj[prop]","marks":[{"type":"code"}]}]],[[{"type":"text","text":"set(target, prop, value, receiver)","marks":[{"type":"code"}]}],[{"type":"text","text":"obj.prop = value","marks":[{"type":"code"}]}]],[[{"type":"text","text":"has(target, prop)","marks":[{"type":"code"}]}],[{"type":"text","text":"prop in obj","marks":[{"type":"code"}]}]],[[{"type":"text","text":"deleteProperty(target, prop)","marks":[{"type":"code"}]}],[{"type":"text","text":"delete obj.prop","marks":[{"type":"code"}]}]],[[{"type":"text","text":"ownKeys(target)","marks":[{"type":"code"}]}],[{"type":"text","text":"Object.keys","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"for…in","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Reflect.ownKeys","marks":[{"type":"code"}]}]],[[{"type":"text","text":"apply(target, thisArg, args)","marks":[{"type":"code"}]}],[{"type":"text","text":"Calling a function proxy"}]],[[{"type":"text","text":"construct(target, args)","marks":[{"type":"code"}]}],[{"type":"text","text":"new","marks":[{"type":"code"}]},{"type":"text","text":" on a proxy"}]]]},"revision":1},{"id":"90f3b6ef-8993-752b-89e7-de422d8785b9","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Validation and defaults"}]},"revision":1},{"id":"f3640b5f-d3f9-7a5e-acfd-8057f86bfa70","type":"code","position":"a4","content":{"language":"javascript","code":"const user = new Proxy({}, {\n  set(target, prop, value, receiver) {\n    if (prop === \"age\" && (!Number.isInteger(value) || value < 0)) {\n      throw new TypeError(`age must be a non-negative integer, got ${value}`);\n    }\n    return Reflect.set(target, prop, value, receiver);   // default behaviour\n  },\n  get(target, prop, receiver) {\n    return prop in target ? Reflect.get(target, prop, receiver) : `<no ${String(prop)}>`;\n  },\n});\nuser.name = \"Asha\";\nuser.age = 30;\ntry { user.age = -5; } catch (e) { console.log(e.message); }\nconsole.log(user.name, user.age, user.email);","filename":"JavaScript"},"revision":1},{"id":"2a7157fd-1c24-78f6-8b6c-1393923da2c1","type":"code","position":"a5","content":{"language":"text","code":"age must be a non-negative integer, got -5\nAsha 30 <no email>","filename":"Output"},"revision":1},{"id":"4f54e01f-70ea-73b6-b406-0204cdda0a1a","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Observing changes (how Vue 3 reactivity works)"}]},"revision":1},{"id":"7f89170f-eb72-78f8-84cb-cb6b5ed766c7","type":"code","position":"a7","content":{"language":"javascript","code":"function reactive(obj, onChange) {\n  return new Proxy(obj, {\n    set(target, prop, value) {\n      const old = target[prop];\n      const ok = Reflect.set(target, prop, value);\n      if (old !== value) onChange(prop, old, value);\n      return ok;\n    },\n  });\n}\nconst state = reactive({ count: 0 }, (k, a, b) => console.log(`${k}: ${a} → ${b}`));\nstate.count++;\nstate.count += 5;\nstate.count = 6;          // unchanged → no notification","filename":"JavaScript"},"revision":1},{"id":"692426d6-ba49-777e-81fd-ac192e84e8db","type":"code","position":"a8","content":{"language":"text","code":"count: 0 → 1\ncount: 1 → 6","filename":"Output"},"revision":1},{"id":"f1da23c9-7d9d-7979-8552-6ed03f572360","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Negative array indices, and hiding private keys"}]},"revision":1},{"id":"b286e717-d3be-72ca-92eb-2c5ecf757fe1","type":"code","position":"aA","content":{"language":"javascript","code":"const arr = new Proxy([10, 20, 30], {\n  get(target, prop, receiver) {\n    const i = Number(prop);\n    return Number.isInteger(i) && i < 0 ? target[target.length + i] : Reflect.get(target, prop, receiver);\n  },\n});\nconsole.log(arr[-1], arr[0], arr.length);\n\nconst hidden = new Proxy({ id: 1, _secret: \"x\" }, {\n  has: (t, p) => !String(p).startsWith(\"_\") && p in t,\n  ownKeys: (t) => Reflect.ownKeys(t).filter((k) => !String(k).startsWith(\"_\")),\n});\nconsole.log(\"_secret\" in hidden, Object.keys(hidden));","filename":"JavaScript"},"revision":1},{"id":"d5600fdb-5bfc-7b42-bb29-7476d735f172","type":"code","position":"aB","content":{"language":"text","code":"30 10 3\nfalse [ ''id'' ]","filename":"Output"},"revision":1},{"id":"a23549b6-ce45-7511-b2b6-b401e997df9d","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Reflect"}]},"revision":1},{"id":"86e37ff6-fd5a-70e7-9f1c-69b150914bbc","type":"code","position":"aD","content":{"language":"javascript","code":"const obj = { a: 1 };\nconsole.log(Reflect.has(obj, \"a\"), Reflect.ownKeys(obj), Reflect.get(obj, \"a\"));\nconsole.log(Reflect.defineProperty(Object.freeze({}), \"x\", { value: 1 }));   // false, no throw\nconsole.log(Reflect.apply(Math.max, null, [1, 5, 3]));","filename":"JavaScript"},"revision":1},{"id":"391b1afb-0297-79d3-831a-6b2b9beabb78","type":"code","position":"aE","content":{"language":"text","code":"true [ ''a'' ] 1\nfalse\n5","filename":"Output"},"revision":1},{"id":"d36b57e0-0643-793a-b418-9ffcc567b0cc","type":"callout","position":"aF","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reflect","marks":[{"type":"code"}]},{"type":"text","text":" methods mirror the proxy traps one-to-one and return booleans instead of throwing. Inside a trap, forward to "},{"type":"text","text":"Reflect.x(...)","marks":[{"type":"code"}]},{"type":"text","text":" with the same arguments (including "},{"type":"text","text":"receiver","marks":[{"type":"code"}]},{"type":"text","text":") to keep getters and inheritance working."}]}]}},"revision":1},{"id":"e8b2bb0a-384c-7540-b896-16c858027b51","type":"callout","position":"aG","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Proxies add overhead to every intercepted operation, and "},{"type":"text","text":"===","marks":[{"type":"code"}]},{"type":"text","text":" sees the proxy and target as different objects. Built-ins with internal slots ("},{"type":"text","text":"Map","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"Date","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"#private","marks":[{"type":"code"}]},{"type":"text","text":" fields) don''t work transparently through a proxy."}]}]}},"revision":1},{"id":"790e2854-75e2-7d72-ab37-fe7a4b7863c7","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are real-world uses of Proxy?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reactivity systems (Vue 3, MobX), validation, default values, logging/tracing, access control, negative indexing, API clients that turn property access into requests, and mocks in tests."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
