m","marks":[{"type":"code"}]},{"type":"text","text":"), word boundary"}]],[[{"type":"text","text":"* + ? {n,m}","marks":[{"type":"code"}]}],[{"type":"text","text":"0+, 1+, 0–1, n to m — add "},{"type":"text","text":"?","marks":[{"type":"code"}]},{"type":"text","text":" for lazy ("},{"type":"text","text":"*?","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"(…)","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"(?<name>…)","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"(?:…)","marks":[{"type":"code"}]}],[{"type":"text","text":"Capture group, named group, non-capturing group"}]],[[{"type":"text","text":"a|b","marks":[{"type":"code"}]}],[{"type":"text","text":"Alternation"}]],[[{"type":"text","text":"(?=…)","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"(?!…)","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"(?<=…)","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"(?<!…)","marks":[{"type":"code"}]}],[{"type":"text","text":"Lookahead, negative lookahead, lookbehind, negative lookbehind"}]]]},"revision":1},{"id":"9ca76042-100e-715e-9484-338973eb7d9d","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Flag"}],[{"type":"text","text":"Meaning"}]],[[{"type":"text","text":"g","marks":[{"type":"code"}]}],[{"type":"text","text":"Global — all matches"}]],[[{"type":"text","text":"i","marks":[{"type":"code"}]}],[{"type":"text","text":"Case-insensitive"}]],[[{"type":"text","text":"m","marks":[{"type":"code"}]}],[{"type":"text","text":"Multiline "},{"type":"text","text":"^","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"$","marks":[{"type":"code"}]}]],[[{"type":"text","text":"s","marks":[{"type":"code"}]}],[{"type":"text","text":".","marks":[{"type":"code"}]},{"type":"text","text":" matches newlines (dotAll)"}]],[[{"type":"text","text":"u