const strict = new Function(`
  "use strict";
  try { leaked2 = 1; } catch (e) { return e.name + " / this=" + this; }
`);
console.log("strict:", strict());

function args(a) { a = 99; return arguments[0]; }       // module → strict
console.log("arguments unlinked:", args(1));
