pe":"text","text":"trim / trimStart / trimEnd","marks":[{"type":"code"}]}],[{"type":"text","text":"Remove whitespace"}],[{"type":"text","text":"'' x ''.trim()","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"''x''","marks":[{"type":"code"}]}]],[[{"type":"text","text":"padStart / padEnd","marks":[{"type":"code"}]}],[{"type":"text","text":"Pad to a length"}],[{"type":"text","text":"''5''.padStart(3, ''0'')","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"''005''","marks":[{"type":"code"}]}]],[[{"type":"text","text":"repeat(n)","marks":[{"type":"code"}]}],[{"type":"text","text":"Repeat"}],[{"type":"text","text":"''ab''.repeat(3)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"''ababab''","marks":[{"type":"code"}]}]],[[{"type":"text","text":"split(sep)","marks":[{"type":"code"}]}],[{"type":"text","text":"String → array"}],[{"type":"text","text":"''a,b''.split('','')","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"[''a'', ''b'']","marks":[{"type":"code"}]}]],[[{"type":"text","text":"replace / replaceAll","marks":[{"type":"code"}]}],[{"type":"text","text":"Substitute (string or regex)"}],[{"type":"text","text":"''a-a''.replaceAll(''-'', ''+'')","marks":[{"type":"code"}]}]],[[{"type":"text","text":"at(i)","marks":[{"type":"code"}]}],[{"type":"text","text":"Index with negatives"}],[{"type":"text","text":"''abc''.at(-1)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"''c''","marks":[{"type":"code"}]}]],[[{"type":"text","text":"localeCompare","marks":[{"type":"code"}]}],[{"type":"text","text":"Locale-aware compare for sorting"}],[{"type":"text","text":"''a''.localeCompare(''b'')","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"-1","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"b7f3cf18-a0a5-787e-bcb6-9d045b3c018b","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"In action"}]},"revision":1},{"id":"21c7c33f-ff62-70db-aa3d-aa09ed8848f8","type":"code","position":"a4","content":{"language":"javascript","code":"const text = \"  The quick brown fox  \";\nconst t = text.trim();\nconsole.log(`[${t}]`, t.length);\nconsole.log(t.includes(\"quick\"), t.indexOf(\"o\"), t.lastIndexOf(\"o\"));\nconsole.log(t.split(\" \"), t.split(\" \", 2));\nconsole.log(t.replace(\"o\", \"0\"), \"|\", t.replaceAll(\"o\", \"0\"));\nconsole.log(t.replace(/o/g, (m) => m.toUpperCase()));\nconsole.log(\"7\".padStart(3, \"0\"), \"ab\".padEnd(5, \".\"), \"=\".repeat(5));","filename":"JavaScript"},"revision":1},{"id":"697171c1-d79b-7af9-910c-1d8cba5763f9","type":"code","position":"a5","content":{"language":"text","code":"[The quick brown fox] 19\ntrue 12 17\n[ ''The'', ''quick'', ''brown'', ''fox'' ] [ ''The'', ''quick'' ]\nThe quick br0wn fox | The quick br0wn f0x\nThe quick brOwn fOx\n007 ab... =====","filename":"Output"},"revision":1},{"id":"c8eda9a5-c342-7cb7-8abe-935760297bfb","type":"callout","position":"a6","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"replace","marks":[{"type":"code"}]},{"type":"text","text":" with a "},{"type":"text","text":"string","marks":[{"type":"bold"}]},{"type":"text","text":" pattern replaces only the "},{"type":"text","text":"first","marks":[{"type":"italic"}]},{"type":"text","text":" match. Use "},{"type":"text","text":"replaceAll","marks":[{"type":"code"}]},{"type":"text","text":", or a regex with the "},{"type":"text","text":"g","marks":[{"type":"code"}]},{"type":"text","text":" flag."}]}]}},"revision":1},{"id":"35f31f08-3505-7e65-8c0c-1b110212722c","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Common interview manipulations"}]},"revision":1},{"id":"4760c648-fed1-70d5-bda0-a0065f393ef9","type":"code","position":"a8","content":{"language":"javascript","code":"const reverse = (s) => [...s].reverse().join(\"\");\nconst isPalindrome = (s) => {\n  const clean = s.toLowerCase().replace(/[^a-z0-9]/g, \"\");\n  return clean === reverse(clean);\n};\nconst capitalize = (s) => s.charAt(0).toUpperCase() + s.slice(1);\nconst titleCase = (s) => s.split(\" \").map(capitalize).join(\" \");\nconst countChars = (s) =>\n  [...s].reduce((acc, ch) => ({ ...acc, [ch]: (acc[ch] ?? 0) + 1 }), {});\n\nconsole.log(reverse(\"hello\"));\nconsole.log(isPalindrome(\"A man, a plan, a canal: Panama\"));\nconsole.log(titleCase(\"learn via notes\"));\nconsole.log(countChars(\"banana\"));","filename":"JavaScript"},"revision":1},{"id":"ddb1256e-6e76-7040-ba45-031326f0a2e0","type":"code","position":"a9","content":{"language":"text","code":"olleh\ntrue\nLearn Via Notes\n{ b: 1, a: 3, n: 2 }","filename":"Output"},"revision":1},{"id":"a22344eb-5bd9-7283-aa26-a92d349a950b","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"substring vs slice vs substr"}]},"revision":1},{"id":"cebcad8f-1e46-75a7-826d-68abf886b5dd","type":"table","position":"aB","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Method"}],[{"type":"text","text":"Negative indices"}],[{"type":"text","text":"start > end"}],[{"type":"text","text":"Status"}]],[[{"type":"text","text":"slice(s, e)","marks":[{"type":"code"}]}],[{"type":"text","text":"Count from end"}],[{"type":"text","text":"Returns "},{"type":"text","text":"''''","marks":[{"type":"code"}]}],[{"type":"text","text":"Use this"}]],[[{"type":"text","text":"substring(s, e)","marks":[{"type":"code"}]}],[{"type":"text","text":"Treated as "},{"type":"text","text":"0","marks":[{"type":"code"}]}],[{"type":"text","text":"Swaps the arguments"}],[{"type":"text","text":"OK"}]],[[{"type":"text","text":"substr(s, len)","marks":[{"type":"code"}]}],[{"type":"text","text":"Start may be negative"}],[{"type":"text","text":"Second arg is a "},{"type":"text","text":"length","marks":[{"type":"italic"}]}],[{"type":"text","text":"Deprecated"}]]]},"revision":1},{"id":"f9cdda14-f4ad-7e0b-8be8-1cf76774c9af","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you reverse a string in JavaScript?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"[...s].reverse().join('''')","marks":[{"type":"code"}]},{"type":"text","text":". Strings have no "},{"type":"text","text":"reverse","marks":[{"type":"code"}]},{"type":"text","text":", so convert to an array first; spread (rather than "},{"type":"text","text":"split('''')","marks":[{"type":"code"}]},{"type":"text","text":") keeps emoji and other surrogate pairs intact."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
