SELECT '8c048b6b-1305-7509-9050-267fe550128f', '7fc91938-cbef-736a-bfeb-2cc95fbb3778', 1, 'PUBLISHED', 'WeakMap, WeakSet & WeakRef', '[{"id":"ff6c093d-b7f1-7c60-aef1-0a6a86f99377","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Weak collections hold their keys "},{"type":"text","text":"weakly","marks":[{"type":"italic"}]},{"type":"text","text":": if nothing else references a key object, it can be garbage-collected and its entry silently disappears."}]}]}},"revision":1},{"id":"612fdaf3-0d71-7a1f-a3e5-c897a5a875d5","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Map","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"Set","marks":[{"type":"code"}]}],[{"type":"text","text":"WeakMap","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"WeakSet","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Keys"}],[{"type":"text","text":"Anything"}],[{"type":"text","text":"Objects (and non-registered symbols) only"}]],[[{"type":"text","text":"Keeps key alive?"}],[{"type":"text","text":"Yes — strong reference"}],[{"type":"text","text":"No — weak reference"}]],[[{"type":"text","text":"Iterable / "},{"type":"text","text":"size","marks":[{"type":"code"}]},{"type":"text","text":"?"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"No (contents depend on the GC)"}]],[[{"type":"text","text":"Methods"}],[{"type":"text","text":"Full API"}],[{"type":"text","text":"get/set/has/delete","marks":[{"type":"code"}]},{"type":"text","text":" · "},{"type":"text","text":"add/has/delete","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"4e3492c6-528c-72ec-921a-9d7fcb6f36dd","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Use case: private data / metadata per object"}]},"revision":1},{"id":"3590649b-c744-7a01-9044-44a6a11fefa3","type":"code","position":"a3","content":{"language":"javascript","code":"const privateData = new WeakMap();\nclass Person {\n  constructor(name, ssn) {\n    this.name = name;\n    privateData.set(this, { ssn });   // disappears when the Person is collected\n  }\n  lastFour() { return privateData.get(this).ssn.slice(-4); }\n}\nconst p = new Person(\"Asha\", \"123-45-6789\");\nconsole.log(p.lastFour(), p);","filename":"JavaScript"},"revision":1},{"id":"6a3999d7-1bb4-7e28-a9ef-301d2eecb6dc","type":"code","position":"a4","content":{"language":"text","code":"6789 Person { name: ''Asha'' }","filename":"Output"},"revision":1},{"id":"5aabcbd3-aaac-7a39-8e71-ee2be3ad7354","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Use case: caching without leaks"}]},"revision":1},{"id":"abdceacc-e67a-79f4-9ce2-871a1e28c606","type":"code","position":"a6","content":{"language":"javascript","code":"const cache = new WeakMap();\nfunction expensiveSummary(obj) {\n  if (cache.has(obj)) return cache.get(obj) + \" (cached)\";\n  const result = `keys=${Object.keys(obj).length}`;\n  cache.set(obj, result);\n  return result;\n}\nconst report = { a: 1, b: 2 };\nconsole.log(expensiveSummary(report));\nconsole.log(expensiveSummary(report));","filename":"JavaScript"},"revision":1},{"id":"a48d5ab4-7853-73e5-988f-5e9007ea5d66","type":"code","position":"a7","content":{"language":"text","code":"keys=2\nkeys=2 (cached)","filename":"Output"},"revision":1},{"id":"d6039434-e502-779b-89fd-3da68b389c2a","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"WeakSet: tagging objects"}]},"revision":1},{"id":"a4ce888a-1fb4-718f-bc2f-0c6c08de99f2","type":"code","position":"a9","content":{"language":"javascript","code":"const visited = new WeakSet();\nfunction visit(node) {\n  if (visited.has(node)) return \"already visited\";\n  visited.add(node);\n  return \"visiting\";\n}\nconst node = {};\nconsole.log(visit(node), \"/\", visit(node));\ntry {\n  visited.add(\"string\");\n} catch (e) {\n  console.log(e.message);\n}","filename":"JavaScript"},"revision":1},{"id":"bd427ad3-6f08-79f5-9e36-cb89a0a74789","type":"code","position":"aA","content":{"language":"text","code":"visiting / already visited\nInvalid value used in weak set","filename":"Output"},"revision":1},{"id":"8daa058c-5403-7f41-ae51-3f42c3315cc9","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"WeakRef and FinalizationRegistry (ES2021)"}]},"revision":1},{"id":"7a52799e-66ab-7985-b30d-c24dbbb6a1e1","type":"code","position":"aC","content":{"language":"javascript","code":"let big = { data: \"large object\" };\nconst ref = new WeakRef(big);\nconsole.log(ref.deref()?.data);   // still alive\nbig = null;                       // now only weakly reachable — may be collected later\nconst registry = new FinalizationRegistry((label) => console.log(\"collected\", label));\nregistry.register({}, \"temp object\");","filename":"JavaScript"},"revision":1},{"id":"2c0793eb-05f4-74f3-8706-fc22eb2e8532","type":"code","position":"aD","content":{"language":"text","code":"large object","filename":"Output"},"revision":1},{"id":"c2d15756-3e8c-7e02-a64b-f2d046f2a016","type":"callout","position":"aE","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GC timing is unpredictable: "},{"type":"text","text":"deref()","marks":[{"type":"code"}]},{"type":"text","text":" may return the object long after you dropped it, and finalizers may never run. Use these only for caches and resource cleanup hints — never for program logic."}]}]}},"revision":1},{"id":"b3e11e81-3232-7fce-8a89-2348e23a511a","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why can''t you iterate a WeakMap?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Its entries vanish whenever the garbage collector reclaims a key, which happens at non-deterministic times. Exposing iteration or "},{"type":"text","text":"size","marks":[{"type":"code"}]},{"type":"text","text":" would make program behaviour depend on GC timing, so the API deliberately hides them."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
