SELECT '95f39a5a-4a8d-705e-a447-7bd4119a7d31', '362bae51-1897-7794-93d2-2e5d446ab6b5', 1, 'PUBLISHED', 'Users, Roles, GRANT & REVOKE', '[{"id":"2458af17-b3a9-7f31-80df-12170dc0657f","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DCL controls "},{"type":"text","text":"who","marks":[{"type":"bold"}]},{"type":"text","text":" may do "},{"type":"text","text":"what","marks":[{"type":"bold"}]},{"type":"text","text":" on "},{"type":"text","text":"which","marks":[{"type":"bold"}]},{"type":"text","text":" objects. Grant the minimum needed — the principle of least privilege."}]}]}},"revision":1},{"id":"8fc550de-523d-73ce-8515-80af6b6c5125","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Users and roles"}]},"revision":1},{"id":"17353874-5c14-7a2e-be68-6d2d21f6400c","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"role","marks":[{"type":"bold"}]},{"type":"text","text":" is a named bundle of privileges; users get privileges by being members of roles. Manage roles, not individual grants."}]}]}},"revision":1},{"id":"d4da7038-90c3-7f64-bbf2-35474bab74d4","type":"code","position":"a3","content":{"language":"sql","code":"CREATE ROLE analyst;                                    -- a group of privileges\nCREATE ROLE app_rw;\nCREATE USER priya WITH PASSWORD ''s3cret'';               -- PostgreSQL: a role that can log in\nGRANT analyst TO priya;","filename":"PostgreSQL"},"revision":1},{"id":"76316259-8c49-79e3-8c56-6dff0de371f7","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"GRANT and REVOKE"}]},"revision":1},{"id":"4e74ef21-8e23-7550-8f1c-957dceb1f1ce","type":"code","position":"a5","content":{"language":"sql","code":"-- read-only reporting\nGRANT SELECT ON employees, departments TO analyst;\n\n-- the application: data changes, no schema changes\nGRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO app_rw;\n\n-- column-level: hide salary from HR assistants\nGRANT SELECT (emp_id, name, dept_id) ON employees TO hr_assistant;\n\n-- let a user pass on the privilege\nGRANT SELECT ON orders TO team_lead WITH GRANT OPTION;\n\nREVOKE DELETE ON orders FROM app_rw;\nREVOKE analyst FROM priya;","filename":"PostgreSQL (MySQL / SQL Server are similar)"},"revision":1},{"id":"648afd54-d0a9-70e8-a8cd-64a9a045ed16","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Privilege"}],[{"type":"text","text":"Allows"}]],[[{"type":"text","text":"SELECT","marks":[{"type":"code"}]}],[{"type":"text","text":"Read rows (optionally only some columns)"}]],[[{"type":"text","text":"INSERT","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"UPDATE","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"DELETE","marks":[{"type":"code"}]}],[{"type":"text","text":"Change data"}]],[[{"type":"text","text":"EXECUTE","marks":[{"type":"code"}]}],[{"type":"text","text":"Run a procedure/function"}]],[[{"type":"text","text":"REFERENCES","marks":[{"type":"code"}]}],[{"type":"text","text":"Create a foreign key pointing at the table"}]],[[{"type":"text","text":"CREATE","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"ALTER","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"DROP","marks":[{"type":"code"}]}],[{"type":"text","text":"Schema changes (usually only for migration users)"}]],[[{"type":"text","text":"ALL PRIVILEGES","marks":[{"type":"code"}]}],[{"type":"text","text":"Everything on the object — avoid for applications"}]]]},"revision":1},{"id":"6817649f-8949-7341-b8a3-ce2006a84ef9","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Row-level and view-based security"}]},"revision":1},{"id":"72dc88d7-5483-7270-8ed4-591c108f6b07","type":"code","position":"a8","content":{"language":"sql","code":"-- expose a safe subset through a view and grant access only to the view\nCREATE VIEW employee_public AS\nSELECT emp_id, name, dept_id, hire_date FROM employees;     -- no salary, no email\n\nSELECT * FROM employee_public WHERE dept_id = 3 ORDER BY emp_id;","filename":"SQL"},"revision":1},{"id":"e261d92d-57ea-7c27-ae81-c42e961097cd","type":"code","position":"a9","content":{"language":"text","code":"emp_id | name   | dept_id | hire_date\n-------+--------+---------+-----------\n8      | Vikram | 3       | 2018-09-05\n9      | Sara   | 3       | 2023-01-09","filename":"Output"},"revision":1},{"id":"06855846-a908-76a6-8864-68d6b1ce3810","type":"code","position":"aA","content":{"language":"sql","code":"ALTER TABLE orders ENABLE ROW LEVEL SECURITY;\nCREATE POLICY own_orders ON orders\n    USING (customer_id = current_setting(''app.customer_id'')::int);","filename":"PostgreSQL (row-level security)"},"revision":1},{"id":"ee9e0217-6ed0-7d25-b030-39abc98322f8","type":"callout","position":"aB","content":{"variant":"note","title":"SQLite","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SQLite has no users or "},{"type":"text","text":"GRANT","marks":[{"type":"code"}]},{"type":"text","text":": access control is the file system''s permissions plus whatever the application enforces."}]}]}},"revision":1},{"id":"1ffd7e6b-5a50-7f5a-b741-21128bc684e2","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Checklist"}]},"revision":1},{"id":"f3ca7827-2ba2-71fb-85f2-c1377726cf55","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Separate accounts for the app, migrations, analysts and admins."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No application connects as "},{"type":"text","text":"root","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"postgres","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"sa","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Revoke defaults you don''t need (e.g. PostgreSQL''s "},{"type":"text","text":"CREATE","marks":[{"type":"code"}]},{"type":"text","text":" on "},{"type":"text","text":"public","marks":[{"type":"code"}]},{"type":"text","text":" for everyone before v15)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Store credentials in a secret manager; rotate them; require TLS."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audit privileged actions and review grants periodically."}]}]}]}]}},"revision":1},{"id":"1caf738b-9fc9-72ea-8071-87613838fd88","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between GRANT and REVOKE?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GRANT","marks":[{"type":"code"}]},{"type":"text","text":" gives privileges (or role membership) to a user/role: "},{"type":"text","text":"GRANT SELECT ON t TO analyst","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"REVOKE","marks":[{"type":"code"}]},{"type":"text","text":" removes them: "},{"type":"text","text":"REVOKE SELECT ON t FROM analyst","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"WITH GRANT OPTION","marks":[{"type":"code"}]},{"type":"text","text":" lets the grantee pass the privilege on; revoking can then cascade."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
