  ('6817649f-8949-7341-b8a3-ce2006a84ef9', 'a7', 'heading', '{"level":1,"content":[{"type":"text","text":"Row-level and view-based security"}]}'),
  ('72dc88d7-5483-7270-8ed4-591c108f6b07', 'a8', 'code', '{"language":"sql","code":"-- expose a safe subset through a view and grant access only to the view\nCREATE VIEW employee_public AS\nSELECT emp_id, name, dept_id, hire_date FROM employees;     -- no salary, no email\n\nSELECT * FROM employee_public WHERE dept_id = 3 ORDER BY emp_id;","filename":"SQL"}'),
