  ('ee9e0217-6ed0-7d25-b030-39abc98322f8', 'aB', 'callout', '{"variant":"note","title":"SQLite","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SQLite has no users or "},{"type":"text","text":"GRANT","marks":[{"type":"code"}]},{"type":"text","text":": access control is the file system''s permissions plus whatever the application enforces."}]}]}}'),
  ('1ffd7e6b-5a50-7f5a-b741-21128bc684e2', 'aC', 'heading', '{"level":1,"content":[{"type":"text","text":"Checklist"}]}'),
  ('f3ca7827-2ba2-71fb-85f2-c1377726cf55', 'aD', 'text', '{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Separate accounts for the app, migrations, analysts and admins."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No application connects as "},{"type":"text","text":"root","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"postgres","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"sa","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Revoke defaults you don''t need (e.g. PostgreSQL''s "},{"type":"text","text":"CREATE","marks":[{"type":"code"}]},{"type":"text","text":" on "},{"type":"text","text":"public","marks":[{"type":"code"}]},{"type":"text","text":" for everyone before v15)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Store credentials in a secret manager; rotate them; require TLS."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Audit privileged actions and review grants periodically."}]}]}]}]}}'),
  ('1caf738b-9fc9-72ea-8071-87613838fd88', 'aE', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between GRANT and REVOKE?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"GRANT","marks":[{"type":"code"}]},{"type":"text","text":" gives privileges (or role membership) to a user/role: "},{"type":"text","text":"GRANT SELECT ON t TO analyst","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"REVOKE","marks":[{"type":"code"}]},{"type":"text","text":" removes them: "},{"type":"text","text":"REVOKE SELECT ON t FROM analyst","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"WITH GRANT OPTION","marks":[{"type":"code"}]},{"type":"text","text":" lets the grantee pass the privilege on; revoking can then cascade."}]}]}}')
