SELECT 'e5218439-335e-7545-bc03-7caa38269745', 'abc21206-a7c1-7340-b996-a414b0b2ce1b', 1, 'PUBLISHED', 'Aggregate Functions', '[{"id":"a6b11c06-5a7a-789f-ad10-74a699851ed4","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Aggregate functions collapse many rows into one value: how many, how much, the average, the extremes."}]}]}},"revision":1},{"id":"70e831b6-c4e6-7f97-a89b-fb755e0c4ce4","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Function"}],[{"type":"text","text":"Returns"}],[{"type":"text","text":"NULLs"}]],[[{"type":"text","text":"COUNT(*)","marks":[{"type":"code"}]}],[{"type":"text","text":"Number of rows"}],[{"type":"text","text":"Counted"}]],[[{"type":"text","text":"COUNT(col)","marks":[{"type":"code"}]}],[{"type":"text","text":"Number of non-null values"}],[{"type":"text","text":"Ignored"}]],[[{"type":"text","text":"COUNT(DISTINCT col)","marks":[{"type":"code"}]}],[{"type":"text","text":"Number of different non-null values"}],[{"type":"text","text":"Ignored"}]],[[{"type":"text","text":"SUM(col)","marks":[{"type":"code"}]}],[{"type":"text","text":"Total"}],[{"type":"text","text":"Ignored (all "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":")"}]],[[{"type":"text","text":"AVG(col)","marks":[{"type":"code"}]}],[{"type":"text","text":"Mean = "},{"type":"text","text":"SUM / COUNT(col)","marks":[{"type":"code"}]}],[{"type":"text","text":"Ignored"}]],[[{"type":"text","text":"MIN(col)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"MAX(col)","marks":[{"type":"code"}]}],[{"type":"text","text":"Smallest / largest (also for text and dates)"}],[{"type":"text","text":"Ignored"}]]]},"revision":1},{"id":"b9e2578a-5627-7793-956e-a881dcf84a96","type":"code","position":"a2","content":{"language":"sql","code":"SELECT COUNT(*)                 AS employees,\n       COUNT(email)             AS with_email,\n       COUNT(DISTINCT dept_id)  AS departments,\n       SUM(salary)              AS payroll,\n       AVG(salary)              AS avg_salary,\n       MIN(hire_date)           AS first_hire,\n       MAX(name)                AS last_name_alpha\nFROM employees;","filename":"SQL"},"revision":1},{"id":"a38e0feb-16b8-74fd-a26b-73bd2c7dfe31","type":"code","position":"a3","content":{"language":"text","code":"employees | with_email | departments | payroll | avg_salary | first_hire | last_name_alpha\n----------+------------+-------------+---------+------------+------------+----------------\n10        | 8          | 3           | 937000  | 93700.0    | 2015-03-01 | Vikram","filename":"Output"},"revision":1},{"id":"fefafc75-2c1c-7b76-b07b-e2df879b3308","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"NULLs change averages"}]},"revision":1},{"id":"381a0bb2-b5b5-70d3-b00a-8f06918f8438","type":"code","position":"a5","content":{"language":"sql","code":"CREATE TABLE ratings (product TEXT, stars INTEGER);\nINSERT INTO ratings VALUES (''A'', 5), (''A'', 3), (''A'', NULL), (''B'', NULL);\n\nSELECT product,\n       COUNT(*)              AS rows_,\n       COUNT(stars)          AS rated,\n       AVG(stars)            AS avg_ignoring_null,\n       AVG(COALESCE(stars, 0)) AS avg_null_as_zero,\n       SUM(stars)            AS total\nFROM ratings\nGROUP BY product\nORDER BY product;","filename":"SQL"},"revision":1},{"id":"a65a3cdb-cef1-7f21-a78f-164264da951b","type":"code","position":"a6","content":{"language":"text","code":"product | rows_ | rated | avg_ignoring_null | avg_null_as_zero   | total\n--------+-------+-------+-------------------+--------------------+------\nA       | 3     | 2     | 4.0               | 2.6666666666666665 | 8\nB       | 1     | 0     | NULL              | 0.0                | NULL","filename":"Output"},"revision":1},{"id":"587ed22f-4fef-7007-afbe-8a36dd5a767e","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Decide what "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" means for your metric. Product B shows the other surprise: "},{"type":"text","text":"SUM","marks":[{"type":"code"}]},{"type":"text","text":" over only "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"s is "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":", not "},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" — wrap it: "},{"type":"text","text":"COALESCE(SUM(x), 0)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"9255e430-659d-7b52-813b-11c7ea987aeb","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Aggregates over an empty set"}]},"revision":1},{"id":"a87bda9f-eca8-7e8d-9ec3-0140f1ae5f5b","type":"code","position":"a9","content":{"language":"sql","code":"SELECT COUNT(*) AS n, SUM(salary) AS total, MAX(salary) AS top\nFROM employees\nWHERE dept_id = 4;             -- Marketing has nobody","filename":"SQL"},"revision":1},{"id":"e5e592d2-c92f-7994-abb2-9a341b34e5f4","type":"code","position":"aA","content":{"language":"text","code":"n | total | top\n--+-------+-----\n0 | NULL  | NULL","filename":"Output"},"revision":1},{"id":"bcabea31-f836-7757-971d-b95d2f5feddb","type":"callout","position":"aB","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Without "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":", an aggregate query always returns "},{"type":"text","text":"exactly one row","marks":[{"type":"bold"}]},{"type":"text","text":" — even when no rows matched. With "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":", no matching rows means no groups and zero result rows."}]}]}},"revision":1},{"id":"dcb0946a-3d77-7230-b4c2-07c5edf0bcac","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"Conditional aggregation"}]},"revision":1},{"id":"ae05bb61-b8ec-7081-8406-efbcff4eebec","type":"code","position":"aD","content":{"language":"sql","code":"SELECT SUM(CASE WHEN category = ''Electronics'' THEN price END) AS electronics_value,\n       AVG(CASE WHEN category = ''Furniture''   THEN price END) AS avg_furniture,\n       COUNT(CASE WHEN price < 100 THEN 1 END)                 AS cheap_items\nFROM products;","filename":"SQL"},"revision":1},{"id":"8e6b0195-a92e-7685-bbc4-081f8e4f3146","type":"code","position":"aE","content":{"language":"text","code":"electronics_value | avg_furniture | cheap_items\n------------------+---------------+------------\n69500             | 6250.0        | 2","filename":"Output"},"revision":1},{"id":"1d9f5584-4689-7c01-811e-5e1d0896f57e","type":"callout","position":"aF","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You cannot nest aggregates ("},{"type":"text","text":"MAX(AVG(salary))","marks":[{"type":"code"}]},{"type":"text","text":") in one level in most engines. Aggregate in a subquery or CTE first, then aggregate the result."}]}]}},"revision":1},{"id":"873ce6e7-a6dc-70b0-89e4-0e450ab8fd66","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between COUNT(*), COUNT(1) and COUNT(column)?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"COUNT(*)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"COUNT(1)","marks":[{"type":"code"}]},{"type":"text","text":" both count rows and perform the same in modern engines. "},{"type":"text","text":"COUNT(column)","marks":[{"type":"code"}]},{"type":"text","text":" counts rows where that column is "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"COUNT(DISTINCT column)","marks":[{"type":"code"}]},{"type":"text","text":" counts distinct non-null values."}]}]}},"revision":1},{"id":"87a9cbe3-c105-7e5d-951f-056d1af7b8a4","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Does AVG include NULL values?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"No. "},{"type":"text","text":"AVG(x)","marks":[{"type":"code"}]},{"type":"text","text":" = "},{"type":"text","text":"SUM(x) / COUNT(x)","marks":[{"type":"code"}]},{"type":"text","text":" over non-null values only. To treat missing as zero, use "},{"type":"text","text":"AVG(COALESCE(x, 0))","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
