SELECT '1a335107-3345-7bca-8cfd-26ee26a6f15c', '7fcbf696-b14a-76c6-8614-751dbc5308b0', 1, 'PUBLISHED', 'Constraints', '[{"id":"917220dc-6824-7a5f-9ecd-35c5f31703cb","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Constraints are rules the database enforces on every insert and update. They keep bad data out no matter which application, script or person writes it."}]}]}},"revision":1},{"id":"a11129f8-cf84-7bc1-a09a-f54a631db6cb","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Constraint"}],[{"type":"text","text":"Guarantees"}],[{"type":"text","text":"Sample database"}]],[[{"type":"text","text":"PRIMARY KEY","marks":[{"type":"code"}]}],[{"type":"text","text":"Unique "},{"type":"text","text":"and","marks":[{"type":"bold"}]},{"type":"text","text":" not null; identifies each row"}],[{"type":"text","text":"employees.emp_id","marks":[{"type":"code"}]}]],[[{"type":"text","text":"FOREIGN KEY","marks":[{"type":"code"}]}],[{"type":"text","text":"Value must exist in the referenced table (or be "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":")"}],[{"type":"text","text":"employees.dept_id → departments","marks":[{"type":"code"}]}]],[[{"type":"text","text":"UNIQUE","marks":[{"type":"code"}]}],[{"type":"text","text":"No two rows share the value ("},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"s allowed)"}],[{"type":"text","text":"employees.email","marks":[{"type":"code"}]}]],[[{"type":"text","text":"NOT NULL","marks":[{"type":"code"}]}],[{"type":"text","text":"A value must be supplied"}],[{"type":"text","text":"employees.name","marks":[{"type":"code"}]}]],[[{"type":"text","text":"CHECK","marks":[{"type":"code"}]}],[{"type":"text","text":"A boolean condition must not be false"}],[{"type":"text","text":"salary > 0","marks":[{"type":"code"}]}]],[[{"type":"text","text":"DEFAULT","marks":[{"type":"code"}]}],[{"type":"text","text":"Value used when the column is omitted"}],[{"type":"text","text":"status DEFAULT ''pending''","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"d4acf02d-885a-7662-8464-4bfc20c8980e","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Each one rejecting bad data"}]},"revision":1},{"id":"f83f1108-a442-7c2d-a63e-0dd66caa379b","type":"code","position":"a3","content":{"language":"sql","code":"INSERT INTO employees (emp_id, name, dept_id, salary, hire_date)\nVALUES (11, NULL, 1, 50000, ''2024-06-01'');","filename":"SQL — NOT NULL"},"revision":1},{"id":"95df4aab-4954-7421-acde-68e6f1976c05","type":"code","position":"a4","content":{"language":"text","code":"NOT NULL constraint failed: employees.name","filename":"Error"},"revision":1},{"id":"a9fe0864-8950-7fd4-9ff6-82cf12855e77","type":"code","position":"a5","content":{"language":"sql","code":"INSERT INTO employees (emp_id, name, email, dept_id, salary, hire_date)\nVALUES (11, ''Tara'', ''asha@corp.in'', 1, 50000, ''2024-06-01'');","filename":"SQL — UNIQUE"},"revision":1},{"id":"7011f205-9616-711e-a054-dd55acd37b80","type":"code","position":"a6","content":{"language":"text","code":"UNIQUE constraint failed: employees.email","filename":"Error"},"revision":1},{"id":"d3c3e951-9a64-761f-ad85-2d90530edb4a","type":"code","position":"a7","content":{"language":"sql","code":"UPDATE employees SET salary = -100 WHERE emp_id = 3;","filename":"SQL — CHECK"},"revision":1},{"id":"61527d0a-b776-759d-9aac-16e0659839d1","type":"code","position":"a8","content":{"language":"text","code":"CHECK constraint failed: salary > 0","filename":"Error"},"revision":1},{"id":"3de71dd0-beae-7dd9-baaf-3ea7e9b8c40d","type":"code","position":"a9","content":{"language":"sql","code":"INSERT INTO employees (emp_id, name, dept_id, salary, hire_date)\nVALUES (11, ''Tara'', 99, 50000, ''2024-06-01'');     -- there is no department 99","filename":"SQL — FOREIGN KEY (child side)"},"revision":1},{"id":"3c0074a7-08f9-76f4-a389-e59e7bc09720","type":"code","position":"aA","content":{"language":"text","code":"FOREIGN KEY constraint failed","filename":"Error"},"revision":1},{"id":"08e88285-83be-7462-b559-d4363e2904b4","type":"code","position":"aB","content":{"language":"sql","code":"DELETE FROM departments WHERE dept_id = 1;         -- Engineering still has employees","filename":"SQL — FOREIGN KEY (parent side)"},"revision":1},{"id":"96671e5a-3324-72b2-9464-1a8cd3655897","type":"code","position":"aC","content":{"language":"text","code":"FOREIGN KEY constraint failed","filename":"Error"},"revision":1},{"id":"2bda9221-fbdc-7168-acf0-cc010165b963","type":"code","position":"aD","content":{"language":"sql","code":"INSERT INTO employees (emp_id, name, dept_id, salary, hire_date)\nVALUES (1, ''Tara'', 1, 50000, ''2024-06-01'');       -- emp_id 1 is Asha","filename":"SQL — PRIMARY KEY"},"revision":1},{"id":"e01e9147-c90d-7552-9cde-a283ed4d65f4","type":"code","position":"aE","content":{"language":"text","code":"UNIQUE constraint failed: employees.emp_id","filename":"Error"},"revision":1},{"id":"38dc66d7-e859-7aec-aec8-50bec6a5448c","type":"callout","position":"aF","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"UNIQUE","marks":[{"type":"code"}]},{"type":"text","text":" still allows several "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"s — Neha and Dev both have a "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" email. "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" means "},{"type":"text","text":"unknown","marks":[{"type":"italic"}]},{"type":"text","text":", and two unknowns are not considered equal. (SQL Server is the exception: it allows only one "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" in a unique column unless you use a filtered index.)"}]}]}},"revision":1},{"id":"06a566de-eacd-7bc0-8c48-ccb397ad70b1","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Named constraints, composite keys, defaults"}]},"revision":1},{"id":"0d85d928-0442-7df5-a0dd-efc9337fbd26","type":"code","position":"aH","content":{"language":"sql","code":"CREATE TABLE enrollments (\n    student_id  INTEGER NOT NULL,\n    course_id   INTEGER NOT NULL,\n    grade       CHAR(1),\n    enrolled_on TEXT    NOT NULL DEFAULT CURRENT_DATE,\n    status      TEXT    NOT NULL DEFAULT ''active'',\n    CONSTRAINT pk_enrollment PRIMARY KEY (student_id, course_id),\n    CONSTRAINT chk_grade CHECK (grade IN (''A'', ''B'', ''C'', ''D'', ''F''))\n);\nINSERT INTO enrollments (student_id, course_id) VALUES (1, 10);\nSELECT student_id, course_id, grade, status,\n       enrolled_on = CURRENT_DATE AS enrolled_today\nFROM enrollments;","filename":"SQL"},"revision":1},{"id":"b7088756-533a-74ab-bfdc-5f96af366f40","type":"code","position":"aI","content":{"language":"text","code":"student_id | course_id | grade | status | enrolled_today\n-----------+-----------+-------+--------+---------------\n1          | 10        | NULL  | active | 1","filename":"Output"},"revision":1},{"id":"88b39f12-59b4-77bf-89a7-489cffed56dc","type":"code","position":"aJ","content":{"language":"sql","code":"INSERT INTO enrollments (student_id, course_id, grade) VALUES (1, 11, ''Z'');","filename":"SQL"},"revision":1},{"id":"e1322bdf-b01a-7c25-a176-795913983464","type":"code","position":"aK","content":{"language":"text","code":"CHECK constraint failed: chk_grade","filename":"Error"},"revision":1},{"id":"a5142b34-6101-7040-8e07-04df9060285e","type":"text","position":"aL","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"named","marks":[{"type":"bold"}]},{"type":"text","text":" constraint shows up in the error ("},{"type":"text","text":"chk_grade","marks":[{"type":"code"}]},{"type":"text","text":"), which makes failures much easier to diagnose — and you need the name to drop it later ("},{"type":"text","text":"ALTER TABLE … DROP CONSTRAINT chk_grade","marks":[{"type":"code"}]},{"type":"text","text":"). Notice too that the first row''s "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" grade passed the "},{"type":"text","text":"CHECK","marks":[{"type":"code"}]},{"type":"text","text":": a check only rejects a condition that is "},{"type":"text","text":"false","marks":[{"type":"bold"}]},{"type":"text","text":", and "},{"type":"text","text":"NULL IN (…)","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"unknown","marks":[{"type":"italic"}]},{"type":"text","text":". Add "},{"type":"text","text":"NOT NULL","marks":[{"type":"code"}]},{"type":"text","text":" if the value is mandatory."}]}]}},"revision":1},{"id":"a9c33019-3b88-7ced-9caf-689653b8378a","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"Referential actions: what happens to children?"}]},"revision":1},{"id":"8bc8c51f-04cf-7589-80d3-09691d5a478f","type":"table","position":"aN","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"ON DELETE …","marks":[{"type":"code"}]}],[{"type":"text","text":"When the parent row is deleted"}]],[[{"type":"text","text":"RESTRICT","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"NO ACTION","marks":[{"type":"code"}]},{"type":"text","text":" (default)"}],[{"type":"text","text":"Refuse the delete while children exist"}]],[[{"type":"text","text":"CASCADE","marks":[{"type":"code"}]}],[{"type":"text","text":"Delete the children too"}]],[[{"type":"text","text":"SET NULL","marks":[{"type":"code"}]}],[{"type":"text","text":"Set the child''s foreign key to "},{"type":"text","text":"NULL","marks":[{"type":"code"}]}]],[[{"type":"text","text":"SET DEFAULT","marks":[{"type":"code"}]}],[{"type":"text","text":"Set it to the column default"}]]]},"revision":1},{"id":"333e4008-6515-758c-b530-7d4caa54fcd5","type":"code","position":"aO","content":{"language":"sql","code":"PRAGMA foreign_keys = ON;\nCREATE TABLE authors (id INTEGER PRIMARY KEY, name TEXT);\nCREATE TABLE posts (\n    id        INTEGER PRIMARY KEY,\n    author_id INTEGER REFERENCES authors(id) ON DELETE CASCADE,\n    title     TEXT\n);\nCREATE TABLE comments (\n    id        INTEGER PRIMARY KEY,\n    author_id INTEGER REFERENCES authors(id) ON DELETE SET NULL,\n    body      TEXT\n);\nINSERT INTO authors  VALUES (1, ''Asha''), (2, ''Ravi'');\nINSERT INTO posts    VALUES (1, 1, ''Intro to SQL''), (2, 2, ''Joins''), (3, 1, ''Indexes'');\nINSERT INTO comments VALUES (1, 1, ''Nice!''), (2, 2, ''Thanks'');\n\nDELETE FROM authors WHERE id = 1;\n\nSELECT * FROM posts ORDER BY id;\nSELECT * FROM comments ORDER BY id;","filename":"SQL"},"revision":1},{"id":"3bba9c7f-43ce-7a21-82a6-c7decde49172","type":"code","position":"aP","content":{"language":"text","code":"id | author_id | title\n---+-----------+------\n2  | 2         | Joins\n\nid | author_id | body\n---+-----------+-------\n1  | NULL      | Nice!\n2  | 2         | Thanks","filename":"Output"},"revision":1},{"id":"f1e36b3c-d1a1-7f50-bd79-e3eb610c9d1a","type":"callout","position":"aQ","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Use "},{"type":"text","text":"CASCADE","marks":[{"type":"code"}]},{"type":"text","text":" deliberately: deleting one customer could silently remove years of orders. Many teams prefer "},{"type":"text","text":"RESTRICT","marks":[{"type":"code"}]},{"type":"text","text":" plus soft deletes ("},{"type":"text","text":"is_active = 0","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"0ce1f896-54e8-7422-a42a-d09dec029687","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between PRIMARY KEY and UNIQUE?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both enforce uniqueness and create an index. A table has "},{"type":"text","text":"one","marks":[{"type":"bold"}]},{"type":"text","text":" primary key and it can never be "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"; it is the row''s identity and the target of foreign keys. A table can have "},{"type":"text","text":"many","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"UNIQUE","marks":[{"type":"code"}]},{"type":"text","text":" constraints and they allow "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"s (multiple, in most engines)."}]}]}},"revision":1},{"id":"8ece2836-47eb-72d9-8301-de8d94789489","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Can a foreign key column be NULL?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yes, unless it is also "},{"type":"text","text":"NOT NULL","marks":[{"type":"code"}]},{"type":"text","text":". A "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" foreign key means “no related row” (e.g. Dev has no department). The constraint is only checked for non-null values."}]}]}},"revision":1},{"id":"d09ac052-0b5f-72a9-8711-9f8d76d93d22","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why enforce constraints in the database if the application validates input?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Several applications, scripts, admins and migrations write to the same database; bugs and race conditions happen (two requests inserting the same email at once). Only the database sees every write and can guarantee integrity atomically."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
