INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'b82b0af4-0adb-70df-bc68-f01ea9a5f451', '9c02de43-39f4-7aed-b913-4caaa2b7527a', 1, 'PUBLISHED', 'CROSS JOIN & SELF JOIN', '[{"id":"2b6a1576-4980-78eb-be08-e4d6deb2676d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A cross join pairs every row with every row; a self join matches a table with itself. Both are ordinary joins used in less ordinary ways."}]}]}},"revision":1},{"id":"47d56b49-8d98-7f54-a88d-fcabe24c7c96","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"CROSS JOIN: every combination"}]},"revision":1},{"id":"c1ae73b4-a0dd-7d10-a73c-55c08341a59d","type":"code","position":"a2","content":{"language":"sql","code":"CREATE TABLE sizes  (size TEXT);\nCREATE TABLE colors (color TEXT);\nINSERT INTO sizes  VALUES (''S''), (''M''), (''L'');\nINSERT INTO colors VALUES (''Black''), (''White'');\n\nSELECT s.size, c.color\nFROM sizes s CROSS JOIN colors c\nORDER BY c.color, s.size;","filename":"SQL"},"revision":1},{"id":"6a2ee09c-83c8-75b3-b407-96b954252c8b","type":"code","position":"a3","content":{"language":"text","code":"size | color\n-----+------\nL    | Black\nM    | Black\nS    | Black\nL    | White\nM    | White\nS    | White","filename":"Output"},"revision":1},{"id":"37a63ec8-6111-7f3c-b537-24ed5997081a","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"3 × 2 = 6 rows. Real uses: generating all product variants, a calendar × store grid to report zero-sales days, or combining a single-row settings table with every row."}]}]}},"revision":1},{"id":"e2759e06-f84f-7d40-b90a-b45f63dba40d","type":"code","position":"a5","content":{"language":"sql","code":"-- every department × every month of Q1, so empty months still appear\nWITH months(m) AS (VALUES (''2024-01''), (''2024-02''), (''2024-03''))\nSELECT d.name, m.m AS month\nFROM departments d CROSS JOIN months m\nWHERE d.dept_id <= 2\nORDER BY d.name, month;","filename":"SQL"},"revision":1},{"id":"7ee1e721-de9a-702b-84b5-5a623cae4333","type":"code","position":"a6","content":{"language":"text","code":"name        | month\n------------+--------\nEngineering | 2024-01\nEngineering | 2024-02\nEngineering | 2024-03\nSales       | 2024-01\nSales       | 2024-02\nSales       | 2024-03","filename":"Output"},"revision":1},{"id":"6dfe8772-3bdb-713e-bb66-74504157470a","type":"callout","position":"a7","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cross joins grow multiplicatively: 10 000 × 10 000 rows = 100 million. An accidental one (missing join condition) is a classic cause of runaway queries."}]}]}},"revision":1},{"id":"e177adae-64cc-79b9-b645-11431350ec7f","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"SELF JOIN: employees and their managers"}]},"revision":1},{"id":"543bd173-85f2-78a9-ade3-ae3e989f6135","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"employees.manager_id","marks":[{"type":"code"}]},{"type":"text","text":" points at another row of "},{"type":"text","text":"employees","marks":[{"type":"code"}]},{"type":"text","text":". Join the table to itself under two aliases — one playing "},{"type":"text","text":"employee","marks":[{"type":"italic"}]},{"type":"text","text":", one playing "},{"type":"text","text":"manager","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"94fd937a-02ec-78eb-99a9-41ce35fe651a","type":"code","position":"aA","content":{"language":"sql","code":"SELECT e.name AS employee, m.name AS manager\nFROM employees e\nLEFT JOIN employees m ON m.emp_id = e.manager_id\nORDER BY e.emp_id;","filename":"SQL"},"revision":1},{"id":"7e9c8f4b-428e-7561-9692-ffc2d5dfc9d8","type":"code","position":"aB","content":{"language":"text","code":"employee | manager\n---------+--------\nAsha     | NULL\nRavi     | Asha\nMeera    | Ravi\nKaran    | Ravi\nPriya    | Asha\nArjun    | Priya\nNeha     | Priya\nVikram   | Asha\nSara     | Vikram\nDev      | Asha","filename":"Output"},"revision":1},{"id":"11b846cd-c262-791c-81d9-2d8c163fd459","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"LEFT JOIN","marks":[{"type":"code"}]},{"type":"text","text":" keeps Asha, who has no manager. With an inner join she would vanish."}]}]}},"revision":1},{"id":"ea180ac3-ab7d-7eae-9334-2f0ce8ec28d2","type":"code","position":"aD","content":{"language":"sql","code":"-- employees who earn more than their manager (a top interview question)\nSELECT e.name AS employee, e.salary, m.name AS manager, m.salary AS manager_salary\nFROM employees e\nJOIN employees m ON m.emp_id = e.manager_id\nWHERE e.salary > m.salary;","filename":"SQL"},"revision":1},{"id":"add90fc9-ecc2-7b5d-8dd6-83f5ed21c423","type":"code","position":"aE","content":{"language":"text","code":"employee | salary | manager | manager_salary\n---------+--------+---------+---------------\nSara     | 85000  | Vikram  | 80000","filename":"Output"},"revision":1},{"id":"f50f6d9c-392d-7ae9-86d8-30540c7b7b30","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Self join to compare rows: pairs"}]},"revision":1},{"id":"968cd19e-481f-790a-8716-ba415c63d507","type":"code","position":"aG","content":{"language":"sql","code":"-- pairs of employees in the same department (each pair once)\nSELECT a.name AS first, b.name AS second, a.dept_id\nFROM employees a\nJOIN employees b ON b.dept_id = a.dept_id AND a.emp_id < b.emp_id\nWHERE a.dept_id IN (2, 3)\nORDER BY a.dept_id, a.emp_id, b.emp_id;","filename":"SQL"},"revision":1},{"id":"3f7ec1b4-6c48-7cbe-9330-b9ee30682e01","type":"code","position":"aH","content":{"language":"text","code":"first  | second | dept_id\n-------+--------+--------\nPriya  | Arjun  | 2\nPriya  | Neha   | 2\nArjun  | Neha   | 2\nVikram | Sara   | 3","filename":"Output"},"revision":1},{"id":"15880ca9-ef29-78b2-9dfe-6489213ef57b","type":"callout","position":"aI","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"a.emp_id < b.emp_id","marks":[{"type":"code"}]},{"type":"text","text":" removes self-pairs (Priya–Priya) and mirrored duplicates (Priya–Arjun and Arjun–Priya). "},{"type":"text","text":"<>","marks":[{"type":"code"}]},{"type":"text","text":" would keep both mirrors."}]}]}},"revision":1},{"id":"e3e33c0c-6fd7-7208-b619-e3a498de738d","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a self join and when is it used?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A join of a table with itself using two aliases. Used for hierarchical data stored as a parent pointer (employee → manager, category → parent category), for comparing rows within the same table (pairs, duplicates, consecutive events), and for “earns more than manager”-style questions."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
