  ('968cd19e-481f-790a-8716-ba415c63d507', 'aG', 'code', '{"language":"sql","code":"-- pairs of employees in the same department (each pair once)\nSELECT a.name AS first, b.name AS second, a.dept_id\nFROM employees a\nJOIN employees b ON b.dept_id = a.dept_id AND a.emp_id < b.emp_id\nWHERE a.dept_id IN (2, 3)\nORDER BY a.dept_id, a.emp_id, b.emp_id;","filename":"SQL"}'),
  ('3f7ec1b4-6c48-7cbe-9330-b9ee30682e01', 'aH', 'code', '{"language":"text","code":"first  | second | dept_id\n-------+--------+--------\nPriya  | Arjun  | 2\nPriya  | Neha   | 2\nArjun  | Neha   | 2\nVikram | Sara   | 3","filename":"Output"}'),
