INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '4403bde9-29b3-7c56-826a-30593d29fb5d', 'f87dd1dc-a395-7e7b-b772-ca552d1bd522', 1, 'PUBLISHED', 'Common Table Expressions (WITH)', '[{"id":"76b57424-4709-70a4-b4b6-44be8f0b95f9","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A CTE names a subquery at the top of a statement with "},{"type":"text","text":"WITH name AS (…)","marks":[{"type":"code"}]},{"type":"text","text":". Queries read top-down like a pipeline instead of inside-out."}]}]}},"revision":1},{"id":"4cb5b095-68e7-7215-b9ab-1e04f110a8ea","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Syntax"}]},"revision":1},{"id":"3f26153b-17b0-7831-be28-51901966de3b","type":"code","position":"a2","content":{"language":"sql","code":"WITH dept_stats AS (\n    SELECT dept_id, COUNT(*) AS staff, AVG(salary) AS avg_sal\n    FROM employees\n    WHERE dept_id IS NOT NULL\n    GROUP BY dept_id\n)\nSELECT d.name, s.staff, ROUND(s.avg_sal) AS avg_sal\nFROM dept_stats s\nJOIN departments d ON d.dept_id = s.dept_id\nORDER BY s.avg_sal DESC;","filename":"SQL"},"revision":1},{"id":"d1268b64-daf1-7f58-ab26-3a4b86199208","type":"code","position":"a3","content":{"language":"text","code":"name        | staff | avg_sal\n------------+-------+---------\nEngineering | 4     | 115000.0\nSales       | 3     | 84000.0\nHR          | 2     | 82500.0","filename":"Output"},"revision":1},{"id":"5fa38d74-ab8c-7812-99d4-1842c9216e39","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Chaining CTEs"}]},"revision":1},{"id":"1b7cdaa9-f524-7c4f-91d4-87fa9e3f08d4","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Each CTE can use the ones defined before it. A multi-step report becomes a list of named steps."}]}]}},"revision":1},{"id":"acc00e05-41e1-79c0-89ce-c238610f5c81","type":"code","position":"a6","content":{"language":"sql","code":"WITH order_totals AS (           -- step 1: value of each valid order\n    SELECT o.order_id, o.customer_id, SUM(oi.quantity * oi.unit_price) AS total\n    FROM orders o\n    JOIN order_items oi ON oi.order_id = o.order_id\n    WHERE o.status <> ''cancelled''\n    GROUP BY o.order_id, o.customer_id\n),\ncustomer_totals AS (             -- step 2: per customer\n    SELECT customer_id, COUNT(*) AS orders, SUM(total) AS spent\n    FROM order_totals\n    GROUP BY customer_id\n),\noverall AS (                     -- step 3: one number to compare against\n    SELECT AVG(spent) AS avg_spent FROM customer_totals\n)\nSELECT c.name, ct.orders, ct.spent,\n       CASE WHEN ct.spent > o.avg_spent THEN ''above avg'' ELSE ''below avg'' END AS segment\nFROM customer_totals ct\nJOIN customers c ON c.customer_id = ct.customer_id\nCROSS JOIN overall o\nORDER BY ct.spent DESC;","filename":"SQL"},"revision":1},{"id":"18e3bd90-98fb-7f72-8624-d7cd8f696612","type":"code","position":"a7","content":{"language":"text","code":"name   | orders | spent | segment\n-------+--------+-------+----------\nAnanya | 3      | 68400 | above avg\nRahul  | 2      | 61200 | above avg\nSneha  | 2      | 13700 | below avg","filename":"Output"},"revision":1},{"id":"d7af9c69-2090-75db-a60c-d0ce502cd2a4","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"CTE vs subquery vs view vs temp table"}]},"revision":1},{"id":"6ff9e662-33d7-726a-8bb5-4e1cfc076e5d","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"Scope"}],[{"type":"text","text":"Reusable in the statement"}],[{"type":"text","text":"Stored"}]],[[{"type":"text","text":"Derived table (subquery)"}],[{"type":"text","text":"One place in one query"}],[{"type":"text","text":"No — repeat it"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"CTE"}],[{"type":"text","text":"One statement"}],[{"type":"text","text":"Yes — reference by name, many times"}],[{"type":"text","text":"No"}]],[[{"type":"text","text":"View"}],[{"type":"text","text":"The database"}],[{"type":"text","text":"Across all queries"}],[{"type":"text","text":"Definition only"}]],[[{"type":"text","text":"Temporary table"}],[{"type":"text","text":"Session"}],[{"type":"text","text":"Across statements"}],[{"type":"text","text":"Yes (data, can be indexed)"}]]]},"revision":1},{"id":"79eee502-7bd7-7830-8100-044802778d96","type":"callout","position":"aA","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Whether a CTE is computed once ("},{"type":"text","text":"materialised","marks":[{"type":"bold"}]},{"type":"text","text":") or inlined like a subquery depends on the engine. PostgreSQL 12+ inlines by default and lets you force either with "},{"type":"text","text":"AS MATERIALIZED","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"AS NOT MATERIALIZED","marks":[{"type":"code"}]},{"type":"text","text":"; SQLite accepts the same hints."}]}]}},"revision":1},{"id":"37158c21-fa6f-72ca-bf3e-34f9c937f422","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"CTEs with DML"}]},"revision":1},{"id":"445c93b8-ebe9-7209-9916-aaec6ea9c87e","type":"code","position":"aC","content":{"language":"sql","code":"-- give a 5% raise to everyone below their department''s average\nWITH below AS (\n    SELECT e.emp_id\n    FROM employees e\n    WHERE e.salary < (SELECT AVG(salary) FROM employees i WHERE i.dept_id = e.dept_id)\n)\nUPDATE employees\nSET salary = salary * 105 / 100\nWHERE emp_id IN (SELECT emp_id FROM below);\n\nSELECT name, salary FROM employees WHERE emp_id IN (3, 4, 6, 7, 8) ORDER BY emp_id;","filename":"SQL"},"revision":1},{"id":"cbaa6470-2585-7ae9-9949-13a9939784ce","type":"code","position":"aD","content":{"language":"text","code":"name   | salary\n-------+-------\nMeera  | 99750\nKaran  | 99750\nArjun  | 73500\nNeha   | 75600\nVikram | 84000","filename":"Output"},"revision":1},{"id":"245aff91-439e-71f4-93ce-9bd9d5a67d41","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a CTE and why use it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A Common Table Expression is a named, temporary result defined with "},{"type":"text","text":"WITH","marks":[{"type":"code"}]},{"type":"text","text":" and visible only to the statement that follows. It improves readability (step-by-step logic), lets you reference the same intermediate result several times, and is required for recursive queries."}]}]}},"revision":1},{"id":"5f01423a-9fea-761b-a3e8-4297b0cfb68e","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Is a CTE faster than a subquery?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Usually neither — most optimizers treat a non-recursive CTE like an inline subquery. It can be faster if it is materialised once and referenced many times, or slower if materialisation blocks predicate push-down. Choose it for clarity and check the plan when performance matters."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
