SELECT '062f9e30-602a-7596-b949-6ab048b82dd6', '685ce0d3-8c83-7871-9fa6-3c0f4cce6f70', 1, 'PUBLISHED', 'Denormalization & OLTP vs OLAP', '[{"id":"cb217b23-2aef-77cb-b652-453ab38d4ba1","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Denormalization deliberately re-introduces redundancy to make reads faster or simpler — trading write complexity and consistency risk for fewer joins."}]}]}},"revision":1},{"id":"2595885f-efe4-7f2b-bb3c-c45f1de3a385","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Common techniques"}]},"revision":1},{"id":"55ab5797-1911-7131-9d92-6b34fab203c2","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Technique"}],[{"type":"text","text":"Example"}],[{"type":"text","text":"Kept in sync by"}]],[[{"type":"text","text":"Stored aggregate"}],[{"type":"text","text":"customers.lifetime_value","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"posts.comment_count","marks":[{"type":"code"}]}],[{"type":"text","text":"Trigger, application code, batch job"}]],[[{"type":"text","text":"Duplicated column"}],[{"type":"text","text":"orders.customer_city","marks":[{"type":"code"}]},{"type":"text","text":" copied from customers"}],[{"type":"text","text":"Trigger / app"}]],[[{"type":"text","text":"Snapshot of a value at a time"}],[{"type":"text","text":"order_items.unit_price","marks":[{"type":"code"}]},{"type":"text","text":" (price "},{"type":"text","text":"when bought","marks":[{"type":"italic"}]},{"type":"text","text":")"}],[{"type":"text","text":"Written once — not really redundancy"}]],[[{"type":"text","text":"Pre-joined reporting table"}],[{"type":"text","text":"One wide "},{"type":"text","text":"sales_fact","marks":[{"type":"code"}]},{"type":"text","text":" row per order line"}],[{"type":"text","text":"ETL / materialised view"}]],[[{"type":"text","text":"Materialised view"}],[{"type":"text","text":"monthly_revenue","marks":[{"type":"code"}]}],[{"type":"text","text":"REFRESH","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"3f26486a-437e-74a1-bfba-333eb16054e0","type":"callout","position":"a3","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"order_items.unit_price","marks":[{"type":"code"}]},{"type":"text","text":" looks redundant with "},{"type":"text","text":"products.price","marks":[{"type":"code"}]},{"type":"text","text":" but isn''t: it records a "},{"type":"text","text":"different fact","marks":[{"type":"italic"}]},{"type":"text","text":" (the price paid on that day). Order 106 paid 52000 while the list price is 55000."}]}]}},"revision":1},{"id":"ce88ceb8-cc4e-7aac-bcad-a5e5fffd7002","type":"code","position":"a4","content":{"language":"sql","code":"SELECT oi.order_id, p.name, p.price AS list_price, oi.unit_price AS paid\nFROM order_items oi JOIN products p ON p.product_id = oi.product_id\nWHERE p.name = ''Laptop''\nORDER BY oi.order_id;","filename":"SQL"},"revision":1},{"id":"a6110e7f-a2d6-71f7-ad53-6397c113d20b","type":"code","position":"a5","content":{"language":"text","code":"order_id | name   | list_price | paid\n---------+--------+------------+------\n101      | Laptop | 55000      | 55000\n106      | Laptop | 55000      | 52000","filename":"Output"},"revision":1},{"id":"e5d5c685-aa0f-79f1-841b-f85b27abfc0a","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"OLTP vs OLAP"}]},"revision":1},{"id":"7d4321d5-f72d-7255-b1c1-17aefaf2c907","type":"table","position":"a7","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"OLTP (transactions)"}],[{"type":"text","text":"OLAP (analytics)"}]],[[{"type":"text","text":"Workload"}],[{"type":"text","text":"Many small reads/writes by key"}],[{"type":"text","text":"Few huge scans and aggregations"}]],[[{"type":"text","text":"Schema"}],[{"type":"text","text":"Normalised (3NF)"}],[{"type":"text","text":"Denormalised "},{"type":"text","text":"star / snowflake","marks":[{"type":"bold"}]},{"type":"text","text":" schema"}]],[[{"type":"text","text":"Examples"}],[{"type":"text","text":"PostgreSQL, MySQL, SQL Server for the app"}],[{"type":"text","text":"Snowflake, BigQuery, Redshift, ClickHouse, DuckDB"}]],[[{"type":"text","text":"Storage"}],[{"type":"text","text":"Row-oriented"}],[{"type":"text","text":"Column-oriented, compressed"}]],[[{"type":"text","text":"Freshness"}],[{"type":"text","text":"Real time"}],[{"type":"text","text":"Loaded by ETL/ELT (minutes–hours)"}]]]},"revision":1},{"id":"2a71322e-034d-7a64-95bc-6e08877ffafa","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Star schema"}]},"revision":1},{"id":"630376c8-c9fb-7a51-bbea-7f7221c65738","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A central "},{"type":"text","text":"fact table","marks":[{"type":"bold"}]},{"type":"text","text":" of measurable events ("},{"type":"text","text":"sales_fact","marks":[{"type":"code"}]},{"type":"text","text":": quantity, amount) with foreign keys to "},{"type":"text","text":"dimension tables","marks":[{"type":"bold"}]},{"type":"text","text":" describing them ("},{"type":"text","text":"dim_date","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"dim_customer","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"dim_product","marks":[{"type":"code"}]},{"type":"text","text":"). Dimensions are wide and denormalised, so queries need one join per dimension."}]}]}},"revision":1},{"id":"6b0041eb-d561-72f1-b963-5eea3a307e49","type":"code","position":"aA","content":{"language":"sql","code":"CREATE TABLE sales_fact AS\nSELECT o.order_date AS date_key, o.customer_id, oi.product_id,\n       oi.quantity, oi.quantity * oi.unit_price AS amount\nFROM orders o JOIN order_items oi ON oi.order_id = o.order_id\nWHERE o.status <> ''cancelled'';\n\nSELECT p.category, c.city, SUM(f.amount) AS revenue\nFROM sales_fact f\nJOIN products  p ON p.product_id  = f.product_id\nJOIN customers c ON c.customer_id = f.customer_id\nGROUP BY p.category, c.city\nORDER BY revenue DESC;","filename":"SQL"},"revision":1},{"id":"d86547aa-c787-78ee-b91d-af39542dc9f9","type":"code","position":"aB","content":{"language":"text","code":"category    | city      | revenue\n------------+-----------+--------\nElectronics | Mumbai    | 60000\nElectronics | Delhi     | 52000\nFurniture   | Bengaluru | 12500\nFurniture   | Delhi     | 9000\nFurniture   | Mumbai    | 8000\nStationery  | Bengaluru | 1200\nStationery  | Mumbai    | 400\nStationery  | Delhi     | 200","filename":"Output"},"revision":1},{"id":"ba47322b-2967-709a-a7b5-b7fcb89bfaa6","type":"callout","position":"aC","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Normalise first; denormalise a specific hot path after measuring, with a clear owner of the sync logic (trigger, job, or materialised view)."}]}]}},"revision":1},{"id":"04b9d68d-4550-7456-801a-852dbd1b94a8","type":"callout","position":"aD","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Denormalise “for speed” up front — you pay forever in inconsistent data and complex writes."}]}]}},"revision":1},{"id":"dd361f58-7ba7-7a0f-9912-0bb6e261c678","type":"question","position":"aE","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When would you denormalize?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When a read path is hot and joins/aggregations are measurably too slow even with good indexes, for reporting/analytics (star schemas), or to cache expensive aggregates (counters). Accept the cost: extra storage, slower writes and code/triggers to keep copies consistent."}]}]}},"revision":1},{"id":"0be9b1ad-7421-762c-b7ad-483d4cf0975d","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a star schema?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A data-warehouse design with one central fact table (numeric measures + foreign keys) surrounded by denormalised dimension tables (date, customer, product, store). Snowflake schema = the dimensions are further normalised into sub-dimensions."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
