SELECT '5c15c2b0-5713-719e-ab21-5fbe4a7a94de', '01c56c68-c0c5-78ea-a419-c38e96a8aa30', 1, 'PUBLISHED', 'DISTINCT & Aliases', '[{"id":"04811796-9384-77f2-9fd0-402f3041893a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DISTINCT","marks":[{"type":"code"}]},{"type":"text","text":" removes duplicate result rows; aliases give columns and tables short, readable names."}]}]}},"revision":1},{"id":"68b36040-5682-7618-b5c3-2818b9259e1a","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"DISTINCT"}]},"revision":1},{"id":"b1ecd081-1e36-7ca4-b823-39367d5d4ba0","type":"code","position":"a2","content":{"language":"sql","code":"SELECT DISTINCT category FROM products ORDER BY category;\n\nSELECT DISTINCT city FROM customers ORDER BY city;       -- NULL counts as one value here","filename":"SQL"},"revision":1},{"id":"e85c5086-b2ed-7250-a038-96d87f86c7a4","type":"code","position":"a3","content":{"language":"text","code":"category\n-----------\nElectronics\nFurniture\nStationery\n\ncity\n---------\nNULL\nBengaluru\nDelhi\nMumbai","filename":"Output"},"revision":1},{"id":"1fe6ea34-9b57-75e9-ba32-5b59a940e3df","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DISTINCT","marks":[{"type":"code"}]},{"type":"text","text":" applies to the "},{"type":"text","text":"whole row","marks":[{"type":"bold"}]},{"type":"text","text":", not to one column:"}]}]}},"revision":1},{"id":"aeb3c2e9-b66b-7050-9cd5-edd597b74713","type":"code","position":"a5","content":{"language":"sql","code":"SELECT DISTINCT customer_id, status FROM orders ORDER BY customer_id, status;","filename":"SQL"},"revision":1},{"id":"d5982bfd-e41c-791f-bf28-8529cffb0965","type":"code","position":"a6","content":{"language":"text","code":"customer_id | status\n------------+----------\n1           | delivered\n1           | shipped\n2           | delivered\n3           | pending\n3           | shipped\n4           | cancelled","filename":"Output"},"revision":1},{"id":"27246904-57b2-734f-9af4-dc6fbdfc1942","type":"code","position":"a7","content":{"language":"sql","code":"SELECT COUNT(DISTINCT customer_id) AS customers_who_ordered,\n       COUNT(DISTINCT status)      AS statuses\nFROM orders;","filename":"SQL"},"revision":1},{"id":"853f5eb9-3992-72f4-a22b-114ea6e5cab6","type":"code","position":"a8","content":{"language":"text","code":"customers_who_ordered | statuses\n----------------------+---------\n4                     | 4","filename":"Output"},"revision":1},{"id":"3c7dcbca-8918-712f-90d9-2f896c9cec99","type":"callout","position":"a9","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Reaching for "},{"type":"text","text":"DISTINCT","marks":[{"type":"code"}]},{"type":"text","text":" to hide duplicates caused by a join usually hides a bug (a missing join condition or a one-to-many join). Fix the join — or use "},{"type":"text","text":"EXISTS","marks":[{"type":"code"}]},{"type":"text","text":" — instead."}]}]}},"revision":1},{"id":"fb333077-fcf3-7384-9748-e941fe1f5722","type":"code","position":"aA","content":{"language":"sql","code":"-- PostgreSQL only: first row per group (by the ORDER BY)\nSELECT DISTINCT ON (dept_id) dept_id, name, salary\nFROM employees\nORDER BY dept_id, salary DESC;","filename":"PostgreSQL (DISTINCT ON)"},"revision":1},{"id":"ed453ed1-45c6-71dc-9322-af3f46be08c9","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Column aliases"}]},"revision":1},{"id":"09d0ce88-3b9c-722c-a701-3f1e1ee7e4b6","type":"code","position":"aC","content":{"language":"sql","code":"SELECT name AS employee,\n       salary * 12 AS \"annual pay\",       -- double quotes: spaces or reserved words\n       hire_date joined                    -- AS is optional\nFROM employees\nWHERE emp_id <= 2\nORDER BY emp_id;","filename":"SQL"},"revision":1},{"id":"465826b7-3f0b-72e1-87c4-4cabb0cf2fa4","type":"code","position":"aD","content":{"language":"text","code":"employee | annual pay | joined\n---------+------------+-----------\nAsha     | 1800000    | 2015-03-01\nRavi     | 1440000    | 2017-06-15","filename":"Output"},"revision":1},{"id":"7a13e52e-fae6-7c44-bb54-4d5fa41f1b84","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Table aliases"}]},"revision":1},{"id":"69f422c5-bd96-72d2-8929-29ab33a8ff25","type":"code","position":"aF","content":{"language":"sql","code":"SELECT e.name, d.name AS department\nFROM employees AS e\nJOIN departments d ON d.dept_id = e.dept_id\nWHERE e.salary > 100000\nORDER BY e.emp_id;","filename":"SQL"},"revision":1},{"id":"7acac0d8-4175-7a17-9115-e153be82aebf","type":"code","position":"aG","content":{"language":"text","code":"name  | department\n------+------------\nAsha  | Engineering\nRavi  | Engineering\nPriya | Sales","filename":"Output"},"revision":1},{"id":"69a0275a-f1d3-7176-a309-71f7056d0b10","type":"callout","position":"aH","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A table alias is required when the same table appears twice (self-join) and makes every multi-table query readable. Oracle does not accept "},{"type":"text","text":"AS","marks":[{"type":"code"}]},{"type":"text","text":" before a "},{"type":"text","text":"table","marks":[{"type":"italic"}]},{"type":"text","text":" alias."}]}]}},"revision":1},{"id":"cb15882c-3124-7177-8740-2ebe00f7af03","type":"callout","position":"aI","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A column alias cannot be used in "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" of the same query (the "},{"type":"text","text":"SELECT","marks":[{"type":"code"}]},{"type":"text","text":" list is evaluated "},{"type":"text","text":"after","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":") — see the next topic. SQLite and MySQL relax this in places, which is not portable."}]}]}},"revision":1},{"id":"fa10dafc-7fea-7c4f-822f-1e44e04ccd6a","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between DISTINCT and GROUP BY?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SELECT DISTINCT a, b","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"SELECT a, b … GROUP BY a, b","marks":[{"type":"code"}]},{"type":"text","text":" return the same rows and usually get the same plan. Use "},{"type":"text","text":"DISTINCT","marks":[{"type":"code"}]},{"type":"text","text":" to de-duplicate; use "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":" when you also compute aggregates per group."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
