SELECT '5f8b8322-d98f-7075-9adc-3065d29280a7', '9a6aef43-42ad-74e8-af67-e5439ae05f54', 1, 'PUBLISHED', 'Finding & Deleting Duplicates', '[{"id":"d98fc49c-8007-71f3-8285-dbddc93497dd","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find rows that repeat a value that should be unique, show all copies, and delete all but one — three variations of the same "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"ROW_NUMBER","marks":[{"type":"code"}]},{"type":"text","text":" idea."}]}]}},"revision":1},{"id":"1fc58541-5ffc-7d26-a8f6-44d67c6a0f4d","type":"code","position":"a1","content":{"language":"sql","code":"SELECT * FROM contacts ORDER BY id;","filename":"SQL"},"revision":1},{"id":"dc2f8af1-5e8d-7783-807a-11e615b980b5","type":"code","position":"a2","content":{"language":"text","code":"id | name  | email\n---+-------+---------------\n1  | Asha  | asha@mail.com\n2  | Ravi  | ravi@mail.com\n3  | Asha  | ASHA@mail.com\n4  | Meera | meera@mail.com\n5  | Ravi  | ravi@mail.com\n6  | Ravi  | ravi@mail.com","filename":"Output"},"revision":1},{"id":"ac07bb66-f2a5-7c5a-af9c-28b5ea6f21e1","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Which values are duplicated?"}]},"revision":1},{"id":"6311e116-694a-7355-8ff3-e2130100c23a","type":"code","position":"a4","content":{"language":"sql","code":"SELECT email, COUNT(*) AS copies\nFROM contacts\nGROUP BY email\nHAVING COUNT(*) > 1;\n\n-- case-insensitive duplicates\nSELECT lower(email) AS email, COUNT(*) AS copies, group_concat(id) AS ids\nFROM contacts\nGROUP BY lower(email)\nHAVING COUNT(*) > 1\nORDER BY email;","filename":"SQL"},"revision":1},{"id":"eb05dbf2-ed09-7f7f-acdf-466f0391571d","type":"code","position":"a5","content":{"language":"text","code":"email         | copies\n--------------+-------\nravi@mail.com | 3\n\nemail         | copies | ids\n--------------+--------+------\nasha@mail.com | 2      | 1,3\nravi@mail.com | 3      | 2,5,6","filename":"Output"},"revision":1},{"id":"9cad56a8-3b70-7cc8-99d4-66ce9067a574","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Show every duplicate row"}]},"revision":1},{"id":"f59b164a-502d-7607-88ae-bbf49245a8c7","type":"code","position":"a7","content":{"language":"sql","code":"SELECT id, name, email,\n       COUNT(*) OVER (PARTITION BY email) AS copies\nFROM contacts\nORDER BY email, id;","filename":"SQL"},"revision":1},{"id":"c1b0a37c-4b04-71c4-8393-ccdadcec6d61","type":"code","position":"a8","content":{"language":"text","code":"id | name  | email          | copies\n---+-------+----------------+-------\n3  | Asha  | ASHA@mail.com  | 1\n1  | Asha  | asha@mail.com  | 1\n4  | Meera | meera@mail.com | 1\n2  | Ravi  | ravi@mail.com  | 3\n5  | Ravi  | ravi@mail.com  | 3\n6  | Ravi  | ravi@mail.com  | 3","filename":"Output"},"revision":1},{"id":"f157ba22-a8b0-738d-90e6-ff1df2111e6e","type":"code","position":"a9","content":{"language":"sql","code":"-- rows whose (name, email) combination appears more than once\nSELECT c.*\nFROM contacts c\nJOIN (SELECT name, email FROM contacts GROUP BY name, email HAVING COUNT(*) > 1) d\n  ON d.name = c.name AND d.email = c.email\nORDER BY c.id;","filename":"SQL"},"revision":1},{"id":"c51f6a76-2b35-732f-9373-e83956fc749c","type":"code","position":"aA","content":{"language":"text","code":"id | name | email\n---+------+--------------\n2  | Ravi | ravi@mail.com\n5  | Ravi | ravi@mail.com\n6  | Ravi | ravi@mail.com","filename":"Output"},"revision":1},{"id":"adc27845-1555-7ffc-8b55-d9ebe46a0222","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Delete duplicates, keep the lowest id"}]},"revision":1},{"id":"7eb8266b-1cb6-7926-b242-9cd7c002a843","type":"code","position":"aC","content":{"language":"sql","code":"DELETE FROM contacts\nWHERE id IN (\n    SELECT id FROM (\n        SELECT id, ROW_NUMBER() OVER (PARTITION BY email ORDER BY id) AS rn\n        FROM contacts\n    ) WHERE rn > 1\n);\n\nSELECT * FROM contacts ORDER BY id;","filename":"SQL"},"revision":1},{"id":"4bf3376a-a948-7117-a9cd-742d2c8dcb72","type":"code","position":"aD","content":{"language":"text","code":"id | name  | email\n---+-------+---------------\n1  | Asha  | asha@mail.com\n2  | Ravi  | ravi@mail.com\n3  | Asha  | ASHA@mail.com\n4  | Meera | meera@mail.com","filename":"Output"},"revision":1},{"id":"f72ed024-b8cc-7812-b850-1190ac7a86dc","type":"code","position":"aE","content":{"language":"sql","code":"-- without window functions: keep MIN(id) of each group\nDELETE FROM contacts\nWHERE id NOT IN (SELECT MIN(id) FROM contacts GROUP BY email);\n\nSELECT * FROM contacts ORDER BY id;","filename":"SQL"},"revision":1},{"id":"d8f309a8-5bf0-738b-b200-00f73627d4bc","type":"code","position":"aF","content":{"language":"text","code":"id | name  | email\n---+-------+---------------\n1  | Asha  | asha@mail.com\n2  | Ravi  | ravi@mail.com\n3  | Asha  | ASHA@mail.com\n4  | Meera | meera@mail.com","filename":"Output"},"revision":1},{"id":"d84dbe31-01e2-7744-9cc1-b502468e9ccd","type":"text","position":"aG","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Contact 3 ("},{"type":"text","text":"ASHA@mail.com","marks":[{"type":"code"}]},{"type":"text","text":") survived both deletes: the comparison is case-sensitive. Partition/group by "},{"type":"text","text":"lower(email)","marks":[{"type":"code"}]},{"type":"text","text":" when duplicates should be detected case-insensitively."}]}]}},"revision":1},{"id":"51360dae-3a96-7854-b128-04d28c0c59d4","type":"code","position":"aH","content":{"language":"sql","code":"-- MySQL: self-join delete\nDELETE c1 FROM contacts c1\nJOIN contacts c2 ON c2.email = c1.email AND c2.id < c1.id;\n\n-- SQL Server: delete through a CTE\nWITH d AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY email ORDER BY id) AS rn FROM contacts)\nDELETE FROM d WHERE rn > 1;","filename":"MySQL / SQL Server"},"revision":1},{"id":"cf34a4a7-659b-729b-a9a2-b29d0bc2c7a7","type":"callout","position":"aI","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After cleaning, add the constraint that should have been there: "},{"type":"text","text":"CREATE UNIQUE INDEX ux_contacts_email ON contacts (lower(email));","marks":[{"type":"code"}]}]}]}},"revision":1},{"id":"f70277ba-1295-7e7d-8f95-e8a4d1ba883a","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you delete duplicate rows but keep one?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Number the rows within each duplicate group with "},{"type":"text","text":"ROW_NUMBER() OVER (PARTITION BY <dup columns> ORDER BY id)","marks":[{"type":"code"}]},{"type":"text","text":" and delete those with "},{"type":"text","text":"rn > 1","marks":[{"type":"code"}]},{"type":"text","text":"; or delete where "},{"type":"text","text":"id NOT IN (SELECT MIN(id) … GROUP BY <dup columns>)","marks":[{"type":"code"}]},{"type":"text","text":". If the table has no unique id at all, copy distinct rows to a new table (or use the engine''s physical row id: "},{"type":"text","text":"rowid","marks":[{"type":"code"}]},{"type":"text","text":" in SQLite, "},{"type":"text","text":"ctid","marks":[{"type":"code"}]},{"type":"text","text":" in PostgreSQL)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
WHERE EXISTS (SELECT 1 FROM "notes"."Note" n WHERE n.id = '9a6aef43-42ad-74e8-af67-e5439ae05f54' AND n."ownerId" = '019a118c-f480-7000-8000-000000000001' AND n."publishedVersionId" IS NULL AND n.visibility = 'PRIVATE' AND n."deletedAt" IS NULL AND n."draftUpdatedAt" = TIMESTAMPTZ '2026-10-07 03:23:53+00')
