INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '4f9aef61-9e75-76d2-a5e9-bdc5b23149db', '65799c13-f3c0-72a5-9e49-ae479a0e7ec7', 1, 'PUBLISHED', 'Employee–Manager Queries', '[{"id":"d8ef1be4-4675-7d95-b6aa-4ffa3a5d814b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The self-referencing "},{"type":"text","text":"employees","marks":[{"type":"code"}]},{"type":"text","text":" table powers a whole family of interview questions. All of them are a self join, an aggregate, or a recursive CTE."}]}]}},"revision":1},{"id":"4cea1190-728e-7b69-a785-db47ccef4205","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Employees earning more than their manager"}]},"revision":1},{"id":"18a95636-3d9e-7ba2-b54a-44f633d67ca7","type":"code","position":"a2","content":{"language":"sql","code":"SELECT e.name AS employee, e.salary, m.name AS manager, m.salary AS manager_salary\nFROM employees e\nJOIN employees m ON m.emp_id = e.manager_id\nWHERE e.salary > m.salary;","filename":"SQL"},"revision":1},{"id":"e943c59f-efa2-77d0-82c2-bc789a10cc94","type":"code","position":"a3","content":{"language":"text","code":"employee | salary | manager | manager_salary\n---------+--------+---------+---------------\nSara     | 85000  | Vikram  | 80000","filename":"Output"},"revision":1},{"id":"bea8dda7-9e03-7071-8235-8a0561f5c122","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Managers with at least N direct reports"}]},"revision":1},{"id":"1fc616a3-ef42-7e29-96ba-a43007071a6b","type":"code","position":"a5","content":{"language":"sql","code":"SELECT m.name AS manager, COUNT(*) AS direct_reports\nFROM employees e\nJOIN employees m ON m.emp_id = e.manager_id\nGROUP BY m.emp_id, m.name\nHAVING COUNT(*) >= 2\nORDER BY direct_reports DESC, manager;","filename":"SQL"},"revision":1},{"id":"90e6cff9-6743-708f-ac7a-f888e78f4a1a","type":"code","position":"a6","content":{"language":"text","code":"manager | direct_reports\n--------+---------------\nAsha    | 4\nPriya   | 2\nRavi    | 2","filename":"Output"},"revision":1},{"id":"927bdf46-b032-77f8-a0db-f559ce458e2e","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Employees who are not managers (leaf nodes)"}]},"revision":1},{"id":"91e0b0c6-4b97-7824-be0f-ae3bc51d22ea","type":"code","position":"a8","content":{"language":"sql","code":"SELECT e.name\nFROM employees e\nWHERE NOT EXISTS (SELECT 1 FROM employees r WHERE r.manager_id = e.emp_id)\nORDER BY e.emp_id;","filename":"SQL"},"revision":1},{"id":"3a199c21-6f4d-7abd-9035-7af428094206","type":"code","position":"a9","content":{"language":"text","code":"name\n-----\nMeera\nKaran\nArjun\nNeha\nSara\nDev","filename":"Output"},"revision":1},{"id":"90a603ef-67cf-7fe8-8be6-15d7c13d8271","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Employee, manager and department in one row"}]},"revision":1},{"id":"6244d6c2-3245-72cb-99fe-3cc7a248e6f6","type":"code","position":"aB","content":{"language":"sql","code":"SELECT e.name AS employee,\n       COALESCE(m.name, ''—'')      AS manager,\n       COALESCE(d.name, ''Unassigned'') AS department,\n       CASE WHEN e.dept_id = m.dept_id THEN ''same'' ELSE ''different'' END AS manager_dept\nFROM employees e\nLEFT JOIN employees m   ON m.emp_id = e.manager_id\nLEFT JOIN departments d ON d.dept_id = e.dept_id\nORDER BY e.emp_id;","filename":"SQL"},"revision":1},{"id":"f30f1ab2-3f2b-71e5-b3aa-da24943cbc4d","type":"code","position":"aC","content":{"language":"text","code":"employee | manager | department  | manager_dept\n---------+---------+-------------+-------------\nAsha     | —       | Engineering | different\nRavi     | Asha    | Engineering | same\nMeera    | Ravi    | Engineering | same\nKaran    | Ravi    | Engineering | same\nPriya    | Asha    | Sales       | different\nArjun    | Priya   | Sales       | same\nNeha     | Priya   | Sales       | same\nVikram   |