SELECT '7e01631e-e8ac-7f3b-b8c5-cdc4d22ff933', '10d95a3c-5565-7545-b764-e50c6c6b7590', 1, 'PUBLISHED', 'Consecutive Days, Gaps & Islands', '[{"id":"adc67a67-c253-779c-b026-6cac436e83e8","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"“Users who logged in 3 days in a row”, “longest streak”, “missing ids” — the "},{"type":"text","text":"gaps-and-islands","marks":[{"type":"bold"}]},{"type":"text","text":" family, solved elegantly with "},{"type":"text","text":"ROW_NUMBER","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"LAG","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"97d8fad5-ee27-7b50-9427-63f921f4f975","type":"code","position":"a1","content":{"language":"sql","code":"SELECT user_id, group_concat(substr(login_date, 9), '', '') AS march_days\nFROM (SELECT * FROM logins ORDER BY user_id, login_date)\nGROUP BY user_id\nORDER BY user_id;","filename":"SQL"},"revision":1},{"id":"0110cc92-51ae-7d30-b1a2-10210e04a91c","type":"code","position":"a2","content":{"language":"text","code":"user_id | march_days\n--------+-------------------\n1       | 01, 02, 03, 05, 06\n2       | 01, 03\n3       | 02, 03, 04, 05","filename":"Output"},"revision":1},{"id":"d373e397-e7ec-7aa7-bd15-e53f958762d4","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"The islands trick"}]},"revision":1},{"id":"e2bb5013-0143-73a4-88e1-40a42c2e1285","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Within one user, subtract the row number (in days) from the date. Consecutive dates produce the "},{"type":"text","text":"same","marks":[{"type":"bold"}]},{"type":"text","text":" anchor value; a gap changes it. Group by that anchor and each group is one streak (“island”)."}]}]}},"revision":1},{"id":"8b4f9a09-95b2-7238-8b64-2cf62fbe382c","type":"code","position":"a5","content":{"language":"sql","code":"SELECT user_id, login_date,\n       ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY login_date) AS rn,\n       date(login_date, ''-'' || ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY login_date) || '' days'') AS grp\nFROM logins\nWHERE user_id = 1\nORDER BY login_date;","filename":"SQL"},"revision":1},{"id":"9b79a3f8-5d11-756f-8c57-fb471552bb8a","type":"code","position":"a6","content":{"language":"text","code":"user_id | login_date | rn | grp\n--------+------------+----+-----------\n1       | 2024-03-01 | 1  | 2024-02-29\n1       | 2024-03-02 | 2  | 2024-02-29\n1       | 2024-03-03 | 3  | 2024-02-29\n1       | 2024-03-05 | 4  | 2024-03-01\n1       | 2024-03-06 | 5  | 2024-03-01","filename":"Output"},"revision":1},{"id":"3152ace7-eba2-7262-b85f-d694e17ef805","type":"code","position":"a7","content":{"language":"sql","code":"WITH marked AS (\n    SELECT user_id, login_date,\n           date(login_date, ''-'' || ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY login_date) || '' days'') AS grp\n    FROM logins\n)\nSELECT user_id, MIN(login_date) AS streak_start, MAX(login_date) AS streak_end, COUNT(*) AS days\nFROM marked\nGROUP BY user_id, grp\nORDER BY user_id, streak_start;","filename":"SQL"},"revision":1},{"id":"756794bd-ec57-758c-9e3a-544d70736d44","type":"code","position":"a8","content":{"language":"text","code":"user_id | streak_start | streak_end | days\n--------+--------------+------------+-----\n1       | 2024-03-01   | 2024-03-03 | 3\n1       | 2024-03-05   | 2024-03-06 | 2\n2       | 2024-03-01   | 2024-03-01 | 1\n2       | 2024-03-03   | 2024-03-03 | 1\n3       | 2024-03-02   | 2024-03-05 | 4","filename":"Output"},"revision":1},{"id":"05541074-73d8-7548-bb6f-e0bac2b0f909","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Users with 3+ consecutive days, and longest streak"}]},"revision":1},{"id":"1a56b563-8391-7f10-8036-8883bc4b36a5","type":"code","position":"aA","content":{"language":"sql","code":"WITH marked AS (\n    SELECT user_id,\n           date(login_date, ''-'' || ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY login_date) || '' days'') AS grp\n    FROM logins\n),\nstreaks AS (\n    SELECT user_id, COUNT(*) AS days FROM marked GROUP BY user_id, grp\n)\nSELECT user_id, MAX(days) AS longest_streak\nFROM streaks\nGROUP BY user_id\nHAVING MAX(days) >= 3\nORDER BY user_id;","filename":"SQL"},"revision":1},{"id":"49bde643-4309-7cca-ad3b-b38e529b94b8","type":"code","position":"aB","content":{"language":"text","code":"user_id | longest_streak\n--------+---------------\n1       | 3\n3       | 4","filename":"Output"},"revision":1},{"id":"403ef036-58ef-7778-b8b5-9c62e8722d5d","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"The LAG alternative: detect breaks"}]},"revision":1},{"id":"2834f24b-e0c9-7eae-b7c0-cce4f6946c49","type":"code","position":"aD","content":{"language":"sql","code":"-- 3 consecutive days = today, yesterday and the day before are all present\nSELECT DISTINCT user_id\nFROM (\n    SELECT user_id, login_date,\n           LAG(login_date, 2) OVER (PARTITION BY user_id ORDER BY login_date) AS two_back\n    FROM logins\n)\nWHERE julianday(login_date) - julianday(two_back) = 2\nORDER BY user_id;","filename":"SQL"},"revision":1},{"id":"8bbe9a31-cb85-7ede-8a45-94bdc718fa62","type":"code","position":"aE","content":{"language":"text","code":"user_id\n-------\n1\n3","filename":"Output"},"revision":1},{"id":"aea7f7e3-0f0a-7c82-aabf-2caa32a99c99","type":"heading","position":"aF","content":{"level":1,"content":[{"type":"text","text":"Gaps: missing values in a sequence"}]},"revision":1},{"id":"3179bcd2-889a-7619-ab28-a37947c6d719","type":"code","position":"aG","content":{"language":"sql","code":"-- gaps in order ids (orders 101..108 exist; pretend 103 and 104 were deleted)\nDELETE FROM order_items WHERE order_id IN (103, 104);\nDELETE FROM orders WHERE order_id IN (103, 104);\n\nSELECT order_id + 1 AS gap_start, next_id - 1 AS gap_end\nFROM (SELECT order_id, LEAD(order_id) OVER (ORDER BY order_id) AS next_id FROM orders)\nWHERE next_id - order_id > 1;","filename":"SQL"},"revision":1},{"id":"42af3684-984b-7f96-8ac4-d556d03c75b0","type":"code","position":"aH","content":{"language":"text","code":"gap_start | gap_end\n----------+--------\n103       | 104","filename":"Output"},"revision":1},{"id":"c8f360a6-f650-7caf-9741-28fa4255f860","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find users who logged in on 3 consecutive days."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Either "},{"type":"text","text":"LAG(login_date, 2) OVER (PARTITION BY user_id ORDER BY login_date)","marks":[{"type":"code"}]},{"type":"text","text":" and keep rows where the date difference is exactly 2 days (deduplicate dates first), or the islands trick: "},{"type":"text","text":"login_date − ROW_NUMBER()","marks":[{"type":"code"}]},{"type":"text","text":" days is constant across a streak, so "},{"type":"text","text":"GROUP BY user_id, that_value HAVING COUNT(*) >= 3","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
