SELECT 'b91600c9-684f-76a1-b8d8-df6559a4ef22', 'e21d9f2d-605a-797b-8ad4-4357a575be9a', 1, 'PUBLISHED', 'HAVING vs WHERE', '[{"id":"3cb2f9fa-3b44-7ea9-954e-13513379820c","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" filters "},{"type":"text","text":"rows","marks":[{"type":"bold"}]},{"type":"text","text":" before grouping; "},{"type":"text","text":"HAVING","marks":[{"type":"code"}]},{"type":"text","text":" filters "},{"type":"text","text":"groups","marks":[{"type":"bold"}]},{"type":"text","text":" after aggregation. Same idea, different stage."}]}]}},"revision":1},{"id":"56781b62-af4e-7a40-8b86-4826d919fafd","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[],[{"type":"text","text":"WHERE","marks":[{"type":"code"}]}],[{"type":"text","text":"HAVING","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Filters"}],[{"type":"text","text":"Individual rows"}],[{"type":"text","text":"Groups (aggregated rows)"}]],[[{"type":"text","text":"Runs"}],[{"type":"text","text":"Before "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]}],[{"type":"text","text":"After "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Can use aggregates"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Yes"}]],[[{"type":"text","text":"Can use indexes"}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Rarely — groups are computed first"}]],[[{"type":"text","text":"Needs "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"Usually (without it, the whole table is one group)"}]]]},"revision":1},{"id":"3e27aca4-2ef7-7cb2-91a9-26fa472b9eaf","type":"code","position":"a2","content":{"language":"sql","code":"-- departments whose average salary exceeds 90000, counting only people hired before 2023\nSELECT dept_id,\n       COUNT(*)            AS staff,\n       ROUND(AVG(salary))  AS avg_salary\nFROM employees\nWHERE hire_date < ''2023-01-01''          -- rows\nGROUP BY dept_id\nHAVING AVG(salary) > 90000              -- groups\nORDER BY avg_salary DESC;","filename":"SQL"},"revision":1},{"id":"be1e665f-7941-732d-9037-5979b235e424","type":"code","position":"a3","content":{"language":"text","code":"dept_id | staff | avg_salary\n--------+-------+-----------\n1       | 4     | 115000.0","filename":"Output"},"revision":1},{"id":"b01e1df5-444b-7756-af7a-fb0d9b2f7fb1","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Customers with more than one order"}]},"revision":1},{"id":"07513a42-4808-7469-8d6b-0aa5ae48df80","type":"code","position":"a5","content":{"language":"sql","code":"SELECT customer_id, COUNT(*) AS orders\nFROM orders\nGROUP BY customer_id\nHAVING COUNT(*) > 1\nORDER BY customer_id;","filename":"SQL"},"revision":1},{"id":"2850158f-c389-7944-a8d4-0740af3ac827","type":"code","position":"a6","content":{"language":"text","code":"customer_id | orders\n------------+-------\n1           | 3\n2           | 2\n3           | 2","filename":"Output"},"revision":1},{"id":"0b4ebde9-347f-73aa-9265-9bac6a532974","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Put row filters in WHERE"}]},"revision":1},{"id":"4cfe1d30-24d7-7caa-aa25-56fc82122e1c","type":"callout","position":"a8","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"WHERE status <> ''cancelled'' … GROUP BY customer_id","marks":[{"type":"code"}]},{"type":"text","text":" — discards rows early, can use an index, groups less data."}]}]}},"revision":1},{"id":"f1ada5e5-2fc4-77f6-99fc-135b9e9ed606","type":"callout","position":"a9","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"… GROUP BY customer_id, status HAVING status <> ''cancelled''","marks":[{"type":"code"}]},{"type":"text","text":" — works, but groups everything first and changes the grouping."}]}]}},"revision":1},{"id":"0f99dedf-8a77-7664-81d7-6546e73d8f44","type":"code","position":"aA","content":{"language":"sql","code":"-- HAVING without GROUP BY: the whole table is one group\nSELECT COUNT(*) AS products FROM products HAVING MIN(price) < 100;\nSELECT COUNT(*) AS products FROM products HAVING MIN(price) < 10;","filename":"SQL"},"revision":1},{"id":"277196be-fc8e-7476-9551-a1412bf75aaa","type":"code","position":"aB","content":{"language":"text","code":"products\n--------\n7\n\nproducts\n--------","filename":"Output"},"revision":1},{"id":"5d32087c-1d77-787f-91d5-a1035261054a","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between WHERE and HAVING?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" filters rows before grouping and cannot reference aggregates. "},{"type":"text","text":"HAVING","marks":[{"type":"code"}]},{"type":"text","text":" filters groups after "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":" and can reference aggregates like "},{"type":"text","text":"COUNT(*) > 1","marks":[{"type":"code"}]},{"type":"text","text":". Use "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" for anything that doesn''t need an aggregate — it''s cheaper."}]}]}},"revision":1},{"id":"907095e4-a8b4-7888-bfb1-7c3a28cf19e5","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find duplicate emails in a users table."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SELECT email, COUNT(*) FROM users GROUP BY email HAVING COUNT(*) > 1;","marks":[{"type":"code"}]},{"type":"text","text":" — group by the value that should be unique and keep groups with more than one row."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
