SELECT '52bd6511-5022-70d1-9f2b-17d275d41864', '339f983a-8f2b-76ca-b805-90f7ecc03630', 1, 'PUBLISHED', 'Indexes', '[{"id":"a3c13bbf-a0e8-7e0f-ba73-4eb50e8eb57a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An index is a separate, sorted structure that lets the database find rows without scanning the whole table — like the index at the back of a book. It speeds reads and slows writes."}]}]}},"revision":1},{"id":"4f6f0c66-28ed-7147-82eb-4443f8c4ce0e","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"B-tree: the default index"}]},"revision":1},{"id":"19f7d5ab-968b-7c77-af33-fa931802d97e","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A B-tree (B+tree) keeps keys sorted in a shallow, balanced tree: a lookup touches ~3–4 pages even for millions of rows (O(log n)), and because keys are sorted it also serves ranges, prefixes and "},{"type":"text","text":"ORDER BY","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"f068a19e-adb9-75e0-bbcf-f242a8f01a9a","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Query shape"}],[{"type":"text","text":"Can a B-tree on "},{"type":"text","text":"col","marks":[{"type":"code"}]},{"type":"text","text":" help?"}]],[[{"type":"text","text":"col = 5","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"col IN (…)","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes — seek"}]],[[{"type":"text","text":"col > 5","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"BETWEEN","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"LIKE ''abc%''","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes — range scan"}]],[[{"type":"text","text":"ORDER BY col","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"MIN/MAX(col)","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes — already sorted"}]],[[{"type":"text","text":"LIKE ''%abc''","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"lower(col) = …","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"col + 1 = 6","marks":[{"type":"code"}]}],[{"type":"text","text":"No — needs a full scan (or an expression index)"}]]]},"revision":1},{"id":"d84f3672-ceb5-76b8-b31c-09ea510d3129","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Reading a query plan"}]},"revision":1},{"id":"dc670853-9461-7737-8d56-9370795d234e","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"EXPLAIN QUERY PLAN","marks":[{"type":"code"}]},{"type":"text","text":" (SQLite) shows how a query will run; read the "},{"type":"text","text":"detail","marks":[{"type":"code"}]},{"type":"text","text":" column. "},{"type":"text","text":"SCAN","marks":[{"type":"bold"}]},{"type":"text","text":" = read every row; "},{"type":"text","text":"SEARCH … USING INDEX","marks":[{"type":"bold"}]},{"type":"text","text":" = jump straight to matching rows."}]}]}},"revision":1},{"id":"035fdbde-7e47-7429-80f4-24e8fa85b8dd","type":"code","position":"a6","content":{"language":"sql","code":"EXPLAIN QUERY PLAN\nSELECT * FROM events WHERE user_id = 42;","filename":"SQL"},"revision":1},{"id":"d2b25eea-80b8-7141-bb4b-4ea25e2f8397","type":"code","position":"a7","content":{"language":"text","code":"id | parent | notused | detail\n---+--------+---------+------------\n2  | 0      | 216     | SCAN events","filename":"Output"},"revision":1},{"id":"ffead954-fd21-7d6d-8e6f-d95fb6ffdebf","type":"code","position":"a8","content":{"language":"sql","code":"CREATE INDEX idx_events_user ON events (user_id);\n\nEXPLAIN QUERY PLAN\nSELECT * FROM events WHERE user_id = 42;","filename":"SQL"},"revision":1},{"id":"bb9ca93c-29b7-7cb3-8017-b5a92fea691f","type":"code","position":"a9","content":{"language":"text","code":"id | parent | notused | detail\n---+--------+---------+------------------------------------------------------\n3  | 0      | 61      | SEARCH events USING INDEX idx_events_user (user_id=?)","filename":"Output"},"revision":1},{"id":"24b8bc64-1b8e-7c7e-a7cd-5946bfeb1fd5","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Engine"}],[{"type":"text","text":"Show the plan"}],[{"type":"text","text":"Run and measure"}]],[[{"type":"text","text":"SQLite"}],[{"type":"text","text":"EXPLAIN QUERY PLAN …","marks":[{"type":"code"}]}],[{"type":"text","text":".timer on","marks":[{"type":"code"}]},{"type":"text","text":" in the shell"}]],[[{"type":"text","text":"PostgreSQL"}],[{"type":"text","text":"EXPLAIN …","marks":[{"type":"code"}]}],[{"type":"text","text":"EXPLAIN (ANALYZE, BUFFERS) …","marks":[{"type":"code"}]}]],[[{"type":"text","text":"MySQL"}],[{"type":"text","text":"EXPLAIN …","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"EXPLAIN FORMAT=TREE","marks":[{"type":"code"}]}],[{"type":"text","text":"EXPLAIN ANALYZE …","marks":[{"type":"code"}]}]],[[{"type":"text","text":"SQL Server"}],[{"type":"text","text":"Estimated plan (Ctrl+L)"}],[{"type":"text","text":"Actual plan, "},{"type":"text","text":"SET STATISTICS IO ON","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"042f8277-3361-7f3d-8cc4-881f6fbaa60c","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Composite indexes and the leftmost-prefix rule"}]},"revision":1},{"id":"983a44cc-ccbc-790d-8878-24f422f1f107","type":"text","position":"aC","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An index on "},{"type":"text","text":"(user_id, created_at)","marks":[{"type":"code"}]},{"type":"text","text":" is sorted by "},{"type":"text","text":"user_id","marks":[{"type":"code"}]},{"type":"text","text":", then by "},{"type":"text","text":"created_at","marks":[{"type":"code"}]},{"type":"text","text":" within each user — like a phone book sorted by surname, then first name. It helps queries that constrain a "},{"type":"text","text":"leftmost prefix","marks":[{"type":"bold"}]},{"type":"text","text":" of its columns."}]}]}},"revision":1},{"id":"df06a930-78a3-7267-a3fa-efea4e52c3aa","type":"code","position":"aD","content":{"language":"sql","code":"CREATE INDEX idx_events_user_time ON events (user_id, created_at);\n\nEXPLAIN QUERY PLAN SELECT * FROM events WHERE user_id = 42 AND created_at >= ''2024-03-01'';\nEXPLAIN QUERY PLAN SELECT * FROM events WHERE user_id = 42;\nEXPLAIN QUERY PLAN SELECT * FROM events WHERE created_at >= ''2024-03-01'';","filename":"SQL"},"revision":1},{"id":"eb79efeb-0741-7bef-8a41-b6510764d3f0","type":"code","position":"aE","content":{"language":"text","code":"id | parent | notused | detail\n---+--------+---------+----------------------------------------------------------------------------\n3  | 0      | 51      | SEARCH events USING INDEX idx_events_user_time (user_id=? AND created_at>?)\n\nid | parent | notused | detail\n---+--------+---------+-----------------------------------------------------------\n3  | 0      | 62      | SEARCH events USING INDEX idx_events_user_time (user_id=?)\n\nid | parent | notused | detail\n---+--------+---------+------------\n2  | 0      | 216     | SCAN events","filename":"Output"},"revision":1},{"id":"be50c3b9-348d-7482-b0d8-5a7c20bbc59b","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The third query cannot use the index: without "},{"type":"text","text":"user_id","marks":[{"type":"code"}]},{"type":"text","text":", the "},{"type":"text","text":"created_at","marks":[{"type":"code"}]},{"type":"text","text":" values are scattered across the whole index. Column order rule of thumb: "},{"type":"text","text":"equality columns first, then the range/sort column","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"ed0209d6-e71a-72d1-9d0b-1799e5401f60","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Covering indexes"}]},"revision":1},{"id":"831d1f22-6c0d-7076-a3c5-8881012f746c","type":"text","position":"aH","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"If the index contains every column the query needs, the engine answers from the index alone and never touches the table."}]}]}},"revision":1},{"id":"88890537-8168-7e93-aea1-445ae9ee3d3c","type":"code","position":"aI","content":{"language":"sql","code":"CREATE INDEX idx_events_user_kind ON events (user_id, kind);\n\nEXPLAIN QUERY PLAN\nSELECT kind, COUNT(*) FROM events WHERE user_id = 42 GROUP BY kind;","filename":"SQL"},"revision":1},{"id":"08208fd3-c42f-7e8d-bd00-6fa31b6524d7","type":"code","position":"aJ","content":{"language":"text","code":"id | parent | notused | detail\n---+--------+---------+--------------------------------------------------------------------\n6  | 0      | 55      | SEARCH events USING COVERING INDEX idx_events_user_kind (user_id=?)","filename":"Output"},"revision":1},{"id":"7dffacfb-70ab-71d7-b283-1a6bd4387a17","type":"code","position":"aK","content":{"language":"sql","code":"-- PostgreSQL 11+ / SQL Server: extra payload columns stored in the leaf, not part of the key\nCREATE INDEX idx_orders_cust ON orders (customer_id) INCLUDE (order_date, status);","filename":"PostgreSQL / SQL Server (INCLUDE)"},"revision":1},{"id":"51d8aa8c-83c6-70ea-b9f2-978a306b0d6f","type":"heading","position":"aL","content":{"level":1,"content":[{"type":"text","text":"Other kinds of index"}]},"revision":1},{"id":"6216b8ed-25e1-75f4-b150-d33bf3c33049","type":"code","position":"aM","content":{"language":"sql","code":"CREATE UNIQUE INDEX ux_users_name ON users (name);                          -- also a constraint\nCREATE INDEX idx_events_buy ON events (created_at) WHERE kind = ''buy'';      -- partial\nCREATE INDEX idx_emp_lower_name ON employees (lower(name));                 -- expression\n\nEXPLAIN QUERY PLAN SELECT event_id FROM events WHERE kind = ''buy'' AND created_at >= ''2024-03-25'';\nEXPLAIN QUERY PLAN SELECT * FROM employees WHERE lower(name) = ''sara'';","filename":"SQL"},"revision":1},{"id":"b6412463-f412-738e-b7ad-9e91f23b7630","type":"code","position":"aN","content":{"language":"text","code":"id | parent | notused | detail\n---+--------+---------+-----------------------------------------------------------------\n2  | 0      | 183     | SEARCH events USING COVERING INDEX idx_events_buy (created_at>?)\n\nid | parent | notused | detail\n---+--------+---------+-----------------------------------------------------------\n3  | 0      | 61      | SEARCH employees USING INDEX idx_emp_lower_name (<expr>=?)","filename":"Output"},"revision":1},{"id":"9fff5067-f234-7445-bab8-9c25008da065","type":"table","position":"aO","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Index type"}],[{"type":"text","text":"Good for"}],[{"type":"text","text":"Where"}]],[[{"type":"text","text":"B-tree"}],[{"type":"text","text":"Equality, ranges, sorting — the default"}],[{"type":"text","text":"All"}]],[[{"type":"text","text":"Hash"}],[{"type":"text","text":"Equality only"}],[{"type":"text","text":"PostgreSQL, MySQL MEMORY"}]],[[{"type":"text","text":"GIN / full-text"}],[{"type":"text","text":"Arrays, JSONB, text search"}],[{"type":"text","text":"PostgreSQL, MySQL "},{"type":"text","text":"FULLTEXT","marks":[{"type":"code"}]},{"type":"text","text":", SQLite FTS5"}]],[[{"type":"text","text":"GiST / R-tree / spatial"}],[{"type":"text","text":"Geometry, ranges, nearest neighbour"}],[{"type":"text","text":"PostgreSQL, MySQL, SQLite R*Tree"}]],[[{"type":"text","text":"BRIN"}],[{"type":"text","text":"Huge, naturally ordered tables (time series)"}],[{"type":"text","text":"PostgreSQL"}]],[[{"type":"text","text":"Bitmap"}],[{"type":"text","text":"Low-cardinality columns in warehouses"}],[{"type":"text","text":"Oracle"}]]]},"revision":1},{"id":"0b50565c-2d54-74e5-8f24-ea3dbf7f0101","type":"heading","position":"aP","content":{"level":1,"content":[{"type":"text","text":"Clustered vs non-clustered"}]},"revision":1},{"id":"79426f13-76e6-7f41-9d13-752a93e6efc5","type":"callout","position":"aQ","content":{"variant":"note","title":"Clustered index","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The table rows themselves are stored in index order — one per table. InnoDB and SQL Server cluster on the primary key; SQLite tables are clustered on "},{"type":"text","text":"rowid","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"5df7b34c-89a0-7009-9cd1-c6c13e739fdf","type":"callout","position":"aR","content":{"variant":"note","title":"Non-clustered (secondary)","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A separate structure of key + pointer (row id or primary key) back to the table. Many per table; a lookup may need an extra hop to fetch the row."}]}]}},"revision":1},{"id":"6a2abfd7-f0a5-73ad-a23a-dc4621672a3a","type":"heading","position":"aS","content":{"level":1,"content":[{"type":"text","text":"The cost side"}]},"revision":1},{"id":"7b9d48e2-34d1-7f78-ab3a-e4ba76cf56bd","type":"text","position":"aT","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Every "},{"type":"text","text":"INSERT","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"DELETE","marks":[{"type":"code"}]},{"type":"text","text":" and indexed-column "},{"type":"text","text":"UPDATE","marks":[{"type":"code"}]},{"type":"text","text":" must update every index — write-heavy tables should have few."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Indexes take disk and memory (buffer cache)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Low-selectivity columns ("},{"type":"text","text":"status","marks":[{"type":"code"}]},{"type":"text","text":" with 4 values, booleans) rarely benefit alone — the planner prefers a scan when a large fraction of rows match."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Unused and duplicate indexes ("},{"type":"text","text":"(a)","marks":[{"type":"code"}]},{"type":"text","text":" next to "},{"type":"text","text":"(a, b)","marks":[{"type":"code"}]},{"type":"text","text":") are pure cost; drop them."}]}]}]}]}},"revision":1},{"id":"20346ef5-e4ad-7b4b-a0ac-4ff3050b5a25","type":"question","position":"aU","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How does an index speed up a query?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"It keeps column values sorted in a B-tree with pointers to rows, so the engine can binary-search to the matching keys in O(log n) page reads instead of scanning all rows, and can return rows already sorted for "},{"type":"text","text":"ORDER BY","marks":[{"type":"code"}]},{"type":"text","text":". The price is extra storage and slower writes."}]}]}},"revision":1},{"id":"d388e1b6-6973-7b65-9ec6-ae23fea6ba9c","type":"question","position":"aV","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why might a query not use an index?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The predicate doesn''t match the index (function on the column, leading wildcard, implicit type conversion, not the leftmost column of a composite index), "},{"type":"text","text":"OR","marks":[{"type":"code"}]},{"type":"text","text":" across different columns, low selectivity so a scan is cheaper, stale statistics, or a tiny table."}]}]}},"revision":1},{"id":"406f3ac0-7f77-749b-b69e-ea6b5e06c563","type":"question","position":"aW","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Clustered vs non-clustered index?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A clustered index defines the physical order of the table''s rows (only one per table, usually the primary key). A non-clustered index is a separate structure with keys and row locators; a table can have many."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
