  ('a3c13bbf-a0e8-7e0f-ba73-4eb50e8eb57a', 'a0', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An index is a separate, sorted structure that lets the database find rows without scanning the whole table — like the index at the back of a book. It speeds reads and slows writes."}]}]}}'),
  ('4f6f0c66-28ed-7147-82eb-4443f8c4ce0e', 'a1', 'heading', '{"level":1,"content":[{"type":"text","text":"B-tree: the default index"}]}'),
  ('19f7d5ab-968b-7c77-af33-fa931802d97e', 'a2', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A B-tree (B+tree) keeps keys sorted in a shallow, balanced tree: a lookup touches ~3–4 pages even for millions of rows (O(log n)), and because keys are sorted it also serves ranges, prefixes and "},{"type":"text","text":"ORDER BY","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
  ('f068a19e-adb9-75e0-bbcf-f242a8f01a9a', 'a3', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Query shape"}],[{"type":"text","text":"Can a B-tree on "},{"type":"text","text":"col","marks":[{"type":"code"}]},{"type":"text","text":" help?"}]],[[{"type":"text","text":"col = 5","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"col IN (…)","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes — seek"}]],[[{"type":"text","text":"col > 5","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"BETWEEN","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"LIKE ''abc%''","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes — range scan"}]],[[{"type":"text","text":"ORDER BY col","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"MIN/MAX(col)","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes — already sorted"}]],[[{"type":"text","text":"LIKE ''%abc''","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"lower(col) = …","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"col + 1 = 6","marks":[{"type":"code"}]}],[{"type":"text","text":"No — needs a full scan (or an expression index)"}]]]}'),
  ('d84f3672-ceb5-76b8-b31c-09ea510d3129', 'a4', 'heading', '{"level":1,"content":[{"type":"text","text":"Reading a query plan"}]}'),
  ('dc670853-9461-7737-8d56-9370795d234e', 'a5', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"EXPLAIN QUERY PLAN","marks":[{"type":"code"}]},{"type":"text","text":" (SQLite) shows how a query will run; read the "},{"type":"text","text":"detail","marks":[{"type":"code"}]},{"type":"text","text":" column. "},{"type":"text","text":"SCAN","marks":[{"type":"bold"}]},{"type":"text","text":" = read every row; "},{"type":"text","text":"SEARCH … USING INDEX","marks":[{"type":"bold"}]},{"type":"text","text":" = jump straight to matching rows."}]}]}}'),
