  ('24b8bc64-1b8e-7c7e-a7cd-5946bfeb1fd5', 'aA', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Engine"}],[{"type":"text","text":"Show the plan"}],[{"type":"text","text":"Run and measure"}]],[[{"type":"text","text":"SQLite"}],[{"type":"text","text":"EXPLAIN QUERY PLAN …","marks":[{"type":"code"}]}],[{"type":"text","text":".timer on","marks":[{"type":"code"}]},{"type":"text","text":" in the shell"}]],[[{"type":"text","text":"PostgreSQL"}],[{"type":"text","text":"EXPLAIN …","marks":[{"type":"code"}]}],[{"type":"text","text":"EXPLAIN (ANALYZE, BUFFERS) …","marks":[{"type":"code"}]}]],[[{"type":"text","text":"MySQL"}],[{"type":"text","text":"EXPLAIN …","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"EXPLAIN FORMAT=TREE","marks":[{"type":"code"}]}],[{"type":"text","text":"EXPLAIN ANALYZE …","marks":[{"type":"code"}]}]],[[{"type":"text","text":"SQL Server"}],[{"type":"text","text":"Estimated plan (Ctrl+L)"}],[{"type":"text","text":"Actual plan, "},{"type":"text","text":"SET STATISTICS IO ON","marks":[{"type":"code"}]}]]]}'),
