SELECT '23449505-3299-70f4-a196-5403b607ad6e', 'e09145be-e486-7236-9d7c-1d96f0233570', 1, 'PUBLISHED', 'INSERT', '[{"id":"bcbf3474-1d8c-7120-9a9e-1e1c38f4a935","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"INSERT","marks":[{"type":"code"}]},{"type":"text","text":" adds rows — one at a time, many at once, or straight from a query."}]}]}},"revision":1},{"id":"5ea6fb90-2260-7bcb-ae13-0a5e30047d7d","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Basic forms"}]},"revision":1},{"id":"fac35828-5546-73ee-89f1-dc7b95a685dc","type":"code","position":"a2","content":{"language":"sql","code":"-- always name the columns: robust to column order and future new columns\nINSERT INTO customers (customer_id, name, city, signup_date)\nVALUES (6, ''Farhan'', ''Pune'', ''2024-04-02'');\n\n-- several rows in one statement (one round trip, one transaction)\nINSERT INTO customers (customer_id, name, city, signup_date) VALUES\n    (7, ''Divya'', ''Chennai'', ''2024-04-05''),\n    (8, ''Gautam'', NULL,     ''2024-04-07'');\n\nSELECT * FROM customers WHERE customer_id >= 6 ORDER BY customer_id;","filename":"SQL"},"revision":1},{"id":"35aaaf44-e341-7690-8a09-33a634fd9a99","type":"code","position":"a3","content":{"language":"text","code":"customer_id | name   | city    | signup_date\n------------+--------+---------+------------\n6           | Farhan | Pune    | 2024-04-02\n7           | Divya  | Chennai | 2024-04-05\n8           | Gautam | NULL    | 2024-04-07","filename":"Output"},"revision":1},{"id":"d96cc328-d2b3-7572-aacf-d59441f3f85a","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Auto-generated keys and DEFAULTs"}]},"revision":1},{"id":"c52c7d57-9770-7e7b-9f3a-046d172181b9","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Omit the key column and the database generates it. In SQLite an "},{"type":"text","text":"INTEGER PRIMARY KEY","marks":[{"type":"code"}]},{"type":"text","text":" auto-assigns "},{"type":"text","text":"max + 1","marks":[{"type":"italic"}]},{"type":"text","text":"; "},{"type":"text","text":"RETURNING","marks":[{"type":"code"}]},{"type":"text","text":" hands back the generated values without a second query."}]}]}},"revision":1},{"id":"97f11fe5-ad42-720b-8e79-c24783152b19","type":"code","position":"a6","content":{"language":"sql","code":"INSERT INTO products (name, category, price)\nVALUES (''Keyboard'', ''Electronics'', 1800)\nRETURNING product_id, name;","filename":"SQL"},"revision":1},{"id":"63e26218-759a-7880-b273-7f05bc80391a","type":"code","position":"a7","content":{"language":"text","code":"product_id | name\n-----------+---------\n8          | Keyboard","filename":"Output"},"revision":1},{"id":"18c42b6e-7019-7455-998c-4b4d56d8360a","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Engine"}],[{"type":"text","text":"Get the new id"}]],[[{"type":"text","text":"PostgreSQL, SQLite 3.35+"}],[{"type":"text","text":"INSERT … RETURNING id","marks":[{"type":"code"}]}]],[[{"type":"text","text":"SQL Server"}],[{"type":"text","text":"INSERT … OUTPUT inserted.id VALUES …","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"SCOPE_IDENTITY()","marks":[{"type":"code"}]}]],[[{"type":"text","text":"MySQL"}],[{"type":"text","text":"SELECT LAST_INSERT_ID()","marks":[{"type":"code"}]},{"type":"text","text":" after the insert"}]],[[{"type":"text","text":"Oracle"}],[{"type":"text","text":"RETURNING id INTO :v","marks":[{"type":"code"}]},{"type":"text","text":" (PL/SQL)"}]]]},"revision":1},{"id":"732f2170-1788-7100-b6c2-a4c34515e047","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"INSERT … SELECT"}]},"revision":1},{"id":"330e9478-24f2-7dd6-b819-4c909c9a031e","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Copy rows produced by any query — no "},{"type":"text","text":"VALUES","marks":[{"type":"code"}]},{"type":"text","text":" keyword."}]}]}},"revision":1},{"id":"8e71fb47-d436-76b9-84f9-2e3683f81409","type":"code","position":"aB","content":{"language":"sql","code":"CREATE TABLE vip_customers (customer_id INTEGER PRIMARY KEY, name TEXT, total_spent INTEGER);\n\nINSERT INTO vip_customers (customer_id, name, total_spent)\nSELECT c.customer_id, c.name, SUM(oi.quantity * oi.unit_price)\nFROM customers c\nJOIN orders o       ON o.customer_id = c.customer_id\nJOIN order_items oi ON oi.order_id   = o.order_id\nWHERE o.status <> ''cancelled''\nGROUP BY c.customer_id, c.name\nHAVING SUM(oi.quantity * oi.unit_price) > 50000;\n\nSELECT * FROM vip_customers ORDER BY total_spent DESC;","filename":"SQL"},"revision":1},{"id":"94bc4364-1726-77bb-b33a-ee42cd525ad1","type":"code","position":"aC","content":{"language":"text","code":"customer_id | name   | total_spent\n------------+--------+------------\n1           | Ananya | 68400\n2           | Rahul  | 61200","filename":"Output"},"revision":1},{"id":"12b7f710-58d7-7b3e-988c-559f265bd9a2","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Skipping rows that would violate a constraint"}]},"revision":1},{"id":"36429015-0bcb-7e94-8d88-1ad1b7c87ca2","type":"code","position":"aE","content":{"language":"sql","code":"INSERT OR IGNORE INTO departments (dept_id, name, location)\nVALUES (1, ''Engineering'', ''Bengaluru''), (5, ''Finance'', ''Delhi'');\n\nSELECT * FROM departments ORDER BY dept_id;","filename":"SQLite"},"revision":1},{"id":"7a88bf05-338d-7ba5-a859-1df8c311c27d","type":"code","position":"aF","content":{"language":"text","code":"dept_id | name        | location\n--------+-------------+----------\n1       | Engineering | Bengaluru\n2       | Sales       | Mumbai\n3       | HR          | Hyderabad\n4       | Marketing   | Pune\n5       | Finance     | Delhi","filename":"Output"},"revision":1},{"id":"84ad44b5-dc28-7061-98ef-98e2c8863236","type":"code","position":"aG","content":{"language":"sql","code":"INSERT IGNORE INTO departments (dept_id, name, location) VALUES (5, ''Finance'', ''Delhi'');          -- MySQL\nINSERT INTO departments (dept_id, name, location) VALUES (5, ''Finance'', ''Delhi'')\nON CONFLICT DO NOTHING;                                                                     -- PostgreSQL","filename":"MySQL / PostgreSQL"},"revision":1},{"id":"b972de11-fbba-7dec-85f5-88e6f8854d40","type":"callout","position":"aH","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"INSERT INTO t VALUES (…)","marks":[{"type":"code"}]},{"type":"text","text":" without a column list depends on the physical column order — it breaks (or silently puts values in the wrong columns) after an "},{"type":"text","text":"ALTER TABLE","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"a8e9b0c7-e8de-7058-9747-a858ca5ee104","type":"callout","position":"aI","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Batch inserts: one multi-row "},{"type":"text","text":"INSERT","marks":[{"type":"code"}]},{"type":"text","text":" (or many inserts inside one transaction) is often 10–100× faster than autocommitting each row separately."}]}]}},"revision":1},{"id":"a7e35efb-1375-7c01-8a84-a8ebd87af6ab","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you insert data from one table into another?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"INSERT INTO target (cols…) SELECT cols… FROM source WHERE …;","marks":[{"type":"code"}]},{"type":"text","text":" — the column counts and types must line up. To create the target at the same time use "},{"type":"text","text":"CREATE TABLE t AS SELECT …","marks":[{"type":"code"}]},{"type":"text","text":" (or "},{"type":"text","text":"SELECT … INTO t","marks":[{"type":"code"}]},{"type":"text","text":" in SQL Server)."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
