INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '223d239b-526e-76f3-a8b0-0d4a8f56ad59', 'd4100a17-1457-70ff-9a45-b62073e0ed92', 1, 'PUBLISHED', 'Isolation Levels & Anomalies', '[{"id":"e07fa77a-fc1d-71c1-9670-72578db2c1a4","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Full isolation is expensive, so SQL defines four levels that trade correctness for concurrency. Each level forbids a different set of "},{"type":"text","text":"anomalies","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"0c313a45-e88c-7c1e-a0c4-fae1949432b4","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The anomalies"}]},"revision":1},{"id":"aac04e47-871d-756e-940f-cfdcd55fa741","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Anomaly"}],[{"type":"text","text":"What happens"}],[{"type":"text","text":"Example"}]],[[{"type":"text","text":"Dirty read","marks":[{"type":"bold"}]}],[{"type":"text","text":"T2 reads data T1 has written but not committed"}],[{"type":"text","text":"T1 debits 200, T2 reads 800, T1 rolls back — T2 used a value that never existed"}]],[[{"type":"text","text":"Non-repeatable read","marks":[{"type":"bold"}]}],[{"type":"text","text":"T1 reads a row twice and gets different values because T2 committed an update in between"}],[{"type":"text","text":"Balance 1000, then 800 in the same report"}]],[[{"type":"text","text":"Phantom read","marks":[{"type":"bold"}]}],[{"type":"text","text":"T1 re-runs a range query and sees new/removed rows committed by T2"}],[{"type":"text","text":"COUNT(*) WHERE dept_id = 1","marks":[{"type":"code"}]},{"type":"text","text":" is 4, then 5"}]],[[{"type":"text","text":"Lost update","marks":[{"type":"bold"}]}],[{"type":"text","text":"T1 and T2 both read 1000, both write back their own result — one update disappears"}],[{"type":"text","text":"Two withdrawals of 100 leave 900 instead of 800"}]],[[{"type":"text","text":"Write skew","marks":[{"type":"bold"}]}],[{"type":"text","text":"Two transactions each check a condition, then write different rows, together breaking the rule"}],[{"type":"text","text":"Two on-call doctors each go off duty because “the other is on call”"}]]]},"revision":1},{"id":"48ffa2f7-8308-7d72-a312-d98f4d13d5b3","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"The four standard levels"}]},"revision":1},{"id":"f4b2b46a-3432-7a95-a4d9-5addc445dde0","type":"table","position":"a4","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Level"}],[{"type":"text","text":"Dirty read"}],[{"type":"text","text":"Non-repeatable read"}],[{"type":"text","text":"Phantom"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"READ UNCOMMITTED","marks":[{"type":"code"}]}],[{"type":"text","text":"Possible"}],[{"type":"text","text":"Possible"}],[{"type":"text","text":"Possible"}],[{"type":"text","text":"Rarely used; PostgreSQL treats it as Read Committed"}]],[[{"type":"text","text":"READ COMMITTED","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"Possible"}],[{"type":"text","text":"Possible"}],[{"type":"text","text":"Default","marks":[{"type":"bold"}]},{"type":"text","text":" in PostgreSQL, SQL Server, Oracle"}]],[[{"type":"text","text":"REPEATABLE READ","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}],[{"type":"text","text":"Possible (standard) — prevented by snapshots in PostgreSQL/MySQL"}],[{"type":"text","text":"Default","marks":[{"type":"bold"}]},{"type":"text","text":" in MySQL InnoDB"}]],[[{"type":"text","text":"SERIALIZABLE","marks":[{"type":"code"}]}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}],[{"type":"text","text":"No"}],[{"type":"text","text":"As if transactions ran one at a time; may abort with serialization errors — retry"}]]]},"revision":1},{"id":"d3604691-9268-7109-bcb9-32089e5b7553","type":"code","position":"a5","content":{"language":"sql","code":"SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;     -- SQL Server / MySQL (next transaction)\nBEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;      -- PostgreSQL","filename":"PostgreSQL / MySQL / SQL Server"},"revision":1},{"id":"cd861d63-a6f0-7f3b-88cf-8a533e1b1e62","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Seeing it: two sessions on one SQLite file"}]},"revision":1},{"id":"4f8a7d06-074f-74d1-9c2c-789cecba7750","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SQLite in WAL mode gives each reading transaction a "},{"type":"text","text":"snapshot","marks":[{"type":"bold"}]},{"type":"text","text":" (like Repeatable Read/Serializable) and allows one writer at a time. Two connections play two users:"}]}]}},"revision":1},{"id":"af92c9f3-c81b-79ff-9df0-be6e4e4ba9ff","type":"code","position":"a8","content":{"language":"python","code":"import os, sqlite3, tempfile\n\npath = os.path.join(tempfile.mkdtemp(), \"bank.db\")\nwith sqlite3.connect(path) as db:\n    db.execute(\"PRAGMA journal_mode = WAL\")\n    db.executescript(\"CREATE TABLE accounts (id INTEGER PRIMARY KEY, balance INTEGER);\"\n                     \"INSERT INTO accounts VALUES (1, 1000);\")\n\na = sqlite3.connect(path, isolation_level=None, timeout=0)   # session A\nb = sqlite3.connect(path, isolation_level=None, timeout=0)   # session B\nread = lambda s: s.execute(\"SELECT balance FROM accounts WHERE id = 1\").fetchone()[0]\n\nb.execute(\"BEGIN\")                  # B starts a read transaction…\nprint(\"B first read:\", read(b))     # B first read: 1000\n\na.execute(\"BEGIN IMMEDIATE\")        # A takes the write lock\na.execute(\"UPDATE accounts SET balance = balance - 200 WHERE id = 1\")\nprint(\"A sees its change:\", read(a))       # A sees its change: 800\nprint(\"B, A uncommitted:\", read(b))        # B, A uncommitted: 1000   ← no dirty read\na.execute(\"COMMIT\")\n\nprint(\"B, A committed:\", read(b))          # B, A committed: 1000     ← same snapshot: repeatable read\nb.execute(\"COMMIT\")\nprint(\"B, new transaction:\", read(b))      # B, new transaction: 800","filename":"Python + SQLite — isolation"},"revision":1},{"id":"e811be9f-75ec-7055-9f90-272070991127","type":"callout","position":"a9","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Under "},{"type":"text","text":"READ COMMITTED","marks":[{"type":"code"}]},{"type":"text","text":" (PostgreSQL''s default), B''s third read would already return 800 — each "},{"type":"text","text":"statement","marks":[{"type":"italic"}]},{"type":"text","text":" sees the latest committed data. That''s the non-repeatable read the level allows."}]}]}},"revision":1},{"id":"4a6b2c9e-8b93-748e-8ff5-4fe97de4b398","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"Preventing lost updates"}]},"revision":1},{"id":"2269b13d-8ef2-7aa8-b3c3-88505689c173","type":"callout","position":"aB","content":{"variant":"note","title":"Atomic update","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"UPDATE accounts SET balance = balance - 100 WHERE id = 1","marks":[{"type":"code"}]},{"type":"text","text":" — read-modify-write happens inside one statement. Best when possible."}]}]}},"revision":1},{"id":"168daaf0-bcc0-7921-8e72-0c20caa1bc21","type":"callout","position":"aC","content":{"variant":"note","title":"Pessimistic lock","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SELECT … FOR UPDATE","marks":[{"type":"code"}]},{"type":"text","text":" locks the row until commit, so the second transaction waits."}]}]}},"revision":1},{"id":"6fb7514e-95ff-7535-97be-909f7ad04127","type":"callout","position":"aD","content":{"variant":"note","title":"Optimistic check","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"UPDATE … SET balance = :new, version = version + 1 WHERE id = 1 AND version = :read_version","marks":[{"type":"code"}]},{"type":"text","text":" — 0 rows updated means someone else won; retry."}]}]}},"revision":1},{"id":"8f6fea84-7d62-791f-9ca4-815988f534d2","type":"callout","position":"aE","content":{"variant":"note","title":"Serializable","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Let the database detect the conflict and abort one transaction; the app retries."}]}]}},"revision":1},{"id":"093388ce-592e-7a6a-970f-79f760a64d74","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What isolation level would you use?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Usually the engine default (Read Committed in PostgreSQL/SQL Server/Oracle, Repeatable Read in MySQL) combined with atomic updates or "},{"type":"text","text":"SELECT … FOR UPDATE","marks":[{"type":"code"}]},{"type":"text","text":" for read-modify-write. Use "},{"type":"text","text":"SERIALIZABLE","marks":[{"type":"code"}]},{"type":"text","text":" for complex invariants spanning several rows (write skew) and be ready to retry on serialization failures."}]}]}},"revision":1},{"id":"0ca20d33-5b9a-7002-8f07-2ff2d669b3b3","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a phantom read?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Re-running the same range query in one transaction returns a different "},{"type":"text","text":"set","marks":[{"type":"italic"}]},{"type":"text","text":" of rows because another transaction committed an insert or delete in that range. Non-repeatable reads are about changed values of existing rows; phantoms are about rows appearing or disappearing."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
