SELECT '72ba259d-7ebb-77ea-a7e6-c3d6421c180e', 'e35991ae-6e91-77ef-8b01-769cfe27f75e', 1, 'PUBLISHED', 'JSON in SQL', '[{"id":"f7b97b4c-d554-7392-b8ba-502098c62445","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Modern engines store and query JSON documents inside relational tables — useful for flexible attributes, event payloads and API data, alongside normal columns."}]}]}},"revision":1},{"id":"bc0815ac-1b51-7482-acaf-bd60c42a2fb8","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Extracting values"}]},"revision":1},{"id":"f7c3e022-fa93-78fb-8e05-932722872f4e","type":"code","position":"a2","content":{"language":"sql","code":"CREATE TABLE app_events (\n    id      INTEGER PRIMARY KEY,\n    payload TEXT CHECK (json_valid(payload))\n);\nINSERT INTO app_events (payload) VALUES\n    (''{\"user\": {\"id\": 7, \"name\": \"Asha\"}, \"action\": \"login\",    \"tags\": [\"web\", \"mobile\"]}''),\n    (''{\"user\": {\"id\": 9, \"name\": \"Ravi\"}, \"action\": \"purchase\", \"amount\": 2500, \"tags\": [\"web\"]}''),\n    (''{\"user\": {\"id\": 7, \"name\": \"Asha\"}, \"action\": \"purchase\", \"amount\": 800}'');\n\nSELECT id,\n       payload ->> ''$.user.name''           AS user_name,\n       json_extract(payload, ''$.action'')   AS action,\n       payload ->> ''$.amount''              AS amount,\n       json_array_length(payload, ''$.tags'') AS tag_count\nFROM app_events\nORDER BY id;","filename":"SQL"},"revision":1},{"id":"c785ba4d-2693-7b7f-a784-d18e8902bc80","type":"code","position":"a3","content":{"language":"text","code":"id | user_name | action   | amount | tag_count\n---+-----------+----------+--------+----------\n1  | Asha      | login    | NULL   | 2\n2  | Ravi      | purchase | 2500   | 1\n3  | Asha      | purchase | 800    | NULL","filename":"Output"},"revision":1},{"id":"4300c6f0-c0eb-77ea-8108-a0aaa3d4944b","type":"text","position":"a4","content"