SELECT 'f851ad11-70c2-72fc-b0b0-6a8309b1941d', '758f3acf-4348-7573-a6ad-1185f5841fc2', 1, 'PUBLISHED', 'LAG, LEAD & Value Functions', '[{"id":"528d8337-1fc7-7c76-8d9b-fb4d8d608626","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"LAG","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"LEAD","marks":[{"type":"code"}]},{"type":"text","text":" read a value from a previous or following row of the same window — day-over-day changes, gaps between events and “next step” analysis without a self join."}]}]}},"revision":1},{"id":"85fdf248-f7b2-784f-80d3-14ee8e5b68f1","type":"code","position":"a1","content":{"language":"sql","code":"SELECT day, amount,\n       LAG(amount)       OVER (ORDER BY day) AS prev_day,\n       LEAD(amount)      OVER (ORDER BY day) AS next_day,\n       amount - LAG(amount) OVER (ORDER BY day) AS change,\n       LAG(amount, 2, 0) OVER (ORDER BY day) AS two_days_ago\nFROM daily_sales\nORDER BY day;","filename":"SQL"},"revision":1},{"id":"819330b6-e0f4-7819-9487-08dd318a0f7c","type":"code","position":"a2","content":{"language":"text","code":"day        | amount | prev_day | next_day | change | two_days_ago\n-----------+--------+----------+----------+--------+-------------\n2024-03-01 | 120    | NULL     | 80       | NULL   | 0\n2024-03-02 | 80     | 120      | 150      | -40    | 0\n2024-03-03 | 150    | 80       | 90       | 70     | 120\n2024-03-04 | 90     | 150      | 200      | -60    | 80\n2024-03-05 | 200    | 90       | 60       | 110    | 150\n2024-03-06 | 60     | 200      | NULL     | -140   | 90","filename":"Output"},"revision":1},{"id":"1968463f-526d-757b-8d66-011d02fad227","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Signature: "},{"type":"text","text":"LAG(expr, offset = 1, default = NULL)","marks":[{"type":"code"}]},{"type":"text","text":". The first row has no previous row, so it gets the default."}]}]}},"revision":1},{"id":"760c647c-2dd0-7d4e-a248-a9f03b5f60c7","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Growth in percent"}]},"revision":1},{"id":"d34db488-b18d-75a2-99e4-30ff0a47746d","type":"code","position":"a5","content":{"language":"sql","code":"WITH monthly AS (\n    SELECT strftime(''%Y-%m'', o.order_date) AS month,\n           SUM(oi.quantity * oi.unit_price) AS revenue\n    FROM orders o JOIN order_items oi ON oi.order_id = o.order_id\n    WHERE o.status <> ''cancelled''\n    GROUP BY month\n)\nSELECT month, revenue,\n       LAG(revenue) OVER (ORDER BY month) AS prev,\n       ROUND(100.0 * (revenue - LAG(revenue) OVER (ORDER BY month))\n             / LAG(revenue) OVER (ORDER BY month), 1) AS growth_pct\nFROM monthly\nORDER BY month;","filename":"SQL"},"revision":1},{"id":"585e6707-83ec-7154-826c-412d559ea485","type":"code","position":"a6","content":{"language":"text","code":"month   | revenue | prev  | growth_pct\n--------+---------+-------+-----------\n2024-01 | 66700   | NULL  | NULL\n2024-02 | 12900   | 66700 | -80.7\n2024-03 | 63700   | 12900 | 393.8","filename":"Output"},"revision":1},{"id":"acae83f9-c956-7f91-aeb8-8359057eaac6","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"Per group: time between a customer''s orders"}]},"revision":1},{"id":"920605db-8bc9-7bc6-a8d1-2513d039cc34","type":"code","position":"a8","content":{"language":"sql","code":"SELECT customer_id, order_id, order_date,\n       LAG(order_date) OVER w AS previous_order,\n       julianday(order_date) - julianday(LAG(order_date) OVER w) AS days_since\nFROM orders\nWINDOW w AS (PARTITION BY customer_id ORDER BY order_date)\nORDER BY customer_id, order_date;","filename":"SQL"},"revision":1},{"id":"aba144f0-71d1-7471-a1e7-5dce754d8e0e","type":"code","position":"a9","content":{"language":"text","code":"customer_id | order_id | order_date | previous_order | days_since\n------------+----------+------------+----------------+-----------\n1           | 101      | 2024-01-05 | NULL           | NULL\n1           | 103      | 2024-02-03 | 2024-01-05     | 29.0\n1           | 108      | 2024-03-15 | 2024-02-03     | 41.0\n2           | 102      | 2024-01-12 | NULL           | NULL\n2           | 106      | 2024-03-01 | 2024-01-12     | 49.0\n3           | 104      | 2024-02-14 | NULL           | NULL\n3           | 107      | 2024-03-08 | 2024-02-14     | 23.0\n4           | 105      | 2024-02-20 | NULL           | NULL","filename":"Output"},"revision":1},{"id":"01178ca9-c87b-7757-a1d1-20f6e1c74d1c","type":"callout","position":"aA","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"WINDOW w AS (…)","marks":[{"type":"code"}]},{"type":"text","text":" names a window once and reuses it (standard SQL; PostgreSQL, MySQL 8, SQLite — not SQL Server before 2022)."}]}]}},"revision":1},{"id":"2714be25-0f90-7d91-a6e4-8761d1b61035","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"FIRST_VALUE, LAST_VALUE, NTH_VALUE"}]},"revision":1},{"id":"2efe721a-a5e1-75b0-adc4-cdd44245eb1a","type":"code","position":"aC","content":{"language":"sql","code":"SELECT name, dept_id, salary,\n       FIRST_VALUE(name) OVER (PARTITION BY dept_id ORDER BY salary DESC) AS top_earner,\n       LAST_VALUE(name)  OVER (PARTITION BY dept_id ORDER BY salary DESC) AS last_value_default,\n       LAST_VALUE(name)  OVER (PARTITION BY dept_id ORDER BY salary DESC\n                               ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS lowest_earner\nFROM employees\nWHERE dept_id = 2\nORDER BY salary DESC;","filename":"SQL"},"revision":1},{"id":"5556e820-2b2b-72cd-a595-e273c24c2e9c","type":"code","position":"aD","content":{"language":"text","code":"name  | dept_id | salary | top_earner | last_value_default | lowest_earner\n------+---------+--------+------------+--------------------+--------------\nPriya | 2       | 110000 | Priya      | Priya              | Arjun\nNeha  | 2       | 72000  | Priya      | Neha               | Arjun\nArjun | 2       | 70000  | Priya      | Arjun              | Arjun","filename":"Output"},"revision":1},{"id":"2e2a35a7-0e5b-720b-82d0-7517ec4e0518","type":"callout","position":"aE","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"LAST_VALUE","marks":[{"type":"code"}]},{"type":"text","text":" with the default frame returns the "},{"type":"text","text":"current","marks":[{"type":"bold"}]},{"type":"text","text":" row (the frame ends at the current row), not the last row of the partition. Specify "},{"type":"text","text":"ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING","marks":[{"type":"code"}]},{"type":"text","text":", or use "},{"type":"text","text":"FIRST_VALUE","marks":[{"type":"code"}]},{"type":"text","text":" with the opposite sort."}]}]}},"revision":1},{"id":"8ef52d4d-f97c-726c-943c-a84d9f6de5cf","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you compute the difference between the current row and the previous row?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"value - LAG(value) OVER (PARTITION BY group ORDER BY time)","marks":[{"type":"code"}]},{"type":"text","text":". Before window functions this needed a self join on “the previous row”, which is slower and harder to write."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
