SELECT 'eeba6bff-c0bd-7c72-aa39-35f9ad0c6833', '089d38c1-8413-7f74-acee-3431fe5376b0', 1, 'PUBLISHED', 'LIMIT, OFFSET & Pagination', '[{"id":"e5c303d5-ac52-744f-b8aa-c7969b24b7fa","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"LIMIT","marks":[{"type":"code"}]},{"type":"text","text":" caps the number of rows returned; "},{"type":"text","text":"OFFSET","marks":[{"type":"code"}]},{"type":"text","text":" skips rows first. Together they page through results — but deep offsets get slow."}]}]}},"revision":1},{"id":"8b6e6410-092a-719c-9a3a-800733bba965","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Top-N"}]},"revision":1},{"id":"73087026-a922-7ba8-bf6a-baec9896813b","type":"code","position":"a2","content":{"language":"sql","code":"SELECT name, salary FROM employees\nORDER BY salary DESC, emp_id\nLIMIT 3;","filename":"SQL"},"revision":1},{"id":"781173ca-6473-7e27-9efc-da3f4372ace4","type":"code","position":"a3","content":{"language":"text","code":"name  | salary\n------+-------\nAsha  | 150000\nRavi  | 120000\nPriya | 110000","filename":"Output"},"revision":1},{"id":"ed7ad54f-5d93-70c7-bb42-1034b72cc7a3","type":"callout","position":"a4","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"LIMIT","marks":[{"type":"code"}]},{"type":"text","text":" without "},{"type":"text","text":"ORDER BY","marks":[{"type":"code"}]},{"type":"text","text":" returns an "},{"type":"text","text":"arbitrary","marks":[{"type":"italic"}]},{"type":"text","text":" 3 rows. And when the sort key has ties (Meera and Karan both 95000), add a unique tie-breaker ("},{"type":"text","text":"emp_id","marks":[{"type":"code"}]},{"type":"text","text":") so pages are stable."}]}]}},"revision":1},{"id":"8c8cfcba-7742-7d18-8e4f-45d093a6b91d","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Offset pagination"}]},"revision":1},{"id":"f8fd52f4-2cf6-7819-987c-b10c5e5db46b","type":"code","position":"a6","content":{"language":"sql","code":"-- page 2, page size 3 → OFFSET = (page - 1) * size\nSELECT emp_id, name FROM employees\nORDER BY emp_id\nLIMIT 3 OFFSET 3;","filename":"SQL"},"revision":1},{"id":"61574d73-306b-7384-ac5f-66c555d96fa7","type":"code","position":"a7","content":{"language":"text","code":"emp_id | name\n-------+------\n4      | Karan\n5      | Priya\n6      | Arjun","filename":"Output"},"revision":1},{"id":"eccd52aa-3f96-7bb8-ac87-ab38053139f9","type":"table","position":"a8","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Engine"}],[{"type":"text","text":"Page 2 of size 3"}]],[[{"type":"text","text":"SQLite, PostgreSQL, MySQL"}],[{"type":"text","text":"LIMIT 3 OFFSET 3","marks":[{"type":"code"}]},{"type":"text","text":" (MySQL also "},{"type":"text","text":"LIMIT 3, 3","marks":[{"type":"code"}]},{"type":"text","text":" — offset first!)"}]],[[{"type":"text","text":"SQL Server 2012+"}],[{"type":"text","text":"ORDER BY emp_id OFFSET 3 ROWS FETCH NEXT 3 ROWS ONLY","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Oracle 12c+ / standard"}],[{"type":"text","text":"OFFSET 3 ROWS FETCH NEXT 3 ROWS ONLY","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Old Oracle"}],[{"type":"text","text":"WHERE ROWNUM <= n","marks":[{"type":"code"}]},{"type":"text","text":" in a nested query"}]]]},"revision":1},{"id":"299e5cb5-0728-73af-bf82-f33e41d444c9","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Keyset (seek) pagination"}]},"revision":1},{"id":"85312511-d0b2-7b1a-942b-f98870e47129","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"OFFSET 100000","marks":[{"type":"code"}]},{"type":"text","text":" still reads and throws away 100 000 rows, and rows inserted between requests shift pages (duplicates / gaps). "},{"type":"text","text":"Keyset pagination","marks":[{"type":"bold"}]},{"type":"text","text":" remembers the last key seen and seeks past it using the index."}]}]}},"revision":1},{"id":"62d5b428-24d3-7c00-8d58-d09e92d55558","type":"code","position":"aB","content":{"language":"sql","code":"-- the client got page 1 ending at emp_id = 3; next page:\nSELECT emp_id, name FROM employees\nWHERE emp_id > 3\nORDER BY emp_id\nLIMIT 3;","filename":"SQL"},"revision":1},{"id":"5a85dea4-e53e-7105-a7a0-87f8da10a580","type":"code","position":"aC","content":{"language":"text","code":"emp_id | name\n-------+------\n4      | Karan\n5      | Priya\n6      | Arjun","filename":"Output"},"revision":1},{"id":"6fd46427-6ec4-7982-80ec-3f57c140dad9","type":"code","position":"aD","content":{"language":"sql","code":"-- sorted by a non-unique column: seek on (salary, emp_id) together; last row seen was Meera (95000, 3)\nSELECT emp_id, name, salary FROM employees\nWHERE (salary, emp_id) < (95000, 3)\nORDER BY salary DESC, emp_id DESC\nLIMIT 3;","filename":"SQL"},"revision":1},{"id":"19f7481c-99fe-7dbf-803f-2204a96fd7a6","type":"code","position":"aE","content":{"language":"text","code":"emp_id | name   | salary\n-------+--------+-------\n9      | Sara   | 85000\n8      | Vikram | 80000\n7      | Neha   | 72000","filename":"Output"},"revision":1},{"id":"4fa195f3-699c-7ae2-9193-dc8a8f1e314c","type":"callout","position":"aF","content":{"variant":"note","title":"Offset pagination","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Simple, allows jumping to page N. Cost grows with the offset; unstable when data changes."}]}]}},"revision":1},{"id":"9be49d17-b930-7907-bcda-1411102047f7","type":"callout","position":"aG","content":{"variant":"note","title":"Keyset pagination","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Constant speed on any page, stable under inserts. No random page jumps — ideal for infinite scroll and APIs ("},{"type":"text","text":"?after=…","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"f4dd56ae-7139-785f-965e-18cf1844c48d","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is OFFSET pagination slow for large page numbers?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The database must produce and discard every row before the offset — "},{"type":"text","text":"OFFSET 1000000","marks":[{"type":"code"}]},{"type":"text","text":" reads a million rows to return 20. Keyset pagination ("},{"type":"text","text":"WHERE key > :last ORDER BY key LIMIT 20","marks":[{"type":"code"}]},{"type":"text","text":") jumps straight to the starting point through the index."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
