  ('19f7481c-99fe-7dbf-803f-2204a96fd7a6', 'aE', 'code', '{"language":"text","code":"emp_id | name   | salary\n-------+--------+-------\n9      | Sara   | 85000\n8      | Vikram | 80000\n7      | Neha   | 72000","filename":"Output"}'),
  ('4fa195f3-699c-7ae2-9193-dc8a8f1e314c', 'aF', 'callout', '{"variant":"note","title":"Offset pagination","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Simple, allows jumping to page N. Cost grows with the offset; unstable when data changes."}]}]}}'),
