  ('f4dd56ae-7139-785f-965e-18cf1844c48d', 'aH', 'question', '{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why is OFFSET pagination slow for large page numbers?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The database must produce and discard every row before the offset — "},{"type":"text","text":"OFFSET 1000000","marks":[{"type":"code"}]},{"type":"text","text":" reads a million rows to return 20. Keyset pagination ("},{"type":"text","text":"WHERE key > :last ORDER BY key LIMIT 20","marks":[{"type":"code"}]},{"type":"text","text":") jumps straight to the starting point through the index."}]}]}}')
