SELECT 'a1a2394c-b29e-79ec-a252-86c5acf01bfa', '3d0211d9-62d1-7a6c-aa55-e7892a2abd7c', 1, 'PUBLISHED', 'Locking, MVCC & Deadlocks', '[{"id":"9f787fe1-dd34-710a-b504-853746c3ce3f","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Databases coordinate concurrent transactions with "},{"type":"text","text":"locks","marks":[{"type":"bold"}]},{"type":"text","text":" and, in most modern engines, "},{"type":"text","text":"MVCC","marks":[{"type":"bold"}]},{"type":"text","text":" (multi-version concurrency control), so readers and writers rarely block each other."}]}]}},"revision":1},{"id":"a3504e44-1f81-7385-8231-541d099d5580","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Lock types"}]},"revision":1},{"id":"29795beb-a5e4-7b36-9bee-7a1eae7d2b35","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Lock"}],[{"type":"text","text":"Taken by"}],[{"type":"text","text":"Compatible with"}]],[[{"type":"text","text":"Shared (S)"}],[{"type":"text","text":"Reads that need stability ("},{"type":"text","text":"FOR SHARE","marks":[{"type":"code"}]},{"type":"text","text":", lock-based engines)"}],[{"type":"text","text":"Other shared locks"}]],[[{"type":"text","text":"Exclusive (X)"}],[{"type":"text","text":"INSERT","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"UPDATE","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"DELETE","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"SELECT … FOR UPDATE","marks":[{"type":"code"}]}],[{"type":"text","text":"Nothing — others wait"}]],[[{"type":"text","text":"Intent (IS/IX)"}],[{"type":"text","text":"Table-level marker before row locks"}],[{"type":"text","text":"Lets the engine check table locks cheaply"}]]]},"revision":1},{"id":"00364aa7-18e9-7c7e-9a7b-fae455bfcfd9","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Granularity: "},{"type":"text","text":"row","marks":[{"type":"bold"}]},{"type":"text","text":" locks (InnoDB, PostgreSQL, SQL Server, Oracle) allow high concurrency; "},{"type":"text","text":"table/page","marks":[{"type":"bold"}]},{"type":"text","text":" locks are cheaper but block more; SQLite locks the "},{"type":"text","text":"whole database","marks":[{"type":"bold"}]},{"type":"text","text":" for writing."}]}]}},"revision":1},{"id":"814e4887-7683-7c49-87a8-e8c87ed93851","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"MVCC"}]},"revision":1},{"id":"7e8a9834-ae16-7845-a3b4-1885e041a196","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Instead of overwriting a row in place, an update creates a "},{"type":"text","text":"new version","marks":[{"type":"bold"}]},{"type":"text","text":". Each transaction reads the versions that were committed as of its snapshot. Result: "},{"type":"text","text":"readers don''t block writers and writers don''t block readers","marks":[{"type":"italic"}]},{"type":"text","text":"; only writer-vs-writer on the same row waits."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"PostgreSQL keeps old versions in the table (cleaned up by "},{"type":"text","text":"VACUUM","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"MySQL InnoDB and Oracle rebuild old versions from undo logs."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SQL Server uses locking by default; "},{"type":"text","text":"READ_COMMITTED_SNAPSHOT","marks":[{"type":"code"}]},{"type":"text","text":" switches reads to row versions."}]}]}]}]}},"revision":1},{"id":"7c7b6052-383c-76f1-bf7d-38fe5a1304fb","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"Explicit row locks"}]},"revision":1},{"id":"43450f85-ebaf-7807-8d45-0126f423d3ce","type":"code","position":"a7","content":{"language":"sql","code":"BEGIN;\nSELECT balance FROM accounts WHERE id = 1 FOR UPDATE;       -- lock the row; others'' FOR UPDATE waits\nUPDATE accounts SET balance = balance - 100 WHERE id = 1;\nCOMMIT;\n\n-- job queues: grab the next free job without waiting on rows others locked\nSELECT id FROM jobs WHERE status = ''new''\nORDER BY id LIMIT 1\nFOR UPDATE SKIP LOCKED;","filename":"PostgreSQL / MySQL 8 / Oracle"},"revision":1},{"id":"75734009-c5df-759d-883f-f973650b96ea","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Deadlocks"}]},"revision":1},{"id":"0fe5f683-a23d-70a2-ad2f-5c533a89796f","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"T1","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Locks account 1 ("},{"type":"text","text":"UPDATE … WHERE id = 1","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"T2","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Locks account 2 ("},{"type":"text","text":"UPDATE … WHERE id = 2","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"T1","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Wants account 2 → waits for T2."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"T2","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Wants account 1 → waits for T1. Neither can proceed."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Database","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Detects the cycle and aborts one transaction (the "},{"type":"text","text":"victim","marks":[{"type":"italic"}]},{"type":"text","text":") with a deadlock error; the other continues."}]}]}]}]}},"revision":1},{"id":"d36aa8f4-3816-7432-a24b-c9910044fa6b","type":"callout","position":"aA","content":{"variant":"tip","title":"Do","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Access rows in a consistent order (e.g. always the lower account id first), keep transactions short, index the columns in "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" so fewer rows are locked, and retry on deadlock errors."}]}]}},"revision":1},{"id":"4d1163d1-9f00-740f-a823-6eb2777193bb","type":"callout","position":"aB","content":{"variant":"danger","title":"Avoid","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Hold a transaction open while waiting for user input or a slow API call."}]}]}},"revision":1},{"id":"d421f083-4299-7a87-8317-728767616697","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"SQLite: one writer at a time"}]},"revision":1},{"id":"57660a8a-e306-725e-a6b8-3bb1e7cbf5ef","type":"code","position":"aD","content":{"language":"python","code":"import os, sqlite3, tempfile\n\npath = os.path.join(tempfile.mkdtemp(), \"shop.db\")\nwith sqlite3.connect(path) as db:\n    db.execute(\"PRAGMA journal_mode = WAL\")\n    db.execute(\"CREATE TABLE stock (sku TEXT PRIMARY KEY, qty INTEGER)\")\n    db.execute(\"INSERT INTO stock VALUES (''PEN'', 10)\")\n\na = sqlite3.connect(path, isolation_level=None, timeout=0)\nb = sqlite3.connect(path, isolation_level=None, timeout=0)\n\na.execute(\"BEGIN IMMEDIATE\")                        # A holds the write lock\na.execute(\"UPDATE stock SET qty = qty - 1 WHERE sku = ''PEN''\")\ntry:\n    b.execute(\"UPDATE stock SET qty = qty - 1 WHERE sku = ''PEN''\")\nexcept sqlite3.OperationalError as e:\n    print(\"B:\", e)                                  # B: database is locked\nprint(\"B can still read:\", b.execute(\"SELECT qty FROM stock\").fetchone()[0])   # B can still read: 10\na.execute(\"COMMIT\")\nb.execute(\"UPDATE stock SET qty = qty - 1 WHERE sku = ''PEN''\")   # now it succeeds\nprint(\"final:\", b.execute(\"SELECT qty FROM stock\").fetchone()[0])              # final: 8","filename":"Python + SQLite — write lock"},"revision":1},{"id":"62663407-89dd-7bb7-ba4b-a10d407cc643","type":"text","position":"aE","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Real apps set a "},{"type":"text","text":"timeout","marks":[{"type":"code"}]},{"type":"text","text":" (busy timeout) so the second writer waits instead of failing immediately."}]}]}},"revision":1},{"id":"75e2b1f5-e009-7eaf-9ef4-edf0d87d9aac","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a deadlock and how do databases handle it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Two (or more) transactions each hold a lock the other needs, so all wait forever. The engine''s deadlock detector finds the cycle and rolls back one victim, returning an error (MySQL 1213, SQL Server 1205, PostgreSQL 40P01). Prevent with consistent lock ordering and short transactions; handle by retrying."}]}]}},"revision":1},{"id":"54dda7c2-435c-7f87-b5f2-dd44638d6370","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Optimistic vs pessimistic locking?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pessimistic: lock the data before changing it ("},{"type":"text","text":"SELECT … FOR UPDATE","marks":[{"type":"code"}]},{"type":"text","text":"), so conflicts wait — good for high contention. Optimistic: don''t lock; detect a conflict at write time with a version/timestamp column ("},{"type":"text","text":"WHERE version = :v","marks":[{"type":"code"}]},{"type":"text","text":") and retry — good when conflicts are rare, e.g. web forms."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
