SELECT 'bd4afe89-4044-7df7-aa12-ecd6f37d925f', '517bbde6-844e-7c13-9d61-56223645393a', 1, 'PUBLISHED', 'Logical Order of Query Execution', '[{"id":"526cd3fd-1b7c-731c-b5bf-0ad2bfe1d764","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"You "},{"type":"text","text":"write","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"SELECT","marks":[{"type":"code"}]},{"type":"text","text":" first, but the database "},{"type":"text","text":"evaluates","marks":[{"type":"italic"}]},{"type":"text","text":" it almost last. This single fact explains most “why can''t I use that here?” errors."}]},{"type":"paragraph","content":[{"type":"text","text":"FROM / JOIN → WHERE → GROUP BY → HAVING → SELECT → DISTINCT → ORDER BY → LIMIT"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"FROM + JOINs","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Build the working set of rows from the tables."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"WHERE","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Keep rows whose condition is true. Aggregates don''t exist yet."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"GROUP BY","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Collapse rows into one row per group."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"HAVING","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Keep groups whose condition is true — aggregates are available now."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SELECT","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Compute output expressions, window functions and aliases."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"DISTINCT","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Remove duplicate output rows."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ORDER BY","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Sort — can use aliases, since "},{"type":"text","text":"SELECT","marks":[{"type":"code"}]},{"type":"text","text":" already ran."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"LIMIT / OFFSET","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Cut the sorted result."}]}]}]}]}},"revision":1},{"id":"24f331fe-3cc0-7ccc-b4d1-e97737e7f82f","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Consequences"}]},"revision":1},{"id":"057d5f5c-2054-7d5d-b131-b26bd702b7e3","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"You try"}],[{"type":"text","text":"Result"}],[{"type":"text","text":"Why"}]],[[{"type":"text","text":"WHERE monthly > 9000","marks":[{"type":"code"}]},{"type":"text","text":" (alias)"}],[{"type":"text","text":"Error in standard SQL"}],[{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" runs before "},{"type":"text","text":"SELECT","marks":[{"type":"code"}]},{"type":"text","text":" creates the alias"}]],[[{"type":"text","text":"WHERE COUNT(*) > 2","marks":[{"type":"code"}]}],[{"type":"text","text":"Error everywhere"}],[{"type":"text","text":"Aggregates don''t exist before "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":" — use "},{"type":"text","text":"HAVING","marks":[{"type":"code"}]}]],[[{"type":"text","text":"ORDER BY monthly","marks":[{"type":"code"}]}],[{"type":"text","text":"Works"}],[{"type":"text","text":"OR