SELECT '8befea97-ad75-7e64-b2d8-996b3f120f1c', 'bf88a060-a196-773d-9cf9-b8c2c1af5cf7', 1, 'PUBLISHED', 'Normalization (1NF → BCNF)', '[{"id":"14be8416-3e46-75bc-b1de-4910d1a72a4b","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Normalization organises columns into tables so that "},{"type":"text","text":"each fact is stored once","marks":[{"type":"bold"}]},{"type":"text","text":". It removes update, insert and delete anomalies caused by redundancy."}]}]}},"revision":1},{"id":"c627e173-5352-7ec7-9646-2adabf3389bb","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Functional dependency (A → B)","marks":[{"type":"bold"}]},{"type":"text","text":" — the value of A determines the value of B: "},{"type":"text","text":"emp_id → name","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"customer_name → customer_city","marks":[{"type":"code"}]},{"type":"text","text":". Normal forms are rules about which dependencies may exist inside one table."}]}]}},"revision":1},{"id":"57b7dacf-9f52-7c7a-92df-21f20a71607b","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"The problem: a spreadsheet as a table"}]},"revision":1},{"id":"0b92bfef-c0f6-772a-bbe4-04c4eac373d5","type":"code","position":"a3","content":{"language":"sql","code":"SELECT * FROM order_sheet ORDER BY order_id;","filename":"SQL"},"revision":1},{"id":"63df9291-1bf0-730c-a0af-04d06dfae4ce","type":"code","position":"a4","content":{"language":"text","code":"order_id | order_date | customer_name | customer_city | products\n---------+------------+---------------+---------------+-------------------\n101      | 2024-01-05 | Ananya        | Mumbai        | Laptop, Headphones\n102      | 2024-01-12 | Rahul         | Delhi         | Chair, Pen\n103      | 2024-02-03 | Ananya        | Mumbai        | Notebook, Pen","filename":"Output"},"revision":1},{"id":"d814ca1a-d12c-74e5-acd1-4a06f15b48ae","type":"table","position":"a5","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Anomaly"}],[{"type":"text","text":"In this sheet"}]],[[{"type":"text","text":"Update","marks":[{"type":"bold"}]}],[{"type":"text","text":"Ananya moves city → must update several rows; miss one and data disagrees"}]],[[{"type":"text","text":"Insert","marks":[{"type":"bold"}]}],[{"type":"text","text":"Can''t record a new customer until they place an order"}]],[[{"type":"text","text":"Delete","marks":[{"type":"bold"}]}],[{"type":"text","text":"Delete Rahul''s only order → we forget Rahul exists"}]],[[{"type":"text","text":"Query pain","marks":[{"type":"bold"}]}],[{"type":"text","text":"“How many orders include a Pen?” needs string matching on "},{"type":"text","text":"products","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"b2721bee-8477-7a25-bc4a-f069a747d9d2","type":"heading","position":"a6","content":{"level":1,"content":[{"type":"text","text":"1NF — atomic values, no repeating groups"}]},"revision":1},{"id":"72f4f717-86ce-7c2c-b0eb-a79efcc43857","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every cell holds one value; no lists, no "},{"type":"text","text":"phone1","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"phone2","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"phone3","marks":[{"type":"code"}]},{"type":"text","text":" columns; each row is unique (has a key)."}]}]}},"revision":1},{"id":"b9a04461-e89f-715a-abf6-3197b0ed72b0","type":"code","position":"a8","content":{"language":"sql","code":"-- split the list into one row per product (key: order_id + product)\nWITH RECURSIVE split(order_id, order_date, customer_name, customer_city, product, rest) AS (\n    SELECT order_id, order_date, customer_name, customer_city, '''', products || '',''\n    FROM order_sheet\n    UNION ALL\n    SELECT order_id, order_date, customer_name, customer_city,\n           trim(substr(rest, 1, instr(rest, '','') - 1)),\n           substr(rest, instr(rest, '','') + 1)\n    FROM split WHERE rest <> ''''\n)\nSELECT order_id, order_date, customer_name, customer_city, product\nFROM split WHERE product <> ''''\nORDER BY order_id, product;","filename":"SQL"},"revision":1},{"id":"2d03ce56-b3b0-784a-b853-58ace8d6c9e7","type":"code","position":"a9","content":{"language":"text","code":"order_id | order_date | customer_name | customer_city | product\n---------+------------+---------------+---------------+-----------\n101      | 2024-01-05 | Ananya        | Mumbai        | Headphones\n101      | 2024-01-05 | Ananya        | Mumbai        | Laptop\n102      | 2024-01-12 | Rahul         | Delhi         | Chair\n102      | 2024-01-12 | Rahul         | Delhi         | Pen\n103      | 2024-02-03 | Ananya        | Mumbai        | Notebook\n103      | 2024-02-03 | Ananya        | Mumbai        | Pen","filename":"Output"},"revision":1},{"id":"9ba5df50-7024-7f24-bd34-896b54fe1423","type":"heading","position":"aA","content":{"level":1,"content":[{"type":"text","text":"2NF — no partial dependencies"}]},"revision":1},{"id":"b6017596-34cc-7f2b-b3b9-c04be91cb4d2","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Applies when the key is "},{"type":"text","text":"composite","marks":[{"type":"bold"}]},{"type":"text","text":". Every non-key column must depend on the "},{"type":"text","text":"whole","marks":[{"type":"italic"}]},{"type":"text","text":" key. Here the key is "},{"type":"text","text":"(order_id, product)","marks":[{"type":"code"}]},{"type":"text","text":", but "},{"type":"text","text":"order_date","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"customer_name","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"customer_city","marks":[{"type":"code"}]},{"type":"text","text":" depend on "},{"type":"text","text":"order_id","marks":[{"type":"code"}]},{"type":"text","text":" alone → move them to an "},{"type":"text","text":"orders","marks":[{"type":"code"}]},{"type":"text","text":" table. The line table keeps only "},{"type":"text","text":"(order_id, product, quantity…)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"df1e415e-6c50-7bad-9898-761a4cda9945","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"3NF — no transitive dependencies"}]},"revision":1},{"id":"71752a3a-4782-7f0d-a5df-d1083464b526","type":"text","position":"aD","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Non-key columns must depend on "},{"type":"text","text":"the key, the whole key, and nothing but the key","marks":[{"type":"bold"}]},{"type":"text","text":". In "},{"type":"text","text":"orders(order_id, order_date, customer_name, customer_city)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"order_id → customer_name → customer_city","marks":[{"type":"code"}]},{"type":"text","text":": city depends on the customer, not the order → move customers to their own table and keep "},{"type":"text","text":"customer_id","marks":[{"type":"code"}]},{"type":"text","text":" in "},{"type":"text","text":"orders","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"order_sheet → 1NF: one product per row → 2NF: orders + order_items → 3NF: customers + orders + order_items + products"}]},{"type":"paragraph","content":[{"type":"text","text":"That final shape is exactly the sample database: "},{"type":"text","text":"customers","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"orders","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"order_items","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"products","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"f8316660-38c0-708c-871f-c7060c5cf577","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"BCNF — every determinant is a candidate key"}]},"revision":1},{"id":"63f49699-ea55-776e-a270-fb2d5eaaea75","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A stricter 3NF. Classic case: "},{"type":"text","text":"teaching(student, course, instructor)","marks":[{"type":"code"}]},{"type":"text","text":" where each instructor teaches exactly one course ("},{"type":"text","text":"instructor → course","marks":[{"type":"code"}]},{"type":"text","text":") and a student takes a course from one instructor. Key: "},{"type":"text","text":"(student, course)","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"instructor → course","marks":[{"type":"code"}]},{"type":"text","text":" has a determinant that is not a candidate key → split into "},{"type":"text","text":"instructor_course(instructor, course)","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"student_instructor(student, instructor)","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"bbfcdca8-d9e5-725b-9cf8-d6790eedf12a","type":"code","position":"aG","content":{"language":"sql","code":"CREATE TABLE teaching (student TEXT, course TEXT, instructor TEXT, PRIMARY KEY (student, course));\nINSERT INTO teaching VALUES\n    (''Asha'', ''SQL'', ''Dr. Rao''), (''Ravi'', ''SQL'', ''Dr. Rao''),\n    (''Asha'', ''Python'', ''Dr. Iyer''), (''Meera'', ''SQL'', ''Dr. Sen'');\n\n-- the fact \"Dr. Rao teaches SQL\" is stored twice: redundancy BCNF removes\nSELECT instructor, course, COUNT(*) AS times_stored\nFROM teaching GROUP BY instructor, course ORDER BY instructor;","filename":"SQL"},"revision":1},{"id":"7371b20a-4798-746c-9d99-738d1d31e90c","type":"code","position":"aH","content":{"language":"text","code":"instructor | course | times_stored\n-----------+--------+-------------\nDr. Iyer   | Python | 1\nDr. Rao    | SQL    | 2\nDr. Sen    | SQL    | 1","filename":"Output"},"revision":1},{"id":"4bc28056-96a4-7994-91d2-53231bd3524c","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"Summary"}]},"revision":1},{"id":"bed43f73-dc43-7bf9-80f2-6ab55c13e071","type":"table","position":"aJ","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Form"}],[{"type":"text","text":"Rule"}],[{"type":"text","text":"Removes"}]],[[{"type":"text","text":"1NF"}],[{"type":"text","text":"Atomic values, no repeating groups, a key exists"}],[{"type":"text","text":"Lists in cells"}]],[[{"type":"text","text":"2NF"}],[{"type":"text","text":"1NF + no non-key column depends on part of a composite key"}],[{"type":"text","text":"Partial dependencies"}]],[[{"type":"text","text":"3NF"}],[{"type":"text","text":"2NF + no non-key column depends on another non-key column"}],[{"type":"text","text":"Transitive dependencies"}]],[[{"type":"text","text":"BCNF"}],[{"type":"text","text":"For every dependency X → Y, X is a super key"}],[{"type":"text","text":"Remaining anomalies from overlapping candidate keys"}]],[[{"type":"text","text":"4NF / 5NF"}],[{"type":"text","text":"No independent multi-valued / join dependencies"}],[{"type":"text","text":"Rare in practice"}]]]},"revision":1},{"id":"cbd545c1-56ed-7158-9ff0-b7ec94b79831","type":"callout","position":"aK","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Most OLTP schemas aim for "},{"type":"text","text":"3NF/BCNF","marks":[{"type":"bold"}]},{"type":"text","text":". Going further is rarely needed; going less far should be a deliberate choice (denormalization)."}]}]}},"revision":1},{"id":"104b747d-74c1-74dd-8259-365f6dea3a5d","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is normalization and why is it needed?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The process of structuring tables so each fact is stored once, using normal forms (1NF, 2NF, 3NF, BCNF) based on functional dependencies. It prevents update/insert/delete anomalies, saves space and keeps data consistent; the cost is more tables and joins."}]}]}},"revision":1},{"id":"df711e94-4fe2-70f8-963e-a7f2dede960f","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between 3NF and BCNF?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"3NF allows a dependency X → Y where Y is part of a candidate key (a "},{"type":"text","text":"prime","marks":[{"type":"italic"}]},{"type":"text","text":" attribute) even if X isn''t a key. BCNF forbids it: the left side of every non-trivial dependency must be a super key. They differ only when a table has overlapping composite candidate keys."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
