INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'ec53fbe3-a5ac-71de-b78c-32aee6564bbd', '7b22e941-f536-7ec3-adfb-5810a4509b0d', 1, 'PUBLISHED', 'Nth Highest Salary', '[{"id":"a69d1f7f-b2c9-72e0-9798-cc04f4ab3d53","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The most-asked SQL interview question. Know three solutions, and be precise about "},{"type":"text","text":"ties","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"what to return when there is no Nth value","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Salaries (distinct, highest first): 150000, 120000, 110000, "},{"type":"text","text":"95000","marks":[{"type":"bold"}]},{"type":"text","text":" (Meera and Karan), 85000, 80000, … — so the 4th highest "},{"type":"text","text":"distinct","marks":[{"type":"italic"}]},{"type":"text","text":" salary is 95000."}]}]}},"revision":1},{"id":"cfc6207a-1369-7dab-a2fb-b78802b4c50f","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"1. DENSE_RANK (best general answer)"}]},"revision":1},{"id":"1bf6f703-df9c-7829-8f7a-542cfa3ffc2c","type":"code","position":"a2","content":{"language":"sql","code":"WITH ranked AS (\n    SELECT name, salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS rnk\n    FROM employees\n)\nSELECT name, salary FROM ranked WHERE rnk = 4 ORDER BY name;","filename":"SQL"},"revision":1},{"id":"e27a35dd-ec87-763c-ade8-346f8b01180a","type":"code","position":"a3","content":{"language":"text","code":"name  | salary\n------+-------\nKaran | 95000\nMeera | 95000","filename":"Output"},"revision":1},{"id":"399cc89f-369b-7929-a1d1-d73137adea3f","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Returns "},{"type":"text","text":"every","marks":[{"type":"italic"}]},{"type":"text","text":" employee with that salary. "},{"type":"text","text":"RANK","marks":[{"type":"code"}]},{"type":"text","text":" would skip numbers after ties, and "},{"type":"text","text":"ROW_NUMBER","marks":[{"type":"code"}]},{"type":"text","text":" would arbitrarily return only one of Meera/Karan and shift everyone below."}]}]}},"revision":1},{"id":"09f858c1-4094-71e7-ab7b-e6ccbc11dd26","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"2. LIMIT / OFFSET on distinct salaries"}]},"revision":1},{"id":"39f0104f-22d4-7084-a276-6296a3a9034c","type":"code","position":"a6","content":{"language":"sql","code":"SELECT DISTINCT salary\nFROM employees\nORDER BY salary DESC\nLIMIT 1 OFFSET 3;          -- N - 1\n\n-- return NULL (not zero rows) when N is too large: wrap it in a scalar subquery\nSELECT (SELECT DISTINCT salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET 99) AS nth_salary;","filename":"SQL"},"revision":1},{"id":"eb8d6443-d1a1-7ab6-9eb2-1f1e152e9441","type":"code","position":"a7","content":{"language":"text","code":"salary\n------\n95000\n\nnth_salary\n----------\nNULL","filename":"Output"},"revision":1},{"id":"0061e549-c2d3-7772-942c-c0def8fea728","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"3. Correlated subquery (no window functions)"}]},"revision":1},{"id":"6889a023-c817-71e9-8b52-06d903fec8eb","type":"code","position":"a9","content":{"language":"sql","code":"-- the salary that has exactly N-1 distinct salaries above it\nSELECT DISTINCT e.salary\nFROM employees e\nWHERE 3 = (SELECT COUNT(DISTINCT i.salary) FROM employees i WHERE i.salary > e.salary);","filename":"SQL"},"revision":1},{"id":"d3622b97-92a4-74f0-afda-585371ed54a7","type":"code","position":"aA","content":{"language":"text","code":"salary\n------\n95000","filename":"Output"},"revision":1},{"id":"f3c83e93-c9e3-70c2-91d2-e1c2a5dfc67f","type":"code","position":"aB","content":{"language":"sql","code":"-- 2nd highest, the classic MAX-below-MAX trick\nSELECT MAX(salary) AS second_highest\nFROM employees\nWHERE salary < (SELECT MAX(salary) FROM employees);","filename":"SQL"},"revision":1},{"id":"0fe441cf-2297-7f8c-8e92-766a19d8b8ad","type":"code","position":"aC","content":{"language":"text","code":"second_highest\n--------------\n120000","filename":"Output"},"revision":1},{"id":"5e9cde68-15b2-7ff5-8d25-587fed48b1a1","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Nth highest per department"}]},"revision":1},{"id":"9660a696-53a4-7197-9e6c-adca5d8dab02","type":"code","position":"aE","content":{"language":"sql","code":"WITH ranked AS (\n    SELECT d.name AS department, e.name, e.salary,\n           DENSE_RANK() OVER (PARTITION BY e.dept_id ORDER BY e.salary DESC) AS rnk\n    FROM employees e JOIN departments d ON d.dept_id = e.dept_id\n)\nSELECT department, name, salary FROM ranked WHERE rnk = 2 ORDER BY department;","filename":"SQL"},"revision":1},{"id":"7169415d-2fd3-76e0-9a56-d444aac8a3e7","type":"code","position":"aF","content":{"language":"text","code":"department  | name   | salary\n------------+--------+-------\nEngineering | Ravi   | 120000\nHR          | Vikram | 80000\nSales       | Neha   | 72000","filename":"Output"},"revision":1},{"id":"1d6f9df7-83ed-713c-b228-2b9a80aa8a5a","type":"code","position":"aG","content":{"language":"sql","code":"SELECT DISTINCT salary FROM employees ORDER BY salary DESC\nOFFSET 3 ROWS FETCH NEXT 1 ROWS ONLY;                  -- SQL Server 2012+ / Oracle 12c+\n\nSELECT TOP 1 salary FROM (\n    SELECT DISTINCT TOP 4 salary FROM employees ORDER BY salary DESC\n) t ORDER BY salary ASC;                               -- older SQL Server","filename":"SQL Server / Oracle"},"revision":1},{"id":"10b160fc-0a0a-794d-9171-b4fdc05aa265","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Which approach would you give in an interview?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DENSE_RANK()","marks":[{"type":"code"}]},{"type":"text","text":" in a CTE: it handles ties correctly, generalises to “per department” with "},{"type":"text","text":"PARTITION BY","marks":[{"type":"code"}]},{"type":"text","text":", and reads clearly. Mention "},{"type":"text","text":"LIMIT/OFFSET","marks":[{"type":"code"}]},{"type":"text","text":" on "},{"type":"text","text":"DISTINCT","marks":[{"type":"code"}]},{"type":"text","text":" salaries as the short alternative, and wrap it in a scalar subquery if the spec says “return NULL if there is no Nth salary”."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
