SELECT '0e48f226-b66e-7770-af7f-47f11eb98b1d', '61f3e477-ccac-750c-8001-7caf0f5dd94b', 1, 'PUBLISHED', 'NULL & Three-Valued Logic', '[{"id":"2c8fe73c-e36e-7391-9f77-b129fcf784ee","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" means "},{"type":"text","text":"unknown / missing","marks":[{"type":"italic"}]},{"type":"text","text":". It is not zero, not an empty string, and not equal to anything — not even another "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"63c5baf5-6c90-70f6-a92c-23b3b22f3d8e","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Three-valued logic","marks":[{"type":"bold"}]},{"type":"text","text":" — SQL conditions evaluate to "},{"type":"text","text":"TRUE","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"FALSE","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"UNKNOWN","marks":[{"type":"code"}]},{"type":"text","text":". Any comparison with "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"=","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"<>","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"<","marks":[{"type":"code"}]},{"type":"text","text":"…) is "},{"type":"text","text":"UNKNOWN","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" keeps only "},{"type":"text","text":"TRUE","marks":[{"type":"code"}]},{"type":"text","text":" rows."}]}]}},"revision":1},{"id":"63dfe426-6f42-7a9e-be3c-41c3bfbe9f4d","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"Comparisons with NULL"}]},"revision":1},{"id":"0a0bec30-f3f2-72aa-8c56-92be450d411f","type":"code","position":"a3","content":{"language":"sql","code":"SELECT NULL = NULL      AS eq,\n       NULL <> 1        AS ne,\n       NULL IS NULL     AS is_null,\n       1 IS NOT NULL    AS is_not_null,\n       NULL + 5         AS arithmetic,\n       ''a'' || NULL      AS concat;","filename":"SQL"},"revision":1},{"id":"b6020867-ee59-798f-bbe9-0833abdbcc30","type":"code","position":"a4","content":{"language":"text","code":"eq   | ne   | is_null | is_not_null | arithmetic | concat\n-----+------+---------+-------------+------------+-------\nNULL | NULL | 1       | 1           | NULL       | NULL","filename":"Output"},"revision":1},{"id":"fbe3d6b2-4f6c-74c9-be61-5fe8600fe29c","type":"text","position":"a5","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"(SQLite shows "},{"type":"text","text":"TRUE","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"FALSE","marks":[{"type":"code"}]},{"type":"text","text":" as "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"UNKNOWN","marks":[{"type":"code"}]},{"type":"text","text":" as "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":".) "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" propagates through arithmetic and concatenation — one missing value makes the whole expression "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"e3aedcb9-3b94-71fe-9588-8af1b9da934c","type":"code","position":"a6","content":{"language":"sql","code":"SELECT name FROM employees WHERE email = NULL;        -- always empty!\nSELECT name FROM employees WHERE email IS NULL ORDER BY name;","filename":"SQL"},"revision":1},{"id":"65a9f6a5-084a-70a6-9c47-62f575614bf4","type":"code","position":"a7","content":{"language":"text","code":"name\n----\n\nname\n----\nDev\nNeha","filename":"Output"},"revision":1},{"id":"7a30de95-442b-7179-b080-23494fac5718","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Truth tables"}]},"revision":1},{"id":"4d40bfab-2ed3-7927-a26e-286bf9604ca3","type":"table","position":"a9","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"AND","marks":[{"type":"code"}]}],[{"type":"text","text":"TRUE"}],[{"type":"text","text":"FALSE"}],[{"type":"text","text":"UNKNOWN"}]],[[{"type":"text","text":"TRUE","marks":[{"type":"bold"}]}],[{"type":"text","text":"TRUE"}],[{"type":"text","text":"FALSE"}],[{"type":"text","text":"UNKNOWN"}]],[[{"type":"text","text":"FALSE","marks":[{"type":"bold"}]}],[{"type":"text","text":"FALSE"}],[{"type":"text","text":"FALSE"}],[{"type":"text","text":"FALSE"}]],[[{"type":"text","text":"UNKNOWN","marks":[{"type":"bold"}]}],[{"type":"text","text":"UNKNOWN"}],[{"type":"text","text":"FALSE"}],[{"type":"text","text":"UNKNOWN"}]]]},"revision":1},{"id":"388a3ed7-680b-7574-bcaf-ca18c6374a52","type":"table","position":"aA","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"OR","marks":[{"type":"code"}]}],[{"type":"text","text":"TRUE"}],[{"type":"text","text":"FALSE"}],[{"type":"text","text":"UNKNOWN"}]],[[{"type":"text","text":"TRUE","marks":[{"type":"bold"}]}],[{"type":"text","text":"TRUE"}],[{"type":"text","text":"TRUE"}],[{"type":"text","text":"TRUE"}]],[[{"type":"text","text":"FALSE","marks":[{"type":"bold"}]}],[{"type":"text","text":"TRUE"}],[{"type":"text","text":"FALSE"}],[{"type":"text","text":"UNKNOWN"}]],[[{"type":"text","text":"UNKNOWN","marks":[{"type":"bold"}]}],[{"type":"text","text":"TRUE"}],[{"type":"text","text":"UNKNOWN"}],[{"type":"text","text":"UNKNOWN"}]]]},"revision":1},{"id":"2e0f2a48-265c-7d87-a287-aee535072697","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"NOT UNKNOWN","marks":[{"type":"code"}]},{"type":"text","text":" is still "},{"type":"text","text":"UNKNOWN","marks":[{"type":"code"}]},{"type":"text","text":". So a row with a "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" column fails "},{"type":"text","text":"both","marks":[{"type":"italic"}]},{"type":"text","text":" "},{"type":"text","text":"x = 5","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"NOT (x = 5)","marks":[{"type":"code"}]},{"type":"text","text":":"}]}]}},"revision":1},{"id":"df816036-30f4-7d7c-a2da-0d97171e90c6","type":"code","position":"aC","content":{"language":"sql","code":"SELECT COUNT(*) AS total,\n       SUM(dept_id = 1)                   AS in_eng,\n       SUM(NOT (dept_id = 1))             AS not_in_eng,\n       SUM(dept_id IS NULL)               AS no_dept\nFROM employees;","filename":"SQL"},"revision":1},{"id":"894677ed-6ce5-7f67-ad74-4e85b8ada6db","type":"code","position":"aD","content":{"language":"text","code":"total | in_eng | not_in_eng | no_dept\n------+--------+------------+--------\n10    | 4      | 5          | 1","filename":"Output"},"revision":1},{"id":"3d9b4d72-aab3-78e8-b55b-69a4b2d7e760","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"The NOT IN trap"}]},"revision":1},{"id":"47194522-a6d9-71f7-b835-1c1263965260","type":"code","position":"aF","content":{"language":"sql","code":"-- customers outside Mumbai and Delhi (Kavya''s city is NULL)\nSELECT name FROM customers WHERE city NOT IN (''Mumbai'', ''Delhi'') ORDER BY name;\nSELECT ''x'' AS found WHERE 3 NOT IN (1, 2, NULL);","filename":"SQL"},"revision":1},{"id":"26225bf0-ff22-72bc-8a72-612456e789c8","type":"code","position":"aG","content":{"language":"text","code":"name\n-----\nSneha\n\nfound\n-----","filename":"Output"},"revision":1},{"id":"1786e75b-4427-73e4-b16e-27ebff3ca78e","type":"callout","position":"aH","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"x NOT IN (1, 2, NULL)","marks":[{"type":"code"}]},{"type":"text","text":" is never true: it means "},{"type":"text","text":"x <> 1 AND x <> 2 AND x <> NULL","marks":[{"type":"code"}]},{"type":"text","text":", and the last part is unknown. If a "},{"type":"text","text":"NOT IN (subquery)","marks":[{"type":"code"}]},{"type":"text","text":" can return a "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":", the whole query returns nothing. Use "},{"type":"text","text":"NOT EXISTS","marks":[{"type":"code"}]},{"type":"text","text":" instead (see Semi & Anti Joins). Also note Kavya (city "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":") is missing from the first result."}]}]}},"revision":1},{"id":"a99a68b0-2c85-79c7-9ff5-0ba7d9d46f8f","type":"heading","position":"aI","content":{"level":1,"content":[{"type":"text","text":"NULL-handling functions"}]},"revision":1},{"id":"b54edf65-5314-7d55-bbd9-02caa1414937","type":"table","position":"aJ","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Function"}],[{"type":"text","text":"Returns"}],[{"type":"text","text":"Portability"}]],[[{"type":"text","text":"COALESCE(a, b, c…)","marks":[{"type":"code"}]}],[{"type":"text","text":"First non-"},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" argument"}],[{"type":"text","text":"Standard — everywhere"}]],[[{"type":"text","text":"NULLIF(a, b)","marks":[{"type":"code"}]}],[{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" if "},{"type":"text","text":"a = b","marks":[{"type":"code"}]},{"type":"text","text":", else "},{"type":"text","text":"a","marks":[{"type":"code"}]}],[{"type":"text","text":"Standard — everywhere"}]],[[{"type":"text","text":"IFNULL(a, b)","marks":[{"type":"code"}]}],[{"type":"text","text":"b","marks":[{"type":"code"}]},{"type":"text","text":" if "},{"type":"text","text":"a","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"NULL","marks":[{"type":"code"}]}],[{"type":"text","text":"MySQL, SQLite"}]],[[{"type":"text","text":"ISNULL(a, b)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"NVL(a, b)","marks":[{"type":"code"}]}],[{"type":"text","text":"Same idea"}],[{"type":"text","text":"SQL Server / Oracle"}]],[[{"type":"text","text":"a IS DISTINCT FROM b","marks":[{"type":"code"}]}],[{"type":"text","text":"Null-safe "},{"type":"text","text":"<>","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" vs "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" → false)"}],[{"type":"text","text":"Standard; PostgreSQL, SQL Server 2022, SQLite ("},{"type":"text","text":"IS NOT","marks":[{"type":"code"}]},{"type":"text","text":")"}]]]},"revision":1},{"id":"9602ce11-de99-7051-b25d-db1cba708885","type":"code","position":"aK","content":{"language":"sql","code":"SELECT name,\n       COALESCE(email, ''no email'')          AS contact,\n       COALESCE(dept_id, 0)                 AS dept\nFROM employees\nWHERE emp_id IN (6, 7, 10)\nORDER BY emp_id;\n\n-- NULLIF avoids division by zero: x / 0 → x / NULL → NULL\nSELECT 100 / NULLIF(0, 0) AS safe_div;\n\n-- null-safe equality (SQLite: IS / IS NOT; standard: IS [NOT] DISTINCT FROM)\nSELECT NULL IS NULL AS both_null, 1 IS NOT NULL AS differ, NULL IS 1 AS null_vs_1;","filename":"SQL"},"revision":1},{"id":"2815393c-3e7a-7fa1-ae8c-daada5bf867d","type":"code","position":"aL","content":{"language":"text","code":"name  | contact       | dept\n------+---------------+-----\nArjun | arjun@corp.in | 2\nNeha  | no email      | 2\nDev   | no email      | 0\n\nsafe_div\n--------\nNULL\n\nboth_null | differ | null_vs_1\n----------+--------+----------\n1         | 1      | 0","filename":"Output"},"revision":1},{"id":"b27b6053-7216-7233-8a9f-1cbd04c73b1c","type":"heading","position":"aM","content":{"level":1,"content":[{"type":"text","text":"NULL in aggregates, sorting and grouping"}]},"revision":1},{"id":"cd3d72ad-b1af-7bf8-8e4d-80a94a4851c0","type":"text","position":"aN","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Aggregates "},{"type":"text","text":"ignore","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"s: "},{"type":"text","text":"COUNT(email)","marks":[{"type":"code"}]},{"type":"text","text":" counts non-null emails; "},{"type":"text","text":"AVG","marks":[{"type":"code"}]},{"type":"text","text":" divides by the non-null count."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"COUNT(*)","marks":[{"type":"code"}]},{"type":"text","text":" counts rows, whatever they contain."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"DISTINCT","marks":[{"type":"code"}]},{"type":"text","text":" put all "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"s into "},{"type":"text","text":"one","marks":[{"type":"bold"}]},{"type":"text","text":" group."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"ORDER BY","marks":[{"type":"code"}]},{"type":"text","text":" puts "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"s first or last depending on the engine."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"UNIQUE","marks":[{"type":"code"}]},{"type":"text","text":" allows multiple "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"s (except SQL Server)."}]}]}]}]}},"revision":1},{"id":"39769278-f17f-70fc-9253-5b46fbbb7a65","type":"code","position":"aO","content":{"language":"sql","code":"SELECT COUNT(*) AS all_rows, COUNT(email) AS with_email, COUNT(dept_id) AS with_dept\nFROM employees;","filename":"SQL"},"revision":1},{"id":"e3298eed-0654-7029-8348-54714de763ad","type":"code","position":"aP","content":{"language":"text","code":"all_rows | with_email | with_dept\n---------+------------+----------\n10       | 8          | 9","filename":"Output"},"revision":1},{"id":"2aab1130-a115-7620-bdb8-d28bdae7fc05","type":"question","position":"aQ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between NULL, 0 and an empty string?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"''''","marks":[{"type":"code"}]},{"type":"text","text":" are known values that compare and sort normally. "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" is the absence of a value: comparisons with it yield "},{"type":"text","text":"UNKNOWN","marks":[{"type":"code"}]},{"type":"text","text":", it is skipped by aggregates and needs "},{"type":"text","text":"IS NULL","marks":[{"type":"code"}]},{"type":"text","text":". (Oracle is odd: it treats "},{"type":"text","text":"''''","marks":[{"type":"code"}]},{"type":"text","text":" as "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":".)"}]}]}},"revision":1},{"id":"761beb79-5f06-761a-87ed-70f3f26008eb","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Why does WHERE col <> ''x'' not return rows where col is NULL?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"NULL <> ''x''","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"UNKNOWN","marks":[{"type":"code"}]},{"type":"text","text":", and "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" keeps only "},{"type":"text","text":"TRUE","marks":[{"type":"code"}]},{"type":"text","text":". Write "},{"type":"text","text":"WHERE col <> ''x'' OR col IS NULL","marks":[{"type":"code"}]},{"type":"text","text":", or "},{"type":"text","text":"WHERE col IS DISTINCT FROM ''x''","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
