  ('fbe3d6b2-4f6c-74c9-be61-5fe8600fe29c', 'a5', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"(SQLite shows "},{"type":"text","text":"TRUE","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"FALSE","marks":[{"type":"code"}]},{"type":"text","text":" as "},{"type":"text","text":"1","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"0","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"UNKNOWN","marks":[{"type":"code"}]},{"type":"text","text":" as "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":".) "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" propagates through arithmetic and concatenation — one missing value makes the whole expression "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}}'),
