SELECT 'f79fa21a-6113-7aee-a7b4-d066c8f70a6f', '61931b52-60c5-7c0d-a1c1-8e99759636e8', 1, 'PUBLISHED', 'Numeric Functions & Type Casting', '[{"id":"db9dfda2-305c-779e-9e19-db72a8d2864d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rounding, absolute values, modulo and explicit casts — plus the integer-division and rounding rules that trip people up."}]}]}},"revision":1},{"id":"339fc36c-7666-79b3-9e3d-edfc938d63f4","type":"table","position":"a1","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Function"}],[{"type":"text","text":"Does"}],[{"type":"text","text":"Example → result"}]],[[{"type":"text","text":"ROUND(x, d)","marks":[{"type":"code"}]}],[{"type":"text","text":"Round to "},{"type":"text","text":"d","marks":[{"type":"code"}]},{"type":"text","text":" decimals (half away from zero in most engines)"}],[{"type":"text","text":"ROUND(2.567, 1)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"2.6","marks":[{"type":"code"}]}]],[[{"type":"text","text":"CEIL(x)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"FLOOR(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"Round up / down to an integer"}],[{"type":"text","text":"CEIL(2.1)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"3","marks":[{"type":"code"}]}]],[[{"type":"text","text":"ABS(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"Absolute value"}],[{"type":"text","text":"ABS(-7)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"7","marks":[{"type":"code"}]}]],[[{"type":"text","text":"x % y","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"MOD(x, y)","marks":[{"type":"code"}]}],[{"type":"text","text":"Remainder"}],[{"type":"text","text":"17 % 5","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"2","marks":[{"type":"code"}]}]],[[{"type":"text","text":"POWER(x, y)","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"SQRT(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"Powers and roots"}],[{"type":"text","text":"POWER(2, 10)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"1024","marks":[{"type":"code"}]}]],[[{"type":"text","text":"SIGN(x)","marks":[{"type":"code"}]}],[{"type":"text","text":"−1, 0 or 1"}],[{"type":"text","text":"SIGN(-3)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"-1","marks":[{"type":"code"}]}]],[[{"type":"text","text":"CAST(x AS type)","marks":[{"type":"code"}]}],[{"type":"text","text":"Convert type"}],[{"type":"text","text":"CAST(''42'' AS INTEGER)","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"42","marks":[{"type":"code"}]}]]]},"revision":1},{"id":"d19ae70b-4a20-767a-a35c-e1a7457bf62c","type":"code","position":"a2","content":{"language":"sql","code":"SELECT ROUND(2.567, 1)  AS r1,\n       ROUND(2.5)       AS half_up,\n       ROUND(-2.5)      AS half_neg,\n       CEIL(2.1)        AS ceil_,\n       FLOOR(-2.1)      AS floor_,\n       ABS(-7)          AS abs_,\n       17 % 5           AS mod_,\n       POWER(2, 10)     AS pow_,\n       SQRT(144)        AS sqrt_,\n       SIGN(-3)         AS sign_;","filename":"SQL"},"revision":1},{"id":"b7c8de1d-220c-7c63-9145-b97cc3f6d856","type":"code","position":"a3","content":{"language":"text","code":"r1  | half_up | half_neg | ceil_ | floor_ | abs_ | mod_ | pow_   | sqrt_ | sign_\n----+---------+----------+-------+--------+------+------+--------+-------+------\n2.6 | 3.0     | -3.0     | 3.0   | -3.0   | 7    | 2    | 1024.0 | 12.0  | -1","filename":"Output"},"revision":1},{"id":"ad3665cc-565e-7d7a-bc13-cbbf218df035","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Integer division and averages"}]},"revision":1},{"id":"95a3ea59-4556-7a27-9be5-221fc031cf73","type":"code","position":"a5","content":{"language":"sql","code":"SELECT 7 / 2                    AS int_div,\n       7 / 2.0                  AS real_div,\n       CAST(7 AS REAL) / 2      AS cast_div,\n       7 * 1.0 / 2              AS times_one;\n\n-- percentage of employees in Engineering: the classic integer-division bug\nSELECT SUM(dept_id = 1) * 100 / COUNT(*)                  AS wrong_looking,\n       ROUND(SUM(dept_id = 1) * 100.0 / COUNT(*), 1)      AS pct\nFROM employees;","filename":"SQL"},"revision":1},{"id":"4a6852f3-9c3a-7dea-bbef-c09fb030406b","type":"code","position":"a6","content":{"language":"text","code":"int_div | real_div | cast_div | times_one\n--------+----------+----------+----------\n3       | 3.5      | 3.5      | 3.5\n\nwrong_looking | pct\n--------------+-----\n40            | 40.0","filename":"Output"},"revision":1},{"id":"6d62f033-77ac-756f-8eb7-dbc89d67c597","type":"text","position":"a7","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both answers are 40 here only because 4/10 divides evenly; with 4/9 the first would print "},{"type":"text","text":"44","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"44.4","marks":[{"type":"code"}]},{"type":"text","text":". Multiply by "},{"type":"text","text":"100.0","marks":[{"type":"code"}]},{"type":"text","text":" (or cast) "},{"type":"text","text":"before","marks":[{"type":"bold"}]},{"type":"text","text":" dividing."}]}]}},"revision":1},{"id":"744a7aa4-e40c-7936-b2bb-252b0417568a","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"CAST and conversions"}]},"revision":1},{"id":"cd2ea9ac-fa90-7cc0-b706-08489ebff5ee","type":"code","position":"a9","content":{"language":"sql","code":"SELECT CAST(''42'' AS INTEGER) + 1     AS to_int,\n       CAST(3.99 AS INTEGER)         AS truncates,\n       CAST(150000 AS TEXT) || '' INR'' AS to_text,\n       CAST(''12abc'' AS INTEGER)      AS lenient,\n       ''10'' + 5                      AS implicit;","filename":"SQL"},"revision":1},{"id":"4e3cef65-275a-720b-8f92-3b75328336ec","type":"code","position":"aA","content":{"language":"text","code":"to_int | truncates | to_text    | lenient | implicit\n-------+-----------+------------+---------+---------\n43     | 3         | 150000 INR | 12      | 15","filename":"Output"},"revision":1},{"id":"2b707d8c-14ca-7461-b43b-646b92f6efb2","type":"callout","position":"aB","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SQLite converts leniently ("},{"type":"text","text":"''12abc''","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"12","marks":[{"type":"code"}]},{"type":"text","text":"). PostgreSQL and SQL Server raise an error on a bad cast; use "},{"type":"text","text":"TRY_CAST","marks":[{"type":"code"}]},{"type":"text","text":" (SQL Server), "},{"type":"text","text":"SAFE_CAST","marks":[{"type":"code"}]},{"type":"text","text":" (BigQuery) or validate first. Relying on implicit conversion ("},{"type":"text","text":"''10'' + 5","marks":[{"type":"code"}]},{"type":"text","text":") also hides bugs and can disable index use."}]}]}},"revision":1},{"id":"edee6384-61bb-7f28-9916-537c1c05bd9b","type":"code","position":"aC","content":{"language":"sql","code":"SELECT CAST(salary AS DECIMAL(10, 2)) FROM employees;     -- standard\nSELECT salary::numeric(10, 2) FROM employees;              -- PostgreSQL shorthand\nSELECT CONVERT(VARCHAR(20), salary) FROM employees;        -- SQL Server\nSELECT TRY_CAST(''12abc'' AS INT);                           -- SQL Server → NULL instead of error","filename":"Standard / PostgreSQL / SQL Server"},"revision":1},{"id":"58fc47f8-1d96-764c-8254-910f4d7873e9","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"Bucketing numbers"}]},"revision":1},{"id":"b13c5f24-b070-75ef-8e34-966230b94fd8","type":"code","position":"aE","content":{"language":"sql","code":"SELECT (salary / 25000) * 25000       AS bucket_from,\n       COUNT(*)                        AS employees\nFROM employees\nGROUP BY bucket_from\nORDER BY bucket_from;","filename":"SQL"},"revision":1},{"id":"280c180c-a5e8-7410-bdfc-be0dce7d1c34","type":"code","position":"aF","content":{"language":"text","code":"bucket_from | employees\n------------+----------\n50000       | 3\n75000       | 4\n100000      | 2\n150000      | 1","filename":"Output"},"revision":1},{"id":"30778af2-0ace-7344-b37b-d16ed17e4b2d","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What does ROUND(2.5) return?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"3","marks":[{"type":"code"}]},{"type":"text","text":" in SQLite, MySQL, PostgreSQL (numeric), SQL Server and Oracle — they round half "},{"type":"text","text":"away from zero","marks":[{"type":"italic"}]},{"type":"text","text":". But PostgreSQL''s "},{"type":"text","text":"round()","marks":[{"type":"code"}]},{"type":"text","text":" on "},{"type":"text","text":"double precision","marks":[{"type":"code"}]},{"type":"text","text":" and many programming languages use banker''s rounding (half to even, "},{"type":"text","text":"2","marks":[{"type":"code"}]},{"type":"text","text":"). Know your types when cents matter."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
