SELECT '58630266-e0d3-72f6-86db-c1c9cb229be0', 'd446e058-9a62-7b33-8920-63488653739d', 1, 'PUBLISHED', 'LEFT, RIGHT & FULL OUTER JOIN', '[{"id":"387bcf87-b0f3-75fe-8d18-feb81a574d8d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Outer joins keep rows that have "},{"type":"text","text":"no match","marks":[{"type":"bold"}]},{"type":"text","text":", filling the missing side with "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"s. Use them whenever “no related rows” is a valid answer."}]}]}},"revision":1},{"id":"461cde23-ad01-7c3f-ba62-4d5bcfd7a52b","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"LEFT JOIN"}]},"revision":1},{"id":"e4bcf3dc-4580-7626-8d0f-464df12a5196","type":"code","position":"a2","content":{"language":"sql","code":"SELECT d.name AS department, e.name AS employee\nFROM departments d\nLEFT JOIN employees e ON e.dept_id = d.dept_id\nORDER BY d.dept_id, e.name;","filename":"SQL"},"revision":1},{"id":"f052405b-17d6-70f2-995a-6cbd82911749","type":"code","position":"a3","content":{"language":"text","code":"department  | employee\n------------+---------\nEngineering | Asha\nEngineering | Karan\nEngineering | Meera\nEngineering | Ravi\nSales       | Arjun\nSales       | Neha\nSales       | Priya\nHR          | Sara\nHR          | Vikram\nMarketing   | NULL","filename":"Output"},"revision":1},{"id":"12bca3eb-84a3-75a9-ab25-1f23577e677f","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Marketing appears with a "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" employee: every left row survives. Counting per department must count a "},{"type":"text","text":"column from the right side","marks":[{"type":"italic"}]},{"type":"text","text":":"}]}]}},"revision":1},{"id":"1978e674-b101-7292-b20e-d06940b979ae","type":"code","position":"a5","content":{"language":"sql","code":"SELECT d.name, COUNT(e.emp_id) AS headcount, COUNT(*) AS wrong_count\nFROM departments d\nLEFT JOIN employees e ON e.dept_id = d.dept_id\nGROUP BY d.dept_id, d.name\nORDER BY d.dept_id;","filename":"SQL"},"revision":1},{"id":"11ae9b0a-6d23-7e99-90c9-21995a63af8b","type":"code","position":"a6","content":{"language":"text","code":"name        | headcount | wrong_count\n------------+-----------+------------\nEngineering | 4         | 4\nSales       | 3         | 3\nHR          | 2         | 2\nMarketing   | 0         | 1","filename":"Output"},"revision":1},{"id":"17c4e809-e209-7a5f-8272-39ce46fddfb6","type":"callout","position":"a7","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"COUNT(*)","marks":[{"type":"code"}]},{"type":"text","text":" counts the padded row, so Marketing shows 1. "},{"type":"text","text":"COUNT(e.emp_id)","marks":[{"type":"code"}]},{"type":"text","text":" skips the "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" and correctly shows 0."}]}]}},"revision":1},{"id":"0989a8c6-fe60-7220-a19d-4908c75171de","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"RIGHT and FULL OUTER JOIN"}]},"revision":1},{"id":"069cb714-88ad-73d1-a8af-d6928ae99815","type":"text","position":"a9","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A RIGHT JOIN B","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"B LEFT JOIN A","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"FULL OUTER JOIN","marks":[{"type":"code"}]},{"type":"text","text":" keeps unmatched rows from "},{"type":"text","text":"both","marks":[{"type":"bold"}]},{"type":"text","text":" sides. SQLite supports both since 3.39 (2022); MySQL has "},{"type":"text","text":"no","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"FULL OUTER JOIN","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"897d8268-6fbe-716e-81e3-c502ce730989","type":"code","position":"aA","content":{"language":"sql","code":"SELECT e.name AS employee, d.name AS department\nFROM employees e\nFULL OUTER JOIN departments d ON d.dept_id = e.dept_id\nORDER BY d.dept_id NULLS LAST, e.emp_id;","filename":"SQL"},"revision":1},{"id":"ae909830-c5dc-70a7-8d15-440daa7e5643","type":"code","position":"aB","content":{"language":"text","code":"employee | department\n---------+------------\nAsha     | Engineering\nRavi     | Engineering\nMeera    | Engineering\nKaran    | Engineering\nPriya    | Sales\nArjun    | Sales\nNeha     | Sales\nVikram   | HR\nSara     | HR\nNULL     | Marketing\nDev      | NULL","filename":"Output"},"revision":1},{"id":"a88b055c-1334-7aa7-b9ad-9ff414aa9a35","type":"code","position":"aC","content":{"language":"sql","code":"-- MySQL workaround for FULL OUTER JOIN: LEFT JOIN ∪ the right-only rows\nSELECT e.name AS employee, d.name AS department\nFROM employees e LEFT JOIN departments d ON d.dept_id = e.dept_id\nUNION ALL\nSELECT NULL, d.name\nFROM departments d\nWHERE NOT EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.dept_id)\nORDER BY department, employee;","filename":"SQL"},"revision":1},{"id":"64a11967-c7bb-7980-9ed7-1fc7566eb37b","type":"code","position":"aD","content":{"language":"text","code":"employee | department\n---------+------------\nDev      | NULL\nAsha     | Engineering\nKaran    | Engineering\nMeera    | Engineering\nRavi     | Engineering\nSara     | HR\nVikram   | HR\nNULL     | Marketing\nArjun    | Sales\nNeha     | Sales\nPriya    | Sales","filename":"Output"},"revision":1},{"id":"3d5dbeaf-fcb9-7e73-aa17-a891b670fa6c","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"ON vs WHERE in an outer join"}]},"revision":1},{"id":"f4074d76-5d00-724d-a74d-4d7933693b6a","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"List every customer with their delivered orders.","marks":[{"type":"italic"}]},{"type":"text","text":" The filter on the right table must go in "},{"type":"text","text":"ON","marks":[{"type":"code"}]},{"type":"text","text":" — in "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" it removes the "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" rows and silently turns the query into an inner join."}]}]}},"revision":1},{"id":"b1e1d841-9da6-7785-b57a-8c6a26c5c10f","type":"code","position":"aG","content":{"language":"sql","code":"-- filter in ON: all 5 customers kept\nSELECT c.name, o.order_id\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.customer_id AND o.status = ''delivered''\nORDER BY c.customer_id, o.order_id;","filename":"SQL"},"revision":1},{"id":"e8398e37-6bf5-7ef7-b416-7ac67b24dedc","type":"code","position":"aH","content":{"language":"text","code":"name   | order_id\n-------+---------\nAnanya | 101\nAnanya | 103\nRahul  | 102\nRahul  | 106\nSneha  | NULL\nImran  | NULL\nKavya  | NULL","filename":"Output"},"revision":1},{"id":"c23d335e-b14f-7474-8bfa-9b15ba094793","type":"code","position":"aI","content":{"language":"sql","code":"-- filter in WHERE: Sneha, Imran and Kavya disappear\nSELECT c.name, o.order_id\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.customer_id\nWHERE o.status = ''delivered''\nORDER BY c.customer_id, o.order_id;","filename":"SQL"},"revision":1},{"id":"4e09c825-676b-785c-8d65-0c3d7f6c684e","type":"code","position":"aJ","content":{"language":"text","code":"name   | order_id\n-------+---------\nAnanya | 101\nAnanya | 103\nRahul  | 102\nRahul  | 106","filename":"Output"},"revision":1},{"id":"caf93cd6-ecf9-7984-bddf-9a8d563c77d4","type":"callout","position":"aK","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rule: conditions on the "},{"type":"text","text":"optional","marks":[{"type":"bold"}]},{"type":"text","text":" (right) side of a "},{"type":"text","text":"LEFT JOIN","marks":[{"type":"code"}]},{"type":"text","text":" go in "},{"type":"text","text":"ON","marks":[{"type":"code"}]},{"type":"text","text":"; conditions on the "},{"type":"text","text":"preserved","marks":[{"type":"bold"}]},{"type":"text","text":" (left) side go in "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":". The exception is deliberately testing for "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" ("},{"type":"text","text":"WHERE o.order_id IS NULL","marks":[{"type":"code"}]},{"type":"text","text":"), which finds non-matching rows — an anti-join."}]}]}},"revision":1},{"id":"56386131-0086-7d40-ae25-a4a9448b0463","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between LEFT JOIN and INNER JOIN?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"INNER JOIN","marks":[{"type":"code"}]},{"type":"text","text":" returns only rows with a match on both sides. "},{"type":"text","text":"LEFT JOIN","marks":[{"type":"code"}]},{"type":"text","text":" returns every row of the left table, with the right table''s columns "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" where there is no match. The row count of a left join is always ≥ the left table''s count (more if one left row matches several right rows)."}]}]}},"revision":1},{"id":"e9ad45b7-4c1b-71ab-a91a-a671df31ea24","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you emulate FULL OUTER JOIN in MySQL?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"LEFT JOIN","marks":[{"type":"code"}]},{"type":"text","text":" the two tables, then "},{"type":"text","text":"UNION ALL","marks":[{"type":"code"}]},{"type":"text","text":" the rows of the right table that have no match ("},{"type":"text","text":"RIGHT JOIN … WHERE left.key IS NULL","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"NOT EXISTS","marks":[{"type":"code"}]},{"type":"text","text":"). Plain "},{"type":"text","text":"UNION","marks":[{"type":"code"}]},{"type":"text","text":" of a "},{"type":"text","text":"LEFT","marks":[{"type":"code"}]},{"type":"text","text":" and a "},{"type":"text","text":"RIGHT","marks":[{"type":"code"}]},{"type":"text","text":" join also works but de-duplicates, which can drop genuine duplicate rows."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
