  WHERE n.id = '52abca6f-c2dc-7ddd-8744-57a9d624279d' AND n.visibility = 'PUBLIC' AND n."publishedVersionId" = '3f96ddcd-89a4-7828-b379-ec0dce674601' AND n."deletedAt" IS NULL
)
