INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT '0f424199-c1d8-7639-ac29-f7605ae9f419', '471e9327-a7c7-7c26-a89d-9e8ddadc920d', 1, 'PUBLISHED', 'ROW_NUMBER, RANK, DENSE_RANK & NTILE', '[{"id":"a41cafdf-67ab-78f6-bc9c-59c2872fba81","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ranking functions number rows in a defined order. They differ only in how they treat "},{"type":"text","text":"ties","marks":[{"type":"bold"}]},{"type":"text","text":" — the favourite interview detail."}]}]}},"revision":1},{"id":"43dbf562-6149-77ba-980b-6e3674c57380","type":"code","position":"a1","content":{"language":"sql","code":"SELECT name, salary,\n       ROW_NUMBER() OVER (ORDER BY salary DESC) AS row_num,\n       RANK()       OVER (ORDER BY salary DESC) AS rnk,\n       DENSE_RANK() OVER (ORDER BY salary DESC) AS dense_rnk\nFROM employees\nWHERE dept_id IN (1, 2)\nORDER BY salary DESC, name;","filename":"SQL"},"revision":1},{"id":"3a5efaf5-8274-7803-964c-085469a1ee8a","type":"code","position":"a2","content":{"language":"text","code":"name  | salary | row_num | rnk | dense_rnk\n------+--------+---------+-----+----------\nAsha  | 150000 | 1       | 1   | 1\nRavi  | 120000 | 2       | 2   | 2\nPriya | 110000 | 3       | 3   | 3\nKaran | 95000  | 5       | 4   | 4\nMeera | 95000  | 4       | 4   | 4\nNeha  | 72000  | 6       | 6   | 5\nArjun | 70000  | 7       | 7   | 6","filename":"Output"},"revision":1},{"id":"c6d81061-46a8-7d25-9b9b-2e15ee190b4f","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Function"}],[{"type":"text","text":"Ties"}],[{"type":"text","text":"Sequence for 150, 120, 110, 95, 95, 72"}]],[[{"type":"text","text":"ROW_NUMBER()","marks":[{"type":"code"}]}],[{"type":"text","text":"Arbitrary but unique numbers"}],[{"type":"text","text":"1, 2, 3, 4, 5, 6"}]],[[{"type":"text","text":"RANK()","marks":[{"type":"code"}]}],[{"type":"text","text":"Same rank, then a "},{"type":"text","text":"gap","marks":[{"type":"bold"}]}],[{"type":"text","text":"1, 2, 3, 4, 4, 6"}]],[[{"type":"text","text":"DENSE_RANK()","marks":[{"type":"code"}]}],[{"type":"text","text":"Same rank, "},{"type":"text","text":"no gap","marks":[{"type":"bold"}]}],[{"type":"text","text":"1, 2, 3, 4, 4, 5"}]]]},"revision":1},{"id":"4ed93697-1cfb-724c-9a09-b90827d26b80","type":"callout","position":"a4","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ROW_NUMBER","marks":[{"type":"code"}]},{"type":"text","text":" among ties is non-deterministic — Meera and Karan could swap between runs. Add a tie-breaker: "},{"type":"text","text":"ORDER BY salary DESC, emp_id","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"2f204943-0c26-7134-81d6-ede9a2e7ea8a","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Ranking within groups"}]},"revision":1},{"id":"26a14a44-bd90-7622-9b91-da0c1648c5b3","type":"code","position":"a6","content":{"language":"sql","code":"SELECT dept_id, name, salary,\n       DENSE_RANK() OVER (PARTITION BY dept_id ORDER BY salary DESC) AS rank_in_dept\nFROM employees\nWHERE dept_id IS NOT NULL\nORDER BY dept_id, rank_in_dept, name;","filename":"SQL"},"revision":1},{"id":"89ff6287-8383-7080-a9f2-52b813ca1b8b","type":"code","position":"a7","content":{"language":"text","code":"dept_id | name   | salary | rank_in_dept\n--------+--------+--------+-------------\n1       | Asha   | 150000 | 1\n1       | Ravi   | 120000 | 2\n1       | Karan  | 95000  | 3\n1       | Meera  | 95000  | 3\n2       | Priya  | 110000 | 1\n2       | Neha   | 72000  | 2\n2       | Arjun  | 70000  | 3\n3       | Sara   | 85000  | 1\n3       | Vikram | 80000  | 2","filename":"Output"},"revision":1},{"id":"f496b597-e401-76ff-b27f-451ed161ff76","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Top-N per group"}]},"revision":1},{"id":"b8e60f9f-8b69-7f2c-a175-e9ee116a8674","type":"code","position":"a9","content":{"language":"sql","code":"-- the 2 best-paid employees of each department\nWITH ranked AS (\n    SELECT dept_id, name, salary,\n           ROW_NUMBER() OVER (PARTITION BY dept_id ORDER BY salary DESC, emp_id) AS rn\n    FROM employees\n    WHERE dept_id IS NOT NULL\n)\nSELECT dept_id, name, salary\nFROM ranked\nWHERE rn <= 2\nORDER BY dept_id, rn;","filename":"SQL"},"revision":1},{"id":"e07f5338-e5b8-7ee5-b6d4-9861cd533cca","type":"code","position":"aA","content":{"language":"text","code":"dept_id | name   | salary\n--------+--------+-------\n1       | Asha   | 150000\n1       | Ravi   | 120000\n2       | Priya  | 110000\n2       | Neha   | 72000\n3       | Sara   | 85000\n3       | Vikram | 80000","filename":"Output"},"revision":1},{"id":"96b5472b-ac75-741f-9ea6-11912439a85b","type":"text","position":"aB","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Choose the function by the business rule: "},{"type":"text","text":"ROW_NUMBER","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"exactly N rows","marks":[{"type":"italic"}]},{"type":"text","text":", "},{"type":"text","text":"DENSE_RANK","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"the top N salary levels, including ties","marks":[{"type":"italic"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"084fa135-a9e2-7029-8c74-005066363632","type":"heading","position":"aC","content":{"level":1,"content":[{"type":"text","text":"NTILE, PERCENT_RANK, CUME_DIST"}]},"revision":1},{"id":"f01253c8-7ecc-7a46-94c8-391c69e16da5","type":"code","position":"aD","content":{"language":"sql","code":"SELECT name, salary,\n       NTILE(4)       OVER (ORDER BY salary DESC)          AS quartile,\n       ROUND(PERCENT_RANK() OVER (ORDER BY salary), 2)     AS pct_rank,\n       ROUND(CUME_DIST()    OVER (ORDER BY salary), 2)     AS cume_dist\nFROM employees\nORDER BY salary DESC, emp_id;","filename":"SQL"},"revision":1},{"id":"85b65ca2-0fad-77f1-896f-1504302b1cad","type":"code","position":"aE","content":{"language":"text","code":"name   | salary | quartile | pct_rank | cume_dist\n-------+--------+----------+----------+----------\nAsha   | 150000 | 1        | 1.0      | 1.0\nRavi   | 120000 | 1        | 0.89     | 0.9\nPriya  | 110000 | 1        | 0.78     | 0.8\nMeera  | 95000  | 2        | 0.56     | 0.7\nKaran  | 95000  | 2        | 0.56     | 0.7\nSara   | 85000  | 2        | 0.44     | 0.5\nVikram | 80000  | 3        | 0.33     | 0.4\nNeha   | 72000  | 3        | 0.22     | 0.3\nArjun  | 70000  | 4        | 0.11     | 0.2\nDev    | 60000  | 4        | 0.0      | 0.1","filename":"Output"},"revision":1},{"id":"e07e6d54-ea92-7337-851c-f3316bd576cc","type":"text","position":"aF","content":{"doc":{"type":"doc","content":[{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"NTILE(n)","marks":[{"type":"code"}]},{"type":"text","text":" splits the ordered rows into "},{"type":"text","text":"n","marks":[{"type":"code"}]},{"type":"text","text":" buckets as evenly as possible (earlier buckets get the extra rows: 10 rows → 3, 3, 2, 2)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"PERCENT_RANK()","marks":[{"type":"code"}]},{"type":"text","text":" = "},{"type":"text","text":"(rank − 1) / (rows − 1)","marks":[{"type":"code"}]},{"type":"text","text":" — 0 for the lowest, 1 for the highest."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CUME_DIST()","marks":[{"type":"code"}]},{"type":"text","text":" = fraction of rows with a value ≤ the current one."}]}]}]}]}},"revision":1},{"id":"3854f8f7-d6fd-7069-978c-7fcad131879a","type":"heading","position":"aG","content":{"level":1,"content":[{"type":"text","text":"Deduplicating with ROW_NUMBER"}]},"revision":1},{"id":"cbd7f899-7ed4-77e5-a9a4-7a0f6c3ad2f7","type":"code","position":"aH","content":{"language":"sql","code":"-- each customer''s most recent order\nSELECT customer_id, order_id, order_date\nFROM (\n    SELECT o.*, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY order_date DESC) AS rn\n    FROM orders o\n)\nWHERE rn = 1\nORDER BY customer_id;","filename":"SQL"},"revision":1},{"id":"6b5a08a8-6752-7153-bb25-185c098f2bf5","type":"code","position":"aI","content":{"language":"text","code":"customer_id | order_id | order_date\n------------+----------+-----------\n1           | 108      | 2024-03-15\n2           | 106      | 2024-03-01\n3           | 107      | 2024-03-08\n4           | 105      | 2024-02-20","filename":"Output"},"revision":1},{"id":"821f1ffe-7909-76b6-97bc-6f2cf2213680","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"RANK vs DENSE_RANK vs ROW_NUMBER?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"All number rows in window order. "},{"type":"text","text":"ROW_NUMBER","marks":[{"type":"code"}]},{"type":"text","text":" always gives unique consecutive numbers (ties broken arbitrarily). "},{"type":"text","text":"RANK","marks":[{"type":"code"}]},{"type":"text","text":" gives ties the same number and then skips (1, 2, 2, 4). "},{"type":"text","text":"DENSE_RANK","marks":[{"type":"code"}]},{"type":"text","text":" gives ties the same number without skipping (1, 2, 2, 3). For “Nth highest salary” use "},{"type":"text","text":"DENSE_RANK","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
