SELECT '4fc5677c-65e7-7a57-83c9-243b4ad9bb1d', '2ffb137e-f032-79a1-8659-2cbf8473def9', 1, 'PUBLISHED', 'RDBMS Landscape & Dialects', '[{"id":"d1348fca-2f57-7b21-8658-8ecfcb4ac21a","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"All major databases share core SQL, but each adds its own types, functions and syntax. Knowing the differences saves hours when you switch engines."}]}]}},"revision":1},{"id":"34f26e6c-1bb9-7069-afd8-0267520e6770","type":"callout","position":"a1","content":{"variant":"info","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"RDBMS","marks":[{"type":"bold"}]},{"type":"text","text":" — Relational Database Management System — the software that stores tables, enforces constraints, runs queries and manages transactions and users."}]}]}},"revision":1},{"id":"70b977e4-8937-77c9-8830-4b3bb4f74dd7","type":"heading","position":"a2","content":{"level":1,"content":[{"type":"text","text":"The major engines"}]},"revision":1},{"id":"7340fbca-cdcd-7275-8186-5eeb55038d2d","type":"table","position":"a3","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Engine"}],[{"type":"text","text":"Typical use"}],[{"type":"text","text":"Notable traits"}]],[[{"type":"text","text":"MySQL / MariaDB","marks":[{"type":"bold"}]}],[{"type":"text","text":"Web apps (LAMP), SaaS back ends"}],[{"type":"text","text":"Open source, InnoDB engine, very popular, replication-friendly"}]],[[{"type":"text","text":"PostgreSQL","marks":[{"type":"bold"}]}],[{"type":"text","text":"General purpose, analytics, GIS"}],[{"type":"text","text":"Most standards-compliant open-source engine; rich types ("},{"type":"text","text":"JSONB","marks":[{"type":"code"}]},{"type":"text","text":", arrays), extensions"}]],[[{"type":"text","text":"SQL Server","marks":[{"type":"bold"}]}],[{"type":"text","text":"Microsoft / enterprise stacks"}],[{"type":"text","text":"T-SQL dialect, strong tooling, "},{"type":"text","text":"TOP","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"IDENTITY","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Oracle","marks":[{"type":"bold"}]}],[{"type":"text","text":"Large enterprises, banking"}],[{"type":"text","text":"PL/SQL, "},{"type":"text","text":"ROWNUM","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"DUAL","marks":[{"type":"code"}]},{"type":"text","text":", powerful but commercial"}]],[[{"type":"text","text":"SQLite","marks":[{"type":"bold"}]}],[{"type":"text","text":"Mobile apps, browsers, embedded, tests"}],[{"type":"text","text":"A library, not a server — the whole DB is one file; dynamic typing"}]]]},"revision":1},{"id":"f8bd2c22-4dbd-7ae6-85fd-ad3095697067","type":"callout","position":"a4","content":{"variant":"note","title":"About these notes","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every runnable example in these notes executes on "},{"type":"text","text":"SQLite 3.53","marks":[{"type":"bold"}]},{"type":"text","text":", which supports modern SQL: CTEs, window functions, "},{"type":"text","text":"RIGHT","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"FULL","marks":[{"type":"code"}]},{"type":"text","text":" joins, "},{"type":"text","text":"UPSERT","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"RETURNING","marks":[{"type":"code"}]},{"type":"text","text":" and JSON. Where another engine differs, the variant is shown and labelled."}]}]}},"revision":1},{"id":"d810763e-3f5e-7f0d-9e08-39659824ad6c","type":"heading","position":"a5","content":{"level":1,"content":[{"type":"text","text":"Dialect differences you will meet"}]},"revision":1},{"id":"1b5ffb65-9c5c-729d-9ad7-b4ef4dda53a3","type":"table","position":"a6","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Task"}],[{"type":"text","text":"MySQL"}],[{"type":"text","text":"PostgreSQL"}],[{"type":"text","text":"SQL Server"}],[{"type":"text","text":"Oracle"}],[{"type":"text","text":"SQLite"}]],[[{"type":"text","text":"First N rows"}],[{"type":"text","text":"LIMIT n","marks":[{"type":"code"}]}],[{"type":"text","text":"LIMIT n","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"FETCH FIRST n ROWS ONLY","marks":[{"type":"code"}]}],[{"type":"text","text":"TOP (n)","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"OFFSET … FETCH","marks":[{"type":"code"}]}],[{"type":"text","text":"FETCH FIRST n ROWS ONLY","marks":[{"type":"code"}]},{"type":"text","text":" (12c+)"}],[{"type":"text","text":"LIMIT n","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Auto-increment id"}],[{"type":"text","text":"AUTO_INCREMENT","marks":[{"type":"code"}]}],[{"type":"text","text":"GENERATED … AS IDENTITY","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"SERIAL","marks":[{"type":"code"}]}],[{"type":"text","text":"IDENTITY(1,1)","marks":[{"type":"code"}]}],[{"type":"text","text":"GENERATED AS IDENTITY","marks":[{"type":"code"}]}],[{"type":"text","text":"INTEGER PRIMARY KEY","marks":[{"type":"code"}]}]],[[{"type":"text","text":"String concat"}],[{"type":"text","text":"CONCAT(a, b)","marks":[{"type":"code"}]}],[{"type":"text","text":"a || b","marks":[{"type":"code"}]}],[{"type":"text","text":"a + b","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"CONCAT","marks":[{"type":"code"}]}],[{"type":"text","text":"a || b","marks":[{"type":"code"}]}],[{"type":"text","text":"a || b","marks":[{"type":"code"}]}]],[[{"type":"text","text":"Current timestamp"}],[{"type":"text","text":"NOW()","marks":[{"type":"code"}]}],[{"type":"text","text":"NOW()","marks":[{"type":"code"}]}],[{"type":"text","text":"GETDATE()","marks":[{"type":"code"}]}],[{"type":"text","text":"SYSDATE","marks":[{"type":"code"}]}],[{"type":"text","text":"CURRENT_TIMESTAMP","marks":[{"type":"code"}]}]],[[{"type":"text"