INSERT INTO "notes"."NoteVersion" ("id", "noteId", "number", "kind", "title", "cards", "createdById", "createdAt")
SELECT 'cd0b474d-d6ea-7c54-8ab1-948503c41aea', '776af9e6-6243-7b95-bc18-ea4c2246086f', 1, 'PUBLISHED', 'Recursive CTEs', '[{"id":"b2af06fe-4771-76b3-af13-7a031fe1629d","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"WITH RECURSIVE","marks":[{"type":"code"}]},{"type":"text","text":" lets a CTE refer to itself — the tool for hierarchies (org charts, categories, bills of materials), graphs and generated series."}]}]}},"revision":1},{"id":"3af1c394-23a8-70be-b06b-5fa2b67400a0","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"How it works"}]},"revision":1},{"id":"d5cf190e-bf9b-7cf1-b218-e5a09a0e14dd","type":"text","position":"a2","content":{"doc":{"type":"doc","content":[{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Anchor member","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"A normal "},{"type":"text","text":"SELECT","marks":[{"type":"code"}]},{"type":"text","text":" that produces the starting rows."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"UNION ALL","marks":[{"type":"code"},{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Separates the anchor from the recursive part."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Recursive member","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"SELECT","marks":[{"type":"code"}]},{"type":"text","text":" that joins the CTE''s "},{"type":"text","text":"previous","marks":[{"type":"bold"}]},{"type":"text","text":" rows to produce the next rows."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Stop","marks":[{"type":"bold"}]}]},{"type":"paragraph","content":[{"type":"text","text":"Recursion ends when the recursive member returns no new rows."}]}]}]}]}},"revision":1},{"id":"18859b32-ff07-7883-8e5c-d8a4b3cf32d7","type":"heading","position":"a3","content":{"level":1,"content":[{"type":"text","text":"Generating a series"}]},"revision":1},{"id":"b002a9af-e9ad-7153-857b-17c97e05175b","type":"code","position":"a4","content":{"language":"sql","code":"WITH RECURSIVE n(x) AS (\n    SELECT 1                    -- anchor\n    UNION ALL\n    SELECT x + 1 FROM n         -- recursive step\n    WHERE x < 5                 -- termination\n)\nSELECT x, x * x AS square FROM n;","filename":"SQL"},"revision":1},{"id":"0b7cc097-b7df-70ac-8295-0fa80521f7d1","type":"code","position":"a5","content":{"language":"text","code":"x | square\n--+-------\n1 | 1\n2 | 4\n3 | 9\n4 | 16\n5 | 25","filename":"Output"},"revision":1},{"id":"7a7c6cde-dae4-7a9e-b102-c09546469aa0","type":"code","position":"a6","content":{"language":"sql","code":"-- a month calendar Jan–Apr 2024, then orders per month including empty months\nWITH RECURSIVE months(m) AS (\n    SELECT ''2024-01-01''\n    UNION ALL\n    SELECT date(m, ''+1 month'') FROM months WHERE m < ''2024-04-01''\n)\nSELECT strftime(''%Y-%m'', m) AS month, COUNT(o.order_id) AS orders\nFROM months\nLEFT JOIN orders o ON strftime(''%Y-%m'', o.order_date) = strftime(''%Y-%m'', m)\nGROUP BY m\nORDER BY m;","filename":"SQL"},"revision":1},{"id":"a6a56418-de96-77b7-a81f-f06ec20445d6","type":"code","position":"a7","content":{"language":"text","code":"month   | orders\n--------+-------\n2024-01 | 2\n2024-02 | 3\n2024-03 | 3\n2024-04 | 0","filename":"Output"},"revision":1},{"id":"de0d2ce0-3ab8-735f-9dd8-c148f27a50e2","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Walking a hierarchy: the org chart"}]},"revision":1},{"id":"4a4130d6-2365-7bea-8201-79ceeb0b55f8","type":"code","position":"a9","content":{"language":"sql","code":"WITH RECURSIVE org(emp_id, name, manager_id, level, path) AS (\n    SELECT emp_id, name, manager_id, 0, name\n    FROM employees\n    WHERE manager_id IS NULL                            -- start at the top (Asha)\n    UNION ALL\n    SELECT e.emp_id, e.name, e.manager_id, org.level + 1, org.path || '' > '' || e.name\n    FROM employees e\n    JOIN org ON e.manager_id = org.emp_id               -- children of the previous level\n)\nSELECT substr(''            '', 1, level * 2) || name AS org_chart, level, path\nFROM org\nORDER BY path;","filename":"SQL"},"revision":1},{"id":"06909eaa-1409-7fa0-b6e9-3417211b42ae","type":"code","position":"aA","content":{"language":"text","code":"org_chart | level | path\n----------+-------+---------------------\nAsha      | 0     | Asha\n  Dev     | 1     | Asha > Dev\n  Priya   | 1     | Asha > Priya\n    Arjun | 2     | Asha > Priya > Arjun\n    Neha  | 2     | Asha > Priya > Neha\n  Ravi    | 1     | Asha > Ravi\n    Karan | 2     | Asha > Ravi > Karan\n    Meera | 2     | Asha > Ravi > Meera\n  Vikram  | 1     | Asha > Vikram\n    Sara  | 2     | Asha > Vikram > Sara","filename":"Output"},"revision":1},{"id":"ed35858c-fdab-7cb3-9177-af24e905cf74","type":"heading","position":"aB","content":{"level":1,"content":[{"type":"text","text":"Walking up: all managers of one employee"}]},"revision":1},{"id":"728a262e-0f91-75ed-b3d5-99e98163c16d","type":"code","position":"aC","content":{"language":"sql","code":"WITH RECURSIVE chain(emp_id, name, manager_id, hops) AS (\n    SELECT emp_id, name, manager_id, 0 FROM employees WHERE name = ''Meera''\n    UNION ALL\n    SELECT m.emp_id, m.name, m.manager_id, c.hops + 1\n    FROM employees m\n    JOIN chain c ON m.emp_id = c.manager_id\n)\nSELECT hops, name FROM chain ORDER BY hops;","filename":"SQL"},"revision":1},{"id":"e8ddb84c-04d8-745a-b248-9bf92bff8cca","type":"code","position":"aD","content":{"language":"text","code":"hops | name\n-----+------\n0    | Meera\n1    | Ravi\n2    | Asha","filename":"Output"},"revision":1},{"id":"435ff830-909b-7c5a-97d1-72ccc2343a06","type":"code","position":"aE","content":{"language":"sql","code":"-- total salary cost under each manager (all levels), a \"subtree sum\"\nWITH RECURSIVE reports(boss_id, emp_id) AS (\n    SELECT manager_id, emp_id FROM employees WHERE manager_id IS NOT NULL\n    UNION ALL\n    SELECT r.boss_id, e.emp_id\n    FROM reports r JOIN employees e ON e.manager_id = r.emp_id\n)\nSELECT b.name AS manager, COUNT(*) AS total_reports, SUM(e.salary) AS team_cost\nFROM reports r\nJOIN employees b ON b.emp_id = r.boss_id\nJOIN employees e ON e.emp_id = r.emp_id\nGROUP BY b.emp_id, b.name\nORDER BY total_reports DESC, b.emp_id;","filename":"SQL"},"revision":1},{"id":"0ab49468-4674-75de-bd58-28a0106cf073","type":"code","position":"aF","content":{"language":"text","code":"manager | total_reports | team_cost\n--------+---------------+----------\nAsha    | 9             | 787000\nRavi    | 2             | 190000\nPriya   | 2             | 142000\nVikram  | 1             | 85000","filename":"Output"},"revision":1},{"id":"869755f4-25e2-7f73-b9df-f6f407756cc8","type":"callout","position":"aG","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A cycle in the data (A manages B, B manages A) makes the recursion infinite. Guard with a depth limit ("},{"type":"text","text":"WHERE level < 20","marks":[{"type":"code"}]},{"type":"text","text":"), track visited ids in a path string, or use "},{"type":"text","text":"UNION","marks":[{"type":"code"}]},{"type":"text","text":" instead of "},{"type":"text","text":"UNION ALL","marks":[{"type":"code"}]},{"type":"text","text":" (stops when no "},{"type":"text","text":"new","marks":[{"type":"italic"}]},{"type":"text","text":" rows appear). PostgreSQL 14+ has a "},{"type":"text","text":"CYCLE","marks":[{"type":"code"}]},{"type":"text","text":" clause; SQL Server stops at "},{"type":"text","text":"MAXRECURSION","marks":[{"type":"code"}]},{"type":"text","text":" (default 100)."}]}]}},"revision":1},{"id":"62e145b3-4dfe-76ae-944b-63f7a03dc3ea","type":"callout","position":"aH","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keyword differences: PostgreSQL, MySQL 8 and SQLite require "},{"type":"text","text":"WITH RECURSIVE","marks":[{"type":"code"}]},{"type":"text","text":"; SQL Server and Oracle use plain "},{"type":"text","text":"WITH","marks":[{"type":"code"}]},{"type":"text","text":" (Oracle also has the older "},{"type":"text","text":"CONNECT BY PRIOR","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"4746e4c1-6d03-760f-ab1e-aeffe8f69fcc","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you query hierarchical data in SQL?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Store a parent pointer ("},{"type":"text","text":"manager_id","marks":[{"type":"code"}]},{"type":"text","text":") and use a recursive CTE: the anchor selects the root(s), the recursive member joins the table to the CTE on "},{"type":"text","text":"child.parent_id = cte.id","marks":[{"type":"code"}]},{"type":"text","text":", carrying a "},{"type":"text","text":"level","marks":[{"type":"code"}]},{"type":"text","text":" and "},{"type":"text","text":"path","marks":[{"type":"code"}]},{"type":"text","text":". Alternatives for read-heavy trees: materialised path, nested sets, closure tables, or PostgreSQL''s "},{"type":"text","text":"ltree","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
