SELECT '0f6978b0-9c5b-7185-a80a-7dd20ad694af', '3d0127b4-cc0b-7785-8518-dcda4f61a165', 1, 'PUBLISHED', 'The Sample Database', '[{"id":"8deb98c9-de8a-7ebd-8e70-42e8b73745ca","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every example in these notes runs against this small company-and-shop database. Skim it once — then every query result is easy to verify by eye."}]}]}},"revision":1},{"id":"0da9e588-1295-7f7c-a9fd-f7a9e9ea54a4","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"The tables"}]},"revision":1},{"id":"509ce3a4-ac24-7f68-ac74-786702654c8e","type":"table","position":"a2","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Table"}],[{"type":"text","text":"Rows"}],[{"type":"text","text":"What it holds"}],[{"type":"text","text":"Links"}]],[[{"type":"text","text":"departments","marks":[{"type":"code"}]}],[{"type":"text","text":"4"}],[{"type":"text","text":"Departments and their city"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"employees","marks":[{"type":"code"}]}],[{"type":"text","text":"10"}],[{"type":"text","text":"Staff with salary, hire date and manager"}],[{"type":"text","text":"dept_id","marks":[{"type":"code"}]},{"type":"text","text":" → departments, "},{"type":"text","text":"manager_id","marks":[{"type":"code"}]},{"type":"text","text":" → employees (self)"}]],[[{"type":"text","text":"customers","marks":[{"type":"code"}]}],[{"type":"text","text":"5"}],[{"type":"text","text":"Shop customers"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"products","marks":[{"type":"code"}]}],[{"type":"text","text":"7"}],[{"type":"text","text":"Catalogue with category and list price"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"orders","marks":[{"type":"code"}]}],[{"type":"text","text":"8"}],[{"type":"text","text":"One row per order, with status"}],[{"type":"text","text":"customer_id","marks":[{"type":"code"}]},{"type":"text","text":" → customers"}]],[[{"type":"text","text":"order_items","marks":[{"type":"code"}]}],[{"type":"text","text":"13"}],[{"type":"text","text":"Lines of each order (quantity × price paid)"}],[{"type":"text","text":"order_id","marks":[{"type":"code"}]},{"type":"text","text":" → orders, "},{"type":"text","text":"product_id","marks":[{"type":"code"}]},{"type":"text","text":" → products"}]]]},"revision":1},{"id":"f57380f3-499b-7c4a-beae-59a6a5ee3096","type":"text","position":"a3","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"customers → orders → order_items → products"}]}]}},"revision":1},{"id":"f3c28835-5602-70dd-b694-a75291d313b4","type":"heading","position":"a4","content":{"level":1,"content":[{"type":"text","text":"Schema (DDL)"}]},"revision":1},{"id":"d8431195-3b61-75c0-b3d7-e46f49b7de4a","type":"code","position":"a5","content":{"language":"sql","code":"PRAGMA foreign_keys = ON;\n\nCREATE TABLE departments (\n    dept_id   INTEGER PRIMARY KEY,\n    name      TEXT NOT NULL UNIQUE,\n    location  TEXT NOT NULL\n);\n\nCREATE TABLE employees (\n    emp_id      INTEGER PRIMARY KEY,\n    name        TEXT    NOT NULL,\n    email       TEXT    UNIQUE,\n    dept_id     INTEGER REFERENCES departments(dept_id),\n    manager_id  INTEGER REFERENCES employees(emp_id),\n    salary      INTEGER NOT NULL CHECK (salary > 0),\n    hire_date   TEXT    NOT NULL\n);\n\nCREATE TABLE customers (\n    customer_id  INTEGER PRIMARY KEY,\n    name         TEXT NOT NULL,\n    city         TEXT,\n    signup_date  TEXT NOT NULL\n);\n\nCREATE TABLE products (\n    product_id  INTEGER PRIMARY KEY,\n    name        TEXT    NOT NULL,\n    category    TEXT    NOT NULL,\n    price       INTEGER NOT NULL CHECK (price >= 0)\n);\n\nCREATE TABLE orders (\n    order_id     INTEGER PRIMARY KEY,\n    customer_id  INTEGER NOT NULL REFERENCES customers(customer_id),\n    order_date   TEXT    NOT NULL,\n    status       TEXT    NOT NULL\n                 CHECK (status IN (''pending'', ''shipped'', ''delivered'', ''cancelled''))\n);\n\nCREATE TABLE order_items (\n    order_id    INTEGER NOT NULL REFERENCES orders(order_id),\n    product_id  INTEGER NOT NULL REFERENCES products(product_id),\n    quantity    INTEGER NOT NULL CHECK (quantity > 0),\n    unit_price  INTEGER NOT NULL,\n    PRIMARY KEY (order_id, product_id)\n);","filename":"SQL — schema"},"revision":1},{"id":"fbd06222-bcb6-7af0-83e2-76851096ebc7","type":"callout","position":"a6","content":{"variant":"note","title":"SQLite","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PRAGMA foreign_keys = ON","marks":[{"type":"code"}]},{"type":"text","text":" is SQLite-specific: SQLite enforces foreign keys only when this is switched on for the connection. Other engines always enforce them."}]}]}},"revision":1},{"id":"13f9e424-2953-7ae1-aa51-fcaf4a227d80","type":"heading","position":"a7","content":{"level":1,"content":[{"type":"text","text":"The data"}]},"revision":1},{"id":"f7f61075-1919-7db7-a795-24c956a0829e","type":"code","position":"a8","content":{"language":"sql","code":"SELECT * FROM departments ORDER BY dept_id;\nSELECT * FROM employees ORDER BY emp_id;","filename":"SQL"},"revision":1},{"id":"f74f9d78-b30e-7bf9-9b1f-b93ae14a2a38","type":"code","position":"a9","content":{"language":"text","code":"dept_id | name        | location\n--------+-------------+----------\n1       | Engineering | Bengaluru\n2       | Sales       | Mumbai\n3       | HR          | Hyderabad\n4       | Marketing   | Pune\n\nemp_id | name   | email          | dept_id | manager_id | salary | hire_date\n-------+--------+----------------+---------+------------+--------+-----------\n1      | Asha   | asha@corp.in   | 1       | NULL       | 150000 | 2015-03-01\n2      | Ravi   | ravi@corp.in   | 1       | 1          | 120000 | 2017-06-15\n3      | Meera  | meera@corp.in  | 1       | 2          | 95000  | 2019-01-10\n4      | Karan  | karan@corp.in  | 1       | 2          | 95000  | 2020-08-01\n5      | Priya  | priya@corp.in  | 2       | 1          | 110000 | 2016-11-20\n6      | Arjun  | arjun@corp.in  | 2       | 5          | 70000  | 2021-02-14\n7      | Neha   | NULL           | 2       | 5          | 72000  | 2022-05-30\n8      | Vikram | vikram@corp.in | 3       | 1          | 80000  | 2018-09-05\n9      | Sara   | sara@corp.in   | 3       | 8          | 85000  | 2023-01-09\n10     | Dev    | NULL           | NULL    | 1          | 60000  | 2024-04-01","filename":"Output"},"revision":1},{"id":"e9d76237-284a-7242-8754-a6ed30b019f8","type":"text","position":"aA","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Built-in quirks worth noticing — later topics rely on them:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Asha","marks":[{"type":"bold"}]},{"type":"text","text":" has no manager ("},{"type":"text","text":"manager_id","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":") — she is the root of the hierarchy."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dev","marks":[{"type":"bold"}]},{"type":"text","text":" has no department ("},{"type":"text","text":"dept_id","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":") and "},{"type":"text","text":"Marketing","marks":[{"type":"bold"}]},{"type":"text","text":" has no employees — perfect for outer joins."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Meera","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Karan","marks":[{"type":"bold"}]},{"type":"text","text":" earn the same (95000) — ties for ranking functions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Neha","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Dev","marks":[{"type":"bold"}]},{"type":"text","text":" have no email — "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" handling."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sara","marks":[{"type":"bold"}]},{"type":"text","text":" (85000) earns more than her manager "},{"type":"text","text":"Vikram","marks":[{"type":"bold"}]},{"type":"text","text":" (80000)."}]}]}]}]}},"revision":1},{"id":"2a33e148-b2b6-7fff-8043-0bc42275fabf","type":"code","position":"aB","content":{"language":"sql","code":"SELECT * FROM customers ORDER BY customer_id;\nSELECT * FROM products ORDER BY product_id;","filename":"SQL"},"revision":1},{"id":"f85b5cb2-b70b-7e6e-a8cd-f2418018b918","type":"code","position":"aC","content":{"language":"text","code":"customer_id | name   | city      | signup_date\n------------+--------+-----------+------------\n1           | Ananya | Mumbai    | 2023-11-02\n2           | Rahul  | Delhi     | 2023-12-15\n3           | Sneha  | Bengaluru | 2024-01-20\n4           | Imran  | Delhi     | 2024-02-01\n5           | Kavya  | NULL      | 2024-03-10\n\nproduct_id | name       | category    | price\n-----------+------------+-------------+------\n1          | Laptop     | Electronics | 55000\n2          | Headphones | Electronics | 2500\n3          | Desk       | Furniture   | 8000\n4          | Chair      | Furniture   | 4500\n5          | Notebook   | Stationery  | 60\n6          | Pen        | Stationery  | 20\n7          | Monitor    | Electronics | 12000","filename":"Output"},"revision":1},{"id":"e092a695-2170-70cb-961a-56be873cb18f","type":"code","position":"aD","content":{"language":"sql","code":"SELECT * FROM orders ORDER BY order_id;\nSELECT * FROM order_items ORDER BY order_id, product_id;","filename":"SQL"},"revision":1},{"id":"4751451b-6b96-7cda-9f55-acb1