  ('509ce3a4-ac24-7f68-ac74-786702654c8e', 'a2', 'table', '{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Table"}],[{"type":"text","text":"Rows"}],[{"type":"text","text":"What it holds"}],[{"type":"text","text":"Links"}]],[[{"type":"text","text":"departments","marks":[{"type":"code"}]}],[{"type":"text","text":"4"}],[{"type":"text","text":"Departments and their city"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"employees","marks":[{"type":"code"}]}],[{"type":"text","text":"10"}],[{"type":"text","text":"Staff with salary, hire date and manager"}],[{"type":"text","text":"dept_id","marks":[{"type":"code"}]},{"type":"text","text":" → departments, "},{"type":"text","text":"manager_id","marks":[{"type":"code"}]},{"type":"text","text":" → employees (self)"}]],[[{"type":"text","text":"customers","marks":[{"type":"code"}]}],[{"type":"text","text":"5"}],[{"type":"text","text":"Shop customers"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"products","marks":[{"type":"code"}]}],[{"type":"text","text":"7"}],[{"type":"text","text":"Catalogue with category and list price"}],[{"type":"text","text":"—"}]],[[{"type":"text","text":"orders","marks":[{"type":"code"}]}],[{"type":"text","text":"8"}],[{"type":"text","text":"One row per order, with status"}],[{"type":"text","text":"customer_id","marks":[{"type":"code"}]},{"type":"text","text":" → customers"}]],[[{"type":"text","text":"order_items","marks":[{"type":"code"}]}],[{"type":"text","text":"13"}],[{"type":"text","text":"Lines of each order (quantity × price paid)"}],[{"type":"text","text":"order_id","marks":[{"type":"code"}]},{"type":"text","text":" → orders, "},{"type":"text","text":"product_id","marks":[{"type":"code"}]},{"type":"text","text":" → products"}]]]}'),
  ('f57380f3-499b-7c4a-beae-59a6a5ee3096', 'a3', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"customers → orders → order_items → products"}]}]}}'),
  ('f3c28835-5602-70dd-b694-a75291d313b4', 'a4', 'heading', '{"level":1,"content":[{"type":"text","text":"Schema (DDL)"}]}'),
  ('d8431195-3b61-75c0-b3d7-e46f49b7de4a', 'a5', 'code', '{"language":"sql","code":"PRAGMA foreign_keys = ON;\n\nCREATE TABLE departments (\n    dept_id   INTEGER PRIMARY KEY,\n    name      TEXT NOT NULL UNIQUE,\n    location  TEXT NOT NULL\n);\n\nCREATE TABLE employees (\n    emp_id      INTEGER PRIMARY KEY,\n    name        TEXT    NOT NULL,\n    email       TEXT    UNIQUE,\n    dept_id     INTEGER REFERENCES departments(dept_id),\n    manager_id  INTEGER REFERENCES employees(emp_id),\n    salary      INTEGER NOT NULL CHECK (salary > 0),\n    hire_date   TEXT    NOT NULL\n);\n\nCREATE TABLE customers (\n    customer_id  INTEGER PRIMARY KEY,\n    name         TEXT NOT NULL,\n    city         TEXT,\n    signup_date  TEXT NOT NULL\n);\n\nCREATE TABLE products (\n    product_id  INTEGER PRIMARY KEY,\n    name        TEXT    NOT NULL,\n    category    TEXT    NOT NULL,\n    price       INTEGER NOT NULL CHECK (price >= 0)\n);\n\nCREATE TABLE orders (\n    order_id     INTEGER PRIMARY KEY,\n    customer_id  INTEGER NOT NULL REFERENCES customers(customer_id),\n    order_date   TEXT    NOT NULL,\n    status       TEXT    NOT NULL\n                 CHECK (status IN (''pending'', ''shipped'', ''delivered'', ''cancelled''))\n);\n\nCREATE TABLE order_items (\n    order_id    INTEGER NOT NULL REFERENCES orders(order_id),\n    product_id  INTEGER NOT NULL REFERENCES products(product_id),\n    quantity    INTEGER NOT NULL CHECK (quantity > 0),\n    unit_price  INTEGER NOT NULL,\n    PRIMARY KEY (order_id, product_id)\n);","filename":"SQL — schema"}'),
  ('fbd06222-bcb6-7af0-83e2-76851096ebc7', 'a6', 'callout', '{"variant":"note","title":"SQLite","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"PRAGMA foreign_keys = ON","marks":[{"type":"code"}]},{"type":"text","text":" is SQLite-specific: SQLite enforces foreign keys only when this is switched on for the connection. Other engines always enforce them."}]}]}}'),
