  ('e9d76237-284a-7242-8754-a6ed30b019f8', 'aA', 'text', '{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Built-in quirks worth noticing — later topics rely on them:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Asha","marks":[{"type":"bold"}]},{"type":"text","text":" has no manager ("},{"type":"text","text":"manager_id","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":") — she is the root of the hierarchy."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dev","marks":[{"type":"bold"}]},{"type":"text","text":" has no department ("},{"type":"text","text":"dept_id","marks":[{"type":"code"}]},{"type":"text","text":" is "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":") and "},{"type":"text","text":"Marketing","marks":[{"type":"bold"}]},{"type":"text","text":" has no employees — perfect for outer joins."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Meera","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Karan","marks":[{"type":"bold"}]},{"type":"text","text":" earn the same (95000) — ties for ranking functions."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Neha","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"Dev","marks":[{"type":"bold"}]},{"type":"text","text":" have no email — "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":" handling."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Sara","marks":[{"type":"bold"}]},{"type":"text","text":" (85000) earns more than her manager "},{"type":"text","text":"Vikram","marks":[{"type":"bold"}]},{"type":"text","text":" (80000)."}]}]}]}]}}