SELECT '8ebad9da-927f-759e-a690-03723d30d0d2', '6aec75e4-36c8-7004-ac52-eb33595159b4', 1, 'PUBLISHED', 'Semi & Anti Joins (EXISTS, IN, NOT EXISTS)', '[{"id":"05fe42ae-a871-7888-9d03-788c90eb7566","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"semi join","marks":[{"type":"bold"}]},{"type":"text","text":" keeps rows that "},{"type":"text","text":"have","marks":[{"type":"italic"}]},{"type":"text","text":" a match; an "},{"type":"text","text":"anti join","marks":[{"type":"bold"}]},{"type":"text","text":" keeps rows that have "},{"type":"text","text":"no","marks":[{"type":"italic"}]},{"type":"text","text":" match. Neither returns columns from the other table, and neither duplicates rows."}]}]}},"revision":1},{"id":"c3b3cb56-1f6f-7270-8496-4e652af020b0","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Semi join: customers who ordered"}]},"revision":1},{"id":"b664f8ac-d57a-76cf-b34e-9da157108096","type":"code","position":"a2","content":{"language":"sql","code":"SELECT c.name FROM customers c\nWHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id)\nORDER BY c.name;\n\nSELECT c.name FROM customers c\nWHERE c.customer_id IN (SELECT customer_id FROM orders)\nORDER BY c.name;","filename":"SQL"},"revision":1},{"id":"2f90f7b1-8d26-77b0-bc5f-a840eec1df47","type":"code","position":"a3","content":{"language":"text","code":"name\n------\nAnanya\nImran\nRahul\nSneha\n\nname\n------\nAnanya\nImran\nRahul\nSneha","filename":"Output"},"revision":1},{"id":"d636c0df-02b7-70ae-b976-f7a89904c8df","type":"text","position":"a4","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Compare with a plain join, which returns a customer once "},{"type":"text","text":"per order","marks":[{"type":"bold"}]},{"type":"text","text":":"}]}]}},"revision":1},{"id":"ebc9a73a-c229-7761-a1a0-36d385d6c5e3","type":"code","position":"a5","content":{"language":"sql","code":"SELECT c.name FROM customers c\nJOIN orders o ON o.customer_id = c.customer_id\nORDER BY c.name;","filename":"SQL"},"revision":1},{"id":"f744c705-ad38-709c-8e4f-1f7d0883b489","type":"code","position":"a6","content":{"language":"text","code":"name\n------\nAnanya\nAnanya\nAnanya\nImran\nRahul\nRahul\nSneha\nSneha","filename":"Output"},"revision":1},{"id":"c92ac994-6452-763c-83f3-c857897adecd","type":"callout","position":"a7","content":{"variant":"note","title":"Key point","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"EXISTS","marks":[{"type":"code"}]},{"type":"text","text":" stops at the first match and never multiplies rows. Using "},{"type":"text","text":"JOIN","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"DISTINCT","marks":[{"type":"code"}]},{"type":"text","text":" to get the same list does more work and is a code smell."}]}]}},"revision":1},{"id":"03909a0a-74f3-7ed8-9e2a-96c40a0aa831","type":"heading","position":"a8","content":{"level":1,"content":[{"type":"text","text":"Anti join: customers who never ordered"}]},"revision":1},{"id":"37e8614e-5435-7688-bd2c-8bb2c2420a03","type":"code","position":"a9","content":{"language":"sql","code":"-- 1. NOT EXISTS (recommended)\nSELECT c.name FROM customers c\nWHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id);\n\n-- 2. LEFT JOIN … IS NULL\nSELECT c.name FROM customers c\nLEFT JOIN orders o ON o.customer_id = c.customer_id\nWHERE o.order_id IS NULL;\n\n-- 3. NOT IN (only safe if the subquery can never return NULL)\nSELECT name FROM customers\nWHERE customer_id NOT IN (SELECT customer_id FROM orders);","filename":"SQL"},"revision":1},{"id":"a51dd2d3-c736-74fc-861c-68d8358ddcc1","type":"code","position":"aA","content":{"language":"text","code":"name\n-----\nKavya\n\nname\n-----\nKavya\n\nname\n-----\nKavya","filename":"Output"},"revision":1},{"id":"14d253c9-c0c1-7ac7-9581-7f2eef1bc656","type":"code","position":"aB","content":{"language":"sql","code":"-- products never sold\nSELECT p.name FROM products p\nWHERE NOT EXISTS (SELECT 1 FROM order_items oi WHERE oi.product_id = p.product_id);","filename":"SQL"},"revision":1},{"id":"9720e488-79c9-751c-896c-10b82a7ca0ac","type":"code","position":"aC","content":{"language":"text","code":"name\n-------\nMonitor","filename":"Output"},"revision":1},{"id":"ee606249-683c-7d8a-a59d-61449db90a38","type":"heading","position":"aD","content":{"level":1,"content":[{"type":"text","text":"The NOT IN + NULL trap, for real"}]},"revision":1},{"id":"a364489d-7128-7211-9384-c818b98d2979","type":"code","position":"aE","content":{"language":"sql","code":"-- departments that no employee belongs to…\nSELECT name FROM departments\nWHERE dept_id NOT IN (SELECT dept_id FROM employees);          -- Dev''s NULL dept_id → empty!\n\nSELECT name FROM departments d\nWHERE NOT EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.dept_id);","filename":"SQL"},"revision":1},{"id":"cfcc55c5-4e6d-7777-810c-ed5a1bcf4ba0","type":"code","position":"aF","content":{"language":"text","code":"name\n----\n\nname\n---------\nMarketing","filename":"Output"},"revision":1},{"id":"17d977fe-a023-71ba-b44d-f56da062169d","type":"callout","position":"aG","content":{"variant":"warning","title":"Watch out","doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Marketing should be returned, but "},{"type":"text","text":"NOT IN","marks":[{"type":"code"}]},{"type":"text","text":" returned nothing because the subquery contains a "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":". "},{"type":"text","text":"NOT EXISTS","marks":[{"type":"code"}]},{"type":"text","text":" is immune. If you must use "},{"type":"text","text":"NOT IN","marks":[{"type":"code"}]},{"type":"text","text":", add "},{"type":"text","text":"WHERE dept_id IS NOT NULL","marks":[{"type":"code"}]},{"type":"text","text":" inside the subquery."}]}]}},"revision":1},{"id":"1315a3b7-d8fd-78ca-8e24-1b81f6e060d3","type":"table","position":"aH","content":{"hasHeaderRow":true,"rows":[[[{"type":"text","text":"Form"}],[{"type":"text","text":"Handles NULL"}],[{"type":"text","text":"Duplicates"}],[{"type":"text","text":"Notes"}]],[[{"type":"text","text":"EXISTS","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"NOT EXISTS","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Never"}],[{"type":"text","text":"Clearest intent; optimizers turn it into a semi/anti join"}]],[[{"type":"text","text":"IN (subquery)","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Never"}],[{"type":"text","text":"Fine for semi joins"}]],[[{"type":"text","text":"NOT IN (subquery)","marks":[{"type":"code"}]}],[{"type":"text","text":"No","marks":[{"type":"bold"}]}],[{"type":"text","text":"Never"}],[{"type":"text","text":"Returns nothing if the subquery has a "},{"type":"text","text":"NULL","marks":[{"type":"code"}]}]],[[{"type":"text","text":"LEFT JOIN … IS NULL","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Never (anti)"}],[{"type":"text","text":"Common, portable; test a non-nullable column"}]],[[{"type":"text","text":"JOIN","marks":[{"type":"code"}]},{"type":"text","text":" + "},{"type":"text","text":"DISTINCT","marks":[{"type":"code"}]}],[{"type":"text","text":"Yes"}],[{"type":"text","text":"Removed afterwards"}],[{"type":"text","text":"Extra work; avoid for existence checks"}]]]},"revision":1},{"id":"8d554446-b98f-741e-aa5c-de923865fdec","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"EXISTS vs IN — which is faster?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Modern optimizers (PostgreSQL, SQL Server, Oracle, MySQL 8) usually rewrite both into the same semi join, so pick the clearest. The real difference is "},{"type":"text","text":"NOT IN","marks":[{"type":"code"}]},{"type":"text","text":" vs "},{"type":"text","text":"NOT EXISTS","marks":[{"type":"code"}]},{"type":"text","text":": "},{"type":"text","text":"NOT IN","marks":[{"type":"code"}]},{"type":"text","text":" gives wrong (empty) results when the subquery returns a "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":", so prefer "},{"type":"text","text":"NOT EXISTS","marks":[{"type":"code"}]},{"type":"text","text":" for anti joins."}]}]}},"revision":1},{"id":"afa8b514-fe18-7f4e-96dc-d99c04f9ef05","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Find customers who have never placed an order."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"SELECT c.* FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id);","marks":[{"type":"code"}]},{"type":"text","text":" — or "},{"type":"text","text":"LEFT JOIN orders o ON … WHERE o.order_id IS NULL","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
