INSERT INTO "notes"."NoteSearchDocument" ("noteId", "versionId", "title", "topics", "body", "document", "updatedAt")
SELECT '6aec75e4-36c8-7004-ac52-eb33595159b4', '8ebad9da-927f-759e-a690-03723d30d0d2', 'Semi & Anti Joins (EXISTS, IN, NOT EXISTS)', 'Semi & Anti Joins (EXISTS, IN, NOT EXISTS)', 'A semi join keeps rows that have a match; an anti join keeps rows that have no match. Neither returns columns from the other table, and neither duplicates rows.
Semi join: customers who ordered
SELECT c.name FROM customers c
WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.customer_id)
ORDER BY c.name;

SELECT c.name FROM customers c
WHERE c.customer_id IN (SELECT customer_id FROM orders)
ORDER BY c.name;
