SELECT '3e35489e-4b92-708b-82c0-b1b23e0e140f', 'cd7133b8-2be2-737b-913f-ae85c908c23b', 1, 'PUBLISHED', 'SQL Interview Q&A', '[{"id":"6f9ae4ce-78b6-73f7-94d5-d441af191b28","type":"text","position":"a0","content":{"doc":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rapid-fire theory questions with crisp answers. Each links to the topic where it is explained with runnable examples."}]}]}},"revision":1},{"id":"d8c95b9a-3512-7029-9035-9f7b448d1bca","type":"heading","position":"a1","content":{"level":1,"content":[{"type":"text","text":"Fundamentals"}]},"revision":1},{"id":"514b3ff0-cfaa-7ce4-8c53-00fb47da7132","type":"question","position":"a2","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between DELETE, TRUNCATE and DROP?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"DELETE","marks":[{"type":"code"}]},{"type":"text","text":" removes selected rows (DML, "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":", triggers fire, rollback-able). "},{"type":"text","text":"TRUNCATE","marks":[{"type":"code"}]},{"type":"text","text":" removes all rows fast by deallocating pages (DDL, no "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":", resets identity). "},{"type":"text","text":"DROP","marks":[{"type":"code"}]},{"type":"text","text":" removes the table itself."}]}]}},"revision":1},{"id":"9b68f966-6253-7b47-ae6a-30c09d948802","type":"question","position":"a3","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the difference between WHERE and HAVING?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" filters rows before grouping and can''t use aggregates; "},{"type":"text","text":"HAVING","marks":[{"type":"code"}]},{"type":"text","text":" filters groups after "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":" and can."}]}]}},"revision":1},{"id":"4e24cf77-8a89-73dc-ae0a-8c45c05b4a39","type":"question","position":"a4","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is the logical order of execution of a SELECT?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"FROM","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"JOIN","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"WHERE","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"GROUP BY","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"HAVING","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"SELECT","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"DISTINCT","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"ORDER BY","marks":[{"type":"code"}]},{"type":"text","text":" → "},{"type":"text","text":"LIMIT","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"f1746da7-dca8-7610-a662-1e05c98256d4","type":"question","position":"a5","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is NULL? How do you test for it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The marker for a missing/unknown value. Comparisons with it are "},{"type":"text","text":"UNKNOWN","marks":[{"type":"code"}]},{"type":"text","text":", so use "},{"type":"text","text":"IS NULL","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"IS NOT NULL","marks":[{"type":"code"}]},{"type":"text","text":"; replace it with "},{"type":"text","text":"COALESCE","marks":[{"type":"code"}]},{"type":"text","text":". Aggregates ignore it; "},{"type":"text","text":"COUNT(*)","marks":[{"type":"code"}]},{"type":"text","text":" doesn''t."}]}]}},"revision":1},{"id":"47bfea40-52e9-784c-8058-b981e50074d1","type":"question","position":"a6","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"UNION vs UNION ALL?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Both stack results; "},{"type":"text","text":"UNION","marks":[{"type":"code"}]},{"type":"text","text":" removes duplicates (extra sort/hash), "},{"type":"text","text":"UNION ALL","marks":[{"type":"code"}]},{"type":"text","text":" keeps them and is faster."}]}]}},"revision":1},{"id":"ae2d885b-a0fd-7a42-b61e-7b757ac2316d","type":"question","position":"a7","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are the types of joins?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"INNER","marks":[{"type":"code"}]},{"type":"text","text":" (matches only), "},{"type":"text","text":"LEFT","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"RIGHT","marks":[{"type":"code"}]},{"type":"text","text":" "},{"type":"text","text":"OUTER","marks":[{"type":"code"}]},{"type":"text","text":" (all rows of one side), "},{"type":"text","text":"FULL OUTER","marks":[{"type":"code"}]},{"type":"text","text":" (all rows of both), "},{"type":"text","text":"CROSS","marks":[{"type":"code"}]},{"type":"text","text":" (Cartesian product), plus self joins, non-equi joins, and semi/anti joins via "},{"type":"text","text":"EXISTS","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"NOT EXISTS","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"c9b8ef33-bbad-7da5-8f39-855724126709","type":"question","position":"a8","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CHAR vs VARCHAR?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"CHAR(n)","marks":[{"type":"code"}]},{"type":"text","text":" is fixed length and space-padded; "},{"type":"text","text":"VARCHAR(n)","marks":[{"type":"code"}]},{"type":"text","text":" stores only the actual characters plus a length. Use "},{"type":"text","text":"CHAR","marks":[{"type":"code"}]},{"type":"text","text":" only for truly fixed-length codes."}]}]}},"revision":1},{"id":"b665bc1c-a9ec-72d6-813e-08293c3dd7ae","type":"heading","position":"a9","content":{"level":1,"content":[{"type":"text","text":"Design"}]},"revision":1},{"id":"50cb2408-9c22-7aa2-b092-c1fc349f1c87","type":"question","position":"aA","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Primary key vs unique key?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"One primary key per table, never "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":", the row identity and FK target. Many unique keys allowed, "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"s permitted."}]}]}},"revision":1},{"id":"ff7263fe-b268-7750-a989-783fb8453805","type":"question","position":"aB","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a foreign key?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A column (set) whose values must exist in the referenced key of another table, enforcing referential integrity, with "},{"type":"text","text":"ON DELETE","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"ON UPDATE","marks":[{"type":"code"}]},{"type":"text","text":" actions ("},{"type":"text","text":"RESTRICT","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"CASCADE","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"SET NULL","marks":[{"type":"code"}]},{"type":"text","text":")."}]}]}},"revision":1},{"id":"ef1c07bd-ab74-7b26-8224-ddb800dcdb25","type":"question","position":"aC","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is normalization? Name the normal forms."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Organising data so each fact is stored once: 1NF (atomic values), 2NF (no partial dependency on a composite key), 3NF (no transitive dependency), BCNF (every determinant is a candidate key). Prevents update/insert/delete anomalies."}]}]}},"revision":1},{"id":"2a778b6e-0822-7289-816a-3db50618714d","type":"question","position":"aD","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"When would you denormalize?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"For measured read-performance needs or analytics (star schemas), accepting redundancy and sync logic."}]}]}},"revision":1},{"id":"f396fa4a-975a-7374-8d83-415beb8ff42f","type":"heading","position":"aE","content":{"level":1,"content":[{"type":"text","text":"Advanced querying"}]},"revision":1},{"id":"5ff308a7-d678-7ae3-8401-17d11d81247e","type":"question","position":"aF","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a CTE? A recursive CTE?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A named subquery defined with "},{"type":"text","text":"WITH","marks":[{"type":"code"}]},{"type":"text","text":" for one statement. A recursive CTE references itself (anchor "},{"type":"text","text":"UNION ALL","marks":[{"type":"code"}]},{"type":"text","text":" recursive member) to walk hierarchies or generate series."}]}]}},"revision":1},{"id":"516561ae-e942-7279-8bd6-3eab86d41735","type":"question","position":"aG","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What are window functions?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Functions computed over a set of rows related to the current row via "},{"type":"text","text":"OVER (PARTITION BY … ORDER BY … frame)","marks":[{"type":"code"}]},{"type":"text","text":", without collapsing rows: ranks, running totals, "},{"type":"text","text":"LAG","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"LEAD","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"bdf43e91-07cf-7c23-b3c3-2c3e98a85090","type":"question","position":"aH","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"RANK vs DENSE_RANK vs ROW_NUMBER?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"ROW_NUMBER","marks":[{"type":"code"}]},{"type":"text","text":": 1,2,3,4 always unique. "},{"type":"text","text":"RANK","marks":[{"type":"code"}]},{"type":"text","text":": ties share, then a gap (1,2,2,4). "},{"type":"text","text":"DENSE_RANK","marks":[{"type":"code"}]},{"type":"text","text":": ties share, no gap (1,2,2,3)."}]}]}},"revision":1},{"id":"e2bd54d1-ca2d-71d2-ae4f-d301f5d813e2","type":"question","position":"aI","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Correlated vs non-correlated subquery?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A correlated subquery references the outer query and is evaluated per outer row; a non-correlated one runs once independently."}]}]}},"revision":1},{"id":"4c806f19-7e91-7855-9f4d-c607a8acfc9d","type":"question","position":"aJ","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"EXISTS vs IN vs JOIN?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"EXISTS","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"IN","marks":[{"type":"code"}]},{"type":"text","text":" test membership without duplicating rows (semi join); a "},{"type":"text","text":"JOIN","marks":[{"type":"code"}]},{"type":"text","text":" returns combined rows and can multiply them. Prefer "},{"type":"text","text":"NOT EXISTS","marks":[{"type":"code"}]},{"type":"text","text":" over "},{"type":"text","text":"NOT IN","marks":[{"type":"code"}]},{"type":"text","text":" because of "},{"type":"text","text":"NULL","marks":[{"type":"code"}]},{"type":"text","text":"s."}]}]}},"revision":1},{"id":"d4148b0d-6c3e-7b50-975d-a990bef30b70","type":"heading","position":"aK","content":{"level":1,"content":[{"type":"text","text":"Performance & internals"}]},"revision":1},{"id":"2272463d-6a70-7414-b23d-b7227c6a96c5","type":"question","position":"aL","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is an index? What are its downsides?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A sorted auxiliary structure (usually a B+tree) for fast lookups, ranges and sorts. It costs storage and slows "},{"type":"text","text":"INSERT","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"UPDATE","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"DELETE","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}},"revision":1},{"id":"666f5137-5064-7539-9cf2-c647ec9798f2","type":"question","position":"aM","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Clustered vs non-clustered index?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Clustered: table rows are physically stored in index order (one per table, usually the PK). Non-clustered: separate structure pointing back to rows (many per table)."}]}]}},"revision":1},{"id":"c10dece8-3bc7-7bdb-946f-d6e38af7bd8b","type":"question","position":"aN","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a covering index?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An index that contains all columns a query needs, so the query is answered from the index without reading the table."}]}]}},"revision":1},{"id":"1a0ff882-060a-78c8-a311-390aa0fa8fa3","type":"question","position":"aO","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What makes a query non-sargable?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Functions or arithmetic on the indexed column, leading-wildcard "},{"type":"text","text":"LIKE","marks":[{"type":"code"}]},{"type":"text","text":", implicit type conversion, or "},{"type":"text","text":"OR","marks":[{"type":"code"}]},{"type":"text","text":" across columns — the index can''t be used for a seek."}]}]}},"revision":1},{"id":"0d44f9ce-7eca-7f44-b57a-71d489bedef3","type":"question","position":"aP","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you find why a query is slow?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"EXPLAIN","marks":[{"type":"code"}]},{"type":"text","text":" / "},{"type":"text","text":"EXPLAIN ANALYZE","marks":[{"type":"code"}]},{"type":"text","text":": look for full scans, bad estimates, sorts and nested loops over big inputs; then index, rewrite, or reduce data."}]}]}},"revision":1},{"id":"879045cd-2968-7001-804f-5b54850cbf29","type":"heading","position":"aQ","content":{"level":1,"content":[{"type":"text","text":"Transactions & security"}]},"revision":1},{"id":"e7a05928-90b9-78e7-81f1-e97678a4e49b","type":"question","position":"aR","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is ACID?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Atomicity (all or nothing), Consistency (constraints hold), Isolation (concurrent transactions don''t interfere, per isolation level), Durability (committed data survives crashes)."}]}]}},"revision":1},{"id":"2f0cdd8e-db6e-7349-8069-6d1afa12c548","type":"question","position":"aS","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Name the isolation levels and the anomalies they prevent."}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Read Uncommitted (none), Read Committed (dirty reads), Repeatable Read (+ non-repeatable reads), Serializable (+ phantoms and all others)."}]}]}},"revision":1},{"id":"b13abc24-e857-79f5-aada-4658bf297725","type":"question","position":"aT","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a deadlock?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Transactions waiting on each other''s locks in a cycle; the database kills one. Avoid with consistent lock order and short transactions; retry on error."}]}]}},"revision":1},{"id":"3b72d725-d816-7c0f-b0d3-e6bb355a0cb4","type":"question","position":"aU","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is SQL injection and how do you prevent it?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Untrusted input concatenated into SQL changes the query. Prevent with parameterized queries, allow-lists for identifiers and least-privilege accounts."}]}]}},"revision":1},{"id":"5877e21c-c852-7167-9f2b-00ece4ba5ee7","type":"question","position":"aV","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"View vs materialized view?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A view is a stored query run on each access (always fresh, no storage). A materialized view stores the result (fast, but stale until refreshed)."}]}]}},"revision":1},{"id":"a6f8d72f-df10-7995-b9f9-c8ac3967bd3a","type":"question","position":"aW","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Stored procedure vs function?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Procedures are called with "},{"type":"text","text":"CALL","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"EXEC","marks":[{"type":"code"}]},{"type":"text","text":", may modify data, return result sets/"},{"type":"text","text":"OUT","marks":[{"type":"code"}]},{"type":"text","text":" params and control transactions; functions return a value/table and are used inside queries."}]}]}},"revision":1},{"id":"4922fdcb-25b9-7090-9d13-acd414f56845","type":"question","position":"aX","content":{"prompt":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What is a trigger?"}]}]},"answer":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Code run automatically "},{"type":"text","text":"BEFORE","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"AFTER","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"INSTEAD OF","marks":[{"type":"code"}]},{"type":"text","text":" an "},{"type":"text","text":"INSERT","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"UPDATE","marks":[{"type":"code"}]},{"type":"text","text":"/"},{"type":"text","text":"DELETE","marks":[{"type":"code"}]},{"type":"text","text":" — for audit logs, derived values and complex rules; use sparingly because it hides logic."}]}]}},"revision":1}]'::jsonb, '019a118c-f480-7000-8000-000000000001', TIMESTAMPTZ '2026-10-07 03:23:53+00'
